    fn resume_construct_after_script(
        &mut self,
        object_id: ObjectId,
        command_instance_id: u64,
        result: AcquireScriptResult,
    ) -> Result<bool, EngineError> {
        self.execute_object_command_now_inner(
            object_id,
            ImmediateCommandResume::ConstructScript {
                command_instance_id,
                result,
            },
        )
    }

    /// Finish Construct after CreateObjectConstruction and the conkit's
    /// AssignRemoval have both completed. This is still the same native
    /// Execute invocation: Finish(true) and AddCommand(Build) happen before
    /// the event handler returns.
    fn resume_construct_after_spawn(
        &mut self,
        object_id: ObjectId,
        command_instance_id: u64,
        construction_id: Option<ObjectId>,
    ) -> Result<bool, EngineError> {
        self.execute_object_command_now_inner(
            object_id,
            ImmediateCommandResume::ConstructSpawn {
                command_instance_id,
                construction_id,
            },
        )
    }

    /// Resume the exact command body after its first callbackful FairCrew
    /// physical read. This remains the same native `C4Command::Execute`
    /// invocation, so its update interval and InitEvaluation gates must not
    /// run a second time.
    fn resume_command_after_physical(
        &mut self,
        object_id: ObjectId,
        command_instance_id: u64,
        physical: PhysicalInfo,
    ) -> Result<bool, EngineError> {
        self.execute_object_command_now_inner(
            object_id,
            ImmediateCommandResume::Physical {
                command_instance_id,
                physical,
            },
        )
    }

    fn execute_object_command_now_inner(
        &mut self,
        object_id: ObjectId,
        resume: ImmediateCommandResume,
    ) -> Result<bool, EngineError> {
        let Some(initial_index) = self.find_object_index(object_id) else {
            return Ok(false);
        };
        let physical_deferred = !matches!(resume, ImmediateCommandResume::Physical { .. })
            && self.object_physical_will_fill_fair_cache(initial_index);

        // Structural command snapshots never trigger FairCrew promotion.
        // The exact handler branch that reaches GetPhysical emits a live
        // continuation event; that event rebuilds this table after the hook.
        let mut command_snapshots = HashMap::with_capacity(self.objects.len());
        for index in 0..self.objects.len() {
            let id = self.objects[index].id;
            command_snapshots.insert(id, self.live_command_snapshot(index));
        }
        if let Some(snapshot) = command_snapshots.get_mut(&object_id) {
            match resume {
                ImmediateCommandResume::Physical { physical, .. } => {
                    // Keep the exact pointer value returned by the final
                    // native GetPhysical call even if its hook changed Def,
                    // Info, or the global FairCrew controls afterward.
                    snapshot.physical = physical;
                    snapshot.physical_deferred = false;
                }
                _ => snapshot.physical_deferred = physical_deferred,
            }
        }
        let player_snapshots = self
            .players
            .iter()
            .map(|(&id, player)| {
                (
                    id,
                    CommandPlayerSnapshot {
                        status: player.status(),
                        surrendered: player.surrendered(),
                        wealth: player.wealth(),
                        home_base_material: player.home_base_material().clone(),
                        home_base_material_entries: player
                            .home_base_material_entries()
                            .to_vec(),
                        knowledge: player.knowledge().cloned().collect(),
                        hostile_to: self
                            .players
                            .keys()
                            .copied()
                            .filter(|opponent| player.is_hostile_towards(*opponent))
                            .collect(),
                    },
                )
            })
            .collect::<HashMap<_, _>>();
        let definition_snapshots = self.command_definition_snapshot_table();
        let transfer_zones = self.transfer_zones.clone();
        let Some(index) = self.find_object_index(object_id) else {
            return Ok(false);
        };
        let Some(object_snapshot) = command_snapshots.get(&object_id) else {
            return Ok(false);
        };
        let command_rng = std::cell::RefCell::new(std::mem::take(&mut self.rng));
        let command_context = CommandRuntimeContext {
            rng: Some(&command_rng),
            frame: self.frame,
            position: object_snapshot.position,
            landscape: self.landscape.as_ref(),
            object: object_snapshot,
            objects: &command_snapshots,
            players: &player_snapshots,
            definitions: definition_snapshots.as_ref(),
            structures_need_energy: self.structures_need_energy,
            base_buy_enabled: self.base_buy_enabled,
            base_sell_enabled: self.base_sell_enabled,
            transfer_zones: &transfer_zones,
        };
        let command_gravity = self.physics.gravity_as_c4fixed();
        let result = match resume {
            ImmediateCommandResume::Front => {
                self.objects[index].step_command_stack(command_context, command_gravity)
            }
            ImmediateCommandResume::MoveToAfterStop => self.objects[index]
                .commands
                .execute_pending_move_to_stop(&command_context),
            ImmediateCommandResume::MoveToAfterFlight(command_instance_id) => self.objects[index]
                .commands
                .execute_pending_move_to_flight(&command_context, command_instance_id),
            ImmediateCommandResume::BuildAfterStop(command_instance_id) => self.objects[index]
                .commands
                .execute_pending_build_stop(&command_context, command_instance_id),
            ImmediateCommandResume::ExitAfterStop(command_instance_id) => self.objects[index]
                .commands
                .execute_pending_exit_stop(&command_context, command_instance_id),
            ImmediateCommandResume::ThrowPrelude(command_instance_id) => {
                self.objects[index].commands.execute_pending_throw_prelude(
                    &command_context,
                    command_gravity,
                    command_instance_id,
                )
            }
            ImmediateCommandResume::DropPrelude(command_instance_id) => self.objects[index]
                .commands
                .execute_pending_drop_prelude(&command_context, command_instance_id),
            ImmediateCommandResume::PutAfterStop(command_instance_id) => self.objects[index]
                .commands
                .execute_pending_put_stop(&command_context, command_gravity, command_instance_id),
            ImmediateCommandResume::ConstructAfterStop(command_instance_id) => self.objects[index]
                .commands
                .execute_pending_construct_stop(&command_context, command_instance_id),
            ImmediateCommandResume::ConstructScript {
                command_instance_id,
                result,
            } => self.objects[index]
                .commands
                .execute_pending_construct_script(&command_context, command_instance_id, result),
            ImmediateCommandResume::ConstructSpawn {
                command_instance_id,
                construction_id,
            } => self.objects[index]
                .commands
                .execute_pending_construct_spawn(
                    &command_context,
                    command_instance_id,
                    construction_id,
                ),
            ImmediateCommandResume::Physical {
                command_instance_id,
                physical,
            } => self.objects[index].commands.execute_pending_physical(
                &command_context,
                command_gravity,
                command_instance_id,
                physical,
            ),
        };
        self.rng = command_rng.into_inner();

        let mut resolved_command_physical = false;
        if let Some(result) = result {
            if let Some(update) = result.update {
                self.apply_object_update(object_id, update)?;
            }
            for event in result.events {
                resolved_command_physical |= self.apply_command_event(event)?;
            }
        }
        self.finish_object_command_execution(object_id)?;
        Ok(resolved_command_physical)
    }

    /// Advance one simulation frame and return its full presentation snapshot.
    pub fn tick(&mut self) -> Result<SimulationSnapshot, EngineError> {
        self.advance_tick()?;
        let mut snapshot = self.snapshot();
        let presentation = self.drain_tick_presentation();
        snapshot.hud.scoreboard_presentations = presentation.scoreboard_presentations;
        snapshot.menu_requests = presentation.menu_requests;
        snapshot.audio = presentation.audio;
        Ok(snapshot)
    }

    /// Advance one simulation frame and return only its transient presentation
    /// requests, without constructing the frame's full [`SimulationSnapshot`].
    ///
    /// Simulation and presentation-queue semantics are identical to
    /// [`Engine::tick`].
    pub fn tick_with_presentation(&mut self) -> Result<TickPresentation, EngineError> {
        self.advance_tick()?;
        Ok(self.drain_tick_presentation())
    }

    /// Advance one simulation frame without constructing its presentation
    /// snapshot. Presentation requests are still consumed and audio registry
    /// state is still updated exactly as if the caller had discarded the
    /// value returned by [`Engine::tick`].
    pub fn tick_without_snapshot(&mut self) -> Result<(), EngineError> {
        self.tick_with_presentation()?;
        Ok(())
    }

    fn advance_tick(&mut self) -> Result<(), EngineError> {
        // The previous frame's C4Landscape::Draw ran DoRelights before its
        // blit. Start the new simulation frame after that presentation
        // boundary so fresh SetLandscapePixel writes may survive again.
        if let Some(landscape) = &mut self.landscape {
            landscape.finish_surface32_draw();
        }
        self.exec_cursor = None;
        self.frame += 1;
        // C4Game::Ticks only arms the external one-second timer; it does not
        // increment Game.Time itself (C4Game.cpp:1899-1913).
        self.time_go = true;
        self.objective_check_counter =
            (self.objective_check_counter + 1) % GAME_OVER_CHECK_INTERVAL;
        let frame = self.frame;
        // C4GameControl::Ticks runs with the frame advance (C4Game.cpp:801)
        self.control_ticks();
        if std::env::var("LC_RUST_RNG_TRACE").is_ok() {
            crate::rng::rng_trace_frame_marker(frame);
        }
        // The per-tick scenario Step (and its `random` argument DRAW) is a
        // JSON-fixture convention: C++ never calls Step on scenario
        // scripts, and the draw would shift the synced stream every frame.
        let fixture_scenario_step = self
            .scenario_script
            .as_ref()
            .map(|script| !script.c4_args)
            .unwrap_or(false);
        if fixture_scenario_step {
            let snapshot = self.snapshot();
            let world = self.host_world_context();
            let random = self.next_random_i32();
            let rng_state = self.rng.clone();
            let environment = self.environment;
            let global_effects = self.global_effects.clone();
            let particle_defs = self.particle_system.def_names();
            let definition_metadata_table = self.definition_metadata_table();
            let definition_order = Rc::clone(&self.runtime_definition_order);
            let network_game = self.network_game;
            let engine_next_object_id = self.next_object_id;
            let scenario_script_counter = self.scenario_script_counter;
            let scoreboard = Rc::clone(&self.scoreboard);
            let materials = self.materials_shared();
            let (batch, audio_state, new_rng) = {
                let definition_scripts = self.definition_script_table();
                let script = self
                    .scenario_script
                    .as_mut()
                    .expect("scenario script must be present");
                script.step(
                    &snapshot,
                    world,
                    scoreboard,
                    materials,
                    rng_state,
                    random,
                    frame,
                    &global_effects,
                    self.physics,
                    environment,
                    self.audio_registry.clone(),
                    particle_defs,
                    definition_scripts,
                    definition_metadata_table.clone(),
                    definition_order,
                    network_game,
                    engine_next_object_id,
                    scenario_script_counter,
                )?
            };
            self.rng = new_rng;
            self.audio_registry = audio_state;
            self.apply_scenario_batch(batch)?;
        }
        let mut spawn_requests = Vec::new();
        let selected_objects: HashSet<_> = self
            .objects
            .iter()
            .filter(|object| object.state.selected)
            .map(|object| object.id)
            .collect();
        let solid_mask_indices = self.active_solid_mask_indices();

        let master_list_indices = self
            .exec_list
            .iter()
            .rev()
            .copied()
            .enumerate()
            .map(|(index, id)| (id, index))
            .collect::<HashMap<_, _>>();
        let command_snapshot_object_count = self.objects.len();
        let mut command_snapshots: HashMap<ObjectId, CommandObjectSnapshot> =
            HashMap::with_capacity(command_snapshot_object_count);
        for fallback_order in 0..command_snapshot_object_count {
            let physical = self.object_physical_without_fair_fill(fallback_order);
            let object = &self.objects[fallback_order];
            let (
                procedure,
                line_connect,
                collectible,
                move_to_range,
                pathfinder,
                no_transfer_zones,
                no_push_enter,
                action_idle,
                action_disabled,
            ) = self
                .definitions
                .get(&object.definition_id)
                .map(|definition| {
                    let procedure = definition
                        .action_library()
                        .procedure_for_entry(
                            &object.state.action.name,
                            object.state.action.act_map_index,
                        );
                    (
                        procedure,
                        definition.line_connect(),
                        definition.is_collectible(),
                        definition.move_to_range(),
                        definition.pathfinder(),
                        definition.no_transfer_zones(),
                        definition.no_push_enter(),
                        definition
                            .action_library()
                            .is_idle_state(&object.state.action),
                        definition.action_library().disables_object_for_entry(
                            &object.state.action.name,
                            object.state.action.act_map_index,
                        ),
                    )
                })
                .unwrap_or((
                    ActionProcedure::default(),
                    OCF_NORMAL,
                    false,
                    0,
                    0,
                    0,
                    0,
                    true,
                    false,
                ));
            // ExecuteCommand reads the CACHED obj->OCF (C4Command.cpp uses
            // Target->OCF etc. straight off the objects).
            let ocf = object.state.ocf;
            command_snapshots.insert(
                object.id,
                CommandObjectSnapshot {
                    id: object.id,
                    master_list_order: master_list_indices
                        .get(&object.id)
                        .copied()
                        .unwrap_or_else(|| self.exec_list.len().saturating_add(fallback_order)),
                    definition_id: object.definition_id.clone(),
                    position: object.state.position,
                    fixed_position: object.fixed_position,
                    fixed_velocity: object.fixed_velocity,
                    move_to_range,
                    pathfinder,
                    no_transfer_zones,
                    no_push_enter,
                    // C4Object::t_contact from the previous movement frame.
                    contact: object.frame_t_contact,
                    action_time: object.state.action.time,
                    shape_top: object.current_shape_rect().map(|rect| rect.y).unwrap_or(0),
                    shape_height: object
                        .current_shape_rect()
                        .map(|rect| rect.height)
                        .unwrap_or(0),
                    shape: self.object_shape_rect(object),
                    entrance: self.object_entrance_area(object),
                    status: object.state.status,
                    destroyed: object.destroyed,
                    category: object.state.category,
                    container: object.state.container,
                    action_name: object.state.action.name.clone(),
                    action_idle,
                    action_disabled,
                    action_target: object.state.action.target,
                    action_target2: object.state.action.target2,
                    action_procedure: procedure,
                    command_direction: object.state.command_direction,
                    construction: object.state.construction,
                    direction: object.state.direction,
                    physical,
                    physical_deferred: false,
                    owner: object.state.owner,
                    controller: object.state.controller,
                    base: object.state.base,
                    crew_member: object.state.crew_member,
                    selected: selected_objects.contains(&object.id),
                    alive: object.state.alive,
                    need_energy: object.state.need_energy,
                    on_fire: object.state.on_fire,
                    contents: object.state.contents.clone(),
                    commands: object.commands.command_views(),
                    line_connect,
                    ocf,
                    entrance_status: object.state.entrance_status,
                    collectible,
                },
            );
        }

        let player_snapshots: HashMap<i32, CommandPlayerSnapshot> = self
            .players
            .iter()
            .map(|(&id, player)| {
                (
                    id,
                    CommandPlayerSnapshot {
                        status: player.status(),
                        surrendered: player.surrendered(),
                        wealth: player.wealth(),
                        home_base_material: player.home_base_material().clone(),
                        home_base_material_entries: player
                            .home_base_material_entries()
                            .to_vec(),
                        knowledge: player.knowledge().cloned().collect(),
                        hostile_to: self
                            .players
                            .keys()
                            .copied()
                            .filter(|opponent| player.is_hostile_towards(*opponent))
                            .collect(),
                    },
                )
            })
            .collect();

        let definition_snapshots = self.command_definition_snapshot_table();

        // The synced RNG rides along for command-AI draws (C4Command Get's
        // Random calls); swapped in only around step_command_stack so the
        // effect-callback paths below keep using self.rng directly.
        let command_rng = std::cell::RefCell::new(LcgRng::default());
        // C4Game::ExecObjects iterates the main list from the BACK
        // (BeginLast, C4Game.cpp:1582); `exec_list` IS that list kept
        // reversed (see the field docs and `insert_into_exec_list`).
        // Prune ids whose objects were removed since the last frame, then
        // map to indices. Any live object missing from the list would be
        // a missed insertion site — execute it last and say so loudly.
        let mut exec_list = std::mem::take(&mut self.exec_list);
        exec_list.retain(|&id| self.find_object_index(id).is_some());
        self.exec_list = exec_list;
        let mut exec_order: Vec<usize> = self
            .exec_list
            .iter()
            .filter_map(|&id| self.find_object_index(id))
            .collect();
        let listed: HashSet<usize> = exec_order.iter().copied().collect();
        for idx in 0..self.objects.len() {
            let object = &self.objects[idx];
            // Inactive objects belong only to C4GameObjects::InactiveObjects;
            // deleted/destroyed objects must never be repaired back into the
            // executable main list after ResortUnsorted removed their link.
            if !object.destroyed && object.state.status.is_active() && !listed.contains(&idx) {
                tracing::warn!(
                    object = object.id.as_u64(),
                    "active object missing from exec_list; appending"
                );
                self.insert_exec_link(self.exec_list.len(), object.id);
                exec_order.push(idx);
            }
        }
        // Command scans walk `Game.Objects` from First to Next, while
        // `exec_list` is that master list reversed. Refresh the ephemeral
        // rank after pruning/fixing/appending so HashMap iteration can never
        // decide an equal-distance command target.
        Self::refresh_command_master_list_order(&self.exec_list, &mut command_snapshots);
        let mut command_snapshot_exec_insert_generation = self.exec_list_insert_generation;
        if let Some(traced) = coach_debug_id().filter(|_| (1..=300).contains(&frame)) {
            if let Some(idx) = self.find_object_index(ObjectId::new(traced)) {
                let object = &self.objects[idx];
                crate::rng::rng_trace_line(&format!(
                    "RCOACH f{frame} x={} fix_x={} xdir={} y={} fix_y={} ydir={} mobile={} t_attach={} act={} ph={} comdir={:?} dir={:?} liq={} tgt={} tgt2={}",
                    object.state.position.x,
                    object.fixed_position.x.val(),
                    object.fixed_velocity.x.val(),
                    object.state.position.y,
                    object.fixed_position.y.val(),
                    object.fixed_velocity.y.val(),
                    object.state.mobile,
                    object.frame_t_attach,
                    object.state.action.name,
                    object.state.action.phase,
                    object.state.command_direction,
                    object.state.direction,
                    object.state.in_liquid,
                    object.state.action.target.map(|id| id.as_u64()).unwrap_or(0),
                    object.state.action.target2.map(|id| id.as_u64()).unwrap_or(0)
                ));
                let commands = object.commands.snapshot().command_names();
                if !commands.is_empty() {
                    crate::rng::rng_trace_line(&format!("RCMD f{frame} {}", commands.join(",")));
                }
            }
        }
        // LC_EXECDBG=<frame>: dump the full exec order for that frame
        // (bare LC_EXECDBG keeps the legacy f1-2 intro-window dump).
        if let Ok(raw) = std::env::var("LC_EXECDBG") {
            let requested: Option<u64> = raw.trim().parse().ok();
            let hit = match requested {
                Some(target) => frame == target,
                None => (1..=2).contains(&frame),
            };
            if hit {
                for &idx in &exec_order {
                    let id = self.objects[idx].id.as_u64();
                    if requested.is_some() || (1449..=1460).contains(&id) {
                        crate::rng::rng_trace_line(&format!(
                            "REXEC f{frame} {id} {}",
                            self.objects[idx].definition_id.as_str()
                        ));
                    }
                }
            }
        }
        self.exec_cursor = Some(0);
        let mut previous_exec_object = None;
        while self
            .exec_cursor
            .is_some_and(|cursor| cursor < self.exec_list.len())
        {
            // Native removal paths can leave through many early-continue
            // arms. Clear their layer pointers before the next object gets
            // a callback-visible world snapshot; the post-loop sweep handles
            // a removal by the final object.
            if previous_exec_object.take().is_some_and(|id| {
                self.find_object_index(id).is_some_and(|index| {
                    self.objects[index].destroyed
                        || matches!(self.objects[index].state.status, ObjectStatus::Deleted)
                })
            }) {
                self.clear_destroyed_object_layers();
            }
            if command_snapshot_exec_insert_generation != self.exec_list_insert_generation {
                Self::refresh_command_master_list_order(&self.exec_list, &mut command_snapshots);
                command_snapshot_exec_insert_generation = self.exec_list_insert_generation;
            }
            let cursor = self.exec_cursor.unwrap_or_default();
            let current_id = self.exec_list[cursor];
            previous_exec_object = Some(current_id);
            self.exec_cursor = Some(cursor + 1);
            let Some(idx) = self.find_object_index(current_id) else {
                continue;
            };
            // UpdateOCF runs first in C4Object::Execute (C4Object.cpp:1058).
            self.refresh_object_ocf(idx);
            let build_target = (self.objects[idx].commands.front_command_name() == Some("Build"))
                .then(|| {
                    self.objects[idx]
                        .commands
                        .command_views()
                        .first()
                        .and_then(|command| command.target)
                })
                .flatten();
            if let Some(target_id) = build_target {
                let live_target = self
                    .find_object_index(target_id)
                    .map(|target_index| self.live_command_snapshot(target_index));
                let completing = live_target
                    .as_ref()
                    .is_some_and(|target| target.construction >= FULL_CON);
                if let Some(target) = live_target {
                    command_snapshots.insert(target_id, target);
                }
                if completing {
                    // Completion scans every live command stack and each
                    // co-builder's current contents. Foreign callbacks can
                    // mutate either after that object's own Execute, so
                    // refresh the full table where C++ calls FindObjectByCommand.
                    let live_snapshots = (0..self.objects.len())
                        .map(|index| {
                            let snapshot = self.live_command_snapshot(index);
                            (snapshot.id, snapshot)
                        })
                        .collect::<Vec<_>>();
                    command_snapshots.extend(live_snapshots);
                }
            }
            let Some(idx) = self.find_object_index(current_id) else {
                continue;
            };
            // C++ command handlers read the live object and command lists.
            // Refresh the executing object after any earlier object in this
            // frame may have changed it; completed objects are likewise
            // written back below for later command scans.
            let mut actor_snapshot = self.live_command_snapshot(idx);
            actor_snapshot.physical_deferred = self.object_physical_will_fill_fair_cache(idx);
            command_snapshots.insert(current_id, actor_snapshot);
            let (mut definition_id, mut action_library) =
                self.object_definition_context(idx)?;
            let previous_action_state = self.objects[idx].state.action.clone();
            let previous_action_name = previous_action_state.name.clone();
            let mut landscape_slot = self.landscape.take();
            let command_gravity = self.physics.gravity_as_c4fixed();
            let (
                queued_spawns,
                queue_destroy,
                queue_events,
                container_updates,
                command_events,
                queue_definition_changed,
                queue_change_def_reinsert,
                (
                    object_id,
                    previous_owner,
                    previous_crew,
                    new_owner,
                    new_crew,
                    previous_status,
                    new_status,
                ),
            ) = {
                let object = &mut self.objects[idx];
                let object_id = object.id;
                let current_position = object.state.position;
                let builder_snapshot = command_snapshots
                    .get(&object_id)
                    .expect("command snapshot exists");
                command_rng.replace(std::mem::take(&mut self.rng));
                let command_context = CommandRuntimeContext {
                    rng: Some(&command_rng),
                    frame: self.frame,
                    position: current_position,
                    landscape: landscape_slot.as_ref(),
                    object: builder_snapshot,
                    objects: &command_snapshots,
                    players: &player_snapshots,
                    definitions: definition_snapshots.as_ref(),
                    structures_need_energy: self.structures_need_energy,
                    base_buy_enabled: self.base_buy_enabled,
                    base_sell_enabled: self.base_sell_enabled,
                    transfer_zones: &self.transfer_zones,
                };
                let step_result = object.step_command_stack(command_context, command_gravity);
                self.rng = command_rng.take();
                if let Some(result) = step_result {
                    if result.update.is_some() || !result.events.is_empty() {
                        let update = result.update.unwrap_or_default();
                        let mut queued = QueuedCommand::immediate(update);
                        if !result.events.is_empty() {
                            queued = queued.with_events(result.events.clone());
                        }
                        object.command_queue.push_front(queued);
                    }
                }
                let previous_owner = object.state.owner;
                let previous_crew = object.state.crew_member;
                let previous_status = object.state.status;
                let outcome = object.execute_command_queue(
                    &self.physics,
                    &self.materials,
                    landscape_slot.as_mut(),
                    &action_library,
                    &self.definitions,
                    &self.players,
                );
                let new_owner = object.state.owner;
                let new_crew = object.state.crew_member;
                let new_status = object.state.status;
                (
                    outcome.spawns,
                    outcome.destroy,
                    outcome.effect_events,
                    outcome.container_updates,
                    outcome.command_events,
                    outcome.definition_changed,
                    outcome.change_def_reinsert,
                    (
                        object.id,
                        previous_owner,
                        previous_crew,
                        new_owner,
                        new_crew,
                        previous_status,
                        new_status,
                    ),
                )
            };
            self.landscape = landscape_slot;
            self.update_inactive_list_for_status_change(object_id, previous_status, new_status);
            self.update_selection_for_state_change(
                object_id,
                previous_owner,
                previous_crew,
                new_owner,
                new_crew,
            );

            if queue_definition_changed {
                self.update_sector_for_index(idx);
                self.update_solid_mask(idx);
                self.refresh_object_ocf(idx);
            }

            for update in container_updates {
                self.apply_container_change(update.object_id, update.previous, update.new, false)?;
            }
            if queue_change_def_reinsert {
                self.reinsert_change_def_contents_link(object_id)?;
            }

            // GetFairCrewPhysical is ordinary script. Its callback can
            // mutate any object which a later ExecObjects command will read,
            // so the frame-wide structural table from before that callback
            // is no longer valid even though only the actor's captured
            // physical value feeds the retained continuation.
            let mut resolved_command_physical = false;
            for event in command_events {
                resolved_command_physical |= self.apply_command_event(event)?;
            }
            if resolved_command_physical {
                command_snapshots = (0..self.objects.len())
                    .map(|index| {
                        let snapshot = self.live_command_snapshot(index);
                        (snapshot.id, snapshot)
                    })
                    .collect();
                Self::refresh_command_master_list_order(&self.exec_list, &mut command_snapshots);
                command_snapshot_exec_insert_generation = self.exec_list_insert_generation;
            }

            if !queue_events.is_empty() {
                let object_id = self.objects[idx].id;
                let previous_container = self.objects[idx].state.container;
                let global_view = self.global_effects.clone();
                let rng_state = self.rng.clone();
                let world = self.host_world_context_for_object(idx);
                let (
                    global_cmds,
                    emitted_particles,
                    physics_delta,
                    audio_events,
                    event_messages,
                    player_commands,
                    object_order_commands,
                    next_mission_commands,
                    landscape_ops,
                    effect_transfer_zones,
                    effect_spawns,
                    effect_other_objects,
                    effect_solid_mask_operations,
                    effect_host_raster_preview,
                    effect_solid_mask_changed,
                    _effect_action_callbacks_dispatched,
                    effect_change_def_reinsert,
                    effect_next_object_id,
                    triggered_game_over,
                    effect_script_go,
                    effect_script_counter,
                    audio_state,
                    new_rng,
                ) = {
                    let definition = self
                        .definitions
                        .get(&definition_id)
                        .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
                    let definitions_ref = &self.definitions;
                    let object = &mut self.objects[idx];
                    Self::run_effect_events_for_object(
                        definition,
                        definitions_ref,
                        self.game_over_triggered,
                        rng_state,
                        object_id,
                        object,
                        queue_events,
                        global_view,
                        &mut self.environment,
                        self.physics,
                        self.frame,
                        world.clone(),
                        self.audio_registry.clone(),
                    )?
                };
                let was_deferred = self.defer_solid_mask_updates;
                let mut outermost = self.stage_host_solid_mask_operations(
                    effect_solid_mask_operations,
                    effect_host_raster_preview,
                );
                let fold_result = (|| -> Result<(), EngineError> {
                    self.rng = new_rng;
                    self.audio_registry = audio_state;
                    if effect_solid_mask_changed {
                        self.update_solid_mask(idx);
                    }
                    self.sync_next_object_id(effect_next_object_id);
                    if !effect_spawns.is_empty() {
                        self.process_spawn_queue(effect_spawns)?;
                    }
                    if !effect_transfer_zones.is_empty() {
                        self.apply_transfer_zone_commands(effect_transfer_zones)?;
                    }
                    if !effect_other_objects.is_empty() {
                        self.apply_nested_object_outcomes(effect_other_objects)?;
                    }
                    if !landscape_ops.is_empty() {
                        self.apply_landscape_operations(landscape_ops);
                    }
                    if !player_commands.is_empty() {
                        self.apply_player_commands(player_commands)?;
                    }
                    self.pending_object_order_commands
                        .extend(object_order_commands);
                    self.apply_next_mission_commands(next_mission_commands);
                    if !audio_events.is_empty() {
                        self.pending_audio.extend(audio_events);
                    }
                    if !event_messages.is_empty() {
                        for command in event_messages {
                            self.messages.apply_command(command);
                        }
                    }
                    if let Some(go) = effect_script_go {
                        self.scenario_script_go = go;
                    }
                    if let Some(counter) = effect_script_counter {
                        self.scenario_script_counter = counter;
                    }
                    if triggered_game_over {
                        self.request_game_over()?;
                    }
                    if !physics_delta.is_empty() {
                        self.apply_physics_delta(physics_delta);
                    }
                    if !global_cmds.is_empty() {
                        self.apply_global_effect_commands(&global_cmds);
                    }
                    self.apply_particle_commands(emitted_particles);
                    let new_container = self.objects[idx].state.container;
                    if previous_container != new_container {
                        self.apply_container_change(
                            object_id,
                            previous_container,
                            new_container,
                            false,
                        )?;
                    }
                    if effect_change_def_reinsert.unwrap_or(false) {
                        self.reinsert_change_def_contents_link(object_id)?;
                    }
                    Ok(())
                })();
                outermost |= !was_deferred && self.defer_solid_mask_updates;
                self.finish_host_solid_mask_operations(outermost, fold_result)?;
            }

            self.finish_object_command_execution(object_id)?;
            let Some(idx) = self.find_object_index(object_id) else {
                continue;
            };
            // ExecuteCommand and its synchronous callbacks run before every
            // later C4Object::Execute stage. ChangeDef therefore changes the
            // live Def/ActMap used by ExecAction, movement, effects and Timer
            // in this same frame — including a swap from queue effects or
            // ControlCommandFinished rather than the direct queued delta.
            if !queued_spawns.is_empty() {
                spawn_requests.extend(queued_spawns);
            }

            if queue_destroy || self.objects[idx].destroyed {
                continue;
            }

            if !self.objects[idx].state.status.is_active() {
                continue;
            }

            dbg_stage(&self.objects[idx], "POSTCMD");
            // ExecAction captures pAction before procedure steering. SetDir
            // may replace the live action through TurnAction, but C++ keeps
            // this entry for phase advance through the end of ExecAction.
            let exec_action_source = self.objects[idx].state.action.name.clone();
            let exec_action_index = self.objects[idx].state.action.act_map_index;
            let (exec_action_definition_id, exec_action_library) =
                self.object_definition_context(idx)?;
            let mut exec_action_physical = None;
            let exec_action_returned_early =
                self.apply_physics_at_index_inner(idx, Some(&mut exec_action_physical))?;
            if self.objects[idx].destroyed {
                continue;
            }
            dbg_stage(&self.objects[idx], "POSTACT");

            // Phase advance runs at the END of ExecAction
            // (C4Object.cpp:5440-5465) — AFTER the procedure steering
            // updated xdir/ydir, so WALK/SCALE/HANGLE advances read THIS
            // frame's velocity (the old pre-steer order lagged BISO's
            // walk phase one step behind on every acceleration frame).
            // An early `return` inside ExecAction (the free-fall swim
            // exit) skips it entirely; movement below still runs.
            let mut allow_deleted_phase_end_start = false;
            if !exec_action_returned_early {
                let physical_for_advance = exec_action_physical
                    .unwrap_or_else(|| self.object_physical_without_fair_fill(idx));
                let mut advance_outcome = {
                    let object = &mut self.objects[idx];
                    // iPhaseAdvance (C4Object.cpp:4696): WALK fixtoi(|xdir|*10)
                    // (:4787-4789), SCALE fixtoi(|ydir|*14) (:4830-4832),
                    // HANGLE fixtoi(|xdir|*10) (:4867-4869), PUSH the same
                    // for nonzero xdir while retaining the default 1 at
                    // rest (:5106-5108), PULL the same with a zero baseline
                    // (:5189-5192), SWIM
                    // fixtoi(swimlimit*10) with the PHYSICAL limit, not the
                    // velocity (:5010-ish "iPhaseAdvance = fixtoi(lLimit*10)"),
                    // DIG fixtoi(diglimit*40) (:4894-4895); everything else 1.
                    let phase_advance =
                        match exec_action_library
                            .procedure_for_entry(&exec_action_source, exec_action_index)
                        {
                        ActionProcedure::Walk | ActionProcedure::Hang => {
                            math::fixtoi(object.fixed_velocity.x.abs() * 10)
                        }
                        ActionProcedure::Push if object.fixed_velocity.x.is_nonzero() => {
                            math::fixtoi(object.fixed_velocity.x.abs() * 10)
                        }
                        ActionProcedure::Push => 1,
                        ActionProcedure::Pull => math::fixtoi(object.fixed_velocity.x.abs() * 10),
                        ActionProcedure::Scale => math::fixtoi(object.fixed_velocity.y.abs() * 14),
                        ActionProcedure::Swim => {
                            math::fixtoi(math::val_by_physical(160, physical_for_advance.swim) * 10)
                        }
                        ActionProcedure::Dig
                            if object.state.command_direction == CommandDirection::Stop =>
                        {
                            0
                        }
                        ActionProcedure::Dig => {
                            math::fixtoi(math::val_by_physical(125, physical_for_advance.dig) * 40)
                        }
                        _ => 1,
                    };
                    exec_action_library.advance_state_from_entry_by(
                        &mut object.state.action,
                        &exec_action_source,
                        exec_action_index,
                        phase_advance,
                        false,
                    )
                };

                if let Some(event) = advance_outcome.phase_event.take() {
                    if let Some(callback) = exec_action_library
                        .phase_callback_for_entry(&event.action, event.act_map_index)
                    {
                        // C++ runs the PhaseCall AFTER `Phase += Step` but
                        // BEFORE the length-wrap SetAction
                        // (C4Object.cpp:5448-5462): the callback sees the
                        // POST-advance phase under the OLD action. The
                        // event snapshot carries exactly that pair; the
                        // rest of the state is live.
                        let mut state_snapshot = self.objects[idx].script_state_snapshot();
                        state_snapshot.action.name = event.live_action;
                        state_snapshot.action.act_map_index = event.live_act_map_index;
                        state_snapshot.action.phase = event.phase;
                        self.invoke_action_callback(
                            idx,
                            ActionCallbackKind::Phase,
                            &event.action,
                            event.act_map_index,
                            Some(callback),
                            Some(state_snapshot),
                            None,
                            Some(&exec_action_definition_id),
                        )?;
                    }
                }

                // Only after PhaseCall returns does C++ compare the LIVE
                // phase against the stale pAction Length and call ordinary
                // SetAction(NextAction). Callback-side SetPhase/SetAction can
                // therefore suppress or alter this transition.
                let transition_previous_state = self.objects[idx].state.action.clone();
                if let Some(phase_end) = advance_outcome.phase_end.take() {
                    let (current_definition_id, current_action_library) =
                        self.object_definition_context(idx)?;
                    // PhaseCall is synchronous and may have changed both
                    // Con and Def. The ensuing SetAction(NextAction) reads
                    // that LIVE pair before applying the incomplete-object
                    // ActIdle coercion (C4Object.cpp:4127-4130,5480-5485).
                    let active_action_allowed = self.objects[idx].state.construction >= FULL_CON
                        || self
                            .definitions
                            .get(&current_definition_id)
                            .is_some_and(Definition::incomplete_activity);
                    advance_outcome.wrapped =
                        exec_action_library.finish_phase_end_against_with_activity(
                            &mut self.objects[idx].state.action,
                            &phase_end,
                            &current_action_library,
                            active_action_allowed,
                        );
                }

                // A successful SetAction always resyncs fixed coords; Hold
                // and NoOtherAction rejection leave them untouched.
                if advance_outcome.wrapped {
                    {
                        let object = &mut self.objects[idx];
                        object.fixed_position =
                            FixedVec2::from_ints(object.state.position.x, object.state.position.y);
                        object.record_action_event(
                            transition_previous_state,
                            ActionTransitionKind::Natural,
                        );
                        // A PhaseCall may have assigned removal already. C++
                        // nevertheless executes the stale pAction phase-end
                        // SetAction, including its new action's StartCall; the
                        // callback dispatcher notices Status=0 only afterward
                        // and suppresses the remaining EndCall.
                        allow_deleted_phase_end_start = object.destroyed
                            || matches!(object.state.status, ObjectStatus::Deleted);
                    }
                    // C4Object::SetAction refreshes OCF after selecting the
                    // actual (possibly incomplete-coerced) action and before
                    // StartCall/EndCall (C4Object.cpp:4165-4183).
                    self.refresh_object_ocf(idx);
                }
            }

            // ExecAction's action transitions fire their StartCall/EndCall
            // INSIDE SetAction (C4Object.cpp:4160-4185), i.e. BEFORE
            // ExecMovement (C4Object::Execute order, :1074/:1079). A
            // StartCall that SetActions again (the coach's Driving ->
            // "Drive2") must take its fix_x/fix_y resync (:4154-4155) at
            // the PRE-movement pixel — draining only after movement let
            // the snap eat the sub-pixel remainder DoMovement just built.
            // Transitions recorded during movement/effects still drain at
            // the post-movement call below.
            self.trigger_action_callbacks_impl(
                idx,
                Some(previous_action_name.clone()),
                allow_deleted_phase_end_start,
            )?;
            if self.objects[idx].destroyed {
                continue;
            }
            (definition_id, action_library) = self.object_definition_context(idx)?;
            dbg_stage(&self.objects[idx], "PREMOVE");

            // C4Object::ExecMovement (C4Movement.cpp:553-616): contained
            // objects copy the container's motion (:556-561), C4D_StaticBack
            // never moves (:564, a MASK test unlike Init's equality), only
            // Mobile objects run DoMovement (:567), and a resting object
            // re-mobilizes with zeroed dirs and pixel-snapped fixed coords
            // on the Tick10 pulse (:576-587; counters advance before
            // objects execute, C4Game.cpp:1888).
            let exec_movement_contained = self.objects[idx].state.container.is_some();
            let exec_movement_static_back =
                self.objects[idx].state.category & CATEGORY_STATIC_BACK != 0;
            if exec_movement_contained {
                self.copy_motion_from_container(idx);
            } else if !exec_movement_static_back {
                if self.objects[idx].state.mobile {
                    // DoMovement itself owns the mask lifecycle: DigFree and
                    // pre-motion contacts see the put mask, the first
                    // DoMotion removes it, and the tail always re-puts it.
                    let movement_outcome = self.exec_object_movement(
                        idx,
                        &action_library,
                        &definition_id,
                        &solid_mask_indices,
                    )?;
                    if !movement_outcome.alive {
                        continue;
                    }
                    // Demobilization (C4Movement.cpp:572) runs after
                    // DoMovement, so same-frame friction/contact zeroing
                    // demobilizes immediately.
                    let object = &mut self.objects[idx];
                    if !object.fixed_velocity.x.is_nonzero()
                        && !object.fixed_velocity.y.is_nonzero()
                        && !object.rotation_velocity.is_nonzero()
                    {
                        object.state.mobile = false;
                    }
                    // Stabilize while not rotating (C4Movement.cpp:574).
                    if !self.objects[idx].rotation_velocity.is_nonzero() {
                        self.stabilize_object(idx, &solid_mask_indices)?;
                    }
                } else {
                    // Static objects stabilize every frame
                    // (C4Movement.cpp:579).
                    self.stabilize_object(idx, &solid_mask_indices)?;
                    if frame % 10 == 0 {
                        // Gravity mobilization (C4Movement.cpp:581-586).
                        let object = &mut self.objects[idx];
                        object.fixed_velocity = FixedVec2::ZERO;
                        object.state.velocity = Vector2::ZERO;
                        object.rotation_velocity = C4Fixed::ZERO;
                        object.fixed_position = FixedVec2::new(
                            itofix(object.state.position.x),
                            itofix(object.state.position.y),
                        );
                        object.fixed_rotation = itofix(object.state.rotation);
                        object.state.mobile = true;
                    }
                }

                // C4Object::ExecMovement applies this raw assignment after
                // both its mobile and static legs (C4Movement.cpp:596). It
                // deliberately leaves fix_r, rdir, Shape, and OCF untouched,
                // and reads the live Def after any movement callbacks.
                let non_rotateable = self
                    .definitions
                    .get(&self.objects[idx].definition_id)
                    .is_some_and(|definition| definition.rotateable() == 0);
                if non_rotateable {
                    self.objects[idx].state.rotation = 0;
                }
            }

            // C4Object::ExecMovement removes ordinary objects whose origin
            // crosses the unbounded landscape sides or bottom, before effects
            // and life execute (src/C4Movement.cpp:598-617).
            let crossed_landscape_bounds = !exec_movement_contained
                && !exec_movement_static_back
                && self.object_should_be_removed_out_of_bounds(idx);
            if crossed_landscape_bounds {
                // Rust defers SetAction callbacks; C++ ran movement-induced
                // Start/Abort calls inline before reaching this predicate.
                // Drain them first, then re-check because a callback may
                // move, save, attach, or delete the object.
                self.trigger_action_callbacks(idx, Some(previous_action_name.clone()))?;
                if self.objects[idx].destroyed
                    || matches!(self.objects[idx].state.status, ObjectStatus::Deleted)
                {
                    continue;
                }
                self.update_sector_for_index(idx);
                if self.object_should_be_removed_out_of_bounds(idx) {
                    self.assign_out_of_bounds_removal(idx)?;
                    continue;
                }
            }

            dbg_stage(&self.objects[idx], "POSTMOVE");
            self.apply_landscape_at_index(idx);
            // Masks follow every state change this frame
            // (C4Object::UpdateSolidMask fires from UpdatePos/Enter/
            // Exit/DoCon; the end-of-exec update covers the net state).
            self.update_solid_mask(idx);
            self.update_sector_for_index(idx);
            // Script effect timers execute HERE in C++ — pEffects->Execute
            // follows ExecAction and ExecMovement inside C4Object::Execute
            // (C4Object.cpp:1069-1090): an action set by a timer callback
            // gets its first PhaseDelay increment the NEXT frame, and the
            // callbacks read POST-movement state. Script effects (low
            // priority) run before the internal fire (priority 100 —
            // C4Effect execution is priority-ordered).
            // C4Effect::Execute walks the LIVE list one node at a time. Do
            // not pre-advance or snapshot the suffix: callbacks may kill a
            // later node or insert a new upper node that must execute in
            // this same frame (C4Effect.cpp:319-363).
            let mut effect_cursor = None;
            loop {
                if self.objects[idx].destroyed
                    || !self.objects[idx].state.status.is_active()
                {
                    break;
                }
                let Some((next_cursor, timer_event)) = self.objects[idx]
                    .advance_effect_frame_cursor(effect_cursor)
                else {
                    break;
                };
                effect_cursor = Some(next_cursor);
                let Some(event) = timer_event else {
                    continue;
                };
                definition_id = self.objects[idx].definition_id.clone();

                // The engine-internal fire timer (FnFxFireTimer,
                // C4Effect.cpp:643-658 → C4Object::ExecFire) executes at
                // its live-list position unless a script overload shadows
                // the engine function (C4Script.cpp:6995).
                let native_fire = event.effect.name == C4FX_FIRE
                    && !self.effect_has_script_callback(&event.effect, &definition_id, "Timer");
                if !native_fire {
                    self.dispatch_object_effect_events(idx, &definition_id, vec![event])?;
                    continue;
                }

                let entry = event.effect;
                if !entry.start_dispatched {
                    // Runtime constructors dispatch native FxFireStart in
                    // their Started event. Loaded effects also mark Start as
                    // complete. Never reinterpret persistent Fire EffectVars
                    // (Mode/CausedBy/Blasted/Incinerating) as constructor rVals.
                    if let Some(pending) = self.objects[idx]
                        .state
                        .effects
                        .iter_mut()
                        .find(|effect| effect.number == entry.number)
                    {
                        pending.start_dispatched = true;
                    }
                }
                let stop_events = self.exec_object_fire(idx, frame, entry.number);
                definition_id = self.objects[idx].definition_id.clone();
                if !stop_events.is_empty()
                    && !self.objects[idx].destroyed
                    && self.objects[idx].state.status.is_active()
                {
                    self.dispatch_object_effect_events(idx, &definition_id, stop_events)?;
                }
            }
            if self.objects[idx].destroyed
                || !self.objects[idx].state.status.is_active()
            {
                // pEffects->Execute may remove the object; C++ returns
                // before ExecLife/ExecBase/Timer (C4Object.cpp:1087-1090).
                continue;
            }
            // ExecLife runs after the fire effect (C4Object.cpp:1074-1080)
            self.exec_object_life(idx, frame)?;
            // ExecBase runs after ExecLife (C4Object.cpp:1082-1083)
            self.exec_object_base(idx, frame)?;
            if self.objects[idx].destroyed || !self.objects[idx].state.status.is_active() {
                continue;
            }
            definition_id = self.objects[idx].definition_id.clone();

            // Def TimerCall (C4Object::Execute, C4Object.cpp:1085-1091):
            // Timer++ every Execute; reaching Def->Timer resets the counter
            // and Execs Def->TimerCall. C++ resolves the name at link time
            // (missing -> nullptr, no call); the Exec itself is fail-safe.
            if self.objects[idx].state.status.is_active() && !self.objects[idx].destroyed {
                if std::env::var("LC_RUST_RNG_TRACE").is_ok()
                    && self.objects[idx].id.as_u64() == 569
                    && (16..=18).contains(&self.frame)
                {
                    tracing::warn!(
                        frame = self.frame,
                        action = %self.objects[idx].state.action.name,
                        phase = self.objects[idx].state.action.phase,
                        in_liquid = self.objects[idx].state.in_liquid,
                        "RSNKTIMER"
                    );
                }
                let timer_call = self.definitions.get(&definition_id).and_then(|definition| {
                    let interval = definition.timer().max(1);
                    let object_timer = &mut self.objects[idx].state.timer;
                    *object_timer += 1;
                    (*object_timer >= interval)
                        .then(|| {
                            *object_timer = 0;
                            definition.timer_callback()
                        })
                        .flatten()
                });
                if let Some(callback) = timer_call {
                    tolerate_script_error(self.call_object_callback(idx, &callback, Vec::new()))?;
                }
                if self.objects[idx].destroyed
                    || matches!(self.objects[idx].state.status, ObjectStatus::Deleted)
                {
                    continue;
                }
            }
            (definition_id, action_library) = self.object_definition_context(idx)?;

            // C4Object::Execute advances its active menu immediately after
            // TimerCall (C4Object.cpp:1085-1093; C4Menu.cpp:990-1000).
            if let Some(menu) = self.objects[idx]
                .state
                .menu
                .as_mut()
                .filter(|menu| menu.text_progressing)
            {
                let _ = menu.set_text_progress(1, true);
            }

            let object_id = self.objects[idx].id;
            // Step is the command-DSL fixture callback; real content has no
            // Step function (call_step would return an empty batch) — skip
            // the world snapshot, the state clone and the random draw it
            // would never consume.
            let definition_has_step = self
                .definitions
                .get(&definition_id)
                .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?
                .has_step;
            let command = if definition_has_step {
                let state_snapshot = self.objects[idx].script_state_snapshot();
                let random = self.next_random_i32();

                let rng_state = self.rng.clone();
                let (command, audio_state, new_rng, next_object_id) = {
                    let definition = self
                        .definitions
                        .get(&definition_id)
                        .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
                    definition.call_step(
                        &state_snapshot,
                        object_id,
                        frame,
                        random,
                        rng_state,
                        &self.global_effects,
                        self.physics,
                        self.environment,
                        self.host_world_context_for_object(idx),
                        self.game_over_triggered,
                        self.audio_registry.clone(),
                    )?
                };
                self.rng = new_rng;
                self.sync_next_object_id(next_object_id);
                self.audio_registry = audio_state;
                command
            } else {
                CommandBatch::default()
            };

            let CommandBatch {
                delta,
                spawns,
                destroy,
                commands,
                command_ops,
                effects,
                other_objects,
                global_effects,
                environment,
                physics,
                landscape_ops,
                solid_mask_operations,
                host_raster_preview: command_host_raster_preview,
                particles,
                transfer_zones,
                audio,
                messages,
                player_commands,
                object_order_commands,
                next_mission_commands,
                trigger_game_over,
                script_go,
                script_counter,
            } = command;

            let was_deferred = self.defer_solid_mask_updates;
            let mut outermost = self.stage_host_solid_mask_operations(
                solid_mask_operations,
                command_host_raster_preview,
            );
            let command_fold_result = (|| -> Result<(), EngineError> {
                let change_def = delta.change_def.clone();
                let change_def_reinsert = delta.change_def_reinsert;

                let action_library = change_def
                    .as_deref()
                    .and_then(|new_def| {
                        self.apply_change_object_def(idx, new_def);
                        self.shared_action_library_for(&self.objects[idx].definition_id)
                    })
                    .unwrap_or_else(|| action_library.clone());

                if let Some(go) = script_go {
                    self.scenario_script_go = go;
                }
                if let Some(counter) = script_counter {
                    self.scenario_script_counter = counter;
                }
                if trigger_game_over {
                    self.request_game_over()?;
                }

                if !player_commands.is_empty() {
                    self.apply_player_commands(player_commands)?;
                }
                self.pending_object_order_commands.extend(object_order_commands);
                self.apply_next_mission_commands(next_mission_commands);

                if !landscape_ops.is_empty() {
                    self.apply_landscape_operations(landscape_ops);
                }

                if let Some(update) = environment {
                    self.apply_environment_delta(&update);
                }
                if let Some(delta) = physics {
                    self.apply_physics_delta(delta);
                }

                let mut effect_events = Vec::new();
                if !messages.is_empty() {
                    for command in messages {
                        self.messages.apply_command(command);
                    }
                }
                let (
                    object_id,
                    previous_owner,
                    previous_crew,
                    new_owner,
                    new_crew,
                    previous_status,
                    new_status,
                    container_change,
                ) = {
                    let object = &mut self.objects[idx];
                    let previous_owner = object.state.owner;
                    let previous_crew = object.state.crew_member;
                    let previous_status = object.state.status;
                    let mut container_change = None;
                    let callbacks_dispatched = delta
                        .action
                        .as_ref()
                        .map(|action| action.callbacks_dispatched)
                        .unwrap_or(false);
                    let delta_outcome = object.apply_delta(&delta, &action_library);
                    if let Some(change) = delta_outcome.action_change {
                        if !callbacks_dispatched {
                            object
                                .record_action_event(change.previous, ActionTransitionKind::Forced);
                        }
                    }
                    if let Some(change) = delta_outcome.container_change {
                        container_change = Some(change);
                    }
                    let mut applied = object.apply_effect_commands(&effects);
                    effect_events.append(&mut applied);
                    if !matches!(
                        action_library.procedure_for_entry(
                            &object.state.action.name,
                            object.state.action.act_map_index,
                        ),
                        ActionProcedure::Flight
                    ) {
                        object.clamp_velocity(&self.physics);
                    }
                    if destroy {
                        effect_events.extend(object.mark_destroyed());
                    }
                    if !command_ops.is_empty() {
                        object.apply_command_operations(command_ops);
                    }
                    if !commands.is_empty() {
                        object.enqueue_commands(commands);
                    }
                    (
                        object.id,
                        previous_owner,
                        previous_crew,
                        object.state.owner,
                        object.state.crew_member,
                        previous_status,
                        object.state.status,
                        container_change,
                    )
                };
                self.update_inactive_list_for_status_change(object_id, previous_status, new_status);
                self.update_sector_for_index(idx);
                if !audio.is_empty() {
                    self.pending_audio.extend(audio);
                }
                self.update_selection_for_state_change(
                    object_id,
                    previous_owner,
                    previous_crew,
                    new_owner,
                    new_crew,
                );
                if let Some((previous_container, new_container)) = container_change {
                    self.apply_container_change(
                        object_id,
                        previous_container,
                        new_container,
                        false,
                    )?;
                }
                if change_def_reinsert {
                    self.reinsert_change_def_contents_link(object_id)?;
                }
                if change_def.is_some() {
                    self.update_solid_mask(idx);
                    self.refresh_object_ocf(idx);
                }

                self.apply_particle_commands(particles);
                if !transfer_zones.is_empty() {
                    self.apply_transfer_zone_commands(transfer_zones)?;
                }

                if !global_effects.is_empty() {
                    self.apply_global_effect_commands(&global_effects);
                }

                if !effect_events.is_empty() {
                    let previous_container = self.objects[idx].state.container;
                    let world = self.host_world_context_for_object(idx);
                    let (
                        global_cmds,
                        emitted_particles,
                        physics_delta,
                        audio_events,
                        event_messages,
                        player_commands,
                        object_order_commands,
                        next_mission_commands,
                        landscape_ops,
                        effect_transfer_zones,
                        effect_spawns,
                        effect_other_objects,
                        effect_solid_mask_operations,
                        effect_host_raster_preview,
                        effect_solid_mask_changed,
                        _effect_action_callbacks_dispatched,
                        effect_change_def_reinsert,
                        effect_next_object_id,
                        triggered_game_over,
                        effect_script_go,
                        effect_script_counter,
                        audio_state,
                        new_rng,
                    ) = {
                        let definition = self
                            .definitions
                            .get(&definition_id)
                            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
                        let definitions_ref = &self.definitions;
                        let global_view = self.global_effects.clone();
                        let rng_state = self.rng.clone();
                        let object = &mut self.objects[idx];
                        Self::run_effect_events_for_object(
                            definition,
                            definitions_ref,
                            self.game_over_triggered,
                            rng_state,
                            object_id,
                            object,
                            effect_events,
                            global_view,
                            &mut self.environment,
                            self.physics,
                            self.frame,
                            world.clone(),
                            self.audio_registry.clone(),
                        )?
                    };
                    self.stage_host_solid_mask_operations(
                        effect_solid_mask_operations,
                        effect_host_raster_preview,
                    );
                    self.rng = new_rng;
                    self.audio_registry = audio_state;
                    if effect_solid_mask_changed {
                        self.update_solid_mask(idx);
                    }
                    self.sync_next_object_id(effect_next_object_id);
                    if !effect_spawns.is_empty() {
                        self.process_spawn_queue(effect_spawns)?;
                    }
                    if !effect_transfer_zones.is_empty() {
                        self.apply_transfer_zone_commands(effect_transfer_zones)?;
                    }
                    if !effect_other_objects.is_empty() {
                        self.apply_nested_object_outcomes(effect_other_objects)?;
                    }
                    if !player_commands.is_empty() {
                        self.apply_player_commands(player_commands)?;
                    }
                    self.pending_object_order_commands
                        .extend(object_order_commands);
                    self.apply_next_mission_commands(next_mission_commands);
                    if !landscape_ops.is_empty() {
                        self.apply_landscape_operations(landscape_ops);
                    }
                    if !audio_events.is_empty() {
                        self.pending_audio.extend(audio_events);
                    }
                    if !event_messages.is_empty() {
                        for command in event_messages {
                            self.messages.apply_command(command);
                        }
                    }
                    if let Some(go) = effect_script_go {
                        self.scenario_script_go = go;
                    }
                    if let Some(counter) = effect_script_counter {
                        self.scenario_script_counter = counter;
                    }
                    if triggered_game_over {
                        self.request_game_over()?;
                    }
                    if !physics_delta.is_empty() {
                        self.apply_physics_delta(physics_delta);
                    }
                    let new_container = self.objects[idx].state.container;
                    if !global_cmds.is_empty() {
                        self.apply_global_effect_commands(&global_cmds);
                    }
                    self.apply_particle_commands(emitted_particles);
                    if previous_container != new_container {
                        self.apply_container_change(
                            object_id,
                            previous_container,
                            new_container,
                            false,
                        )?;
                    }
                    if effect_change_def_reinsert.unwrap_or(false) {
                        self.reinsert_change_def_contents_link(object_id)?;
                    }
                }
                self.update_sector_for_index(idx);

                self.apply_nested_object_outcomes(other_objects)?;

                Ok(())
            })();
            outermost |= !was_deferred && self.defer_solid_mask_updates;
            self.finish_host_solid_mask_operations(outermost, command_fold_result)?;

            self.trigger_action_callbacks(idx, Some(previous_action_name))?;
            self.update_sector_for_index(idx);

            if self.objects[idx].destroyed {
                continue;
            }

            self.apply_landscape_at_index(idx);
            self.update_sector_for_index(idx);
            let (
                procedure,
                line_connect,
                collectible,
                move_to_range,
                pathfinder,
                no_transfer_zones,
                no_push_enter,
                action_idle,
                action_disabled,
            ) = self
                .definitions
                .get(&self.objects[idx].definition_id)
                .map(|definition| {
                    (
                        definition
                            .action_library()
                            .procedure_for_entry(
                                &self.objects[idx].state.action.name,
                                self.objects[idx].state.action.act_map_index,
                            ),
                        definition.line_connect(),
                        definition.is_collectible(),
                        definition.move_to_range(),
                        definition.pathfinder(),
                        definition.no_transfer_zones(),
                        definition.no_push_enter(),
                        definition
                            .action_library()
                            .is_idle_state(&self.objects[idx].state.action),
                        definition.action_library().disables_object_for_entry(
                            &self.objects[idx].state.action.name,
                            self.objects[idx].state.action.act_map_index,
                        ),
                    )
                })
                .unwrap_or((
                    action_library.procedure_for_entry(
                        &self.objects[idx].state.action.name,
                        self.objects[idx].state.action.act_map_index,
                    ),
                    OCF_NORMAL,
                    false,
                    0,
                    0,
                    0,
                    0,
                    action_library.is_idle_state(&self.objects[idx].state.action),
                    action_library.disables_object_for_entry(
                        &self.objects[idx].state.action.name,
                        self.objects[idx].state.action.act_map_index,
                    ),
                ));
            // ExecuteCommand reads the CACHED obj->OCF (refreshed at this
            // object's Execute-start, C4Object.cpp:1058).
            let ocf = self.objects[idx].state.ocf;
            let master_list_order = self
                .exec_list
                .iter()
                .rev()
                .position(|&id| id == object_id)
                .unwrap_or_else(|| self.exec_list.len().saturating_add(idx));
            command_snapshots.insert(
                object_id,
                CommandObjectSnapshot {
                    id: object_id,
                    master_list_order,
                    definition_id: self.objects[idx].definition_id.clone(),
                    position: self.objects[idx].state.position,
                    fixed_position: self.objects[idx].fixed_position,
                    fixed_velocity: self.objects[idx].fixed_velocity,
                    move_to_range,
                    pathfinder,
                    no_transfer_zones,
                    no_push_enter,
                    contact: self.objects[idx].frame_t_contact,
                    action_time: self.objects[idx].state.action.time,
                    shape_top: self.objects[idx]
                        .current_shape_rect()
                        .map(|rect| rect.y)
                        .unwrap_or(0),
                    shape_height: self.objects[idx]
                        .current_shape_rect()
                        .map(|rect| rect.height)
                        .unwrap_or(0),
                    shape: self.object_shape_rect(&self.objects[idx]),
                    entrance: self.object_entrance_area(&self.objects[idx]),
                    status: self.objects[idx].state.status,
                    destroyed: self.objects[idx].destroyed,
                    category: self.objects[idx].state.category,
                    container: self.objects[idx].state.container,
                    action_name: self.objects[idx].state.action.name.clone(),
                    action_idle,
                    action_disabled,
                    action_target: self.objects[idx].state.action.target,
                    action_target2: self.objects[idx].state.action.target2,
                    action_procedure: procedure,
                    command_direction: self.objects[idx].state.command_direction,
                    construction: self.objects[idx].state.construction,
                    direction: self.objects[idx].state.direction,
                    physical: self.object_physical_without_fair_fill(idx),
                    physical_deferred: false,
                    owner: self.objects[idx].state.owner,
                    controller: self.objects[idx].state.controller,
                    base: self.objects[idx].state.base,
                    crew_member: self.objects[idx].state.crew_member,
                    selected: self.objects[idx].state.selected,
                    alive: self.objects[idx].state.alive,
                    need_energy: self.objects[idx].state.need_energy,
                    on_fire: self.objects[idx].state.on_fire,
                    contents: self.objects[idx].state.contents.clone(),
                    commands: self.objects[idx].commands.command_views(),
                    line_connect,
                    ocf,
                    entrance_status: self.objects[idx].state.entrance_status,
                    collectible,
                },
            );
            spawn_requests.extend(spawns.into_iter());
        }
        self.exec_cursor = None;

        // CreateObject is synchronous inside C4Object::Execute. Rust defers
        // materialization only so a freshly linked object cannot enter the
        // current execution-list walk; once that walk closes it must exist
        // for CrossCheck, world systems, and especially Players.Execute's
        // Tick35 CrewCnt snapshot.
        self.process_spawn_queue(spawn_requests)?;

        // AssignRemoval calls Game.ClearPointers before returning. Native
        // engine-owned removal paths do not pass through the synchronous
        // script host, so clear their pLayer references at the last common
        // seam before this frame's CrossCheck.
        self.clear_destroyed_object_layers();

        // C4GameObjects::CrossCheck runs once per frame after object        // execution (C4Game.cpp ExecObjects → Objects.CrossCheck()).
        self.cross_check(frame)?;
        self.execute_object_order_commands();

        for index in 0..self.objects.len() {
            if self.objects[index].destroyed {
                // AssignRemoval destroys the mask (C4Object.cpp:5647).
                self.remove_solid_mask(index);
            }
        }
        self.detach_destroyed_objects()?;
        let object_count_before_retain = self.objects.len();
        self.objects.retain(|object| !object.destroyed);
        if self.objects.len() != object_count_before_retain {
            self.note_objects_changed();
        }
        self.rebuild_sectors();
        let alive: HashSet<_> = self.objects.iter().map(|object| object.id).collect();
        // C4Game::Execute phase order (C4Game.cpp:810-822): ExecObjects
        // runs FIRST; then GlobalEffects, PXS, Particles, MassMover,
        // Weather, Landscape, Players, Messages, Script. Objects observe
        // the PREVIOUS frame's weather/PXS state and their RNG draws
        // precede every world-system draw within the frame.
        self.tick_global_effects()?;
        self.tick_pxs();
        self.tick_particles();
        self.tick_mass_movers();
        self.weather_events.clear();
        if let Some(points) = self.environment.advance_frame(&mut self.rng, frame) {
            let _ = self.gamma.set_ramp(1, points);
        }
        self.tick_weather_wind_audio(frame);
        self.tick_weather_events(frame)?;
        self.apply_landscape_temperature_conversions();
        if let Some(sky) = &mut self.sky {
            sky.advance(&self.environment);
        }
        // Players.Execute completes each player serially in list order:
        // counts/view/control/menu, Tick35 work, then delays.
        self.tick_player_systems()?;
        self.messages.tick(&alive);
        // C4GameScriptHost::Execute (C4ScriptHost.cpp:222-232): while
        // Game.Script.Go, every 10th frame calls Script%d with the counter
        // post-incrementing — the timed intro/movie sections. Runs AFTER
        // ExecObjects and Messages.Execute in the C++ frame
        // (C4Game.cpp:810-822): effects it adds first execute NEXT frame
        // (the intro Divinity markers compare at t=0 on their add frame).
        if self.scenario_script_go && frame % 10 == 0 && self.scenario_script.is_some() {
            let section = format!("Script{}", self.scenario_script_counter);
            self.scenario_script_counter += 1;
            tolerate_script_error(self.call_scenario_script_function(&section, Vec::new()))?;
        }
        self.transfer_zones.retain_existing(&alive);
        self.prune_selection();
        // C4Game::UpdateRules follows Script.Execute and refreshes only on
        // Tick255 (plus frame one) (C4Game.cpp:845,4038-4047).
        if frame == 1 || frame % 255 == 0 {
            self.refresh_structures_snow_in_rule();
            self.refresh_flag_removeable_rule();
        }
        self.refresh_elimination_state();
        self.check_game_over()?;
        // Control.DoSyncCheck() closes the frame (C4Game.cpp:829)
        self.do_sync_check();
        // C4Game::Execute evaluates only after the synchronized frame closes
        // (C4Game.cpp:845-854).
        if self.game_over_triggered && !self.game_evaluated {
            self.evaluate_game()?;
        }
        Ok(())
    }

    fn drain_tick_presentation(&mut self) -> TickPresentation {
        let scoreboard_presentations = self.take_scoreboard_presentations();
        let menu_requests = self.pending_menu_requests.drain(..).collect();
        for command in &self.pending_audio {
            match command {
                AudioCommand::PlaySound {
                    target: Some(target),
                    ..
                }
                | AudioCommand::PlaySpeech {
                    target: Some(target),
                    ..
                }
                | AudioCommand::SetSoundVolume {
                    target: Some(target),
                    ..
                } => self.audio_registry.note_attached_sound(*target),
                AudioCommand::DetachObjectSounds { target, .. } => {
                    self.audio_registry.note_detached_sounds(*target);
                }
                _ => {}
            }
        }
        let audio = self.pending_audio.drain(..).collect();
        TickPresentation {
            scoreboard_presentations,
            menu_requests,
            audio,
        }
    }

    pub fn object_snapshot(&self, id: ObjectId) -> Option<ObjectSnapshot> {
        let object = &self.objects[self.find_object_index(id)?];
        let library = self
            .definitions
            .get(&object.definition_id)
            .map(|definition| definition.action_library());
        Some(object.snapshot(library))
    }

    /// `C4ObjectList::ObjectCount(C4ID_None, C4D_All)`: count only objects
    /// whose native `Status` is still set.
    pub fn active_object_count(&self) -> usize {
        self.objects
            .iter()
            .filter(|object| !object.destroyed)
            .count()
    }

    /// Lowest-ID object with this definition, matching the ordering exposed
    /// by [`Engine::snapshot`] without constructing that snapshot.
    pub fn first_object_for_definition(&self, definition: &str) -> Option<ObjectId> {
        self.objects
            .iter()
            .filter(|object| object.definition_id == definition)
            .map(|object| object.id)
            .min()
    }

    pub fn object_count_for_definition(&self, definition: &str) -> usize {
        self.objects
            .iter()
            .filter(|object| object.definition_id == definition)
            .count()
    }

    pub fn object_count_for_definition_in_container(
        &self,
        definition: &str,
        container: ObjectId,
    ) -> usize {
        self.objects
            .iter()
            .filter(|object| {
                object.definition_id == definition && object.state.container == Some(container)
            })
            .count()
    }

    /// Exact text used by `C4MouseControl` for an object's help caption:
    /// `C4Object::GetName()`, followed by the definition description when it
    /// exists (src/C4MouseControl.cpp:1134-1142).
    pub fn object_help_caption(&self, id: ObjectId) -> Option<String> {
        let object = self.objects.iter().find(|object| object.id == id)?;
        let definition = self.definitions.get(&object.definition_id)?;
        let name = object
            .state
            .custom_name
            .as_deref()
            .filter(|name| !name.is_empty())
            .or_else(|| {
                self.crew_object_infos
                    .get(&id)
                    .map(|info| info.name.as_str())
            })
            .unwrap_or_else(|| definition.name());
        Some(match definition.description() {
            Some(description) => format!("{name}: {description}"),
            None => name.to_string(),
        })
    }

    pub fn apply_object_update(
        &mut self,
        id: ObjectId,
        update: ObjectUpdate,
    ) -> Result<(), EngineError> {
        let landscape = self.landscape.clone();
        let index = self
            .objects
            .iter()
            .position(|object| object.id == id)
            .ok_or(EngineError::UnknownObject(id))?;
        let previous_status = self.objects[index].state.status;

        let ObjectUpdate {
            custom_name,
            layer,
            compiler_cache,
            visibility,
            blit_mode,
            picture_rect: update_picture_rect,
            position,
            velocity,
            fixed_velocity,
            fixed_velocity_x,
            fixed_velocity_y,
            mobile,
            t_attach,
            rotation,
            rotation_velocity,
            energy,
            breath,
            energy_loss_cause,
            fire,
            fire_flag,
            construction,
            construction_via_docon,
            construction_preserves_fixed_position,
            resolved_docon_position,
            resolved_docon_fixed_position,
            damage,
            magic_energy,
            magic_capacity,
            direction,
            command_direction,
            action,
            status,
            owner,
            base,
            controller,
            own_mass,
            crew_member,
            plr_view_range,
            crew_status_change,
            info_rank,
            info_link,
            crew_disabled,
            solid_mask_override: update_solid_mask,
            solid_mask_instance_sequence,
            change_def,
            change_def_reinsert,
            alive,
            container,
            live_vertices,
            shape_vertices,
            contact_density,
            vertices,
            graphics_overlays,
            base_graphics: update_base_graphics,
            components,
            component_order,
            physicals,
            entrance_status: update_entrance_status,
            color: update_color,
            color_modulation: update_color_modulation,
            shape_override: update_shape_override,
            menu: update_menu,
            ..
        } = update;
        let mut update_menu = update_menu;
        if let Some(Some(menu)) = update_menu.as_mut() {
            if menu.runtime_id == 0 {
                menu.runtime_id = crate::direct_com::next_object_menu_runtime_id();
            }
        }
        if let Some(sequence) = solid_mask_instance_sequence {
            self.next_solid_mask_instance_sequence = self.next_solid_mask_instance_sequence.max(
                sequence
                    .checked_add(1)
                    .expect("C4SolidMask instance sequence overflow"),
            );
        }
        let fow_range_changed = plr_view_range.is_some();
        let fow_crew_actualize = crew_member == Some(true);

        let definition_id = self.objects[index].definition_id.clone();
        let previous_action_name = self.objects[index].state.action.name.clone();
        let action_library = self
            .shared_action_library_for(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;

        let mut energy_died = false;
        let mut solid_mask_refresh = rotation.is_some()
            || change_def.is_some()
            || construction.is_some()
            || solid_mask_instance_sequence.is_some();
        // FnChangeDef swaps INLINE (C4Object.cpp:1205-1231): apply it
        // BEFORE the staged fields so an action write in the same update
        // resolves against the NEW def's ActMap.
        let action_library = change_def
            .as_ref()
            .and_then(|new_def| {
                self.apply_change_object_def(index, new_def);
                self.shared_action_library_for(&self.objects[index].definition_id)
            })
            .unwrap_or(action_library);
        let (object_id, previous_owner, previous_crew, new_owner, new_crew, container_change) = {
            let object = &mut self.objects[index];
            let previous_owner = object.state.owner;
            let previous_crew = object.state.crew_member;
            let previous_container = object.state.container;
            let mut container_change = None;

            if let Some(custom_name) = custom_name {
                object.state.custom_name = custom_name;
            }
            if let Some(layer) = layer {
                object.state.layer = layer;
            }
            if let Some(compiler_cache) = compiler_cache {
                object.compiler_cache = compiler_cache;
            }
            if let Some(visibility) = visibility {
                object.state.visibility = visibility;
            }
            if let Some(blit_mode) = blit_mode {
                object.state.blit_mode = blit_mode;
            }
            if let Some(picture_rect) = update_picture_rect {
                object.state.picture_rect = picture_rect;
            }
            if let Some(position) = position {
                object.set_position(position);
            }
            if let Some(physicals) = physicals {
                object.state.info_physical = physicals.info;
                object.state.temporary_physical = physicals.temporary;
                object.state.physical_changes = physicals.changes;
            }
            if let Some(velocity) = velocity {
                object.set_velocity(velocity);
            }
            if let Some(fixed_velocity) = fixed_velocity {
                object.fixed_velocity = fixed_velocity;
                object.state.velocity = object.velocity_pixels();
            }
            // Component dir writes land on the TRUE fixed velocity — the
            // untouched component keeps its sub-pixel value, and the write
            // mobilizes like FnSetXDir/FnSetYDir (`pObj->Mobile = 1`,
            // C4Script.cpp:697-732). Dropping these here lost script
            // SetXDir(0)s whose INT mirror didn't change (|xdir| < 0.5 —
            // the GoldRush fish's 0.4 drift surviving TurnLeft, f100 wall).
            if let Some(x) = fixed_velocity_x {
                object.fixed_velocity.x = x;
                object.state.velocity = object.velocity_pixels();
                object.state.mobile = true;
            }
            if let Some(y) = fixed_velocity_y {
                object.fixed_velocity.y = y;
                object.state.velocity = object.velocity_pixels();
                object.state.mobile = true;
            }
            if let Some(rotation) = rotation {
                let previous_rect = object.current_shape_rect();
                let previous_construction = object.state.construction;
                object.state.rotation = rotation.rem_euclid(360);
                object.fixed_rotation = itofix(object.state.rotation);
                object.refresh_shape_after_state_change(
                    previous_construction,
                    previous_rect,
                    false,
                );
            }
            if let Some(rotation_velocity) = rotation_velocity {
                object.rotation_velocity = rotation_velocity;
            }
            // Apply an explicit native-helper result after all velocity
            // writes that may mobilize the object.
            if let Some(mobile) = mobile {
                object.state.mobile = mobile;
            }
            if let Some(t_attach) = t_attach {
                object.state.t_attach = t_attach;
                object.frame_t_attach = t_attach;
            }
            if let Some(contact_density) = contact_density {
                object.state.contact_density = contact_density;
            }
            if let Some(cause) = energy_loss_cause {
                // Kill-trace mark BEFORE the energy write
                // (C4Object.cpp:1351-1361) so AssignDeath credits it.
                object.last_energy_loss_cause = cause;
            }
            if let Some(energy) = energy {
                // AssignDeath below when a nonzero energy reaches 0
                // (C4Object::DoEnergy, C4Object.cpp:1363) — host DoEnergy
                // folds arrive here.
                energy_died = object.state.alive && object.state.energy != 0 && energy == 0;
                object.state.energy = energy;
            }
            if let Some(breath) = breath {
                object.state.breath = breath;
            }
            if let Some(damage) = damage {
                object.state.damage = damage.max(0);
            }
            if let Some((fire_caused_by, fire_phase)) = fire {
                // Staged incinerate outcome — draw + Incineration callback
                // already ran mid-call (fxFireStart core,
                // C4Effect.cpp:632-638); OnFire is a SetOCF-owned bit,
                // refreshed with the rest of the fold below.
                object.state.on_fire = true;
                object.state.fire_caused_by = fire_caused_by;
                object.state.fire_phase = fire_phase;
            }
            if let Some(flag) = fire_flag {
                object.state.on_fire = flag;
            }
            if let Some(magic_energy) = magic_energy {
                object.state.magic_energy = magic_energy.max(0);
            }
            if let Some(magic_capacity) = magic_capacity {
                object.state.magic_capacity = magic_capacity.max(0);
            }
            if let Some(direction) = direction {
                object.state.direction = direction;
            }
            if let Some(command_direction) = command_direction {
                object.state.command_direction = command_direction;
            }
            if let Some(action) = action {
                let previous_action = object.state.action.clone();
                let requested_name_change = action.name.is_some();
                let result = object
                    .state
                    .action
                    .apply_update_with_library(&action, &action_library);
                // C4Object::SetAction resyncs the fixed coords to the
                // integer position once past its early returns
                // (C4Object.cpp:4144).
                if action.name.is_some() && matches!(result, ActionUpdateResult::Applied) {
                    object.fixed_position =
                        FixedVec2::from_ints(object.state.position.x, object.state.position.y);
                }
                if matches!(result, ActionUpdateResult::Applied)
                    && (requested_name_change
                        || object.state.action.name != previous_action.name
                        || object.state.action.act_map_index != previous_action.act_map_index)
                    && !action.callbacks_dispatched
                {
                    object.record_action_event(previous_action, ActionTransitionKind::Forced);
                }
            } else {
                object.state.action.reconcile_with_library(&action_library);
            }
            if let Some(owner) = owner {
                object.state.owner = owner;
                // SetOwner "automatically updates controller"
                // (C4Object.cpp:5499-5500); an explicit SetController in
                // the same batch still wins below.
                object.state.controller = controller.unwrap_or(owner);
            } else if let Some(controller) = controller {
                object.state.controller = controller;
            }
            if let Some(base) = base {
                object.state.base = base;
            }
            if let Some(own_mass) = own_mass {
                object.state.own_mass = own_mass;
                object.compiled_mass = None;
            }
            if let Some(crew_member) = crew_member {
                object.state.crew_member = crew_member;
            }
            if let Some(plr_view_range) = plr_view_range {
                object.state.plr_view_range = plr_view_range;
            }
            if let Some(crew_disabled) = crew_disabled {
                object.state.crew_disabled = crew_disabled;
            }
            if let Some(rect) = update_solid_mask {
                object.state.solid_mask_override = Some(rect);
                object.solid_mask_instance_sequence = None;
                solid_mask_refresh = true;
            }
            if let Some(alive) = alive {
                object.state.alive = alive;
            }
            if let Some(entrance_status) = update_entrance_status {
                object.state.entrance_status = entrance_status;
            }
            let menu_written = update_menu.is_some();
            if let Some(menu) = update_menu {
                object.state.menu = menu;
            }
            if let Some(color) = update_color {
                object.state.color = color;
            }
            if let Some(color_modulation) = update_color_modulation {
                object.state.color_modulation = color_modulation;
            }
            if let Some(status) = status {
                object.apply_status(status);
            }
            if let Some(container_update) = container {
                if object.state.container != container_update {
                    object.state.container = container_update;
                    container_change = Some((previous_container, object.state.container));
                    // C4Object::Enter/Exit force-close the moving object's
                    // menu (CloseMenu(true), C4Object.cpp:1555/:1594) —
                    // unless this update carries its own (already correctly
                    // ordered) menu write.
                    if !menu_written {
                        object.state.menu = None;
                    }
                }
            }
            if let Some(vertices) = vertices {
                object.set_owned_shape_vertices(vertices);
            }
            if let Some(construction) = construction {
                let fixed_position = object.fixed_position;
                if construction_via_docon {
                    object.set_construction_from_docon(construction);
                } else {
                    object.set_construction(construction);
                }
                if construction_via_docon && construction_preserves_fixed_position {
                    object.fixed_position = fixed_position;
                }
            }
            if let Some(position) = resolved_docon_position {
                object.state.position = position;
            }
            if let Some(position) = resolved_docon_fixed_position {
                object.fixed_position = position;
            }
            if let Some(vertices) = live_vertices.as_ref() {
                object.set_live_shape_vertices(vertices.clone());
            }
            if let Some(vertices) = shape_vertices.as_ref() {
                object.set_shape_vertex_buffer(vertices.clone());
            }
            if let Some(overlays) = graphics_overlays {
                object.state.graphics_overlays = overlays;
            }
            if let Some(base_graphics) = update_base_graphics {
                if object.state.base_graphics != base_graphics {
                    object.state.base_graphics = base_graphics;
                    object.solid_mask_instance_sequence = None;
                    solid_mask_refresh = true;
                }
            }
            if let Some(sequence) = solid_mask_instance_sequence {
                object.solid_mask_instance_sequence = Some(sequence);
            }
            if let Some(components) = components {
                object.state.component_order = normalized_component_order(
                    &components,
                    component_order
                        .clone()
                        .unwrap_or_else(|| object.state.component_order.clone()),
                    &[],
                );
                object.state.components = components;
            } else if let Some(component_order) = component_order {
                object.state.component_order =
                    normalized_component_order(&object.state.components, component_order, &[]);
            }

            object.clamp_velocity(&self.physics);

            if !object.state.vertices.is_empty() {
                if let Some(landscape) = landscape.as_ref() {
                    let resolution =
                        landscape.resolve_collision(object.state.position, object.state.velocity);
                    if resolution.collided {
                        object.apply_collision_resolution(&resolution);
                        if let Some(material_id) = resolution.material {
                            if let Some(material) = self.materials.get_by_id(material_id) {
                                object.apply_material_interaction(material);
                            }
                        }
                    }
                }
            }

            (
                object.id,
                previous_owner,
                previous_crew,
                object.state.owner,
                object.state.crew_member,
                container_change,
            )
        };

        let current_status = self.objects[index].state.status;
        self.update_inactive_list_for_status_change(object_id, previous_status, current_status);
        if fow_range_changed || fow_crew_actualize {
            self.actualize_object_fow_view_range(object_id);
        } else if previous_owner != new_owner {
            self.actualize_object_fow_after_owner_change(object_id, new_owner);
        } else if current_status == ObjectStatus::Deleted {
            self.remove_object_from_fow_view_lists(object_id);
        }

        if solid_mask_refresh {
            // SetSolidMask and SetGraphics reflow the bake immediately
            // (C4Object.cpp:3792 and UpdateGraphics at :381-402).
            self.update_solid_mask(index);
        }
        self.apply_info_update(object_id, info_rank, info_link);
        self.update_sector_for_index(index);
        if energy_died {
            self.assign_death(index, false)?;
        }
        self.update_selection_for_state_change(
            object_id,
            previous_owner,
            if crew_status_change {
                new_crew
            } else {
                previous_crew
            },
            new_owner,
            new_crew,
        );
        if let Some((previous_container, new_container)) = container_change {
            self.apply_container_change(object_id, previous_container, new_container, false)?;
        }
        if change_def_reinsert {
            self.reinsert_change_def_contents_link(object_id)?;
        }
        // Host callbacks collapse several ordered native calls into one
        // ObjectUpdate. SetR/DoCon/Enter/StatusActivate stage an explicit
        // clear, while a later SetShape replaces it with the final rect.
        // Apply that ordering token only after every native shape refresh so
        // `Enter(); SetShape(...)` and its inverse match C++.
        if let Some(shape_override) = update_shape_override {
            let object = &mut self.objects[index];
            object.state.shape_override = shape_override;
            match shape_override {
                Some(rect) => object.shape_rect = Some(rect),
                None => {
                    object.refresh_shape_geometry();
                    // The ordering token may represent an earlier SetR,
                    // Enter, DoCon or activation. Script vertex edits after
                    // that native UpdateShape are the final C++ state and
                    // must survive this deferred refresh.
                    if let Some(vertices) = live_vertices.as_ref() {
                        object.set_live_shape_vertices(vertices.clone());
                    }
                    if let Some(vertices) = shape_vertices.as_ref() {
                        object.set_shape_vertex_buffer(vertices.clone());
                    }
                }
            }
        }
        // Host-driven changes are SetOCF events (SetAlive C4Object.h:361,
        // DoCon C4Object.cpp:1417, status C4Object.cpp:4139).
        self.refresh_object_ocf(index);
        self.trigger_action_callbacks(index, Some(previous_action_name))?;
        self.update_sector_for_index(index);
        if self.objects[index].destroyed
            || matches!(self.objects[index].state.status, ObjectStatus::Deleted)
        {
            self.detach_destroyed_objects()?;
            self.update_sector_for_index(index);
        }
        self.refresh_elimination_state();
        self.check_game_over()?;

        Ok(())
    }

    fn apply_info_update(
        &mut self,
        object_id: ObjectId,
        rank_update: Option<Option<i32>>,
        link_update: Option<Option<CrewInfoLink>>,
    ) {
        if let Some(rank) = rank_update {
            match rank {
                Some(rank) => {
                    Rc::make_mut(&mut self.crew_ranks).insert(object_id.as_u64(), rank);
                    if let Some(info) =
                        Rc::make_mut(&mut self.crew_object_infos).get_mut(&object_id)
                    {
                        info.rank = rank;
                    }
                }
                None => {
                    Rc::make_mut(&mut self.crew_ranks).remove(&object_id.as_u64());
                    Rc::make_mut(&mut self.crew_object_infos).remove(&object_id);
                }
            }
        }
        if let Some(link) = link_update {
            match link {
                Some(link) => {
                    Rc::make_mut(&mut self.crew_info_links).insert(object_id, link);
                }
                None => {
                    Rc::make_mut(&mut self.crew_info_links).remove(&object_id);
                }
            }
        }
    }

    fn trigger_action_callbacks(
        &mut self,
        index: usize,
        previous_action: Option<String>,
    ) -> Result<(), EngineError> {
        self.trigger_action_callbacks_impl(index, previous_action, false)
    }

    fn trigger_action_callbacks_impl(
        &mut self,
        index: usize,
        previous_action: Option<String>,
        allow_deleted_initial_start: bool,
    ) -> Result<(), EngineError> {
        if self.objects[index].destroyed && !allow_deleted_initial_start {
            return Ok(());
        }

        let mut needs_start = previous_action.is_none();

        // C++ has NO deferred callback queue (SetAction runs its calls
        // inline) — an unbounded drain here is always a rust-side artifact
        // (the coach Driving loop drained forever against stale state).
        let mut drained = 0u32;
        while let Some(event) = self.objects[index].pending_action_events.pop_front() {
            drained += 1;
            if drained > 32 {
                tracing::warn!(
                    object = self.objects[index].id.as_u64(),
                    "action-callback drain backstop hit; dropping queued transitions"
                );
                self.objects[index].pending_action_events.clear();
                break;
            }
            let current_action = self.objects[index].state.action.clone();
            let callback_definition = self.objects[index].definition_id.clone();
            self.invoke_action_callback(
                index,
                ActionCallbackKind::Start,
                &current_action.name,
                current_action.act_map_index,
                None,
                None,
                None,
                None,
            )?;
            if self.objects[index].destroyed
                || matches!(self.objects[index].state.status, ObjectStatus::Deleted)
                || self.objects[index].definition_id != callback_definition
            {
                self.objects[index].pending_action_events.clear();
                return Ok(());
            }

            let callback_kind = match event.kind {
                ActionTransitionKind::Natural => ActionCallbackKind::End,
                ActionTransitionKind::Forced => ActionCallbackKind::Abort,
            };
            self.invoke_action_callback(
                index,
                callback_kind,
                &event.previous_action.name,
                event.previous_action.act_map_index,
                None,
                None,
                matches!(event.kind, ActionTransitionKind::Forced)
                    .then_some(event.previous_action.phase),
                None,
            )?;
            if self.objects[index].destroyed
                || matches!(self.objects[index].state.status, ObjectStatus::Deleted)
                || self.objects[index].definition_id != callback_definition
            {
                self.objects[index].pending_action_events.clear();
                return Ok(());
            }

            needs_start = false;
        }

        if needs_start {
            let current_action = self.objects[index].state.action.clone();
            self.invoke_action_callback(
                index,
                ActionCallbackKind::Start,
                &current_action.name,
                current_action.act_map_index,
                None,
                None,
                None,
                None,
            )?;
        }

        Ok(())
    }

    fn invoke_action_callback(
        &mut self,
        index: usize,
        kind: ActionCallbackKind,
        action_name: &str,
        action_index: Option<u32>,
        callback_override: Option<ScriptCallbackTarget>,
        state_override: Option<ObjectState>,
        abort_phase: Option<i32>,
        callback_definition_override: Option<&str>,
    ) -> Result<(), EngineError> {
        let definition_id = self.objects[index].definition_id.clone();
        let callback_definition_id = callback_definition_override.unwrap_or(&definition_id);
        let object_definition = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        let action_library = self
            .shared_action_library_for(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        let callback_definition = self
            .definitions
            .get(callback_definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(callback_definition_id.to_string()))?;

        let callback = match callback_override {
            Some(callback) => Some(callback),
            None => match kind {
                ActionCallbackKind::Start => callback_definition
                    .action_library()
                    .start_callback_for_entry(action_name, action_index),
                ActionCallbackKind::End => callback_definition
                    .action_library()
                    .end_callback_for_entry(action_name, action_index),
                ActionCallbackKind::Phase => callback_definition
                    .action_library()
                    .phase_callback_for_entry(action_name, action_index),
                ActionCallbackKind::Abort => callback_definition
                    .action_library()
                    .abort_callback_for_entry(action_name, action_index),
            },
        };

        let Some(callback) = callback else {
            return Ok(());
        };
        let function = callback.function_name();

        tracing::debug!(
            definition = %callback_definition_id,
            object_definition = %definition_id,
            function,
            ?kind,
            action = action_name,
            object = self.objects[index].id.as_u64(),
            "action callback"
        );
        let object_id = self.objects[index].id;
        let state_snapshot = match state_override {
            Some(state) => state,
            None => self.objects[index].script_state_snapshot(),
        };
        let definitions_ref = &self.definitions;
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context_for_object(index);
        let callback = callback_definition.call_action_callback(
            object_definition,
            &callback,
            kind,
            &state_snapshot,
            object_id,
            action_name,
            abort_phase,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        );
        let callback = callback.map_err(|error| {
            self.apply_script_error_recovery(
                error,
                index,
                &action_library,
                object_id,
                &definition_id,
                true,
            )
        });
        // StartCall/EndCall/PhaseCall/AbortCall are engine-initiated game
        // calls: a script error logs and the action proceeds (C++ fail-safe
        // exec, C4AulExec.cpp:1318-1342).
        let Some((outcome, audio_state, new_rng)) = tolerate_script_error(callback)? else {
            return Ok(());
        };
        self.rng = new_rng;
        self.audio_registry = audio_state;

        self.apply_action_callback_outcome(
            index,
            outcome,
            &action_library,
            object_id,
            &definition_id,
        )
    }

    /// Apply the pre-error mutations a failed outer call carried before
    /// handing the error on (C4AulExec.cpp:1318-1342: the error aborts the
    /// call, but C++ already mutated the live objects — nothing rolls
    /// back). Errors without a payload pass through untouched.
    fn apply_script_error_recovery(
        &mut self,
        error: EngineError,
        index: usize,
        action_library: &ActionLibrary,
        object_id: ObjectId,
        definition_id: &str,
        clamp_velocity: bool,
    ) -> EngineError {
        let (definition, function, source, recovery) = match error {
            EngineError::Script {
                definition,
                function,
                source,
                recovery: Some(recovery),
            } => (definition, function, source, recovery),
            other => return other,
        };
        let ScriptCallRecovery {
            outcome,
            audio,
            rng,
        } = *recovery;
        self.rng = rng;
        self.audio_registry = audio;
        if let Err(apply_error) = self.apply_callback_outcome(
            index,
            outcome,
            action_library,
            object_id,
            definition_id,
            clamp_velocity,
        ) {
            return apply_error;
        }
        EngineError::Script {
            definition,
            function,
            source,
            recovery: None,
        }
    }

    fn apply_action_callback_outcome(
        &mut self,
        index: usize,
        outcome: compat::EffectContextOutcome,
        action_library: &ActionLibrary,
        object_id: ObjectId,
        definition_id: &str,
    ) -> Result<(), EngineError> {
        self.apply_callback_outcome(
            index,
            outcome,
            action_library,
            object_id,
            definition_id,
            true,
        )
    }

    fn apply_callback_outcome(
        &mut self,
        index: usize,
        outcome: compat::EffectContextOutcome,
        action_library: &ActionLibrary,
        object_id: ObjectId,
        definition_id: &str,
        clamp_velocity: bool,
    ) -> Result<(), EngineError> {
        let solid_mask_operations = outcome.solid_mask_operations.clone();
        let host_raster_preview = outcome.host_raster_preview.clone();
        // The outcome's outer-object, spawn, and foreign-object channels do
        // not preserve the interleaving of synchronous UpdateSolidMask
        // calls. Apply every non-mask state change first while suppressing
        // their channel-local mask folds, then replay the captured C++ call
        // order against the now-materialized objects.
        let was_deferred = self.defer_solid_mask_updates;
        let mut outermost = self.stage_host_solid_mask_operations(
            solid_mask_operations,
            host_raster_preview,
        );
        let result = self.apply_callback_outcome_inner(
            index,
            outcome,
            action_library,
            object_id,
            definition_id,
            clamp_velocity,
        );
        outermost |= !was_deferred && self.defer_solid_mask_updates;
        self.finish_host_solid_mask_operations(outermost, result)
    }

    fn apply_callback_outcome_inner(
        &mut self,
        index: usize,
        outcome: compat::EffectContextOutcome,
        action_library: &ActionLibrary,
        object_id: ObjectId,
        definition_id: &str,
        clamp_velocity: bool,
    ) -> Result<(), EngineError> {
        let compat::EffectContextOutcome {
            object: object_effects,
            global: global_effects,
            object_update,
            mut object_commands,
            command_operations,
            command_events,
            destroy_object,
            other_objects,
            environment,
            physics,
            spawns,
            landscape: host_landscape_ops,
            solid_mask_operations: _,
            host_raster_preview: _,
            particles,
            transfer_zones,
            messages,
            player_commands,
            object_order_commands,
            next_mission_commands,
            menu_requests,
            audio: outcome_audio,
            trigger_game_over,
            script_go,
            script_counter,
            next_object_id,
            context_locals,
        } = outcome;
        let refresh_ocf = object_update
            .as_ref()
            .is_some_and(ObjectUpdate::refreshes_ocf_like_cpp);
        let ocf_override = object_update
            .as_ref()
            .and_then(|update| update.ocf_override);
        let info_rank_update = object_update.as_ref().and_then(|update| update.info_rank);
        let info_link_update = object_update.as_ref().and_then(|update| update.info_link);
        let crew_status_change = object_update
            .as_ref()
            .is_some_and(|update| update.crew_status_change);
        let final_shape_override = object_update
            .as_ref()
            .and_then(|update| update.shape_override);
        let final_live_vertices = object_update
            .as_ref()
            .and_then(|update| update.live_vertices.clone());
        let final_shape_vertices = object_update
            .as_ref()
            .and_then(|update| update.shape_vertices.clone());

        if !host_landscape_ops.is_empty() {
            self.apply_landscape_operations(host_landscape_ops);
        }

        // FnExecuteCommand executes one command synchronously
        // (C4Script.cpp:922-929). Its object/player/spawn events therefore
        // become visible before this host callback returns, not on the next
        // simulation tick.
        for event in &command_events {
            self.apply_command_event(event.clone())?;
        }
        // Other callback consumers still use the historical zero-delay
        // event queue. This path applied the same events synchronously, so
        // remove only those pure carrier commands before they reach the
        // object's next-tick queue.
        object_commands.retain(|command| {
            !(command.delay == 0
                && command.update.is_empty()
                && command.effects.is_empty()
                && !command.events.is_empty()
                && command
                    .events
                    .iter()
                    .all(|event| command_events.contains(event))
                && !command.destroy
                && command.spawns.is_empty()
                && command.landscape.is_empty()
                && command.particles.is_empty())
        });

        if !player_commands.is_empty() {
            self.apply_player_commands(player_commands)?;
        }
        self.pending_object_order_commands.extend(object_order_commands);
        self.apply_next_mission_commands(next_mission_commands);

        if let Some(update) = environment {
            self.apply_environment_delta(&update);
        }
        if let Some(delta) = physics {
            self.apply_physics_delta(delta);
        }

        self.sync_next_object_id(next_object_id);
        if !spawns.is_empty() {
            self.process_spawn_queue(spawns)?;
        }
        self.apply_particle_commands(particles);
        if !transfer_zones.is_empty() {
            self.apply_transfer_zone_commands(transfer_zones)?;
        }

        if !outcome_audio.events.is_empty() {
            self.pending_audio.extend(outcome_audio.events);
        }
        if !messages.is_empty() {
            for command in messages {
                self.messages.apply_command(command);
            }
        }
        for request in menu_requests {
            let MenuRequest {
                crew_id,
                owner,
                kind,
            } = request;
            let Some(crew_index) = self.find_object_index(crew_id) else {
                continue;
            };
            match kind {
                MenuRequestKind::Activate => {
                    self.apply_container_menu_request(MenuRequest {
                        crew_id,
                        owner,
                        kind: MenuRequestKind::Activate,
                    })?;
                }
                MenuRequestKind::ActivateTarget { container } => {
                    self.apply_container_menu_request(MenuRequest {
                        crew_id,
                        owner,
                        kind: MenuRequestKind::ActivateTarget { container },
                    })?;
                }
                MenuRequestKind::Construction => {
                    self.open_construction_menu(crew_index)?;
                }
                MenuRequestKind::Buy { base } => {
                    if let Some(base_index) = self.find_object_index(base) {
                        self.open_base_buy_menu(crew_index, base_index)?;
                    }
                }
                MenuRequestKind::Sell { base } => {
                    if let Some(base_index) = self.find_object_index(base) {
                        self.open_base_sell_menu(crew_index, base_index)?;
                    }
                }
                MenuRequestKind::Get { container } => {
                    self.apply_container_menu_request(MenuRequest {
                        crew_id,
                        owner,
                        kind: MenuRequestKind::Get { container },
                    })?;
                }
                MenuRequestKind::Contents { container } => {
                    self.apply_container_menu_request(MenuRequest {
                        crew_id,
                        owner,
                        kind: MenuRequestKind::Contents { container },
                    })?;
                }
                MenuRequestKind::Info { target } => {
                    if let Some(target_index) = self.find_object_index(target) {
                        self.open_object_info_menu(crew_index, target_index)?;
                    }
                }
                MenuRequestKind::Context {
                    target,
                    position,
                } => {
                    if let Some(target_index) = self.find_object_index(target) {
                        self.open_context_menu(crew_index, target_index, false, position)?;
                    }
                }
                kind => self.pending_menu_requests.push(MenuRequest {
                    crew_id,
                    owner,
                    kind,
                }),
            }
        }

        if let Some(go) = script_go {
            self.scenario_script_go = go;
        }
        if let Some(counter) = script_counter {
            self.scenario_script_counter = counter;
        }
        if trigger_game_over {
            self.request_game_over()?;
        }

        let mut effect_events = Vec::new();
        let mut energy_died = false;
        let mut container_changes = Vec::new();

        let mut command_operations = command_operations;

        let (previous_owner, previous_crew_member, previous_base_graphics, previous_status) = {
            let object = &self.objects[index];
            (
                object.state.owner,
                object.state.crew_member,
                object.state.base_graphics.clone(),
                object.state.status,
            )
        };
        let solid_mask_changed = destroy_object
            || object_update.as_ref().is_some_and(|update| {
                update.change_def.is_some()
                    || update.solid_mask_override.is_some()
                    || update.position.is_some()
                    || update.rotation.is_some()
                    || update.construction.is_some()
            });
        let mut change_def_reinsert = object_update
            .as_ref()
            .is_some_and(|update| update.change_def_reinsert);

        // FnChangeDef swaps the definition INLINE at the call site
        // (C4Object::ChangeDef, C4Object.cpp:1205-1231, incl. the
        // SetAction(ActIdle) pre-reset :1214) — the staged writes that
        // follow it (the horse Death's SetAction("Dead")) must resolve
        // against the NEW def's ActMap, so the swap applies BEFORE the
        // delta and the action library is re-resolved (the f147 wall:
        // cpp "Dead" vs rust "Idle" fallback against the old library).
        let changed_library = object_update
            .as_ref()
            .and_then(|update| update.change_def.clone())
            .and_then(|new_def| {
                self.apply_change_object_def(index, &new_def);
                self.shared_action_library_for(&self.objects[index].definition_id)
            });
        let action_library = changed_library.as_deref().unwrap_or(action_library);

        {
            let object = &mut self.objects[index];

            // Effect-callback VM finals (C4Effect.cpp:129: the callback ran
            // in this object's own context) apply first; host-command
            // updates below may override.
            if let Some(locals) = context_locals {
                object.state.local_vars = locals;
            }

            if let Some(update) = object_update {
                let callbacks_dispatched = update
                    .action
                    .as_ref()
                    .map(|action| action.callbacks_dispatched)
                    .unwrap_or(false);
                let delta: ObjectDelta = update.into();
                let outcome = object.apply_delta(&delta, action_library);
                energy_died = outcome.energy_died;
                if let Some(change) = outcome.action_change {
                    if !callbacks_dispatched {
                        object.record_action_event(change.previous, ActionTransitionKind::Forced);
                    }
                }
                if let Some(change) = outcome.container_change {
                    container_changes.push(change);
                }
            }

            if !command_operations.is_empty() {
                let operations: Vec<_> = std::mem::take(&mut command_operations);
                object.apply_command_operations(operations);
            }

            if !object_commands.is_empty() {
                object.enqueue_commands(object_commands);
            }

            if !object_effects.is_empty() {
                let mut applied = object.apply_effect_commands(&object_effects);
                effect_events.append(&mut applied);
            }

            // Exact AssignRemoval callbacks have already stopped effects
            // synchronously and emit no-callback removals. Fold those before
            // the status write so mark_destroyed cannot stop them twice.
            if destroy_object {
                object.retired_info_physical = object.state.info_physical;
                object.state.info_physical = None;
                effect_events.extend(object.mark_destroyed());
            }

            if clamp_velocity
                && !matches!(
                    action_library.procedure_for_entry(
                        &object.state.action.name,
                        object.state.action.act_map_index,
                    ),
                    ActionProcedure::Flight
                )
            {
                object.clamp_velocity(&self.physics);
            }
        }
        self.apply_info_update(object_id, info_rank_update, info_link_update);
        self.update_sector_for_index(index);

        if energy_died {
            // C4Object::DoEnergy kills synchronously when a nonzero
            // energy reaches 0 (C4Object.cpp:1363).
            self.assign_death(index, false)?;
        }

        let (new_owner, new_crew_member) = {
            let object = &self.objects[index];
            (object.state.owner, object.state.crew_member)
        };

        if previous_owner != new_owner || previous_crew_member != new_crew_member {
            self.update_selection_for_state_change(
                object_id,
                previous_owner,
                if crew_status_change {
                    new_crew_member
                } else {
                    previous_crew_member
                },
                new_owner,
                new_crew_member,
            );
        }

        if !global_effects.is_empty() {
            self.apply_global_effect_commands(&global_effects);
        }

        let mut effect_solid_mask_changed = false;
        if !effect_events.is_empty() {
            let previous_container = self.objects[index].state.container;
            let definition = self
                .definitions
                .get(definition_id)
                .ok_or_else(|| EngineError::UnknownDefinition(definition_id.to_string()))?;
            let definitions_ref = &self.definitions;
            let global_view = self.global_effects.clone();
            let rng_state = self.rng.clone();
            let world = self.host_world_context_for_object(index);
            let object = &mut self.objects[index];
            let (
                global_cmds,
                emitted_particles,
                physics_delta,
                audio_events,
                event_messages,
                player_commands,
                object_order_commands,
                next_mission_commands,
                landscape_ops,
                effect_transfer_zones,
                effect_spawns,
                effect_other_objects,
                nested_effect_solid_mask_operations,
                nested_effect_host_raster_preview,
                nested_effect_solid_mask_changed,
                _nested_effect_action_callbacks_dispatched,
                nested_effect_change_def_reinsert,
                effect_next_object_id,
                triggered_game_over,
                effect_script_go,
                effect_script_counter,
                audio_state,
                new_rng,
            ) = Self::run_effect_events_for_object(
                definition,
                definitions_ref,
                self.game_over_triggered,
                rng_state,
                object_id,
                object,
                effect_events,
                global_view,
                &mut self.environment,
                self.physics,
                self.frame,
                world.clone(),
                self.audio_registry.clone(),
            )?;
            self.stage_host_solid_mask_operations(
                nested_effect_solid_mask_operations,
                nested_effect_host_raster_preview,
            );
            self.rng = new_rng;
            self.audio_registry = audio_state;
            effect_solid_mask_changed |= nested_effect_solid_mask_changed;
            if let Some(marker) = nested_effect_change_def_reinsert {
                change_def_reinsert = marker;
            }
            self.sync_next_object_id(effect_next_object_id);
            if !effect_spawns.is_empty() {
                self.process_spawn_queue(effect_spawns)?;
            }
            if !effect_transfer_zones.is_empty() {
                self.apply_transfer_zone_commands(effect_transfer_zones)?;
            }
            if !effect_other_objects.is_empty() {
                self.apply_nested_object_outcomes(effect_other_objects)?;
            }
            if !landscape_ops.is_empty() {
                self.apply_landscape_operations(landscape_ops);
            }
            if !player_commands.is_empty() {
                self.apply_player_commands(player_commands)?;
            }
            self.pending_object_order_commands.extend(object_order_commands);
            self.apply_next_mission_commands(next_mission_commands);
            if !audio_events.is_empty() {
                self.pending_audio.extend(audio_events);
            }
            if !event_messages.is_empty() {
                for command in event_messages {
                    self.messages.apply_command(command);
                }
            }
            if let Some(go) = effect_script_go {
                self.scenario_script_go = go;
            }
            if let Some(counter) = effect_script_counter {
                self.scenario_script_counter = counter;
            }
            if triggered_game_over {
                self.request_game_over()?;
            }
            if !physics_delta.is_empty() {
                self.apply_physics_delta(physics_delta);
            }
            if !global_cmds.is_empty() {
                self.apply_global_effect_commands(&global_cmds);
            }
            self.apply_particle_commands(emitted_particles);
            let new_container = self.objects[index].state.container;
            if previous_container != new_container {
                container_changes.push((previous_container, new_container));
            }
        }
        self.update_sector_for_index(index);

        for (previous, new) in container_changes {
            self.apply_container_change(object_id, previous, new, false)?;
        }
        if change_def_reinsert {
            self.reinsert_change_def_contents_link(object_id)?;
        }

        if solid_mask_changed
            || effect_solid_mask_changed
            || self.objects[index].state.base_graphics != previous_base_graphics
        {
            // SetSolidMask and SetGraphics both remove, recreate and re-put
            // the active solid mask immediately (C4Object.cpp:3809-3818,
            // :381-402).
            self.update_solid_mask(index);
        }

        self.apply_nested_object_outcomes(other_objects)?;

        // Only the matching C++ host operations refresh OCF. In particular,
        // a no-op Contact callback must preserve Execute's pre-movement
        // HitSpeed cache through the later Splash gate
        // (C4Movement.cpp:166-182,449-456).
        if refresh_ocf || energy_died {
            self.refresh_object_ocf(index);
        }
        if let Some(ocf) = ocf_override {
            self.objects[index].state.ocf = ocf;
        }

        self.update_inactive_list_for_status_change(
            object_id,
            previous_status,
            self.objects[index].state.status,
        );
        if let Some(shape_override) = final_shape_override {
            let object = &mut self.objects[index];
            object.state.shape_override = shape_override;
            match shape_override {
                Some(rect) => object.shape_rect = Some(rect),
                None => {
                    object.refresh_shape_geometry();
                    if let Some(vertices) = final_live_vertices {
                        object.set_live_shape_vertices(vertices);
                    }
                    if let Some(vertices) = final_shape_vertices {
                        object.set_shape_vertex_buffer(vertices);
                    }
                }
            }
            self.update_sector_for_index(index);
        }

        Ok(())
    }

    /// Applies mutations nested script calls (Find_Func/GameCall reentrancy)
    /// made to objects other than the outer call's `this`, in first-call
    /// order. C++ mutates live state mid-call; the copy-in/copy-out model
    /// commits them here, after the outer object's own update.
    fn apply_nested_object_outcomes(
        &mut self,
        outcomes: Vec<compat::NestedObjectOutcome>,
    ) -> Result<(), EngineError> {
        let _ = self.apply_nested_object_outcomes_retaining_missing(outcomes)?;
        Ok(())
    }

    /// Applies every outcome whose target is live and returns only outcomes
    /// for not-yet-materialized targets. Spawn queues use the returned tail
    /// to bridge the gap between C++'s synchronous NewObject insertion and
    /// Rust's deferred SpawnConfig materialization.
    fn apply_nested_object_outcomes_retaining_missing(
        &mut self,
        outcomes: Vec<compat::NestedObjectOutcome>,
    ) -> Result<Vec<compat::NestedObjectOutcome>, EngineError> {
        let was_deferred = self.defer_solid_mask_updates;
        let result = self.apply_nested_object_outcomes_retaining_missing_inner(outcomes);
        let outermost = !was_deferred && self.defer_solid_mask_updates;
        self.finish_host_solid_mask_operations(outermost, result)
    }

    fn apply_nested_object_outcomes_retaining_missing_inner(
        &mut self,
        outcomes: Vec<compat::NestedObjectOutcome>,
    ) -> Result<Vec<compat::NestedObjectOutcome>, EngineError> {
        let mut retained = Vec::new();
        for outcome in outcomes {
            let requested_death = outcome.assign_death;
            let Some(index) = self.find_object_index(outcome.object_id) else {
                retained.push(outcome);
                continue;
            };
            let object_id = outcome.object_id;
            let definition_id = self.objects[index].definition_id.clone();
            let action_library = self
                .shared_action_library_for(&definition_id)
                .unwrap_or_default();

            let mut effect_events = Vec::new();
            let mut container_changes = Vec::new();
            let (previous_owner, previous_crew_member, previous_base_graphics, previous_status) = {
                let object = &self.objects[index];
                (
                    object.state.owner,
                    object.state.crew_member,
                    object.state.base_graphics.clone(),
                    object.state.status,
                )
            };
            let solid_mask_changed = outcome
                .update
                .as_ref()
                .is_some_and(|update| {
                    update.change_def.is_some()
                        || update.solid_mask_override.is_some()
                        || update.position.is_some()
                        || update.rotation.is_some()
                        || update.construction.is_some()
                });
            let mut change_def_reinsert = outcome
                .update
                .as_ref()
                .is_some_and(|update| update.change_def_reinsert);
            let refresh_ocf = outcome
                .update
                .as_ref()
                .is_some_and(ObjectUpdate::refreshes_ocf_like_cpp);
            let ocf_override = outcome
                .update
                .as_ref()
                .and_then(|update| update.ocf_override);
            let info_rank_update = outcome
                .update
                .as_ref()
                .and_then(|update| update.info_rank);
            let info_link_update = outcome
                .update
                .as_ref()
                .and_then(|update| update.info_link);
            let crew_status_change = outcome
                .update
                .as_ref()
                .is_some_and(|update| update.crew_status_change);
            let final_shape_override = outcome
                .update
                .as_ref()
                .and_then(|update| update.shape_override);
            let final_live_vertices = outcome
                .update
                .as_ref()
                .and_then(|update| update.live_vertices.clone());
            let final_shape_vertices = outcome
                .update
                .as_ref()
                .and_then(|update| update.shape_vertices.clone());
            let mut energy_died = false;
            let mut delayed_docon_state = None;
            // FnChangeDef swaps INLINE (C4Object.cpp:1205-1231): apply the
            // def change BEFORE the staged delta so a following
            // SetAction resolves against the NEW ActMap.
            let action_library = outcome
                .update
                .as_ref()
                .and_then(|update| update.change_def.clone())
                .and_then(|new_def| {
                    self.apply_change_object_def(index, &new_def);
                    self.shared_action_library_for(&self.objects[index].definition_id)
                })
                .unwrap_or(action_library);
            {
                let object = &mut self.objects[index];
                if let Some(mut update) = outcome.update {
                    // A nested Enter/Exit followed by DoCon must copy the
                    // container motion first and only then bottom-adjust the
                    // new construction shape. The copy-in/out scope carries
                    // both writes in one update, so delay just this ordered
                    // DoCon fold until after apply_container_change below.
                    if update.construction_via_docon && update.container.is_some() {
                        delayed_docon_state = update.construction.take().map(|construction| {
                            (
                                construction,
                                update.resolved_docon_position.take(),
                                update.resolved_docon_fixed_position.take(),
                            )
                        });
                        update.construction_via_docon = false;
                        update.construction_preserves_fixed_position = false;
                    }
                    let callbacks_dispatched = update
                        .action
                        .as_ref()
                        .map(|action| action.callbacks_dispatched)
                        .unwrap_or(false);
                    let delta: ObjectDelta = update.into();
                    let apply_outcome = object.apply_delta(&delta, &action_library);
                    energy_died = apply_outcome.energy_died;
                    if let Some(change) = apply_outcome.action_change {
                        if !callbacks_dispatched {
                            object
                                .record_action_event(change.previous, ActionTransitionKind::Forced);
                        }
                    }
                    if let Some(change) = apply_outcome.container_change {
                        container_changes.push(change);
                    }
                }
                if !outcome.command_operations.is_empty() {
                    object.apply_command_operations(outcome.command_operations);
                }
                if !outcome.commands.is_empty() {
                    object.enqueue_commands(outcome.commands);
                }
                if !outcome.effects.is_empty() {
                    let mut applied = object.apply_effect_commands(&outcome.effects);
                    effect_events.append(&mut applied);
                }
                // Effect commands happened synchronously before the
                // AssignRemoval status write. In particular, its exact host
                // path already ran Fx*Stop and carries no-callback removals;
                // fold those before mark_destroyed so it cannot emit a
                // second deferred Stop for the same effects.
                if outcome.destroy {
                    object.retired_info_physical = object.state.info_physical;
                    object.state.info_physical = None;
                    effect_events.extend(object.mark_destroyed());
                }
            }
            self.apply_info_update(object_id, info_rank_update, info_link_update);
            self.update_sector_for_index(index);
            if energy_died {
                // C4Object::DoEnergy kills synchronously when a nonzero
                // energy reaches 0 (C4Object.cpp:1363) — foreign writes
                // (Punch, DoEnergy on a named target) included.
                self.assign_death(index, false)?;
            }

            let (new_owner, new_crew_member) = {
                let object = &self.objects[index];
                (object.state.owner, object.state.crew_member)
            };
            if previous_owner != new_owner || previous_crew_member != new_crew_member {
                self.update_selection_for_state_change(
                    object_id,
                    previous_owner,
                    if crew_status_change {
                        new_crew_member
                    } else {
                        previous_crew_member
                    },
                    new_owner,
                    new_crew_member,
                );
            }

            let mut effect_solid_mask_changed = false;
            if !effect_events.is_empty() {
                let previous_container = self.objects[index].state.container;
                let definition = self
                    .definitions
                    .get(&definition_id)
                    .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
                let definitions_ref = &self.definitions;
                let global_view = self.global_effects.clone();
                let rng_state = self.rng.clone();
                let world = self.host_world_context_for_object(index);
                let object = &mut self.objects[index];
                let (
                    global_cmds,
                    emitted_particles,
                    physics_delta,
                    audio_events,
                    event_messages,
                    player_commands,
                    object_order_commands,
                    next_mission_commands,
                    landscape_ops,
                    effect_transfer_zones,
                    effect_spawns,
                    effect_other_objects,
                    nested_effect_solid_mask_operations,
                    nested_effect_host_raster_preview,
                    nested_effect_solid_mask_changed,
                    _nested_effect_action_callbacks_dispatched,
                    nested_effect_change_def_reinsert,
                    effect_next_object_id,
                    triggered_game_over,
                    effect_script_go,
                    effect_script_counter,
                    audio_state,
                    new_rng,
                ) = Self::run_effect_events_for_object(
                    definition,
                    definitions_ref,
                    self.game_over_triggered,
                    rng_state,
                    object_id,
                    object,
                    effect_events,
                    global_view,
                    &mut self.environment,
                    self.physics,
                    self.frame,
                    world.clone(),
                    self.audio_registry.clone(),
                )?;
                self.stage_host_solid_mask_operations(
                    nested_effect_solid_mask_operations,
                    nested_effect_host_raster_preview,
                );
                self.rng = new_rng;
                self.audio_registry = audio_state;
                effect_solid_mask_changed |= nested_effect_solid_mask_changed;
                if let Some(marker) = nested_effect_change_def_reinsert {
                    change_def_reinsert = marker;
                }
                self.sync_next_object_id(effect_next_object_id);
                if !effect_spawns.is_empty() {
                    self.process_spawn_queue(effect_spawns)?;
                }
                if !effect_transfer_zones.is_empty() {
                    self.apply_transfer_zone_commands(effect_transfer_zones)?;
                }
                if !effect_other_objects.is_empty() {
                    retained.extend(
                        self.apply_nested_object_outcomes_retaining_missing(effect_other_objects)?,
                    );
                }
                if !landscape_ops.is_empty() {
                    self.apply_landscape_operations(landscape_ops);
                }
                if !player_commands.is_empty() {
                    self.apply_player_commands(player_commands)?;
                }
                self.pending_object_order_commands.extend(object_order_commands);
                self.apply_next_mission_commands(next_mission_commands);
                if !audio_events.is_empty() {
                    self.pending_audio.extend(audio_events);
                }
                if !event_messages.is_empty() {
                    for command in event_messages {
                        self.messages.apply_command(command);
                    }
                }
                if let Some(go) = effect_script_go {
                    self.scenario_script_go = go;
                }
                if let Some(counter) = effect_script_counter {
                    self.scenario_script_counter = counter;
                }
                if triggered_game_over {
                    self.request_game_over()?;
                }
                if !physics_delta.is_empty() {
                    self.apply_physics_delta(physics_delta);
                }
                if !global_cmds.is_empty() {
                    self.apply_global_effect_commands(&global_cmds);
                }
                self.apply_particle_commands(emitted_particles);
                let new_container = self.objects[index].state.container;
                if previous_container != new_container {
                    container_changes.push((previous_container, new_container));
                }
            }
            self.update_sector_for_index(index);

            for (previous, new) in container_changes {
                self.apply_container_change(object_id, previous, new, false)?;
            }
            if change_def_reinsert {
                self.reinsert_change_def_contents_link(object_id)?;
            }
            if let Some((construction, resolved_position, resolved_fixed_position)) =
                delayed_docon_state
            {
                if let Some(position) = resolved_position {
                    self.objects[index].compiled_mass = None;
                    self.objects[index].state.construction = construction.max(0);
                    self.objects[index].refresh_shape_geometry();
                    self.objects[index].state.position = position;
                    if let Some(fixed_position) = resolved_fixed_position {
                        self.objects[index].fixed_position = fixed_position;
                    }
                } else {
                    let stale_fixed = self.objects[index].fixed_position;
                    self.objects[index].set_construction_from_docon(construction);
                    self.objects[index].fixed_position = stale_fixed;
                }
                self.refresh_object_ocf(index);
                self.update_sector_for_index(index);
            }
            if solid_mask_changed
                || effect_solid_mask_changed
                || self.objects[index].state.base_graphics != previous_base_graphics
            {
                self.update_solid_mask(index);
            }
            if let Some(forced) = requested_death {
                if let Some(death_index) = self.find_object_index(object_id) {
                    self.assign_death(death_index, forced)?;
                }
            }
            if refresh_ocf || energy_died {
                if let Some(refresh_index) = self.find_object_index(object_id) {
                    self.refresh_object_ocf(refresh_index);
                }
            }
            if let Some(ocf) = ocf_override {
                if let Some(override_index) = self.find_object_index(object_id) {
                    self.objects[override_index].state.ocf = ocf;
                }
            }
            if let Some(status_index) = self.find_object_index(object_id) {
                let current_status = self.objects[status_index].state.status;
                self.update_inactive_list_for_status_change(
                    object_id,
                    previous_status,
                    current_status,
                );
                if let Some(shape_override) = final_shape_override {
                    let object = &mut self.objects[status_index];
                    object.state.shape_override = shape_override;
                    match shape_override {
                        Some(rect) => object.shape_rect = Some(rect),
                        None => {
                            object.refresh_shape_geometry();
                            if let Some(vertices) = final_live_vertices {
                                object.set_live_shape_vertices(vertices);
                            }
                            if let Some(vertices) = final_shape_vertices {
                                object.set_shape_vertex_buffer(vertices);
                            }
                        }
                    }
                    self.update_sector_for_index(status_index);
                }
            }
        }
        Ok(retained)
    }

    pub fn queue_object_command(
        &mut self,
        id: ObjectId,
        command: QueuedCommand,
    ) -> Result<(), EngineError> {
        self.queue_object_commands(id, std::iter::once(command))
    }

    pub fn queue_object_commands<I>(&mut self, id: ObjectId, commands: I) -> Result<(), EngineError>
    where
        I: IntoIterator<Item = QueuedCommand>,
    {
        let object = self
            .objects
            .iter_mut()
            .find(|object| object.id == id)
            .ok_or(EngineError::UnknownObject(id))?;
        object.enqueue_commands(commands);
        Ok(())
    }

    pub fn snapshot(&self) -> SimulationSnapshot {
        let mut objects = Vec::with_capacity(self.objects.len());
        for object in &self.objects {
            let library = self
                .definitions
                .get(&object.definition_id)
                .map(|definition| definition.action_library());
            objects.push(object.snapshot(library));
        }
        objects.sort_by_key(|object| object.id);
        let mut particles: Vec<_> = self
            .particles
            .iter()
            .map(ActiveParticle::snapshot)
            .collect();
        particles.extend(self.pxs_system.iter_slots().map(|(chunk, slot, pixel)| {
            pxs_snapshot(
                pixel,
                &self.materials,
                Some((chunk * pxs::PXS_CHUNK_SIZE + slot) as u32),
            )
        }));
        particles.extend(
            self.particle_system
                .particles()
                .iter()
                .map(system_particle_snapshot),
        );
        let crew_selection = self.crew_selection_states();
        let crew_roles = self.crew_roles.clone();
        let mut known_crew_owners: Vec<_> = self.known_crew_owners.iter().cloned().collect();
        known_crew_owners.sort_unstable();
        let mut eliminated_crew_owners: Vec<_> =
            self.eliminated_crew_owners.iter().cloned().collect();
        eliminated_crew_owners.sort_unstable();
        let ambient_temperature = self.environment.ambient_temperature(self.frame);
        let sky_color = self.environment.resolved_sky_color(ambient_temperature);
        let has_fog_player = self.players.values().any(Player::fog_of_war);
        let environment = EnvironmentFrame {
            settings: self.environment,
            wind_force: self.environment.wind_force(self.frame),
            ambient_temperature,
            precipitation: self.environment.precipitation(),
            sky_color: Some(sky_color),
            gamma: self.gamma,
            fow_color: has_fog_player
                .then(|| self.scenario_values.fow_color())
                .unwrap_or(0),
            fow_resolution: has_fog_player
                .then(|| self.scenario_values.fow_resolution())
                .unwrap_or(DEFAULT_FOW_RESOLUTION),
        };
        let sky_snapshot = self.sky.as_ref().map(SkyState::snapshot);
        let weather_events = self.weather_events.clone();
        let mut player_order = self.player_ids_in_order();
        let player_states: Vec<_> = player_order
            .iter()
            .filter_map(|number| self.players.get(number))
            .map(|player| {
                let mut state = player.to_state();
                let owner = player.id();
                state.crew.retain(|id| {
                    self.find_object_index(*id).is_some_and(|index| {
                        let object = &self.objects[index];
                        !object.destroyed && object.state.status != ObjectStatus::Deleted
                    })
                });
                state.cursor = self
                    .crew_selection
                    .get(&owner)
                    .and_then(|selection| selection.cursor())
                    .or(state.cursor);
                if self.eliminated_crew_owners.contains(&owner) {
                    state.status_value = Some(state.exact_status_value());
                    state.eliminated_value = 1;
                    state.status = PlayerStatus::Eliminated;
                } else if state.status == PlayerStatus::Eliminated {
                    state.status = PlayerStatus::Active;
                    state.status_value = None;
                    state.eliminated_value = 0;
                }
                if state.viewports.is_empty() {
                    let focus_id = state
                        .view_cursor
                        .or(state.cursor)
                        .or_else(|| state.crew.first().copied())
                        .or_else(|| {
                            self.objects
                                .iter()
                                .find(|object| object.state.owner == owner)
                                .map(|object| object.id)
                        })
                        .or_else(|| self.objects.first().map(|object| object.id));
                    let mut center = Vector2::ZERO;
                    if let Some(focus) =
                        focus_id.and_then(|id| self.objects.iter().find(|object| object.id == id))
                    {
                        center = focus.state.position;
                        state
                            .viewports
                            .push(PlayerViewport::new(center).with_focus(Some(focus.id)));
                    } else {
                        state.viewports.push(PlayerViewport::new(center));
                    }
                }
                state
            })
            .collect();
        let local_players = player_order
            .iter()
            .copied()
            .filter(|number| {
                self.local_players
                    .as_ref()
                    .is_none_or(|players| players.contains(number))
            })
            .collect();
        let synthetic_owner_start = player_order.len();
        player_order.extend(
            self.known_crew_owners
                .iter()
                .copied()
                .chain(self.eliminated_crew_owners.iter().copied())
                .filter(|owner| !self.players.contains_key(owner)),
        );
        player_order[synthetic_owner_start..].sort_unstable();
        player_order.dedup();
        let mut hud_players = Vec::with_capacity(player_order.len());
        for owner in player_order {
            let mut crew = self.crew_members(owner);
            // The COMPARATOR surface: the bridge std::sort's its HUD crew
            // ascending before export (RustEngineBridge.cpp:1381), so the
            // rust snapshot mirrors that normalization. Engine-internal
            // crew order stays newest-first.
            crew.sort_unstable_by_key(|id| id.as_u64());
            let focus = self
                .crew_selection
                .get(&owner)
                .and_then(|selection| selection.cursor());
            let eliminated = self.eliminated_crew_owners.contains(&owner);
            let (wealth, score) = self
                .players
                .get(&owner)
                .map(|player| (player.wealth(), player.points()))
                .unwrap_or((0, 0));
            hud_players.push(HudPlayerSnapshot {
                owner,
                crew,
                focus,
                eliminated,
                wealth,
                score,
            });
        }
        let fow_players = self
            .players
            .iter()
            .filter(|(_, player)| player.fog_of_war())
            .map(|(&id, player)| {
                (
                    id,
                    FogOfWarPlayerFrame {
                        view_objects: player.fow_view_objects().to_vec(),
                        view_target: player.raw_view_target(),
                    },
                )
            })
            .collect();
        let definition_categories = self
            .definitions
            .iter()
            .map(|(id, definition)| (id.clone(), definition.category()))
            .collect();
        let definition_closed_containers = if has_fog_player {
            self.definitions
                .iter()
                .filter_map(|(id, definition)| {
                    let closed = definition.closed_container();
                    (closed != 0).then(|| (id.clone(), closed))
                })
                .collect()
        } else {
            BTreeMap::new()
        };
        let definition_lines = self
            .definitions
            .iter()
            .filter(|(_, definition)| definition.line() != 0 || definition.line_intersect() != 0)
            .map(|(id, definition)| {
                (
                    id.clone(),
                    DefinitionLineMetadata {
                        line: definition.line(),
                        line_intersect: definition.line_intersect(),
                    },
                )
            })
            .collect();
        let message_snapshots = self.messages.snapshot();
        let transfer_zones = self.transfer_zones.states();
        let mut pathfinder_debug = self.pathfinder_debug.borrow().clone();
        let used_transfer_zones = pathfinder_debug
            .zones
            .iter()
            .filter(|zone| zone.used)
            .map(|zone| zone.owner)
            .collect::<HashSet<_>>();
        // C4PathFinder retains the last ray graph, but Draw walks the live
        // global transfer-zone list. Preserve last-search `Used` markers by
        // owner while reflecting subsequent Set/ClearTransferZone calls.
        pathfinder_debug.zones = transfer_zones
            .iter()
            .map(|zone| PathfinderDebugZone {
                owner: zone.owner,
                x: zone.x,
                y: zone.y,
                width: zone.width,
                height: zone.height,
                used: used_transfer_zones.contains(&zone.owner),
            })
            .collect();
        SimulationSnapshot {
            frame: self.frame,
            game_time: self.game_time,
            game_over: self.game_over_triggered,
            round_results: self.round_results.clone(),
            league_name: self.league_name.as_ref().clone(),
            player_info_league_progress_data: self
                .player_info_league_progress_data
                .as_ref()
                .clone(),
            player_info_league_scores: self.player_info_league_scores.as_ref().clone(),
            physics: Some(self.physics),
            objects,
            render_order: self.exec_list.clone(),
            environment,
            sky: sky_snapshot,
            weather_events,
            global_effects: self.global_effects.clone(),
            script_globals: self.capture_script_globals(),
            particles,
            players: player_states,
            fow_players,
            crew_selection,
            crew_roles,
            known_crew_owners,
            eliminated_crew_owners,
            landscape: self.landscape.clone(),
            rng: self.rng.clone(),
            surfaces: Vec::new(),
            hud: HudSnapshot {
                players: hud_players,
                messages: message_snapshots,
                scoreboard: self.scoreboard.borrow().clone(),
                scoreboard_presentations: Vec::new(),
                local_players,
            },
            controls: Vec::new(),
            network_packets: Vec::new(),
            definition_categories,
            definition_closed_containers,
            definition_lines,
            transfer_zones,
            pathfinder_debug,
            menu_requests: Vec::new(),
            audio: Vec::new(),
        }
    }

    /// `C4ControlSyncCheck::Set` (C4Control.cpp:445-458): the per-frame
    /// determinism digest. `Random3` is the Rnd3 ring pointer (`FRndPtr3`),
    /// `AllCrewPosX` sums `fixtoi(fix_x, 100)` (centipixels) over the
    /// players' crew lists (C4Control.cpp:460-467), `SectShapeSum` counts the
    /// sector shape lists (C4Sector.cpp:197-203). `MassMoverIndex` remains a
    /// signature hash until the mass-mover gets C++ `CreatePtr` slots.
    pub fn sync_check(&self, by_client: i32) -> SyncCheckPacket {
        let frame = saturating_u64_to_i32(self.frame);
        let crew_positions_sum: i64 = self
            .players
            .values()
            .flat_map(|player| player.crew().iter())
            .filter_map(|id| self.find_object_index(*id))
            .map(|index| i64::from(fixtoi_prec(self.objects[index].fixed_position.x, 100)))
            .sum();
        let pxs_count = i32::try_from(self.pxs_system.execute_count()).unwrap_or(i32::MAX);
        // MassMover.CreatePtr (C4Control.cpp:454)
        let mass_mover_index = self.mass_movers.create_ptr();
        let object_count = i32::try_from(
            self.objects
                .iter()
                .filter(|object| !object.destroyed && object.state.status.is_active())
                .count(),
        )
        .unwrap_or(i32::MAX);
        let object_enumeration_index =
            saturating_u64_to_i32(self.next_object_id.saturating_sub(1));
        let sector_shape_sum = self
            .sectors
            .as_ref()
            .map(|sectors| i32::try_from(sectors.shape_sum()).unwrap_or(i32::MAX))
            .unwrap_or(0);

        SyncCheckPacket {
            frame,
            control_tick: self.control_tick,
            random3: self.rng.rnd3_ptr(),
            random_count: self.rng.count,
            crew_positions_sum: saturating_i64_to_i32(crew_positions_sum),
            pxs_count,
            mass_mover_index,
            object_count,
            object_enumeration_index,
            sector_shape_sum,
            by_client,
        }
    }

    /// `C4GameControl::Ticks` (C4GameControl.cpp:326-332): advance
    /// ControlTick every ControlRate frames and request a sync check every
    /// SyncRate frames (C4SyncCheckRate = 100, C4GameControl.h:38).
    fn control_ticks(&mut self) {
        if self.frame % self.control_rate.max(1) as u64 == 0 {
            self.control_tick += 1;
        }
        if self.frame % self.sync_rate.max(1) as u64 == 0 {
            self.do_sync = true;
        }
    }

    /// `C4GameControl::DoSyncCheck` (C4GameControl.cpp:441-468), run at the
    /// end of the frame (C4Game.cpp:829): build the digest once per DoSync,
    /// keep it in the local queue (the network layer exchanges packets and
    /// feeds foreign ones to `register_remote_sync_check`), drop old entries.
    fn do_sync_check(&mut self) {
        if !self.do_sync {
            return;
        }
        self.do_sync = false;
        let packet = self.sync_check(0);
        if self.get_sync_check(packet.frame).is_none() {
            self.sync_checks.push(packet);
        }
        self.remove_old_sync_checks();
    }

    fn capture_script_globals(&self) -> ScriptGlobalState {
        let numbered = self
            .script_global_slots
            .borrow()
            .iter()
            .map(|(&index, cell)| (index, cell.borrow().clone()))
            .collect();
        let named = self
            .script_globals
            .borrow()
            .iter()
            .map(|(name, cell)| (name.clone(), cell.borrow().clone()))
            .collect();
        ScriptGlobalState { numbered, named }
    }

    pub(crate) fn script_global_name_order(&self) -> Vec<String> {
        self.script_globals.borrow().keys().cloned().collect()
    }

    pub(crate) fn script_string_registration_order(&self) -> Vec<String> {
        clonk_script::c4_string_registration_order(&self.script_string_registrations)
    }

    /// C4AulScriptEngine::DenumerateVariablePointers after every object has
    /// loaded (C4Aul.cpp:506-520; C4Game.cpp:2492): restore numbered slots,
    /// then map saved GlobalNamed values onto the declarations registered by
    /// the fresh engine. Obsolete saved names are dropped and new declarations
    /// stay nil, matching C4ValueMapData::SetNameList.
    fn restore_script_globals(&mut self, state: &ScriptGlobalState) {
        let object_numbers: HashSet<u64> = self
            .objects
            .iter()
            .filter(|object| object.state.status != ObjectStatus::Deleted)
            .map(|object| object.id.as_u64())
            .collect();

        let mut numbered = self.script_global_slots.borrow_mut();
        numbered.clear();
        for (&index, value) in &state.numbered {
            // Serialized C4ValueList positions are always within MaxSize;
            // ignore impossible keyed JSON input rather than creating an
            // unreachable runtime slot.
            if !(0..1_000_000).contains(&index) {
                continue;
            }
            let value = denumerate_script_value(value, &object_numbers);
            clonk_script::register_c4_value_strings(&self.script_string_registrations, &value);
            numbered.insert(index, clonk_script::value_cell(value));
        }
        drop(numbered);

        let named_cells: HashMap<String, clonk_script::ValueCell> = self
            .script_globals
            .borrow()
            .iter()
            .map(|(name, cell)| (name.clone(), cell.clone()))
            .collect();
        for cell in named_cells.values() {
            *cell.borrow_mut() = Value::Nil;
        }
        for (name, value) in &state.named {
            if let Some(cell) = named_cells.get(name) {
                let value = denumerate_script_value(value, &object_numbers);
                clonk_script::register_c4_value_strings(&self.script_string_registrations, &value);
                *cell.borrow_mut() = value;
            }
        }
    }

    /// `C4GameControl::GetSyncCheck` (C4GameControl.cpp:493-506).
    pub fn get_sync_check(&self, frame: i32) -> Option<&SyncCheckPacket> {
        self.sync_checks.iter().find(|check| check.frame == frame)
    }

    /// `C4GameControl::RemoveOldSyncChecks` (C4GameControl.cpp:508-522):
    /// drop checks older than `FrameCounter - C4SyncCheckMaxKeep` (50).
    fn remove_old_sync_checks(&mut self) {
        let cutoff = saturating_u64_to_i32(self.frame) - 50;
        self.sync_checks.retain(|check| check.frame >= cutoff);
    }

    /// `C4ControlSyncCheck::Execute` (C4Control.cpp:469-525) for a sync check
    /// received from another client: compare against the local digest for the
    /// same frame, or queue it until that frame's local check exists. Returns
    /// false on synchronization loss.
    pub fn register_remote_sync_check(&mut self, packet: SyncCheckPacket) -> bool {
        let is_replay = self.replay_control;
        let Some(local) = self.get_sync_check(packet.frame) else {
            self.sync_checks.push(packet);
            return true;
        };
        if is_replay {
            local.matches_replay(&packet)
        } else {
            local.matches(&packet)
        }
    }

    /// C4GameObjects::RemoveSolidMasks around landscape persistence, applied
    /// to a clone so the running world's masks and their buffers stay put.
    /// Rust's exec list is the reverse of C++'s master list, hence `rev()`
    /// reproduces the C4GameObjects First->Next walk (C4GameObjects.cpp:
    /// 296-303). Each removal also runs C4SolidMask's global Last->Prev
    /// overlap repair against cloned buffers. That list includes a mask
    /// retained by runtime deactivation even though its owner is no longer
    /// in the active object list.
    fn landscape_without_solid_masks(&self) -> Option<Landscape> {
        let mut landscape = self.landscape.clone()?;
        let Some(vehicle) = landscape.grid_vehicle_byte() else {
            return Some(landscape);
        };
        let mut bakes = self
            .objects
            .iter()
            .map(|object| object.solid_mask_bake.clone())
            .collect::<Vec<_>>();
        for &id in self.exec_list.iter().rev() {
            let Some(index) = self.find_object_index(id) else {
                continue;
            };
            let object = &self.objects[index];
            if object.state.status != ObjectStatus::Normal {
                continue;
            }
            let Some(removed) = bakes[index].take() else {
                continue;
            };
            removed.restore_background(&mut landscape, vehicle);

            let mut overlapping = bakes
                .iter()
                .enumerate()
                .filter_map(|(other_index, other)| {
                    other.as_ref().and_then(|other| {
                        other
                            .overlaps(&removed)
                            .then_some((other_index, other.instance_sequence))
                    })
                })
                .collect::<Vec<_>>();
            overlapping.sort_unstable_by(|left, right| right.1.cmp(&left.1));
            for (other_index, _) in overlapping {
                if let Some(other) = bakes[other_index].as_mut() {
                    other.reput_after_removal(&removed, &mut landscape, vehicle);
                }
            }
        }
        Some(landscape)
    }

    /// C4GameObjects::PutSolidMasks after loading a persisted landscape.
    fn put_all_solid_masks(&mut self) {
        let master_order = self.exec_list.iter().rev().copied().collect::<Vec<_>>();
        for id in master_order {
            let Some(index) = self.find_object_index(id) else {
                continue;
            };
            if self.objects[index].state.status == ObjectStatus::Normal {
                self.put_solid_mask(index);
            }
        }
    }

    /// Snapshot used by C4GameSaveNetwork(false). Its preceding Synchronize
    /// call passes `fSavePlayerFiles=false`, so C4Player::LocalSync does not add
    /// the current Game.Time-GameJoinTime stint to the profile counter.
    pub(crate) fn capture_state_for_network_save(&self) -> EngineState {
        let mut state = self.capture_state();
        for saved in &mut state.players {
            if let Some(player) = self.players.get(&saved.id) {
                saved.total_playing_time = player.total_playing_time();
            }
        }
        state
    }

    pub fn capture_state(&self) -> EngineState {
        let objects = self
            .objects
            .iter()
            .map(|object| {
                let library = self
                    .definitions
                    .get(&object.definition_id)
                    .map(|definition| definition.action_library());
                PersistedObject {
                    snapshot: object.snapshot(library),
                    compiled_mass: self
                        .find_object_index(object.id)
                        .and_then(|index| self.valid_compiled_object_mass(index)),
                    command_queue: object.command_queue.iter().cloned().collect(),
                    command_stack: object.commands.snapshot(),
                    motion_x: object.motion_x,
                    motion_y: object.motion_y,
                    compiler_cache: object.compiler_cache.clone(),
                    last_attach_movement_frame: object.last_attach_movement_frame,
                    no_collect_delay: object.state.no_collect_delay,
                    shape_attach: object.state.shape_attach,
                    entrance_status: object.state.entrance_status,
                    crew_disabled: object.state.crew_disabled,
                    solid_mask_override: object.state.solid_mask_override,
                    shape_vertices: (!object
                        .state
                        .shape_vertices
                        .is_canonical_for(&object.state.vertices))
                    .then(|| object.state.shape_vertices.clone()),
                }
            })
            .collect();

        let crew_selection = self.crew_selection_states();

        let crew_roles = self
            .crew_roles
            .iter()
            .map(|(&owner, roles)| (owner, roles.clone()))
            .collect();

        let mut known_crew_owners: Vec<_> = self.known_crew_owners.iter().cloned().collect();
        known_crew_owners.sort_unstable();
        let mut eliminated_crew_owners: Vec<_> =
            self.eliminated_crew_owners.iter().cloned().collect();
        eliminated_crew_owners.sort_unstable();
        let mut particles: Vec<_> = self
            .particles
            .iter()
            .map(ActiveParticle::snapshot)
            .collect();
        particles.extend(self.pxs_system.iter_slots().map(|(chunk, slot, pixel)| {
            pxs_snapshot(
                pixel,
                &self.materials,
                Some((chunk * pxs::PXS_CHUNK_SIZE + slot) as u32),
            )
        }));
        let player_order = self.player_ids_in_order();
        let players: Vec<_> = player_order
            .iter()
            .map(|number| {
                let player = self
                    .players
                    .get(number)
                    .expect("projected player order contains only live players");
                let mut state = player.to_state();
                if !state.evaluated {
                    let current_stint = self.game_time.wrapping_sub(player.game_join_time());
                    state.total_playing_time = state.total_playing_time.wrapping_add(current_stint);
                }
                // C4Player::ViewTarget is NO-SAVE. Preserve ViewMode and the
                // last ViewX/ViewY center, but never smuggle the transient
                // target through PlayerViewport::focus.
                state.prepare_for_save();
                state
            })
            .collect();
        let joined_player_info_ids = players
            .iter()
            .map(|player| player.player_info_id)
            .filter(|id| *id != 0)
            .collect::<HashSet<_>>();
        let saved_player_info_league_progress_data = self
            .player_info_league_progress_data
            .iter()
            .filter(|(id, _)| joined_player_info_ids.contains(id))
            .map(|(&id, data)| (id, Some(data.clone().unwrap_or_default())))
            .collect();
        let saved_player_info_league_scores = self
            .player_info_league_scores
            .iter()
            .filter(|(id, score)| joined_player_info_ids.contains(id) && **score != 0)
            .map(|(&id, &score)| (id, score))
            .collect();
        let mut round_results = self.round_results.clone();
        round_results.prepare_for_save();

        EngineState {
            frame: self.frame,
            game_time: self.game_time,
            max_players: self.max_players,
            startup_player_count: self.startup_player_count,
            league_name: Some(self.league_name.as_ref().clone()),
            player_info_league_progress_data: Some(saved_player_info_league_progress_data),
            player_info_league_scores: Some(saved_player_info_league_scores),
            use_fair_crew: self.use_fair_crew,
            fair_crew_strength: self.fair_crew_strength,
            fair_crew_forced: Some(self.fair_crew_forced),
            allow_debug: Some(self.allow_debug),
            control_rate: Some(self.control_rate),
            message_board_commands: self.message_board_commands.clone(),
            physics: self.physics,
            environment: self.environment,
            gamma: self.gamma,
            play_list: self.audio_registry.music_playlist().map(str::to_owned),
            music_level: self.audio_registry.music_level(),
            next_object_id: self.next_object_id,
            landscape: self.landscape_without_solid_masks(),
            solid_masks_removed_from_landscape: true,
            scenario_values: Some(self.scenario_values.as_ref().clone()),
            base_reject_entrance_enabled: Some(self.base_reject_entrance_enabled),
            objects,
            object_order: self.exec_list.clone(),
            inactive_object_order: self.inactive_exec_list.clone(),
            particles,
            players,
            player_crew_rosters_authoritative: true,
            last_player_info_id: self.last_player_info_id,
            forced_control_style: self.forced_control_style,
            forced_auto_context_menu: self.forced_auto_context_menu,
            teams: self.teams.as_ref().clone(),
            team_configuration: Some(self.team_configuration),
            team_last_team_id: self.team_last_team_id,
            team_max_script_players: self.team_max_script_players,
            team_script_player_names: self.team_script_player_names.clone(),
            team_random_team_count: self.team_random_team_count,
            crew_selection,
            crew_roles,
            crew_info_rosters: self.crew_rosters.clone(),
            crew_info_order: self.crew_info_order.clone(),
            crew_object_infos: self.crew_object_infos.as_ref().clone(),
            crew_info_links: self.crew_info_links.as_ref().clone(),
            global_effects: self.global_effects.clone(),
            script_globals: self.capture_script_globals(),
            known_crew_owners,
            eliminated_crew_owners,
            transfer_zones: self.transfer_zones.states(),
            messages: self.messages.persisted(),
            pending_menu_requests: self.pending_menu_requests.clone(),
            next_mission: self.next_mission.clone(),
            scoreboard: self.scoreboard.borrow().clone(),
            game_over: self.game_over_triggered,
            round_results,
            landscape_insert_thrust: self.landscape_insert_thrust,
            structures_snow_in: self.structures_snow_in,
            flag_removeable: self.flag_removeable,
            mass_movers: self.mass_movers.clone(),
            sky: self.sky.as_ref().map(SkyState::snapshot),
            rng: self.rng.clone(),
        }
    }

    pub fn restore_state(&mut self, state: &EngineState) -> Result<(), EngineError> {
        // C4Def::pFairCrewPhysical is derived runtime state. A restored game
        // must lazily rebuild it from the restored parameters and RNG epoch.
        self.clear_fair_crew_physicals();
        self.active_message_board_input = None;
        self.pending_game_goal_menu_requests.clear();
        self.network_target_fps_requests.borrow_mut().clear();
        self.viewport_presentation_requests.borrow_mut().clear();
        self.film_viewport_available = false;
        self.player_info_league_progress_updates.clear();
        for object in &state.objects {
            if !self
                .definitions
                .contains_key(&object.snapshot.definition_id)
            {
                return Err(EngineError::UnknownDefinition(
                    object.snapshot.definition_id.clone(),
                ));
            }
        }
        // Game.Input is not part of EngineState. A pre-load direct-removal
        // request must not fire against players from the restored game.
        self.pending_remove_player_controls.clear();
        // Sound instances are presentation state and are not serialized by
        // C4SoundSystem. Loading a game starts without channels or object
        // bindings from the discarded world.
        self.audio_registry.clear_sound_instances();
        self.pending_audio.retain(|command| {
            matches!(
                command,
                AudioCommand::PlayMusic { .. }
                    | AudioCommand::StopMusic
                    | AudioCommand::SetMusicLevel { .. }
                    | AudioCommand::SetMusicPlaylist { .. }
            )
        });

        self.frame = state.frame;
        self.game_time = state.game_time;
        if let Some(max_players) = state.max_players {
            self.max_players = Some(max_players);
        }
        if let Some(startup_player_count) = state.startup_player_count {
            self.startup_player_count = Some(startup_player_count);
        }
        if let Some(league_name) = &state.league_name {
            self.league_name = Rc::new(legacy_c_string_bytes(league_name.clone()));
        }
        if let Some(progress_data) = &state.player_info_league_progress_data {
            self.player_info_league_progress_data = Rc::new(
                progress_data
                    .iter()
                    .filter(|(id, _)| **id != 0)
                    .map(|(&id, data)| {
                        (
                            id,
                            Some(legacy_c_string_bytes(data.clone().unwrap_or_default())),
                        )
                    })
                    .collect(),
            );
        }
        if let Some(scores) = &state.player_info_league_scores {
            self.player_info_league_scores = Rc::new(
                scores
                    .iter()
                    .filter(|(id, score)| **id != 0 && **score != 0)
                    .map(|(&id, &score)| (id, score))
                    .collect(),
            );
        }
        self.use_fair_crew = state.use_fair_crew;
        self.fair_crew_strength = state.fair_crew_strength;
        if let Some(fair_crew_forced) = state.fair_crew_forced {
            self.fair_crew_forced = fair_crew_forced;
        }
        if let Some(allow_debug) = state.allow_debug {
            self.allow_debug = allow_debug;
        }
        if let Some(control_rate) = state.control_rate {
            self.set_control_rate(control_rate);
        }
        self.message_board_commands = state.message_board_commands.clone();
        self.debug_mode = false;
        self.edit_cursor_target = None;
        self.time_go = false;
        let mut physics = state.physics;
        physics.reconcile_raw_gravity();
        self.physics = physics;
        self.environment = state.environment;
        self.environment.refresh_runtime_fields();
        self.gamma = state.gamma;
        let music_playlist = state.play_list.clone();
        self.audio_registry
            .restore_music_playlist(music_playlist.clone());
        self.pending_audio.push(AudioCommand::SetMusicPlaylist {
            playlist: music_playlist,
            restart: false,
        });
        let music_level = self.audio_registry.restore_music_level(state.music_level);
        self.pending_audio.push(AudioCommand::SetMusicLevel {
            level: music_level,
        });
        self.landscape_insert_thrust = state.landscape_insert_thrust;
        self.structures_snow_in = state.structures_snow_in;
        self.flag_removeable = state.flag_removeable;
        self.landscape = state.landscape.clone();
        if let Some(values) = &state.scenario_values {
            self.scenario_values = Rc::new(values.clone());
        }
        if let Some(enabled) = state.base_reject_entrance_enabled {
            self.base_reject_entrance_enabled = enabled;
        }
        // C4MassMoverSet::Load semantics (C4MassMover.cpp:204-217): the
        // saved slots restore verbatim; nothing is re-derived from the
        // landscape.
        self.mass_movers = state.mass_movers.clone();
        if self.landscape.is_none() {
            self.mass_movers.clear();
        }
        // C4Sky::CompileFunc's load half (C4Sky.cpp:248-251); the savegame
        // Init keeps the loaded scroll state (`if (!fSavegame)` reset
        // gate, C4Sky.cpp:77-80). Legacy states without a sky keep the
        // scenario-provided one.
        if let Some(frame) = &state.sky {
            self.sky = Some(SkyState::from_frame(frame));
        }
        self.rng = state.rng.clone();
        self.objects.clear();
        self.exec_list.clear();
        self.inactive_exec_list.clear();
        self.pending_object_order_commands.clear();
        self.resort_any_object = false;
        self.pending_legacy_object_infos.clear();
        self.exec_cursor = None;
        self.note_objects_changed();
        self.crew_rosters = state.crew_info_rosters.clone();
        // Older Rust states predate C4ObjectInfo::WasInAction. Active or
        // already-dead entries prove participation and can be repaired.
        for roster in self.crew_rosters.values_mut() {
            for info in roster {
                info.was_in_action |= info.in_action || info.has_died;
            }
        }
        self.crew_info_order = state.crew_info_order.clone();
        for (&player_id, roster) in &self.crew_rosters {
            let order = self.crew_info_order.entry(player_id).or_default();
            order.retain(|index| *index < roster.len());
            let mut seen = HashSet::new();
            order.retain(|index| seen.insert(*index));
            order.extend((0..roster.len()).filter(|index| seen.insert(*index)));
        }
        self.crew_info_order
            .retain(|player_id, _| self.crew_rosters.contains_key(player_id));
        self.crew_object_infos = Rc::new(state.crew_object_infos.clone());
        self.crew_info_links = Rc::new(state.crew_info_links.clone());
        // Older Rust states already persisted these fields in the roster,
        // but their duplicated live Info projection predates them. The C++
        // object pointer and roster node are one structure, so reconcile the
        // new projection from its linked authoritative node on load.
        for (&object_id, &link) in self.crew_info_links.iter() {
            let Some(entry) = self
                .crew_rosters
                .get(&link.player_id)
                .and_then(|roster| roster.get(link.roster_index))
            else {
                continue;
            };
            if let Some(info) = Rc::make_mut(&mut self.crew_object_infos).get_mut(&object_id) {
                info.death_message = entry.death_message.clone();
                info.core = entry.core.clone();
                info.rank_name = entry.rank_name.clone();
                info.participation = entry.participation;
                info.rounds = entry.rounds;
                info.total_playing_time = entry.total_playing_time;
                info.birthday = entry.birthday;
                info.age = entry.age;
                info.in_action_time = entry.in_action_time;
                info.extra_data = entry.extra_data.clone();
                info.portraits = entry.portraits.clone();
            }
        }
        self.crew_info_control_counts.clear();
        self.crew_ranks = Rc::new(
            state
                .crew_object_infos
                .iter()
                .map(|(object, info)| (object.as_u64(), info.rank))
                .collect(),
        );
        self.global_effects = state.global_effects.clone();
        self.particles.clear();
        self.pxs_system.clear();
        self.particle_system.clear_particles();
        for snapshot in &state.particles {
            if snapshot.definition_id.starts_with("material/pxs/") && snapshot.parameter_b >= 0 {
                if let Some(material) = MaterialId::new(snapshot.parameter_b as usize) {
                    // raw C4Fixed state when present (lossless save/load);
                    // float projections only for legacy snapshots
                    let [x, y, xdir, ydir] = snapshot.pxs_fixed.unwrap_or([
                        math::ftofix(snapshot.position.x).val(),
                        math::ftofix(snapshot.position.y).val(),
                        math::ftofix(snapshot.velocity.x).val(),
                        math::ftofix(snapshot.velocity.y).val(),
                    ]);
                    let pixel = pxs::Pxs {
                        mat: material,
                        x: C4Fixed::from_raw(x),
                        y: C4Fixed::from_raw(y),
                        xdir: C4Fixed::from_raw(xdir),
                        ydir: C4Fixed::from_raw(ydir),
                    };
                    // Saved slot position: C4PXSSystem::Load keeps the
                    // chunk layout verbatim (C4PXS.cpp:383-397). Legacy
                    // snapshots without one fall back to New()-style fill.
                    match snapshot.pxs_slot {
                        Some(index) => {
                            let index = index as usize;
                            self.pxs_system.create_at(
                                index / pxs::PXS_CHUNK_SIZE,
                                index % pxs::PXS_CHUNK_SIZE,
                                pixel,
                            );
                        }
                        None => {
                            self.pxs_system
                                .create(material, pixel.x, pixel.y, pixel.xdir, pixel.ydir);
                        }
                    }
                }
                continue;
            }
            if self
                .particle_system
                .get_def(&snapshot.definition_id)
                .is_some()
            {
                self.particle_system.restore_particle(particles::Particle {
                    def_name: snapshot.definition_id.clone(),
                    x: snapshot.position.x,
                    y: snapshot.position.y,
                    xdir: snapshot.velocity.x,
                    ydir: snapshot.velocity.y,
                    life: snapshot.life,
                    a: snapshot.parameter_a,
                    b: snapshot.parameter_b,
                    layer: snapshot.layer.clone(),
                });
                continue;
            }
            self.particles
                .push(ActiveParticle::from_snapshot(snapshot.clone()));
        }
        self.transfer_zones = TransferZoneTable::from_states(&state.transfer_zones);
        self.messages.restore(state.messages.clone());
        self.pending_menu_requests = state.pending_menu_requests.clone();
        self.crew_selection = state
            .crew_selection
            .iter()
            .map(|(&owner, selection)| (owner, CrewSelection::from(selection.clone())))
            .collect();

        let mut container_assignments = Vec::new();
        for persisted in &state.objects {
            let snapshot = &persisted.snapshot;
            let (shape_template, definition_blit_mode, definition_component_order) = {
                let definition =
                    self.definitions
                        .get(&snapshot.definition_id)
                        .ok_or_else(|| {
                            EngineError::UnknownDefinition(snapshot.definition_id.clone())
                        })?;
                (
                    ObjectShapeTemplate::new(
                        definition.shape_vertices().to_vec(),
                        definition.shape_rect(),
                        definition.fire_top(),
                        definition.stretch_growth(),
                        definition.rotateable(),
                    )
                    .with_line(definition.line()),
                    definition.blit_mode(),
                    definition
                        .components()
                        .iter()
                        .map(|component| component.id.clone())
                        .collect::<Vec<_>>(),
                )
            };
            let mut object = Object::new(
                snapshot.id,
                snapshot.definition_id.clone(),
                ObjectState {
                    custom_name: snapshot.custom_name.clone(),
                    script_fixed_position: None,
                    script_fixed_velocity: None,
                    script_rotation_velocity: snapshot.rotation_velocity,
                    script_fixed_rotation: snapshot.fixed_rotation,
                    position: snapshot.position,
                    velocity: snapshot.velocity,
                    // Objects.txt `Rotation` loads verbatim (C4Object.cpp:
                    // 2769); only the SetR host function normalizes.
                    rotation: snapshot.rotation,
                    shape_attach: persisted.shape_attach,
                    t_attach: 0,
                    no_collect_delay: persisted.no_collect_delay,
                    // C4Object::CompileFunc persists Base verbatim
                    // (C4Object.cpp:2776); owner validation is a separate
                    // post-load pass (C4Object.cpp:3157-3162).
                    base: snapshot.base,
                    energy: snapshot.energy,
                    need_energy: snapshot.need_energy,
                    construction: snapshot.construction,
                    damage: snapshot.damage,
                    magic_energy: snapshot.magic_energy,
                    magic_capacity: snapshot.magic_capacity,
                    action: snapshot.action.clone(),
                    direction: snapshot.direction,
                    command_direction: snapshot.command_direction,
                    effects: snapshot.effects.clone(),
                    vertices: snapshot.vertices.clone(),
                    shape_vertices: persisted
                        .shape_vertices
                        .clone()
                        .unwrap_or_else(|| ShapeVertexBuffer::from_active(&snapshot.vertices)),
                    contact_density: snapshot.contact_density,
                    container: None,
                    layer: snapshot.layer,
                    visibility: snapshot.visibility,
                    blit_mode: if snapshot.blit_mode == 0 {
                        definition_blit_mode
                    } else {
                        snapshot.blit_mode
                    },
                    picture_rect: snapshot.picture_rect,
                    contents: Vec::new(),
                    contents_link_generation: 0,
                    components: snapshot.components.clone(),
                    component_order: normalized_component_order(
                        &snapshot.components,
                        snapshot.component_order.clone(),
                        &definition_component_order,
                    ),
                    status: snapshot.status,
                    owner: snapshot.owner,
                    controller: snapshot.controller,
                    category: snapshot.category,
                    crew_member: snapshot.crew_member,
                    plr_view_range: snapshot.plr_view_range,
                    selected: snapshot.selected,
                    crew_disabled: persisted.crew_disabled,
                    alive: snapshot.alive,
                    base_graphics: snapshot.base_graphics.clone(),
                    graphics_overlays: snapshot.graphics_overlays.clone(),
                    draw_transform: snapshot.draw_transform,
                    local_vars: snapshot.local_vars.clone(),
                    in_liquid: snapshot.in_liquid,
                    mobile: snapshot.mobile,
                    solid_mask_override: persisted.solid_mask_override,
                    timer: snapshot.timer,
                    own_mass: snapshot.own_mass,
                    on_fire: snapshot.on_fire,
                    fire_phase: snapshot.fire_phase,
                    fire_caused_by: snapshot.fire_caused_by,
                    info_physical: snapshot.info_physical,
                    temporary_physical: snapshot.temporary_physical,
                    physical_changes: snapshot.physical_changes.clone(),
                    breath: snapshot.breath,
                    entrance_status: persisted.entrance_status,
                    menu: None,
                    color: snapshot.color,
                    color_modulation: snapshot.color_modulation,
                    shape_override: snapshot.current_shape,
                    ocf: OCF_NORMAL,
                },
                shape_template,
                snapshot.own_vertices.clone(),
            );
            object.compiled_mass = persisted.compiled_mass;
            if let Some(rect) = snapshot.current_shape {
                object.shape_rect = Some(rect);
            }
            if let Some(fire_top) = snapshot.current_fire_top {
                object.shape_fire_top = fire_top;
            }
            object.motion_x = persisted.motion_x;
            object.motion_y = persisted.motion_y;
            object.compiler_cache = persisted.compiler_cache.clone();
            object.last_attach_movement_frame = persisted.last_attach_movement_frame;
            // Restore authoritative sub-pixel state when the snapshot carried it
            // (whole-pixel objects fall back to the `itofix` set by `Object::new`).
            if let Some(fixed_position) = snapshot.fixed_position {
                object.fixed_position = fixed_position;
                object.state.position = object.position_pixels();
            }
            if let Some(fixed_velocity) = snapshot.fixed_velocity {
                object.fixed_velocity = fixed_velocity;
                object.state.velocity = object.velocity_pixels();
            }
            if let Some(rotation_velocity) = snapshot.rotation_velocity {
                object.rotation_velocity = rotation_velocity;
            }
            if let Some(fixed_rotation) = snapshot.fixed_rotation {
                object.fixed_rotation = fixed_rotation;
            }
            object.last_energy_loss_cause = snapshot.last_energy_loss_cause;
            object.command_queue = VecDeque::from(persisted.command_queue.clone());
            object
                .commands
                .restore_from_snapshot(&persisted.command_stack);
            let restored_id = object.id;
            self.objects.push(object);
            self.note_objects_changed();
            // State restores rebuild the list verbatim like a compiled
            // load (C4ObjectList::CompileFunc, C4ObjectList.cpp:508-530).
            self.insert_into_exec_list(restored_id, true);
            if snapshot.status == ObjectStatus::Inactive {
                self.insert_into_inactive_list(restored_id, true);
            }
            if let Some(container) = snapshot.container {
                container_assignments.push((snapshot.id, container));
            }
        }
        // C4ValueMapData compiles LocalNamed through a temporary saved name
        // list, then C4Object::CompileFunc switches it to the freshly linked
        // definition list and copies matching values by name
        // (C4ValueMap.cpp:163-195,236-293; C4Object.cpp:2815,2858-2865).
        // Numbered Local slots use our reserved keys and are independent.
        let definition_local_names: HashMap<DefinitionId, HashSet<String>> = self
            .definitions
            .iter()
            .map(|(id, definition)| {
                (
                    id.clone(),
                    definition
                        .script
                        .local_variable_names()
                        .map(str::to_string)
                        .collect(),
                )
            })
            .collect();

        // C4Object::DenumeratePointers runs only after every object has loaded
        // and recursively resolves both numbered Local and LocalNamed values
        // (C4Object.cpp:2914-2924; C4Value.cpp:684-713). Inactive objects are
        // valid targets through Game.Objects.InactiveObjects; deleted ones are
        // not part of either lookup list.
        let object_numbers: HashSet<u64> = self
            .objects
            .iter()
            .filter(|object| object.state.status != ObjectStatus::Deleted)
            .map(|object| object.id.as_u64())
            .collect();
        let object_definition_ids = self
            .objects
            .iter()
            .filter(|object| object.state.status != ObjectStatus::Deleted)
            .map(|object| (object.id.as_u64(), object.definition_id.clone()))
            .collect::<HashMap<_, _>>();
        container_assignments.retain(|(object, container)| {
            object_numbers.contains(&object.as_u64())
                && object_numbers.contains(&container.as_u64())
        });
        for object in &mut self.objects {
            denumerate_object_reference(&mut object.state.action.target, &object_numbers);
            denumerate_object_reference(&mut object.state.action.target2, &object_numbers);
            denumerate_object_reference(&mut object.state.layer, &object_numbers);
            if let Some(names) = definition_local_names.get(&object.definition_id) {
                object
                    .state
                    .local_vars
                    .retain(|name, _| name.starts_with("__local_") || names.contains(name));
            }
            for value in object.state.local_vars.values_mut() {
                *value = denumerate_script_value(value, &object_numbers);
            }
            object
                .commands
                .denumerate_object_references(&object_numbers);
            for effect in &mut object.state.effects {
                denumerate_loaded_effect(effect, &object_numbers, &object_definition_ids);
            }
        }
        for effect in &mut self.global_effects {
            denumerate_loaded_effect(effect, &object_numbers, &object_definition_ids);
        }
        // Backward compatibility for states written before ObjectSnapshot
        // carried C4Object::Select: project the legacy per-player list onto
        // the now-authoritative object bits. New states serialize both views
        // consistently, so this OR is idempotent.
        for (&owner, selection) in &state.crew_selection {
            for &id in &selection.selected {
                let roster_membership = state
                    .players
                    .iter()
                    .find(|player| player.id == owner)
                    .filter(|_| state.player_crew_rosters_authoritative)
                    .map(|player| player.crew.contains(&id));
                if let Some(object) = self.objects.iter_mut().find(|object| {
                    object.id == id
                        && roster_membership
                            .unwrap_or(object.state.owner == owner && object.state.crew_member)
                        && !object.destroyed
                        && object.state.status != ObjectStatus::Deleted
                }) {
                    object.state.selected = true;
                }
            }
        }
        if !state.object_order.is_empty() {
            let live: HashSet<ObjectId> = self.exec_list.iter().copied().collect();
            let mut seen = HashSet::with_capacity(live.len());
            let mut restored_order: Vec<ObjectId> = state
                .object_order
                .iter()
                .copied()
                .filter(|id| live.contains(id) && seen.insert(*id))
                .collect();
            restored_order.extend(self.exec_list.iter().copied().filter(|id| seen.insert(*id)));
            self.exec_list = restored_order;
        }
        if !state.inactive_object_order.is_empty() {
            let live: HashSet<ObjectId> = self.inactive_exec_list.iter().copied().collect();
            let mut seen = HashSet::with_capacity(live.len());
            let mut restored_order = state
                .inactive_object_order
                .iter()
                .copied()
                .filter(|id| live.contains(id) && seen.insert(*id))
                .collect::<Vec<_>>();
            restored_order.extend(
                self.inactive_exec_list
                    .iter()
                    .copied()
                    .filter(|id| seen.insert(*id)),
            );
            self.inactive_exec_list = restored_order;
        }
        self.reset_sectors_from_landscape();

        for (object_id, container) in container_assignments {
            self.apply_container_change(object_id, None, Some(container), true)?;
            // Restores denumerate Contained without running Enter — the
            // snapshot controller stays authoritative (no C4Object.cpp:1582
            // transfer on load).
            if let (Some(index), Some(snapshot)) = (
                self.find_object_index(object_id),
                state
                    .objects
                    .iter()
                    .find(|persisted| persisted.snapshot.id == object_id)
                    .map(|persisted| &persisted.snapshot),
            ) {
                self.objects[index].state.controller = snapshot.controller;
            }
        }

        self.restore_script_globals(&state.script_globals);

        // Objects.Load updates faces (and thus masks) before SetOCF and
        // FixObjectOrder (C4GameObjects.cpp:657-663). Snapshot projections
        // and legacy Rust states carry a live baked landscape, so only clean
        // capture_state/section states take this re-put path.
        if state.solid_masks_removed_from_landscape {
            self.put_all_solid_masks();
        }

        // C++ recomputes OCF on load rather than persisting it
        // (C4Object.cpp:2863, savegame SetOCF).
        for index in 0..self.objects.len() {
            self.refresh_object_ocf(index);
        }

        self.crew_roles = state
            .crew_roles
            .iter()
            .map(|(&owner, roles)| {
                let mut filtered = HashMap::new();
                let roster = state
                    .players
                    .iter()
                    .find(|player| player.id == owner)
                    .filter(|_| state.player_crew_rosters_authoritative)
                    .map(|player| player.crew.as_slice());
                for (&object_id, role) in roles {
                    if let Some(object) = self.objects.iter().find(|object| object.id == object_id)
                    {
                        if roster
                            .map(|roster| roster.contains(&object_id))
                            .unwrap_or(object.state.owner == owner && object.state.crew_member)
                            && !object.destroyed
                            && object.state.status != ObjectStatus::Deleted
                        {
                            filtered.insert(object_id, role.clone());
                        }
                    }
                }
                (owner, filtered)
            })
            .filter(|(_, roles)| !roles.is_empty())
            .collect();

        self.players.clear();
        self.player_order.clear();
        for mut player_state in state.players.iter().cloned() {
            // C4Player::DenumeratePointers resolves Cursor/ViewCursor,
            // Captain, and every message-board callback object, then
            // rebuilds Crew only after the object table is complete
            // (C4Player.cpp:1789-1796). ViewTarget is NO-SAVE; viewport
            // focus remains the presentation projection only.
            denumerate_object_reference(&mut player_state.cursor, &object_numbers);
            denumerate_object_reference(&mut player_state.view_cursor, &object_numbers);
            denumerate_object_reference(&mut player_state.captain, &object_numbers);
            for query in &mut player_state.message_board_queries {
                denumerate_object_reference(&mut query.target, &object_numbers);
            }
            for viewport in &mut player_state.viewports {
                denumerate_object_reference(&mut viewport.focus, &object_numbers);
            }
            player_state.restore_runtime_view();
            player_state
                .crew
                .retain(|id| object_numbers.contains(&id.as_u64()));
            let player = Player::from_state(player_state);
            let number = player.id();
            self.player_order.push(number);
            self.players.insert(number, player);
        }
        if !state.player_crew_rosters_authoritative {
            let mut player_ids: Vec<_> = self.players.keys().copied().collect();
            player_ids.sort_unstable();
            for player_id in player_ids {
                self.bootstrap_player_crew_from_union(player_id);
            }
        }
        for player in self.players.values_mut() {
            player.set_game_join_time(self.game_time);
        }
        if !self.league_name.is_empty() {
            for player_info_id in self
                .players
                .values()
                .map(Player::player_info_id)
                .filter(|id| *id != 0)
            {
                Rc::make_mut(&mut self.player_info_league_progress_data)
                    .entry(player_info_id)
                    .or_insert(None);
            }
        }
        self.last_player_info_id = state
            .last_player_info_id
            .max(
                state
                    .players
                    .iter()
                    .map(|player| player.player_info_id)
                    .chain(
                        state
                            .round_results
                            .players
                            .iter()
                            .map(|player| player.player_info_id),
                    )
                    .max()
                    .unwrap_or(0),
            )
            .max(
                self.player_info_league_progress_data
                    .keys()
                    .next_back()
                    .copied()
                    .unwrap_or(0),
            )
            .max(
                self.player_info_league_scores
                    .keys()
                    .next_back()
                    .copied()
                    .unwrap_or(0),
            )
            .max(0);
        self.forced_control_style = state.forced_control_style;
        self.forced_auto_context_menu = state.forced_auto_context_menu;
        self.teams = Rc::new(state.teams.clone());
        if let Some(configuration) = state.team_configuration {
            self.set_team_configuration(configuration);
        }
        self.team_last_team_id = state
            .team_last_team_id
            .max(state.teams.iter().map(|team| team.id).max().unwrap_or(0));
        self.team_max_script_players = state.team_max_script_players;
        self.team_script_player_names = state.team_script_player_names.clone();
        self.team_random_team_count = state.team_random_team_count;
        self.recheck_runtime_team_memberships();
        self.players_registered = !self.players.is_empty();
        self.next_mission = state.next_mission.clone();
        *self.scoreboard.borrow_mut() = state.scoreboard.clone();
        self.game_over_triggered = state.game_over;
        self.game_evaluated = false;
        self.round_results = state.round_results.clone();

        self.known_crew_owners = state.known_crew_owners.iter().cloned().collect();
        self.eliminated_crew_owners = state.eliminated_crew_owners.iter().cloned().collect();

        let highest_id = self
            .objects
            .iter()
            .map(|object| object.id.as_u64())
            .max()
            .unwrap_or(0);
        self.next_object_id = state.next_object_id.max(highest_id + 1);

        self.prune_roles();
        self.prune_selection();
        self.sync_all_player_cursors();
        self.refresh_elimination_state();

        self.fix_exec_list_order();
        self.rebuild_fow_view_objects();
        self.rebuild_sectors();
        Ok(())
    }

    /// Apply the no-callback half of savegame `RecreatePlayers`: runtime
    /// players whose current player-info/client entries were skipped never
    /// exist, but their saved objects remain and are orphaned by the later
    /// `ValidateOwners` pass.
    pub fn retain_restored_players(&mut self, retained_numbers: impl IntoIterator<Item = i32>) {
        let retained_numbers = retained_numbers.into_iter().collect::<HashSet<_>>();
        let removed_numbers = self
            .players
            .keys()
            .copied()
            .filter(|number| !retained_numbers.contains(number))
            .collect::<HashSet<_>>();

        self.players
            .retain(|number, _| retained_numbers.contains(number));
        self.player_order
            .retain(|number| retained_numbers.contains(number));
        self.pending_player_joins
            .retain(|number, _| retained_numbers.contains(number));
        self.crew_selection
            .retain(|number, _| retained_numbers.contains(number));
        self.crew_roles
            .retain(|number, _| retained_numbers.contains(number));
        self.crew_rosters
            .retain(|number, _| retained_numbers.contains(number));
        self.crew_info_order
            .retain(|number, _| retained_numbers.contains(number));
        self.known_crew_owners
            .retain(|number| retained_numbers.contains(number));
        self.eliminated_crew_owners
            .retain(|number| retained_numbers.contains(number));
        if let Some(local_players) = &mut self.local_players {
            local_players.retain(|number| retained_numbers.contains(number));
        }

        let removed_info_objects = self
            .crew_info_links
            .iter()
            .filter_map(|(object, link)| {
                removed_numbers.contains(&link.player_id).then_some(*object)
            })
            .collect::<HashSet<_>>();
        Rc::make_mut(&mut self.crew_info_links)
            .retain(|object, _| !removed_info_objects.contains(object));
        Rc::make_mut(&mut self.crew_object_infos)
            .retain(|object, _| !removed_info_objects.contains(object));
        Rc::make_mut(&mut self.crew_ranks)
            .retain(|object, _| !removed_info_objects.contains(&ObjectId::new(*object)));
        for object in &mut self.objects {
            if removed_info_objects.contains(&object.id) {
                object.state.info_physical = None;
            }
        }

        self.players_registered = !self.players.is_empty();
        self.validate_object_player_references();
        self.prune_roles();
        self.prune_selection();
        self.sync_all_player_cursors();
        self.refresh_elimination_state();
    }

    pub fn restore_snapshot(&mut self, snapshot: &SimulationSnapshot) -> Result<(), EngineError> {
        let state = EngineState::from_snapshot(snapshot);
        self.restore_state(&state)
    }

    /// Runs a batch of effect events for one object and folds every side
    /// channel back into the engine — the frame-loop half of
    /// `pEffects->Execute` (C4Object::Execute, C4Object.cpp:1069-1090).
    fn dispatch_object_effect_events(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        events: Vec<EffectEvent>,
    ) -> Result<(), EngineError> {
        let object_id = self.objects[idx].id;
        let previous_container = self.objects[idx].state.container;
        let global_view = self.global_effects.clone();
        let rng_state = self.rng.clone();
        let world = self.host_world_context_for_object(idx);
        let (
            global_cmds,
            emitted_particles,
            physics_delta,
            audio_events,
            event_messages,
            player_commands,
            object_order_commands,
            next_mission_commands,
            landscape_ops,
            effect_transfer_zones,
            effect_spawns,
            effect_other_objects,
            effect_solid_mask_operations,
            effect_host_raster_preview,
            effect_solid_mask_changed,
            _effect_action_callbacks_dispatched,
            effect_change_def_reinsert,
            effect_next_object_id,
            triggered_game_over,
            effect_script_go,
            effect_script_counter,
            audio_state,
            new_rng,
        ) = {
            let definition = self
                .definitions
                .get(definition_id)
                .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
            let definitions_ref = &self.definitions;
            let object = &mut self.objects[idx];
            Self::run_effect_events_for_object(
                definition,
                definitions_ref,
                self.game_over_triggered,
                rng_state,
                object_id,
                object,
                events,
                global_view,
                &mut self.environment,
                self.physics,
                self.frame,
                world.clone(),
                self.audio_registry.clone(),
            )?
        };
        let outermost = self.stage_host_solid_mask_operations(
            effect_solid_mask_operations,
            effect_host_raster_preview,
        );
        let fold_result = (|| -> Result<(), EngineError> {
            self.rng = new_rng;
            self.audio_registry = audio_state;
            if effect_solid_mask_changed {
                self.update_solid_mask(idx);
            }
            self.sync_next_object_id(effect_next_object_id);
            if !effect_spawns.is_empty() {
                self.process_spawn_queue(effect_spawns)?;
            }
            if !effect_transfer_zones.is_empty() {
                self.apply_transfer_zone_commands(effect_transfer_zones)?;
            }
            if !effect_other_objects.is_empty() {
                self.apply_nested_object_outcomes(effect_other_objects)?;
            }
            if !landscape_ops.is_empty() {
                self.apply_landscape_operations(landscape_ops);
            }
            if !player_commands.is_empty() {
                self.apply_player_commands(player_commands)?;
            }
            self.pending_object_order_commands
                .extend(object_order_commands);
            self.apply_next_mission_commands(next_mission_commands);
            if !audio_events.is_empty() {
                self.pending_audio.extend(audio_events);
            }
            if !event_messages.is_empty() {
                for command in event_messages {
                    self.messages.apply_command(command);
                }
            }
            if let Some(go) = effect_script_go {
                self.scenario_script_go = go;
            }
            if let Some(counter) = effect_script_counter {
                self.scenario_script_counter = counter;
            }
            if triggered_game_over {
                self.request_game_over()?;
            }
            if !physics_delta.is_empty() {
                self.apply_physics_delta(physics_delta);
            }
            if !global_cmds.is_empty() {
                self.apply_global_effect_commands(&global_cmds);
            }
            self.apply_particle_commands(emitted_particles);
            let new_container = self.objects[idx].state.container;
            if previous_container != new_container {
                self.apply_container_change(object_id, previous_container, new_container, false)?;
            }
            if effect_change_def_reinsert.unwrap_or(false) {
                self.reinsert_change_def_contents_link(object_id)?;
            }
            Ok(())
        })();
        self.finish_host_solid_mask_operations(outermost, fold_result)
    }

    fn run_effect_events_for_object(
        definition: &Definition,
        definitions: &HashMap<DefinitionId, Definition>,
        game_over_triggered: bool,
        mut rng: LcgRng,
        object_id: ObjectId,
        object: &mut Object,
        events: Vec<EffectEvent>,
        mut global_view: Vec<EffectState>,
        environment: &mut EnvironmentSettings,
        physics: PhysicsSettings,
        frame: u64,
        world: HostWorldContext,
        audio: AudioRegistry,
    ) -> Result<
        (
            Vec<EffectCommand>,
            Vec<ParticleCommand>,
            PhysicsDelta,
            Vec<AudioCommand>,
            Vec<MessageCommand>,
            Vec<PlayerCommand>,
            Vec<ObjectOrderCommand>,
            Vec<NextMissionCommand>,
            Vec<LandscapeOperation>,
            Vec<TransferZoneCommand>,
            Vec<SpawnConfig>,
            Vec<compat::NestedObjectOutcome>,
            Vec<HostSolidMaskOperation>,
            Option<compat::HostRasterPreview>,
            bool,
            bool,
            Option<bool>,
            u64,
            bool,
            Option<bool>,
            Option<i32>,
            AudioRegistry,
            LcgRng,
        ),
        EngineError,
    > {
        if events.is_empty() {
            let next_object_id = world.next_object_id();
            return Ok((
                Vec::new(),
                Vec::new(),
                PhysicsDelta::default(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                None,
                false,
                false,
                None,
                next_object_id,
                false,
                None,
                None,
                audio,
                rng,
            ));
        }

        // Spawns from one callback (CreateContents in an FxStart, the
        // GoldRush bandit equip) must not collide with the next callback's
        // ids: thread the allocator through the loop.
        let mut world = world;
        let mut pending_spawns: Vec<SpawnConfig> = Vec::new();
        let mut queue: VecDeque<EffectEvent> = VecDeque::from(events);
        let mut state_snapshot = object.script_state_snapshot();
        let mut global_commands = Vec::new();
        let mut current_environment = *environment;
        let mut current_physics = physics;
        let mut accumulated_physics = PhysicsDelta::default();
        let mut pending_particles = Vec::new();
        let mut pending_audio = Vec::new();
        let mut pending_messages = Vec::new();
        let mut current_audio = audio;
        let mut pending_player_commands = Vec::new();
        let mut pending_object_order_commands = Vec::new();
        let mut pending_next_mission_commands = Vec::new();
        let mut pending_landscape_ops = Vec::new();
        let mut pending_transfer_zones = Vec::new();
        // Nested-call mutations to OTHER objects (the copy-in/copy-out
        // model's deferred fold; C++ mutates live state mid-call): the
        // CALLER applies them via apply_nested_object_outcomes.
        let mut pending_other_objects = Vec::new();
        let mut pending_solid_mask_operations = Vec::new();
        let mut solid_mask_changed = false;
        let mut action_callbacks_dispatched = false;
        let mut change_def_reinsert = None;
        let mut game_over_requested = false;
        let mut script_go_requested: Option<bool> = None;
        let mut script_counter_requested: Option<i32> = None;
        // Pending-effect bookkeeping is keyed by the effect NUMBER — the
        // C++ identity (C4Effect.cpp:76-78); names may repeat.
        let mut checked_started: HashSet<i32> = HashSet::new();
        let mut denied_started: HashSet<i32> = HashSet::new();
        // C4Fx_Effect_Annul/AnnulCalls (C4Effect.cpp:287-291): pending
        // number -> (acceptor number, AnnulCalls temp-call request). The
        // LAST checker answering -2/-3 wins the merge.
        let mut annulled_started: HashMap<i32, (i32, bool)> = HashMap::new();
        // Anchors whose temp remove/readd bracket was already queued (a
        // re-popped anchor event must not expand again). Start and stop
        // anchors are tracked separately: numbers can be reused within one
        // run after a removal (max existing + 1, C4Effect.cpp:76-78).
        let mut temp_wrapped_started: HashSet<i32> = HashSet::new();
        let mut temp_wrapped_stopped: HashSet<i32> = HashSet::new();

        while let Some(mut event) = queue.pop_front() {
            // A command generated by an earlier callback may have killed a
            // queued callback target. Timer execution normally arrives one
            // live node at a time, but this guard also protects callers that
            // supply an explicit event batch.
            if matches!(event.kind, EffectEventKind::Timer)
                && !object
                    .state
                    .effects
                    .iter()
                    .any(|effect| effect.number == event.effect.number && effect.priority != 0)
            {
                continue;
            }
            // C4Effect::Check (C4Effect.cpp:97-116): before a new effect
            // validates, ask all effects with iPriority >= the new priority
            // via their Fx<Name>Effect callback — except for priority-1
            // effects, which are out of the priority call chain (:170).
            if matches!(event.kind, EffectEventKind::Started) {
                // Fx*Start already ran synchronously inside FnAddEffect
                // (priority-1 effects, C4Effect.cpp:96-152) — do not
                // dispatch it again.
                if event.effect.start_dispatched {
                    continue;
                }
                if denied_started.remove(&event.effect.number) {
                    continue;
                }
                if event.effect.priority != 1 && !checked_started.contains(&event.effect.number) {
                    checked_started.insert(event.effect.number);
                    // C4Effect::Check (C4Effect.cpp:278-282): every OTHER
                    // effect with iPriority >= the new priority is asked —
                    // the walk starts at the new effect's pNext, so only
                    // the effect itself is excluded, never same-name peers.
                    let checkers: Vec<EffectState> = state_snapshot
                        .effects
                        .iter()
                        .filter(|existing| {
                            existing.number != event.effect.number
                                && existing.priority != 0
                                && existing.priority >= event.effect.priority
                        })
                        .cloned()
                        .collect();
                    if !checkers.is_empty() {
                        let pending = event.effect.clone();
                        let constructor_values = event.constructor_values.clone();
                        queue.push_front(event);
                        for checker in checkers.into_iter().rev() {
                            queue.push_front(EffectEvent::check(
                                checker,
                                pending.clone(),
                                constructor_values.clone(),
                            ));
                        }
                        continue;
                    }
                }
                if let Some((acceptor_number, do_temp_calls)) =
                    annulled_started.remove(&event.effect.number)
                {
                    // Add-to-other-effect (C4Effect.cpp:295-313): the new
                    // effect stays dead — no Start, no Stop — and the
                    // acceptor's Fx*Add merges its parameters.
                    object.remove_effect_by_number(event.effect.number);
                    state_snapshot.effects = object.state.effects.clone();
                    if let Some(acceptor) = object
                        .state
                        .effects
                        .iter()
                        .find(|existing| existing.number == acceptor_number)
                        .cloned()
                    {
                        // AnnulCalls (C4Fx_Effect_AnnulCalls,
                        // C4Effects.h:38): the Add runs inside a temp
                        // remove/readd bracket of the effects above the
                        // ACCEPTOR (C4Effect.cpp:297-304).
                        let uppers = do_temp_calls
                            .then(|| upper_effects_of(&object.state.effects, &acceptor))
                            .unwrap_or_default();
                        let mut sequence: Vec<EffectEvent> = uppers
                            .iter()
                            .rev()
                            .cloned()
                            .map(EffectEvent::temp_removed)
                            .collect();
                        sequence.push(EffectEvent::add_to(
                            acceptor,
                            event.effect.clone(),
                            event.constructor_values.clone(),
                        ));
                        sequence.extend(uppers.into_iter().map(EffectEvent::temp_readded));
                        for queued in sequence.into_iter().rev() {
                            queue.push_front(queued);
                        }
                    }
                    continue;
                }
                // C4Effect ctor (C4Effect.cpp:118-133): a validating
                // Fx*Start is bracketed by temp-deactivating all upper
                // effects (high to low) and reactivating them afterwards
                // (low to high) — only when the new effect HAS an Fx*Start
                // and is not priority 1 (`fRemoveUpper && pNext &&
                // pFnStart`, C4Effect.cpp:123). The bracket runs even when
                // the Start then denies (C4Effect.cpp:128-133).
                if event.effect.priority != 1
                    && !temp_wrapped_started.contains(&event.effect.number)
                {
                    let callback_name = format!("Fx{}Start", event.effect.name);
                    let has_start = event.effect.name == C4FX_FIRE
                        || resolve_effect_script_callback(&event.effect, &callback_name, &world)
                            .is_some();
                    if has_start {
                        let uppers = upper_effects_of(&object.state.effects, &event.effect);
                        if !uppers.is_empty() {
                            temp_wrapped_started.insert(event.effect.number);
                            let mut sequence: Vec<EffectEvent> = uppers
                                .iter()
                                .rev()
                                .cloned()
                                .map(EffectEvent::temp_removed)
                                .collect();
                            sequence.push(event);
                            sequence
                                .extend(uppers.into_iter().map(EffectEvent::temp_readded));
                            for queued in sequence.into_iter().rev() {
                                queue.push_front(queued);
                            }
                            continue;
                        }
                    }
                }
                // The constructor has survived Check/annul negotiation and
                // is about to execute its one Start call. Mark the live node
                // before the callback so EffectVar updates cloned from its
                // host snapshot retain the completed-constructor state.
                event.effect.start_dispatched = true;
                if let Some(effect) = object
                    .state
                    .effects
                    .iter_mut()
                    .find(|effect| effect.number == event.effect.number)
                {
                    effect.start_dispatched = true;
                }
                state_snapshot.effects = object.state.effects.clone();
            }
            // C4Effect::Kill (C4Effect.cpp:365-405): the real removal is
            // bracketed by temp-deactivating all upper effects
            // (C4Effect.cpp:370-374) and reactivating them after the Stop
            // (C4Effect.cpp:404). Clear/destroy removals go through
            // ClearAll, which does NO temp calls (C4Effect.cpp:407-425);
            // priority-1 victims skip the bracket (C4Effect.cpp:477).
            if matches!(
                event.kind,
                EffectEventKind::Stopped(EffectStopReason::Removed)
            ) && event.effect.priority != 1
                && !temp_wrapped_stopped.contains(&event.effect.number)
            {
                let uppers = upper_effects_of(&object.state.effects, &event.effect);
                if !uppers.is_empty() {
                    temp_wrapped_stopped.insert(event.effect.number);
                    let mut sequence: Vec<EffectEvent> = uppers
                        .iter()
                        .rev()
                        .cloned()
                        .map(EffectEvent::temp_removed)
                        .collect();
                    sequence.push(event);
                    sequence.extend(uppers.into_iter().map(EffectEvent::temp_readded));
                    for queued in sequence.into_iter().rev() {
                        queue.push_front(queued);
                    }
                    continue;
                }
            }
            let clear_all_stop = matches!(
                event.kind,
                EffectEventKind::Stopped(
                    EffectStopReason::Cleared
                        | EffectStopReason::Death
                        | EffectStopReason::Destroyed
                )
            );
            let death_stop = matches!(
                event.kind,
                EffectEventKind::Stopped(EffectStopReason::Death)
            );
            if clear_all_stop {
                // ClearAll calls SetDead immediately before Fx*Stop, but
                // keeps the node linked so GetEffect(number, include-dead)
                // and the unique-number allocator still see it
                // (C4Effect.cpp:407-424,55-81).
                if let Some(effect) = object
                    .state
                    .effects
                    .iter_mut()
                    .find(|effect| effect.number == event.effect.number)
                {
                    effect.priority = 0;
                    state_snapshot.effects = object.state.effects.clone();
                }
            }

            // TempRemoveUpperEffects flips each live upper node BEFORE its
            // Stop callback; TempReadd walks the then-live suffix and flips
            // only still-inactive nodes before Start. Resolving by number at
            // dispatch time prevents a stale queued readd from resurrecting
            // an effect killed inside its temp Stop.
            match event.kind {
                EffectEventKind::TempRemoved => {
                    let Some(effect) = object
                        .state
                        .effects
                        .iter_mut()
                        .find(|effect| {
                            effect.number == event.effect.number && effect.priority > 0
                        })
                    else {
                        continue;
                    };
                    effect.priority = -effect.priority;
                    event.effect = effect.clone();
                    state_snapshot.effects = object.state.effects.clone();
                }
                EffectEventKind::TempReadded => {
                    let Some(effect) = object
                        .state
                        .effects
                        .iter_mut()
                        .find(|effect| {
                            effect.number == event.effect.number && effect.priority < 0
                        })
                    else {
                        continue;
                    };
                    effect.priority = -effect.priority;
                    event.effect = effect.clone();
                    state_snapshot.effects = object.state.effects.clone();
                }
                _ => {}
            }
            let mut snapshot_for_call = state_snapshot.clone();
            if matches!(event.kind, EffectEventKind::Stopped(_))
                && !snapshot_for_call
                    .effects
                    .iter()
                    .any(|effect| effect.number == event.effect.number)
            {
                // C4Effect::Kill/ClearAll keep the dead list node linked
                // throughout Fx*Stop (C4Effect.cpp:365-424). EffectVar and
                // GetEffect must therefore still resolve the victim even
                // though the Rust command fold already removed it.
                let mut linked = event.effect.clone();
                if clear_all_stop {
                    linked.priority = 0;
                }
                insert_effect_into_stack(&mut snapshot_for_call.effects, linked);
            }
            let dispatch_definition =
                resolve_effect_dispatch_definition(
                    &event.effect,
                    &world,
                    definitions,
                    Some((object_id, object.definition_id.as_str())),
                    definitions.get(&object.definition_id).unwrap_or(definition),
                );
            // Engine-internal fire callbacks: when no script overload
            // shadows the engine function (AddFunc C4Script.cpp:6994-6996),
            // Fx*Stop clears the OnFire flag — real and temp removals alike
            // (FnFxFireStop, C4Effect.cpp:775-791) — and the temp-readd
            // Fx*Start re-arms it (FnFxFireStart iTemp arm,
            // C4Effect.cpp:563-565).
            if event.effect.name == C4FX_FIRE {
                let engine_native = |callback: &str| -> bool {
                    let callback_name = format!("Fx{C4FX_FIRE}{callback}");
                    resolve_effect_script_callback(&event.effect, &callback_name, &world).is_none()
                };
                match event.kind {
                    EffectEventKind::Stopped(_) | EffectEventKind::TempRemoved
                        if engine_native("Stop") =>
                    {
                        object.state.on_fire = false;
                    }
                    EffectEventKind::TempReadded if engine_native("Start") => {
                        object.state.on_fire = true;
                    }
                    _ => {}
                }
            }
            let mut timer_kill = false;
            let mut start_denied = false;
            let mut stop_denied = false;
            let mut add_denied = false;
            // C++ runs Fx* callbacks with fPassErrors=false: a script
            // error logs and the game continues (the erroring callback
            // yields nil). RNG/audio are restored from the pre-call
            // backups on the error path — the callback's partial outcome,
            // including its RNG draws, is dropped (documented seam: C++
            // keeps mutations made before the error).
            let rng_backup = rng.clone();
            let audio_backup = current_audio.clone();
            let call_result = match event.kind {
                EffectEventKind::Started => dispatch_definition
                    .call_effect_start(
                        Some((&snapshot_for_call, object_id)),
                        &event.effect,
                        &event.constructor_values,
                        rng,
                        &global_view,
                        current_physics,
                        current_environment,
                        frame,
                        world.clone(),
                        game_over_triggered,
                        current_audio,
                    )
                    .map(|(outcome, audio_state, new_rng, start_result)| {
                        // C4Fx_Start_Deny (-1, C4Effects.h:43): the effect
                        // is marked dead before validating
                        // (C4Effect.cpp:128-131) and deleted without a
                        // Stop callback.
                        start_denied = start_result
                            .as_ref()
                            .is_some_and(|value| compat::value_as_i32(value) == -1);
                        (outcome, audio_state, new_rng)
                    }),
                EffectEventKind::Timer => dispatch_definition
                    .call_effect_timer(
                        Some((&snapshot_for_call, object_id)),
                        &event.effect,
                        frame,
                        rng,
                        &global_view,
                        current_physics,
                        current_environment,
                        world.clone(),
                        game_over_triggered,
                        current_audio,
                    )
                    .map(|(outcome, audio_state, new_rng, timer_result)| {
                        // C4Effect::Execute (C4Effect.cpp:342-360): FxTimer
                        // returning C4Fx_Execute_Kill (-1, C4Effects.h:40)
                        // kills the effect; an elapsed interval with NO
                        // timer function kills too ("no timer function:
                        // mark dead after time elapsed" — the else arm at
                        // :358-360; the intro's Divinity markers die on
                        // their first exec in C++ as well).
                        timer_kill = timer_result
                            .as_ref()
                            .is_none_or(|value| compat::value_as_i32(value) == -1);
                        (outcome, audio_state, new_rng)
                    }),
                EffectEventKind::Stopped(reason) => dispatch_definition
                    .call_effect_stop(
                        Some((&snapshot_for_call, object_id)),
                        &event.effect,
                        reason,
                        rng,
                        &global_view,
                        current_physics,
                        current_environment,
                        frame,
                        world.clone(),
                        game_over_triggered,
                        current_audio,
                    )
                    .map(|(outcome, audio_state, new_rng, stop_result)| {
                        // AssignDeath uses ClearAll(RemoveDeath), whose Stop
                        // callbacks may deny removal and revive the object
                        // (C4Object.cpp:1162-1170; C4Effect.cpp:407-424).
                        // Object-clear/destroy removals still cannot veto the
                        // object going away.
                        stop_denied = matches!(
                            reason,
                            EffectStopReason::Removed
                                | EffectStopReason::Cleared
                                | EffectStopReason::Death
                                | EffectStopReason::Destroyed
                        )
                            && stop_result
                                .as_ref()
                                .is_some_and(|value| compat::value_as_i32(value) == -1);
                        (outcome, audio_state, new_rng)
                    }),
                EffectEventKind::Check { ref pending } => dispatch_definition
                    .call_effect_effect(
                        Some((&snapshot_for_call, object_id)),
                        &event.effect,
                        pending,
                        &event.constructor_values,
                        rng,
                        &global_view,
                        current_physics,
                        current_environment,
                        frame,
                        world.clone(),
                        game_over_triggered,
                        current_audio,
                    )
                    .map(|(outcome, audio_state, new_rng, check_result)| {
                        match check_result.as_ref().map(compat::value_as_i32) {
                            // C4Fx_Effect_Deny (-1, C4Effects.h:36) blocks
                            // the new effect entirely.
                            Some(-1) => {
                                denied_started.insert(pending.number);
                                annulled_started.remove(&pending.number);
                                object.remove_effect_by_number(pending.number);
                                state_snapshot.effects = object.state.effects.clone();
                                // The deny returns immediately from the
                                // checker walk (C4Effect.cpp:283-285) —
                                // checkers later in the chain are never
                                // asked.
                                queue.retain(|queued| match &queued.kind {
                                    EffectEventKind::Check {
                                        pending: queued_pending,
                                    } => queued_pending.number != pending.number,
                                    _ => true,
                                });
                            }
                            // C4Fx_Effect_Annul/AnnulCalls (-2/-3,
                            // C4Effects.h:37-38): this checker accepts the
                            // new effect; the walk continues and the LAST
                            // acceptor wins (C4Effect.cpp:287-291).
                            Some(-2) => {
                                annulled_started
                                    .insert(pending.number, (event.effect.number, false));
                            }
                            Some(-3) => {
                                annulled_started
                                    .insert(pending.number, (event.effect.number, true));
                            }
                            _ => {}
                        }
                        (outcome, audio_state, new_rng)
                    }),
                EffectEventKind::AddTo { ref pending } => dispatch_definition
                    .call_effect_add(
                        Some((&snapshot_for_call, object_id)),
                        &event.effect,
                        pending,
                        &event.constructor_values,
                        rng,
                        &global_view,
                        current_physics,
                        current_environment,
                        frame,
                        world.clone(),
                        game_over_triggered,
                        current_audio,
                    )
                    .map(|(outcome, audio_state, new_rng, add_result)| {
                        // C4Fx_Start_Deny from Fx*Add kills the ACCEPTOR
                        // (C4Effect.cpp:306-309).
                        add_denied = add_result
                            .as_ref()
                            .is_some_and(|value| compat::value_as_i32(value) == -1);
                        (outcome, audio_state, new_rng)
                    }),
                EffectEventKind::TempRemoved => dispatch_definition
                    .call_effect_stop(
                        Some((&snapshot_for_call, object_id)),
                        &event.effect,
                        EffectStopReason::Temp,
                        rng,
                        &global_view,
                        current_physics,
                        current_environment,
                        frame,
                        world.clone(),
                        game_over_triggered,
                        current_audio,
                    )
                    .map(|(outcome, audio_state, new_rng, _temp_result)| {
                        // The temp stop's result is ignored
                        // (C4Effect.cpp:489 does not check it).
                        (outcome, audio_state, new_rng)
                    }),
                EffectEventKind::TempReadded => dispatch_definition
                    .call_effect_temp_readd(
                        Some((&snapshot_for_call, object_id)),
                        &event.effect,
                        rng,
                        &global_view,
                        current_physics,
                        current_environment,
                        frame,
                        world.clone(),
                        game_over_triggered,
                        current_audio,
                    )
                    .map(|(outcome, audio_state, new_rng, _temp_result)| {
                        // The temp readd's result is ignored
                        // (C4Effect.cpp:505 does not check it).
                        (outcome, audio_state, new_rng)
                    }),
            };
            let (outcome, audio_state, new_rng) = match call_result {
                Ok(value) => value,
                Err(EngineError::Script {
                    definition,
                    function,
                    source,
                    recovery: _,
                }) => {
                    tracing::warn!(
                        %definition,
                        function,
                        error = %source,
                        "script error in effect callback; continuing like the C++ fail-safe exec"
                    );
                    log_runtime_call_frames(&definition, source.call_frames());
                    rng = rng_backup;
                    current_audio = audio_backup;
                    continue;
                }
                Err(other) => return Err(other),
            };
            rng = new_rng;
            current_audio = audio_state;
            if start_denied {
                object.remove_effect_by_number(event.effect.number);
                state_snapshot.effects = object.state.effects.clone();
            }
            if stop_denied
                && !death_stop
                && !object
                    .state
                    .effects
                    .iter()
                    .any(|effect| effect.number == event.effect.number)
            {
                // Deferred command producers may have unlinked the victim
                // before Stop. Reinsert it before folding the callback's
                // EffectVar updates; timer Kill already has the exact dead
                // node linked and therefore skips this compatibility path.
                object.insert_effect(event.effect.clone());
                state_snapshot.effects = object.state.effects.clone();
            }
            if add_denied {
                // pAddToEffect->Kill (C4Effect.cpp:308): a full Kill with
                // the acceptor's own Stop callback.
                if let Some(removed) = object.remove_effect_by_number(event.effect.number) {
                    queue.push_back(EffectEvent::stopped(removed, EffectStopReason::Removed));
                }
                state_snapshot.effects = object.state.effects.clone();
            }

            let compat::EffectContextOutcome {
                object: object_effect_commands,
                global: mut global_effect_commands,
                object_update,
                object_commands,
                command_operations,
                destroy_object,
                environment: environment_update,
                physics: physics_update,
                landscape: host_landscape_ops,
                solid_mask_operations: event_solid_mask_operations,
                host_raster_preview: event_host_raster_preview,
                particles: mut emitted_particles,
                transfer_zones: event_transfer_zones,
                messages: event_messages,
                player_commands: effect_player_commands,
                object_order_commands: effect_object_order_commands,
                next_mission_commands: effect_next_mission_commands,
                audio: outcome_audio,
                trigger_game_over,
                script_go,
                script_counter,
                context_locals,
                spawns,
                next_object_id,
                other_objects: event_other_objects,
                ..
            } = outcome;

            if let Some(preview) = event_host_raster_preview {
                world.apply_host_raster_preview(preview);
            } else {
                world.preview_solid_mask_operations(&event_solid_mask_operations);
            }
            pending_solid_mask_operations.extend(event_solid_mask_operations);

            // Every effect callback receives a cloned host world. Replay
            // transfer-zone mutations into the threaded copy before the
            // next callback, while retaining their original order for the
            // authoritative Engine fold after this batch returns.
            for command in &event_transfer_zones {
                world.preview_transfer_zone_command(command);
            }
            pending_transfer_zones.extend(event_transfer_zones);

            // The callback ran in this object's own context
            // (C4Effect.cpp:129) — persist its local writes. VM finals
            // apply first; host-command updates below may override.
            if let Some(locals) = context_locals {
                object.state.local_vars = locals;
                state_snapshot = object.script_state_snapshot();
            }

            if !spawns.is_empty() {
                pending_spawns.extend(spawns);
            }
            if !event_other_objects.is_empty() {
                for nested in &event_other_objects {
                    if let Some(update) = nested.update.as_ref() {
                        world.preview_object_update(nested.object_id, update);
                    }
                    if nested.destroy {
                        world.preview_object_destroyed(nested.object_id);
                    }
                }
                pending_other_objects.extend(event_other_objects);
            }
            world = world.with_next_object_id(next_object_id);

            if !host_landscape_ops.is_empty() {
                pending_landscape_ops.extend(host_landscape_ops);
            }

            if !effect_player_commands.is_empty() {
                pending_player_commands.extend(effect_player_commands);
            }
            pending_object_order_commands.extend(effect_object_order_commands);
            pending_next_mission_commands.extend(effect_next_mission_commands);

            if let Some(update) = environment_update {
                update.apply(&mut current_environment);
            }
            if let Some(update) = physics_update {
                merge_physics_delta(&mut accumulated_physics, &update);
                update.apply(&mut current_physics);
            }

            if let Some(update) = object_update {
                // Later callbacks in this same deferred batch must see the
                // carrier's complete live update. C++ mutates the object in
                // place; in particular, consecutive DigFree callbacks share
                // MaterialContents rather than reseeding from the batch's
                // entry snapshot.
                world.preview_object_update(object_id, &update);
                solid_mask_changed |= update.change_def.is_some()
                    || update.solid_mask_override.is_some()
                    || update.base_graphics.is_some()
                    || update.position.is_some()
                    || update.construction.is_some()
                    || update.container.is_some()
                    || update.rotation.is_some();
                let mut delta = ObjectDelta::default();
                delta.merge_update(update);
                let definition_changed = delta.change_def.is_some();
                let callback_action_library = if let Some(new_def) = delta.change_def.as_deref() {
                    let new_definition = definitions
                        .get(new_def)
                        .ok_or_else(|| EngineError::UnknownDefinition(new_def.to_string()))?;
                    let material_capacity = object.material_contents.len();
                    Self::apply_change_object_def_to_object(
                        object,
                        new_def,
                        new_definition,
                        material_capacity,
                        None,
                    );
                    new_definition.action_library()
                } else {
                    definitions
                        .get(&object.definition_id)
                        .unwrap_or(definition)
                        .action_library()
                };
                if definition_changed {
                    change_def_reinsert = Some(delta.change_def_reinsert);
                }
                let callbacks_dispatched = delta
                    .action
                    .as_ref()
                    .map(|action| action.callbacks_dispatched)
                    .unwrap_or(false);
                action_callbacks_dispatched |= callbacks_dispatched;
                let outcome = object.apply_delta(&delta, callback_action_library);
                if definition_changed {
                    if let Some(current_definition) = definitions.get(&object.definition_id) {
                        let contents_count = Self::host_retained_contents_count(
                            &world,
                            &object.state.contents,
                        );
                        object.state.ocf = current_definition
                            .compute_ocf_with_contents_count(&object.state, contents_count);
                    }
                }
                if let Some(change) = outcome.action_change {
                    if !callbacks_dispatched {
                        object.record_action_event(change.previous, ActionTransitionKind::Forced);
                    }
                }
                state_snapshot = object.script_state_snapshot();
            }

            if !command_operations.is_empty() {
                object.apply_command_operations(command_operations);
            }

            if !object_commands.is_empty() {
                object.enqueue_commands(object_commands);
            }

            if !object_effect_commands.is_empty() {
                let mut generated = object.apply_effect_commands(&object_effect_commands);
                state_snapshot = object.script_state_snapshot();
                if !generated.is_empty() {
                    queue.extend(generated.drain(..));
                }
            }

            if destroy_object {
                // AssignRemoval already ran ClearAll synchronously inside
                // RemoveObject. Fold its no-callback effect removals before
                // marking the carrier destroyed, so mark_destroyed cannot
                // enqueue duplicate RemoveClear Stops against Deleted state.
                // This mirrors apply_callback_outcome's fold order.
                solid_mask_changed = true;
                object.retired_info_physical = object.state.info_physical;
                object.state.info_physical = None;
                let mut generated = object.mark_destroyed();
                if !generated.is_empty() {
                    queue.extend(generated.drain(..));
                }
            }

            if stop_denied
                && !death_stop
                && !object.destroyed
                && !matches!(object.state.status, ObjectStatus::Deleted)
            {
                // Kill restores iPriority on the same still-linked node
                // after Stop returns. Restore after folding EffectVar
                // updates so writes made while the node was dead survive.
                if let Some(effect) = object
                    .state
                    .effects
                    .iter_mut()
                    .find(|effect| effect.number == event.effect.number)
                {
                    effect.priority = event.effect.priority;
                } else {
                    object.insert_effect(event.effect.clone());
                }
                state_snapshot = object.script_state_snapshot();
            }

            if stop_denied
                && death_stop
                && !object.destroyed
                && !matches!(object.state.status, ObjectStatus::Deleted)
            {
                // ClearAll recovery restores only iPriority on the still
                // linked node. Preserve EffectVar writes made inside Stop,
                // and keep any callback-added effects at their newly
                // allocated numbers (C4Effect.cpp:413-422).
                if let Some(effect) = object
                    .state
                    .effects
                    .iter_mut()
                    .find(|effect| effect.number == event.effect.number)
                {
                    effect.priority = event.effect.priority;
                } else {
                    object.insert_effect(event.effect.clone());
                }
                state_snapshot = object.script_state_snapshot();
            }

            if !global_effect_commands.is_empty() {
                apply_effect_commands_to_stack(&mut global_view, &global_effect_commands);
                global_commands.append(&mut global_effect_commands);
            }

            if !emitted_particles.is_empty() {
                pending_particles.append(&mut emitted_particles);
            }

            if !outcome_audio.events.is_empty() {
                pending_audio.extend(outcome_audio.events);
            }
            if !event_messages.is_empty() {
                pending_messages.extend(event_messages);
            }

            if script_go.is_some() {
                script_go_requested = script_go;
            }
            if script_counter.is_some() {
                script_counter_requested = script_counter;
            }
            if trigger_game_over {
                game_over_requested = true;
            }

            if timer_kill
                && !object.destroyed
                && !matches!(object.state.status, ObjectStatus::Deleted)
            {
                // Execute calls Kill synchronously after the Timer callback
                // has committed all of its mutations. Kill marks this exact
                // node dead but leaves it linked; its Stop/temp bracket must
                // finish before the live cursor advances to the next node.
                if let Some(effect) = object
                    .state
                    .effects
                    .iter_mut()
                    .find(|effect| effect.number == event.effect.number && effect.priority != 0)
                {
                    let stopped = effect.clone();
                    effect.priority = 0;
                    state_snapshot.effects = object.state.effects.clone();
                    queue.push_front(EffectEvent::stopped(stopped, EffectStopReason::Removed));
                }
            }
        }

        *environment = current_environment;

        let next_object_id = world.next_object_id();
        let host_raster_preview = (!pending_solid_mask_operations.is_empty())
            .then(|| world.host_raster_preview());
        Ok((
            global_commands,
            pending_particles,
            accumulated_physics,
            pending_audio,
            pending_messages,
            pending_player_commands,
            pending_object_order_commands,
            pending_next_mission_commands,
            pending_landscape_ops,
            pending_transfer_zones,
            pending_spawns,
            pending_other_objects,
            pending_solid_mask_operations,
            host_raster_preview,
            solid_mask_changed,
            action_callbacks_dispatched,
            change_def_reinsert,
            next_object_id,
            game_over_requested,
            script_go_requested,
            script_counter_requested,
            current_audio,
            rng,
        ))
    }

    fn apply_physics_delta(&mut self, delta: PhysicsDelta) {
        if delta.is_empty() {
            return;
        }
        let mut physics = self.physics;
        delta.apply(&mut physics);
        self.set_physics(physics);
    }

    fn update_selection_for_state_change(
        &mut self,
        _object_id: ObjectId,
        _previous_owner: i32,
        _previous_crew_member: bool,
        _new_owner: i32,
        _new_crew_member: bool,
    ) {
        // Owner, StatusDeactivate(false), and an individual player's crew
        // membership changes do not implicitly clear C4Object::Select or any
        // player pointer. The concrete C++ operations that do clear pointers
        // (death, deletion, StatusDeactivate(true), GrabInfo) handle them at
        // their exact ordered call sites.
    }

    fn remove_from_selection(&mut self, owner: i32, object_id: ObjectId) {
        if let Some(object) = self.objects.iter_mut().find(|object| object.id == object_id) {
            object.state.selected = false;
        }
        if self.crew_cursor(owner) == Some(object_id) {
            let replacement = self.selected_crew(owner).last().copied();
            if let Some(selection) = self.crew_selection.get_mut(&owner) {
                selection.cursor = replacement;
            }
        }
        if self
            .crew_selection
            .get(&owner)
            .is_some_and(CrewSelection::is_empty)
        {
            self.crew_selection.remove(&owner);
        }
        self.sync_player_cursor(owner);
    }

    fn remove_from_roles(&mut self, owner: i32, object_id: ObjectId) {
        if let Some(assignments) = self.crew_roles.get_mut(&owner) {
            assignments.remove(&object_id);
            if assignments.is_empty() {
                self.crew_roles.remove(&owner);
            }
        }
        self.sync_player_cursor(owner);
    }

    fn sync_player_cursor(&mut self, owner: i32) {
        if let Some(player) = self.players.get_mut(&owner) {
            let cursor = self
                .crew_selection
                .get(&owner)
                .and_then(|selection| selection.cursor());
            player.set_cursor(cursor);
        }
    }

    fn sync_all_player_cursors(&mut self) {
        let owners: Vec<i32> = self.players.keys().copied().collect();
        for owner in owners {
            self.sync_player_cursor(owner);
        }
    }

    fn scenario_section_object_spawns(
        &self,
        section: &RuntimeScenarioSection,
    ) -> Result<Vec<scenario::ScenarioSpawn>, EngineError> {
        let group = if let Some(payload) = section.frozen_group.as_ref() {
            Some(
                clonk_resources::Group::from_raw_memory(
                    std::path::PathBuf::from(format!("Sect{}.c4g", section.name)),
                    payload.clone(),
                )
                .map_err(|error| EngineError::ScenarioSectionObjects {
                    section: section.name.clone(),
                    detail: error.to_string(),
                })?,
            )
        } else {
            section.source_group.clone()
        };
        let Some(group) = group else {
            // Unit/synthetic sections have no C4Group to reopen. Preserve
            // their explicit templates as the test-fixture equivalent of an
            // Objects.txt component.
            return Ok(section.initial_objects.clone());
        };
        if section.source_group.is_none() && !group.exists("Objects.txt") {
            // A landscape-only freeze of a synthetic section creates a temp
            // group without an object component. Real named sections copied
            // their original Objects.txt into that group; only fixtures need
            // to fall back to the explicit templates here.
            return Ok(section.initial_objects.clone());
        }

        let definition_ids = self
            .definitions
            .keys()
            .map(String::as_str)
            .collect::<HashSet<_>>();
        let retained_object_numbers = self
            .objects
            .iter()
            .filter(|object| object.state.status != ObjectStatus::Deleted)
            .map(|object| object.id.as_u64())
            .collect::<HashSet<_>>();
        scenario::collect_legacy_objects_with_definition_ids(
            &group,
            &definition_ids,
            &self.legacy_string_table,
            &retained_object_numbers,
        )
        .map_err(|error| EngineError::ScenarioSectionObjects {
            section: section.name.clone(),
            detail: error.to_string(),
        })
    }

    fn spawn_scenario_section_objects(
        &mut self,
        mut pending: Vec<scenario::ScenarioSpawn>,
    ) -> Result<(), EngineError> {
        // Inactive cross-section objects keep their enumeration numbers. If
        // an original section object reused one, C++'s loader resolves the
        // live inactive object first; dropping that one colliding template
        // entry is the safe equivalent until section renumeration is modeled.
        let retained_ids = self
            .objects
            .iter()
            .map(|object| object.id)
            .collect::<HashSet<_>>();
        pending.retain(|spawn| spawn.config.id.is_none_or(|id| !retained_ids.contains(&id)));
        let contents_specs = pending
            .iter()
            .filter_map(|spawn| {
                (!spawn.contents_handles.is_empty()).then(|| {
                    (
                        spawn.handle.clone(),
                        spawn.contents_handles.clone(),
                    )
                })
            })
            .collect::<Vec<_>>();

        let max_explicit_id = pending
            .iter()
            .filter_map(|spawn| spawn.config.id)
            .map(ObjectId::as_u64)
            .max();
        if let Some(max_id) = max_explicit_id {
            self.next_object_id = self.next_object_id.max(max_id.saturating_add(1));
        }

        let mut handles = retained_ids
            .iter()
            .map(|id| (id.as_u64().to_string(), *id))
            .collect::<HashMap<String, ObjectId>>();
        while !pending.is_empty() {
            let ready = pending.iter().position(|spawn| {
                spawn
                    .container_handle
                    .as_ref()
                    .is_none_or(|handle| handles.contains_key(handle))
            });
            let index = match ready {
                Some(index) => index,
                None => {
                    // Missing/cyclic containers denumerate to null in the
                    // existing initial-scenario loader. Break one edge and
                    // let the same deterministic file-order loop continue.
                    pending[0].container_handle = None;
                    0
                }
            };
            let mut spawn = pending.remove(index);
            if let Some(container) = spawn
                .container_handle
                .as_ref()
                .and_then(|handle| handles.get(handle))
                .copied()
            {
                spawn.config = spawn.config.with_container(container);
            }
            let id = self.spawn_object(spawn.config)?;
            if let Some(handle) = spawn.handle {
                handles.insert(handle, id);
            }
        }
        let contents_orders = contents_specs
            .into_iter()
            .filter_map(|(parent, children)| {
                let parent = parent.and_then(|handle| handles.get(&handle).copied())?;
                let children = children
                    .iter()
                    .filter_map(|handle| handles.get(handle).copied())
                    .collect::<Vec<_>>();
                Some((parent, children))
            })
            .collect::<Vec<_>>();
        self.restore_legacy_contents_order(&contents_orders);
        self.finish_legacy_object_load();
        Ok(())
    }

    fn load_scenario_section(
        &mut self,
        name: &str,
        flags: i32,
        preserve_ids: Vec<ObjectId>,
    ) -> Result<bool, EngineError> {
        if !self.scenario_current_section_registered {
            // C4Game::LoadScenarioSection creates the implicit current/root
            // node before it even looks up the requested target. Its
            // constructor prepends the node to Game.pScenarioSections.
            let current = self.current_scenario_section.to_ascii_lowercase();
            if self.scenario_sections.contains_key(&current) {
                self.scenario_section_order
                    .retain(|section| section != &current);
                self.scenario_section_order.insert(0, current);
            }
            self.scenario_current_section_registered = true;
        }
        let key = name.to_ascii_lowercase();
        let Some(target) = self.scenario_sections.get(&key) else {
            return Ok(false);
        };

        // C4ScenarioSection::GetGroupfile can reopen an implicit scenario
        // root only while it is named Main. A resumed network save may bind
        // that implicit root to CurrentScenarioSection (for example Cave);
        // it has neither a child Filename nor a group it can reopen after
        // departure. EnsureTempStore, reached when either save flag is set,
        // gives it the temporary group represented by frozen_group.
        if target.source_is_scenario_root
            && !target.name.eq_ignore_ascii_case("main")
            && target.frozen_group.is_none()
        {
            return Ok(false);
        }

        let preserved = preserve_ids.into_iter().collect::<HashSet<_>>();
        let departing_pxs = self.pxs_system.clone();
        let departing_mass_movers = self.mass_movers.clone();
        let departing_key = self.current_scenario_section.to_ascii_lowercase();
        let changing_section = key != departing_key;
        // Objects.Save enumerates both active and inactive lists even though
        // a section file decompiles active non-player objects only. Capture
        // the enumerated wrappers for the frozen Objects.txt, then perform
        // native Denumerate immediately so surviving inactive objects keep
        // the same refreshed caches and normalized live pointers.
        let object_enumeration = (changing_section && flags & 2 != 0)
            .then(|| self.enumerate_object_compiler_caches_for_save());
        if let Some(enumeration) = object_enumeration.as_ref() {
            self.denumerate_object_compiler_caches_after_save(enumeration);
        }
        // Capture after Denumerate: preserved objects are restored from this
        // state later in the switch and must not resurrect an off-list live
        // pointer that native Denumerate just cleared. The refreshed number
        // caches survive Denumerate and remain available to Objects.txt.
        let mut state = self.capture_state();
        let saved_landscape_systems =
            (changing_section && flags & 1 != 0).then(|| scenario::ScenarioLandscapeSystems {
                pxs: self.pxs_system.to_c4b().map(|bytes| {
                    pxs::PxsSystem::from_c4b(&bytes)
                        .expect("an engine-produced PXS component must reload")
                }),
                mass_movers: self.mass_movers.to_c4b().map(|bytes| {
                    MassMoverSet::from_c4b(&bytes)
                        .expect("an engine-produced MassMover component must reload")
                }),
            });
        let mut saved_section_landscape =
            (changing_section && flags & 1 != 0).then(|| self.landscape_without_solid_masks());
        if changing_section && flags & 3 != 0 {
            let saved_objects = (flags & 2 != 0).then(|| {
                state
                    .objects
                    .iter()
                    .filter(|object| object.snapshot.status.is_active())
                    .filter(|object| !preserved.contains(&object.snapshot.id))
                    .filter(|object| {
                        !self.is_user_player_object_snapshot(&object.snapshot)
                    })
                    .cloned()
                    .collect::<Vec<_>>()
            });
            let saved_object_ids = saved_objects
                .as_deref()
                .unwrap_or_default()
                .iter()
                .map(|object| object.snapshot.id)
                .collect::<HashSet<_>>();
            let saved_order = (flags & 2 != 0)
                .then(|| {
                    state
                        .object_order
                        .iter()
                        .copied()
                        .filter(|id| saved_object_ids.contains(id))
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            let mut current = self
                .scenario_sections
                .get(&departing_key)
                .cloned()
                .expect("departing section remains registered");
            current.modified = true;
            if flags & 1 != 0 {
                current.landscape_modified = true;
                // C4GameObjects::RemoveSolidMasks runs before a section
                // landscape is persisted. Keep the running raster intact and
                // retain the same native persistence clone used by root
                // saves, including linked runtime-inactive mask survivors.
                current.landscape = saved_section_landscape
                    .take()
                    .expect("landscape-save state captured above");
                if let Some(landscape) = current
                    .landscape
                    .as_mut()
                    .filter(|landscape| landscape.pixel_grid().is_some())
                {
                    // Reloading a section recreates pInitial from the full
                    // saved Surface8. Without this, the next SaveDiff would
                    // compare against the pre-departure scenario baseline.
                    landscape
                        .save_initial()
                        .expect("a present section pixel grid can seed pInitial");
                }
                current.exact_landscape = true;
                current.texmap_lookups.clear();
                current.resynthesize_static_map = false;
                current.s2_overload = None;
                current.map_creator = None;
                // A saved section landscape reloads as ExactLandscape;
                // C++ has no S2 creator or callback masks to replay.
                current.post_init_map_callbacks =
                    map_creator_s2::PostInitMapCallbacks::default();
                if let Some(raster) = current
                    .landscape
                    .as_mut()
                    .and_then(Landscape::raster_state_mut)
                {
                    raster.set_map_creator(None);
                }
                current.scenario_values = self.scenario_values.as_ref().clone();
                current.base_reject_entrance_enabled =
                    self.base_reject_entrance_enabled;
                current.base_extinguish_enabled = self.base_extinguish_enabled;
                current.environment = self.environment;
                current.landscape_systems = saved_landscape_systems
                    .clone()
                    .expect("landscape-save state captured above");
            }
            if let Some(objects) = saved_objects {
                current.objects_modified = true;
                current.saved_objects = Some(objects);
                current.saved_object_order = saved_order;
            }

            // Native LoadScenarioSection writes the departing categories to
            // C4ScenarioSection's temporary group at this exact boundary.
            // Preserve the packed image now; final C4GameSave merely copies
            // it and must not observe any subsequent live-state changes.
            let frozen_group = live_c4_save::freeze_scenario_section(
                self,
                &current,
                flags & 1 != 0,
                flags & 2 != 0,
            )
            .map_err(|error| EngineError::ScenarioSectionSave {
                section: self.current_scenario_section.clone(),
                detail: error.to_string(),
            })?;
            current.frozen_group = Some(frozen_group);
            // The persisted snapshots are only scratch input to Objects.Save.
            // Native deletes the departing live objects after producing the
            // temporary group; retaining these structured copies would keep
            // their C4String references registered outside the raw section.
            current.saved_objects = None;
            current.saved_object_order.clear();
            if flags & 1 != 0 {
                // C4Landscape::Save writes a changed retained Map.bmp before
                // the exact section is reloaded. Exact Init then owns no Map,
                // so clear only the post-freeze in-memory representation.
                if let Some(landscape) = current.landscape.as_mut() {
                    landscape.clear_retained_map();
                }
            }
            self.scenario_sections.insert(departing_key, current);
        }

        let target = self
            .scenario_sections
            .get(&key)
            .cloned()
            .expect("section presence checked above");
        let target_landscape_systems = target.landscape_systems.clone();
        let mut post_init_map_callbacks = map_creator_s2::PostInitMapCallbacks::default();
        let keep_map_creator = target.keep_map_creator;
        let retained = state
            .objects
            .iter()
            .filter(|object| preserved.contains(&object.snapshot.id))
            .cloned()
            .collect::<Vec<_>>();
        let retained_order = state
            .object_order
            .iter()
            .copied()
            .filter(|id| preserved.contains(id))
            .collect::<Vec<_>>();

        // C4Landscape::Init repairs an unset persistent MapSeed before its
        // first FixRandom. The draw is deliberately made on the pre-reset
        // game ledger; FixRandom immediately discards its resulting state.
        if state
            .landscape
            .as_ref()
            .is_some_and(|landscape| landscape.map_seed() == 0)
        {
            let map_seed = self.rng.random(3_133_700);
            if let Some(landscape) = state.landscape.as_mut() {
                landscape.set_map_seed(map_seed);
            }
        }

        // C4Landscape::Init brackets section landscape creation with two
        // unconditional FixRandom calls. RuntimeScenarioSection landscapes
        // are built eagerly with the persistent initial MapSeed, so the
        // prepared-landscape swap below is the corresponding creation span
        // (C4Landscape.cpp:564,579,735; C4Game.cpp:2642-2657).
        let persistent_landscape = state.landscape.as_ref().map(|landscape| {
            (
                landscape.map_seed(),
                landscape.modulation(),
                landscape.mode(),
                landscape
                    .raster_state()
                    .map(landscape::LandscapeRasterState::map_zoom),
                landscape
                    .raster_state()
                    .map(|state| state.texmap().clone()),
                landscape
                    .raster_state()
                    .and_then(landscape::LandscapeRasterState::map_creator)
                    .cloned(),
            )
        });
        self.fix_random();
        state.rng = self.rng.clone();
        let mut landscape_loaded = target.landscape.is_some();
        let mut runtime_s2_handled = false;
        if let Some(spec) = target.s2_overload.as_ref() {
            let live_texmap = persistent_landscape
                .as_ref()
                .and_then(|(_, _, _, _, texmap, _)| texmap.clone())
                .or_else(|| {
                    target
                        .landscape
                        .as_ref()
                        .and_then(Landscape::raster_state)
                        .map(|state| state.texmap().clone())
                });
            if let Some(live_texmap) = live_texmap {
                runtime_s2_handled = true;
                let map_seed = persistent_landscape
                    .as_ref()
                    .map(|(seed, _, _, _, _, _)| *seed)
                    .or_else(|| target.landscape.as_ref().map(Landscape::map_seed))
                    .unwrap_or_default();
                let modulation = persistent_landscape
                    .as_ref()
                    .map(|(_, modulation, _, _, _, _)| *modulation)
                    .or_else(|| target.landscape.as_ref().map(Landscape::modulation))
                    .unwrap_or(0xffff_ffff);
                let previous_mode = persistent_landscape
                    .as_ref()
                    .map(|(_, _, mode, _, _, _)| *mode)
                    .unwrap_or(LANDSCAPE_MODE_UNDEFINED);
                let live_creator = persistent_landscape
                    .as_ref()
                    .and_then(|(_, _, _, _, _, creator)| creator.clone());
                let mut classifier = scenario::MapPixelClassifier::from_runtime_state(live_texmap);
                let creation = {
                    let mut script_algo =
                        |rng: &mut LcgRng, function: &str, args: [i32; 4]| {
                            self.call_map_script_algorithm(rng, function, args)
                        };
                    map_creator_s2::create_s2_map_for_section_with_state_and_functions_with_script_algo(
                        live_creator,
                        &spec.source,
                        &mut classifier,
                        spec.map_width,
                        spec.map_height,
                        spec.map_player_extend,
                        spec.player_count,
                        &mut state.rng,
                        &spec.script_functions,
                        &mut script_algo,
                    )
                };
                // restore_state below installs the pending target section.
                // Keep the live Game.Script mutations made while its map was
                // rendered instead of restoring the pre-render snapshot.
                state.script_globals = self.capture_script_globals();
                let runtime_texmap = classifier.into_runtime_state();
                if let Some(bitmap) = creation.bitmap.as_ref() {
                    let map_zoom = spec.map_zoom.evaluate(&mut state.rng) as u32 as i32;
                    let mut landscape = scenario::classified_landscape(
                        bitmap,
                        &scenario::MapPixelClassifier::from_runtime_state(runtime_texmap),
                        map_zoom,
                        map_seed,
                    )
                    .map_err(|error| {
                        EngineError::InvalidScenarioSectionLandscape(error.to_string())
                    })?;
                    landscape.save_initial().map_err(|error| {
                        EngineError::InvalidScenarioSectionLandscape(error.to_string())
                    })?;
                    if let Some(diff) = spec.diff.as_ref() {
                        landscape.apply_diff(diff).map_err(|error| {
                            EngineError::InvalidScenarioSectionLandscape(error.to_string())
                        })?;
                    }
                    landscape.set_shade_materials(spec.shade_materials);
                    landscape.set_no_scan(spec.no_scan);
                    landscape.set_border_open(
                        spec.left_open,
                        spec.right_open,
                        spec.top_open,
                        spec.bottom_open,
                    );
                    if spec.auto_scan_side_open {
                        landscape.scan_side_open();
                    }
                    landscape.set_modulation(modulation);
                    let mut creator = creation.creator;
                    creator.set_callback_map_zoom(map_zoom);
                    let retained_creator = if keep_map_creator {
                        post_init_map_callbacks = creator.callback_state();
                        Some(creator)
                    } else {
                        None
                    };
                    landscape
                        .raster_state_mut()
                        .expect("classified section landscapes carry raster state")
                        .set_map_creator(retained_creator);
                    let mode = if target.exact_landscape
                        && previous_mode == LANDSCAPE_MODE_UNDEFINED
                    {
                        LANDSCAPE_MODE_EXACT
                    } else {
                        LANDSCAPE_MODE_UNDEFINED
                    };
                    landscape.set_runtime_mode(mode);
                    state.landscape = Some(landscape);
                    landscape_loaded = true;
                } else {
                    landscape_loaded = false;
                    if let Some(landscape) = state.landscape.as_mut() {
                        if !landscape.replace_runtime_texmap_state(runtime_texmap.clone()) {
                            let mut raster = landscape::LandscapeRasterState::new(
                                1,
                                map_seed,
                                runtime_texmap,
                            );
                            raster.set_map_creator(Some(creation.creator));
                            landscape.set_raster_state(raster);
                        } else if let Some(raster) = landscape.raster_state_mut() {
                            raster.set_map_creator(Some(creation.creator));
                        }
                    }
                }
            }
        }
        if !runtime_s2_handled && landscape_loaded {
            state.landscape = target.landscape.clone();
            if let Some(landscape) = state.landscape.as_mut() {
                if let Some((
                    map_seed,
                    modulation,
                    previous_mode,
                    persistent_map_zoom,
                    texmap,
                    live_creator,
                )) = persistent_landscape.clone()
                {
                    landscape.set_map_seed(map_seed);
                    landscape.set_modulation(modulation);
                    if target.exact_landscape {
                        if let Some(raster) = landscape.raster_state_mut() {
                            raster.set_map_zoom(persistent_map_zoom.unwrap_or(0));
                        }
                    }
                    if let Some(texmap) = texmap {
                        if target.texmap_lookups.is_empty() {
                            landscape.replace_runtime_texmap_state_and_repaint(texmap);
                        } else {
                            landscape.merge_runtime_texmap_for_section(
                                texmap,
                                &target.texmap_lookups,
                            );
                        }
                    }
                    if target.resynthesize_static_map {
                        landscape.resynthesize_retained_map_for_section();
                    }
                    let prepared_creator = landscape
                        .raster_state()
                        .and_then(landscape::LandscapeRasterState::map_creator)
                        .cloned()
                        .or_else(|| target.map_creator.clone());
                    let mut creator = if keep_map_creator {
                        match (live_creator, prepared_creator) {
                            (Some(mut live), Some(prepared)) => {
                                live.append_from(&prepared);
                                Some(live)
                            }
                            (Some(live), None) => Some(live),
                            (None, Some(prepared)) => Some(prepared),
                            (None, None) => None,
                        }
                    } else {
                        None
                    };
                    if let Some(creator) = creator.as_mut() {
                        if let Some(map_zoom) = landscape
                            .raster_state()
                            .map(landscape::LandscapeRasterState::map_zoom)
                        {
                            creator.set_callback_map_zoom(map_zoom);
                        }
                        post_init_map_callbacks = creator.callback_state();
                    }
                    if let Some(state) = landscape.raster_state_mut() {
                        state.set_map_creator(creator);
                    }
                    let mode = if target.exact_landscape
                        && previous_mode == LANDSCAPE_MODE_UNDEFINED
                    {
                        LANDSCAPE_MODE_EXACT
                    } else {
                        LANDSCAPE_MODE_UNDEFINED
                    };
                    landscape.set_runtime_mode(mode);
                }
            }
        } else if !runtime_s2_handled {
            let mut prepared_creator = target.map_creator.clone();
            if let Some(landscape) = state.landscape.as_mut() {
                if !target.texmap_lookups.is_empty() {
                    if let Some(remap) = landscape
                        .replay_empty_section_texmap_lookups(&target.texmap_lookups)
                    {
                        if let Some(creator) = prepared_creator.as_mut() {
                            creator.remap_material_colors(&remap);
                        }
                    }
                }
                let live_creator = persistent_landscape
                    .as_ref()
                    .and_then(|(_, _, _, _, _, creator)| creator.clone());
                let creator = match (live_creator, prepared_creator) {
                    (Some(mut live), Some(prepared)) => {
                        live.append_from(&prepared);
                        Some(live)
                    }
                    (Some(live), None) => Some(live),
                    (None, Some(prepared)) => Some(prepared),
                    (None, None) => None,
                };
                if let Some(state) = landscape.raster_state_mut() {
                    state.set_map_creator(creator);
                }
            }
        }
        if let Some(landscape) = state.landscape.as_mut() {
            landscape.set_map_changed();
        }
        state.scenario_values = Some(target.scenario_values.clone());
        state.base_reject_entrance_enabled = Some(target.base_reject_entrance_enabled);
        state.environment = target.environment;
        state.global_effects.clear();
        state.particles.clear();
        state.transfer_zones.clear();
        state.mass_movers.clear();

        state.objects.clear();
        state.objects.extend(retained);
        state.object_order = retained_order;

        self.base_extinguish_enabled = target.base_extinguish_enabled;
        self.restore_state(&state)?;
        match target_landscape_systems.pxs {
            Some(mut pxs) => {
                // C4PXSSystem::Load clears chunks but deliberately leaves the
                // public per-Execute Count ledger unchanged.
                pxs.set_execute_count(departing_pxs.execute_count());
                self.pxs_system = pxs;
            }
            None if landscape_loaded => self.pxs_system.clear(),
            None => self.pxs_system = departing_pxs,
        }
        match target_landscape_systems.mass_movers {
            Some(mass_movers) => self.mass_movers = mass_movers,
            None if landscape_loaded => self.mass_movers.clear(),
            None => self.mass_movers = departing_mass_movers,
        }
        // Objects.Load follows Landscape.Init's second FixRandom. Keep the
        // same boundary before fresh section objects run Construction or
        // Initialize callbacks.
        if landscape_loaded {
            self.fix_random();
            let gravity = self.evaluate_scenario_gravity(target.gravity);
            let mut physics = self.physics;
            physics.set_script_gravity(gravity);
            self.set_physics(physics);
        }
        let target_objects = self.scenario_section_object_spawns(&target)?;
        self.spawn_scenario_section_objects(target_objects)?;
        if !target.no_initialize && landscape_loaded && keep_map_creator {
            self.run_post_init_map_callbacks(&post_init_map_callbacks)?;
        }
        self.current_scenario_section = target.name;
        self.last_scenario_section_flags = Some(flags);
        Ok(true)
    }

    /// C4Object::IsUserPlayerObject: section object saves exclude user crew
    /// and user flags, while script-player objects remain ordinary section
    /// state. Membership is read from the player's exact crew list rather
    /// than the definition's CrewMember capability bit.
    fn is_user_player_object_snapshot(&self, object: &ObjectSnapshot) -> bool {
        self.players.get(&object.owner).is_some_and(|player| {
            !player.is_script_player()
                && (object.definition_id.as_str() == "FLAG"
                    || player.crew().contains(&object.id))
        })
    }

    fn is_script_player_object_snapshot(&self, object: &ObjectSnapshot) -> bool {
        self.players.get(&object.owner).is_some_and(|player| {
            player.is_script_player()
                && (object.definition_id.as_str() == "FLAG"
                    || player.crew().contains(&object.id))
        })
    }

    fn apply_script_player_team(
        &mut self,
        player_id: i32,
        team: Option<i32>,
        generated_team: Option<TeamInfo>,
        color: Option<u32>,
        home_base_material_entries: Option<Vec<(DefinitionId, i32)>>,
        synchronize_hostility: bool,
    ) -> Result<(), EngineError> {
        if let Some(generated_team) = generated_team {
            self.team_last_team_id = self.team_last_team_id.max(generated_team.id);
            if !self
                .teams
                .iter()
                .any(|existing| existing.id == generated_team.id)
            {
                Rc::make_mut(&mut self.teams).push(generated_team);
            }
        }
        if !self.players.contains_key(&player_id) {
            return Ok(());
        }
        self.players
            .get_mut(&player_id)
            .expect("player presence checked above")
            .set_team(team);
        if let Some(color) = color {
            self.set_player_color(player_id, color)?;
        }
        self.recheck_runtime_team_memberships();
        if let Some(material) = home_base_material_entries {
            self.players
                .get_mut(&player_id)
                .expect("player remains present")
                .set_home_base_material_entries(material);
        }
        if synchronize_hostility {
            self.set_player_team_hostility(player_id);
        }
        Ok(())
    }

    /// `C4Player::SetTeamHostility`: a nonzero team makes the switching
    /// player mutually hostile to every player in another team and mutually
    /// allied with every teammate. The writes are silent; SetPlayerTeam's
    /// own callbacks bracket this operation in the synchronous host preview.
    fn set_player_team_hostility(&mut self, player_id: i32) {
        let Some(team) = self.players.get(&player_id).and_then(Player::team) else {
            return;
        };
        let mut relations = self
            .players
            .iter()
            .filter_map(|(&other_id, player)| {
                (other_id != player_id).then_some((other_id, player.team() != Some(team)))
            })
            .collect::<Vec<_>>();
        relations.sort_unstable_by_key(|(other_id, _)| *other_id);
        for (other_id, hostile) in relations {
            if let Some(player) = self.players.get_mut(&player_id) {
                player.set_hostile_towards(other_id, hostile);
            }
            if let Some(other) = self.players.get_mut(&other_id) {
                other.set_hostile_towards(player_id, hostile);
            }
        }
    }

    fn adjust_object_info_experience(
        &mut self,
        object_id: ObjectId,
        link: Option<CrewInfoLink>,
        change: i32,
    ) -> Option<CrewObjectInfo> {
        // The C4ObjectInfo belongs to the player's persistent CrewInfoList
        // independently of the live object pointer. Apply there first so a
        // later Retire/Grab in the same ordered stream retains the change.
        let roster_values = link.and_then(|link| {
            self.crew_rosters
                .get_mut(&link.player_id)
                .and_then(|roster| roster.get_mut(link.roster_index))
                .map(|entry| {
                    let mut info = CrewObjectInfo {
                        definition_id: DefinitionId::from(entry.id.as_str()),
                        name: entry.name.clone(),
                        death_message: entry.death_message.clone(),
                        core: entry.core.clone(),
                        rank: entry.rank,
                        rank_name: entry.rank_name.clone(),
                        experience: entry.experience,
                        participation: entry.participation,
                        rounds: entry.rounds,
                        death_count: entry.death_count,
                        total_playing_time: entry.total_playing_time,
                        birthday: entry.birthday,
                        age: entry.age,
                        in_action_time: entry.in_action_time,
                        extra_data: entry.extra_data.clone(),
                        portraits: entry.portraits.clone(),
                    };
                    let promoted = adjust_crew_experience(&mut info, change);
                    entry.rank = info.rank;
                    entry.experience = info.experience;
                    (info, promoted)
                })
        });

        let live_values = {
            let infos = Rc::make_mut(&mut self.crew_object_infos);
            infos.get_mut(&object_id).map(|info| {
                let promoted = if let Some((roster_info, promoted)) = roster_values.as_ref() {
                    info.rank = roster_info.rank;
                    info.rank_name = roster_info.rank_name.clone();
                    info.experience = roster_info.experience;
                    *promoted
                } else {
                    adjust_crew_experience(info, change)
                };
                (info.clone(), promoted)
            })
        };
        let final_values = live_values.as_ref().or(roster_values.as_ref());
        if let Some((info, _)) = final_values {
            Rc::make_mut(&mut self.crew_ranks).insert(object_id.as_u64(), info.rank);
        }
        final_values
            .filter(|(_, promoted)| *promoted)
            .map(|(info, _)| info.clone())
    }

    fn promotion_rank_name(&self, info: &CrewObjectInfo) -> Option<String> {
        match self
            .definitions
            .get(&info.definition_id)
            .and_then(Definition::rank_names)
        {
            Some(names) => usize::try_from(info.rank)
                .ok()
                .and_then(|rank| names.get(rank))
                .map(|name| name.into_owned()),
            None => {
                compat::default_rank_name(&self.default_rank_names, info.rank).map(str::to_owned)
            }
        }
    }

    fn set_object_info_rank_name(
        &mut self,
        object_id: ObjectId,
        link: Option<CrewInfoLink>,
        rank_name: String,
    ) {
        if let Some(link) = link {
            if let Some(entry) = self
                .crew_rosters
                .get_mut(&link.player_id)
                .and_then(|roster| roster.get_mut(link.roster_index))
            {
                entry.rank_name = rank_name.clone();
            }
        }
        if let Some(info) = Rc::make_mut(&mut self.crew_object_infos).get_mut(&object_id) {
            info.rank_name = rank_name;
        }
    }

    /// Native `C4Object::DoExperience`: mutate the persistent info first,
    /// then run the promotion-only physical and presentation half exactly
    /// once. Script `DoCrewExp` previews those effects in its host scope and
    /// deliberately replays only [`Self::adjust_object_info_experience`].
    fn do_object_experience(&mut self, object_id: ObjectId, change: i32) {
        let link = self.crew_info_links.get(&object_id).copied();
        let Some(mut info) = self.adjust_object_info_experience(object_id, link, change) else {
            return;
        };
        let rank_name = self.promotion_rank_name(&info);
        if let Some(rank_name) = rank_name.as_ref() {
            info.rank_name = rank_name.clone();
            self.set_object_info_rank_name(object_id, link, rank_name.clone());
        }

        let definition_physical = self
            .definitions
            .get(&info.definition_id)
            .map(|definition| *definition.physical())
            .unwrap_or_default();
        if let Some(index) = self.find_object_index(object_id) {
            let physical = self.objects[index]
                .state
                .info_physical
                .unwrap_or(definition_physical);
            self.objects[index].state.info_physical =
                Some(promotion_updated_physical(physical, info.rank, None));
        }

        // An exhausted custom rank table promotes silently and retains the
        // preceding stored rank name; only definitions without a custom table
        // fall back to the game-global rank names.
        let Some(rank_name) = rank_name else {
            return;
        };
        let object_name = self
            .find_object_index(object_id)
            .and_then(|index| self.objects[index].state.custom_name.clone())
            .unwrap_or(info.name);
        self.messages.add_message(MessageSpec {
            kind: message::MessageKind::Target,
            text: format!("{object_name} is promoted|to {rank_name}!"),
            target: Some(object_id),
            player: None,
            offset: Vector2::ZERO,
            color: 0xffff_ffff,
            flags: 0,
            width: None,
            decoration: None,
            frame_decoration: None,
            portrait: None,
        });
        self.pending_audio.push(AudioCommand::PlaySound {
            name: "Trumpet".to_string(),
            target: Some(object_id),
            volume: 100,
            looped: false,
            multiple: false,
            custom_falloff: None,
        });
    }

    fn set_linked_crew_info_physical(&mut self, link: CrewInfoLink, physical: PhysicalInfo) {
        if let Some(entry) = self
            .crew_rosters
            .get_mut(&link.player_id)
            .and_then(|roster| roster.get_mut(link.roster_index))
        {
            entry.physical = physical;
        }
    }

    #[doc(hidden)]
    pub fn apply_player_commands(
        &mut self,
        commands: Vec<PlayerCommand>,
    ) -> Result<(), EngineError> {
        for command in commands {
            match command {
                PlayerCommand::SetDefinitionName {
                    definition_id,
                    name,
                } => {
                    if let Some(definition) = self.definitions.get_mut(&definition_id) {
                        definition.set_name(name);
                        self.definition_metadata_cache.borrow_mut().take();
                    }
                }
                PlayerCommand::SetCrewInfoName {
                    object_id,
                    link,
                    name,
                } => {
                    if let Some(link) = link {
                        if let Some(entry) = self
                            .crew_rosters
                            .get_mut(&link.player_id)
                            .and_then(|roster| roster.get_mut(link.roster_index))
                        {
                            entry.name = name.clone();
                        }
                    }
                    if let Some(info) =
                        Rc::make_mut(&mut self.crew_object_infos).get_mut(&object_id)
                    {
                        info.name = name;
                    }
                }
                PlayerCommand::SetCrewInfoPortrait {
                    object_id,
                    link,
                    portraits,
                } => {
                    if let Some(link) = link {
                        if let Some(entry) = self
                            .crew_rosters
                            .get_mut(&link.player_id)
                            .and_then(|roster| roster.get_mut(link.roster_index))
                        {
                            entry.portraits = portraits.clone();
                        }
                    }
                    if let Some(info) =
                        Rc::make_mut(&mut self.crew_object_infos).get_mut(&object_id)
                    {
                        info.portraits = portraits;
                    }
                }
                PlayerCommand::SetCrewExtraData {
                    object_id,
                    link,
                    name,
                    value,
                } => {
                    let write_slot = |slots: &mut Vec<(String, Value)>| match slots
                        .iter_mut()
                        .find(|(slot, _)| *slot == name)
                    {
                        Some((_, stored)) => *stored = value.clone(),
                        None => slots.push((name.clone(), value.clone())),
                    };
                    if let Some(link) = link {
                        if let Some(entry) = self
                            .crew_rosters
                            .get_mut(&link.player_id)
                            .and_then(|roster| roster.get_mut(link.roster_index))
                        {
                            write_slot(&mut entry.extra_data);
                        }
                    }
                    if let Some(info) =
                        Rc::make_mut(&mut self.crew_object_infos).get_mut(&object_id)
                    {
                        write_slot(&mut info.extra_data);
                    }
                }
                PlayerCommand::SetCrewInfoPhysical { link, physical } => {
                    self.set_linked_crew_info_physical(link, physical);
                }
                PlayerCommand::LoadScenarioSection {
                    name,
                    flags,
                    preserve_ids,
                } => {
                    let _ = self.load_scenario_section(&name, flags, preserve_ids)?;
                }
                PlayerCommand::AddEvaluationData {
                    player_info_id,
                    text,
                } => {
                    self.round_results
                        .add_custom_evaluation_string(&text, player_info_id);
                }
                PlayerCommand::HideSettlementScore { hide } => {
                    self.round_results.hide_settlement_score = hide;
                }
                PlayerCommand::SetLeaguePerformance {
                    score,
                    player_info_id,
                } => {
                    self.round_results
                        .set_league_performance(score, player_info_id);
                }
                PlayerCommand::SetLeagueProgressData {
                    player_info_id,
                    data,
                } => {
                    let data = data.map(legacy_c_string_bytes);
                    Rc::make_mut(&mut self.player_info_league_progress_data)
                        .insert(player_info_id, data.clone());
                    self.player_info_league_progress_updates
                        .push((player_info_id, data));
                }
                PlayerCommand::SetRestoreInfos { what } => {
                    self.restart_restore_info_mask = what;
                }
                PlayerCommand::SetMaxPlayer { max_players } => {
                    self.max_players = Some(max_players);
                }
                PlayerCommand::AddMessageBoardCommand { command } => {
                    let _ = self.add_message_board_command(command);
                }
                PlayerCommand::CallMessageBoard { player_id, query } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.call_message_board(query);
                    }
                }
                PlayerCommand::AbortMessageBoard { player_id, target } => {
                    if self
                        .active_message_board_input
                        .as_ref()
                        .is_some_and(|input| input.player == player_id && input.target == target)
                    {
                        self.active_message_board_input = None;
                    }
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.remove_message_board_query(target);
                    }
                }
                PlayerCommand::RemoveMessageBoardQuery { player_id, target } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.remove_message_board_query(target);
                    }
                }
                PlayerCommand::ActivateGameGoalMenu {
                    player_id,
                    open_menu,
                } => {
                    let (goals, fulfilled_goals) =
                        self.evaluate_goals_for_player(player_id)?;
                    self.pending_game_goal_menu_requests
                        .push(GameGoalMenuRequest {
                            player: player_id,
                            goals,
                            fulfilled_goals,
                            open_menu: open_menu && !self.replay_control,
                        });
                }
                PlayerCommand::SetPlayerTeam {
                    player_id,
                    team,
                    generated_team,
                    color,
                    home_base_material_entries,
                    synchronize_hostility,
                } => {
                    self.apply_script_player_team(
                        player_id,
                        team,
                        generated_team,
                        color,
                        home_base_material_entries,
                        synchronize_hostility,
                    )?;
                }
                PlayerCommand::InitScenarioPlayer { player_id, team } => {
                    let _ = self.initialize_scenario_player(player_id, team)?;
                }
                PlayerCommand::SetCrewRosters { rosters } => {
                    for (player_id, crew) in rosters {
                        if let Some(player) = self.players.get_mut(&player_id) {
                            player.set_crew(crew);
                        }
                    }
                }
                PlayerCommand::RetireCrewInfo { object_id, link } => {
                    if let Some(entry) = self
                        .crew_rosters
                        .get_mut(&link.player_id)
                        .and_then(|roster| roster.get_mut(link.roster_index))
                    {
                        // C4ObjectInfo::Retire is idempotent and accrues only
                        // the current active stint.
                        if entry.in_action {
                            entry.total_playing_time = entry
                                .total_playing_time
                                .wrapping_add(self.game_time.wrapping_sub(entry.in_action_time));
                            entry.in_action = false;
                        }
                    }
                    if self.crew_info_links.get(&object_id) == Some(&link) {
                        Rc::make_mut(&mut self.crew_info_links).remove(&object_id);
                        Rc::make_mut(&mut self.crew_object_infos).remove(&object_id);
                        Rc::make_mut(&mut self.crew_ranks).remove(&object_id.as_u64());
                    }
                }
                PlayerCommand::LinkCrewInfo {
                    object_id,
                    link,
                    mut info,
                    created_entry,
                    recruit,
                    has_died,
                } => {
                    let recruited_rank_name = recruit.then(|| {
                        self.recruit_rank_name(
                            &info.definition_id,
                            info.rank,
                            &info.rank_name,
                        )
                    });
                    if let Some(link) = link {
                        let roster = self.crew_rosters.entry(link.player_id).or_default();
                        let mut created = false;
                        if let Some(entry) = created_entry {
                            if link.roster_index == roster.len() {
                                roster.push(entry);
                                created = true;
                            } else if link.roster_index < roster.len() {
                                roster[link.roster_index] = entry;
                            }
                        }
                        if created {
                            let order =
                                self.crew_info_order
                                    .entry(link.player_id)
                                    .or_insert_with(|| {
                                        (0..roster.len())
                                            .filter(|index| *index != link.roster_index)
                                            .collect()
                                    });
                            order.retain(|index| *index != link.roster_index);
                            order.insert(0, link.roster_index);
                            if let Some(player) = self.players.get_mut(&link.player_id) {
                                player.increment_crew_created();
                            }
                        }
                        if let Some(entry) = roster.get_mut(link.roster_index) {
                            entry.has_died = has_died;
                            if recruit && !entry.in_action {
                                entry.in_action = true;
                                entry.was_in_action = true;
                                entry.in_action_time = self.game_time;
                                if let Some(rank_name) = recruited_rank_name.as_ref() {
                                    entry.rank_name = rank_name.clone();
                                }
                            }
                            info.definition_id = DefinitionId::from(entry.id.as_str());
                            info.name = entry.name.clone();
                            info.death_message = entry.death_message.clone();
                            info.core = entry.core.clone();
                            info.rank = entry.rank;
                            info.rank_name = entry.rank_name.clone();
                            info.experience = entry.experience;
                            info.participation = entry.participation;
                            info.rounds = entry.rounds;
                            info.death_count = entry.death_count;
                            info.total_playing_time = entry.total_playing_time;
                            info.birthday = entry.birthday;
                            info.age = entry.age;
                            info.in_action_time = entry.in_action_time;
                            info.extra_data = entry.extra_data.clone();
                            info.portraits = entry.portraits.clone();
                        }
                        Rc::make_mut(&mut self.crew_info_links).insert(object_id, link);
                    } else {
                        Rc::make_mut(&mut self.crew_info_links).remove(&object_id);
                    }
                    Rc::make_mut(&mut self.crew_object_infos).insert(object_id, info.clone());
                    Rc::make_mut(&mut self.crew_ranks).insert(object_id.as_u64(), info.rank);
                }
                PlayerCommand::AdjustCrewExperience {
                    object_id,
                    link,
                    change,
                } => {
                    if let Some(info) =
                        self.adjust_object_info_experience(object_id, link, change)
                    {
                        if let Some(rank_name) = self.promotion_rank_name(&info) {
                            self.set_object_info_rank_name(object_id, link, rank_name);
                        }
                    }
                }
                PlayerCommand::AdjustCrewControlCount { link, gain } => {
                    self.adjust_crew_info_control_count(link, gain);
                }
                PlayerCommand::AdjustHomeBaseMaterial {
                    player_id,
                    definition_id,
                    delta,
                } => {
                    self.adjust_player_home_base_material(player_id, definition_id, delta)?;
                }
                PlayerCommand::SyncHomeBaseMaterialToTeam { player_id } => {
                    self.sync_team_home_base_from_player(player_id);
                }
                PlayerCommand::AdjustHomeBaseProduction {
                    player_id,
                    definition_id,
                    delta,
                } => {
                    self.adjust_player_home_base_production(player_id, definition_id, delta)?;
                }
                PlayerCommand::GrantKnowledge {
                    player_id,
                    definition_id,
                } => {
                    self.grant_player_knowledge(player_id, definition_id)?;
                }
                PlayerCommand::RevokeKnowledge {
                    player_id,
                    definition_id,
                } => {
                    self.revoke_player_knowledge(player_id, &definition_id)?;
                }
                PlayerCommand::GrantMagic {
                    player_id,
                    definition_id,
                } => {
                    self.grant_player_magic(player_id, definition_id)?;
                }
                PlayerCommand::RevokeMagic {
                    player_id,
                    definition_id,
                } => {
                    self.revoke_player_magic(player_id, &definition_id)?;
                }
                PlayerCommand::SetCursor {
                    player_id,
                    object,
                    control,
                } => {
                    // FnSetCursor's callbacks and SelectCrew branch already
                    // ran synchronously inside the host context. This fold
                    // persists cursor/control metadata only; cursor-only
                    // calls must never imply C4Object::Select. Do not repeat
                    // FnSetCursor's object validation here: CreateObject is
                    // live synchronously in C++, while Rust materializes its
                    // already-validated SpawnConfig later in this outcome.
                    // Dragon Rock's Redefine3 sets the cursor to exactly such
                    // a fresh replacement before the spawn queue is folded.
                    let selection = self.crew_selection.entry(player_id).or_default();
                    selection.cursor = object;
                    if selection.is_empty() {
                        self.crew_selection.remove(&player_id);
                    }
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.set_cursor(object);
                        player.control = control;
                    }
                }
                PlayerCommand::SetViewCursor { player_id, object } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.set_view_cursor(object);
                    }
                }
                PlayerCommand::SetPlrView { player_id, object } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.set_view_target(object);
                    }
                }
                PlayerCommand::ClearObjectPointers { object } => {
                    if self
                        .active_message_board_input
                        .as_ref()
                        .is_some_and(|input| input.target == Some(object))
                    {
                        self.active_message_board_input = None;
                    }
                    let owners = self.player_ids_in_order();
                    for owner in owners {
                        let removed_cursor = self.crew_cursor(owner) == Some(object);
                        if removed_cursor {
                            if let Some(selection) = self.crew_selection.get_mut(&owner) {
                                selection.set_cursor(None);
                            }
                            if self
                                .crew_selection
                                .get(&owner)
                                .is_some_and(CrewSelection::is_empty)
                            {
                                self.crew_selection.remove(&owner);
                            }
                        }
                        if let Some(player) = self.players.get_mut(&owner) {
                            player.clear_object_pointers(object);
                        }
                        self.remove_from_roles(owner, object);
                        if removed_cursor {
                            self.player_adjust_cursor_command(owner)?;
                        }
                    }
                }
                PlayerCommand::ClearPlayerObjectPointersWithoutAdjust { player_id, object } => {
                    if self.crew_cursor(player_id) == Some(object) {
                        if let Some(selection) = self.crew_selection.get_mut(&player_id) {
                            selection.set_cursor(None);
                        }
                        if self
                            .crew_selection
                            .get(&player_id)
                            .is_some_and(CrewSelection::is_empty)
                        {
                            self.crew_selection.remove(&player_id);
                        }
                    }
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.clear_object_pointers(object);
                    }
                    self.remove_from_roles(player_id, object);
                }
                PlayerCommand::ClearLastPlrCom { player_id } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.control.last_com = 0;
                        player.control.last_com_down_double = 0;
                    }
                }
                PlayerCommand::SetWealth {
                    player_id,
                    value,
                    show_change,
                } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.set_wealth(value);
                        if show_change {
                            player.arm_view_wealth();
                        }
                    }
                }
                PlayerCommand::AdjustPoints { player_id, delta } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.adjust_points(delta);
                    }
                }
                PlayerCommand::Eliminate { player_id } => {
                    if self
                        .players
                        .get_mut(&player_id)
                        .is_some_and(|player| player.eliminate())
                    {
                        self.eliminated_crew_owners.insert(player_id);
                    }
                }
                PlayerCommand::Surrender { player_id } => {
                    if self.players.contains_key(&player_id) {
                        self.set_player_surrendered(player_id, true)?;
                    }
                }
                PlayerCommand::Remove { player_id } => {
                    self.pending_remove_player_controls
                        .push(RemovePlayerControlData {
                            player: player_id,
                            disconnected: false,
                            by_client: 0,
                        });
                }
                PlayerCommand::SetFogOfWar { player_id, enabled } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.set_fog_of_war(enabled);
                    }
                }
                PlayerCommand::SetShowControlPosition {
                    player_id,
                    position,
                } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.show_control_position = position;
                    }
                }
                PlayerCommand::SetShowControl { player_id, mask } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.show_control = mask;
                    }
                }
                PlayerCommand::SetShowCommand { player_id, command } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.set_flash_command(command);
                        self.show_commands_requests.request_enable();
                    }
                }
                PlayerCommand::SetHostility {
                    player_id,
                    opponent,
                    hostile,
                } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        player.set_hostile_towards(opponent, hostile);
                    }
                }
                // FnSetPlrExtraData (C4Script.cpp:4712-4730): update in
                // place, or append preserving the names-list order.
                PlayerCommand::SetExtraData {
                    player_id,
                    name,
                    value,
                } => {
                    if let Some(player) = self.players.get_mut(&player_id) {
                        match player
                            .extra_data
                            .iter_mut()
                            .find(|(slot, _)| *slot == name)
                        {
                            Some((_, stored)) => *stored = value,
                            None => player.extra_data.push((name, value)),
                        }
                    }
                }
            }
        }
        Ok(())
    }

    fn sync_team_home_base_for(&mut self, id: i32) {
        if !self.team_home_base_rule {
            return;
        }
        let (team, player_info_id) = match self.players.get(&id) {
            Some(player) => match player.team() {
                Some(team) => (team, player.player_info_id()),
                None => return,
            },
            None => return,
        };
        let captain_id = self
            .teams
            .iter()
            .find(|candidate| candidate.id == team)
            .and_then(|team| team.player_ids.first().copied())
            .and_then(|captain_info_id| {
                if captain_info_id == player_info_id {
                    return None;
                }
                self.players
                    .values()
                    .find(|player| player.player_info_id() == captain_info_id)
                    .map(Player::id)
            })
            .or_else(|| {
                let has_player_info_order = self
                    .teams
                    .iter()
                    .find(|candidate| candidate.id == team)
                    .is_some_and(|team| !team.player_ids.is_empty());
                if has_player_info_order {
                    None
                } else {
                    self.runtime_team_members_in_order(team)
                        .into_iter()
                        .next()
                        .filter(|captain| *captain != id)
                }
            });
        let Some(material) = captain_id.and_then(|captain| {
            self.players
                .get(&captain)
                .map(|player| player.home_base_material_entries().to_vec())
        }) else {
            return;
        };
        if let Some(player) = self.players.get_mut(&id) {
            player.set_home_base_material_entries(material);
        }
    }

    /// `C4Player::SyncHomebaseMaterialToTeam`: a runtime mutation propagates
    /// the mutating player's complete ordered list, even when that player is
    /// not the team's first member (C4Player.cpp:2335-2349).
    fn sync_team_home_base_from_player(&mut self, id: i32) {
        if !self.team_home_base_rule {
            return;
        }
        let Some((team, material)) = self.players.get(&id).and_then(|player| {
            player
                .team()
                .map(|team| (team, player.home_base_material_entries().to_vec()))
        }) else {
            return;
        };
        for (&member_id, member) in &mut self.players {
            if member_id != id && member.team() == Some(team) {
                member.set_home_base_material_entries(material.clone());
            }
        }
    }

    fn runtime_team_order_id(player: &Player) -> i32 {
        let info_id = player.player_info_id();
        if info_id > 0 { info_id } else { player.id() }
    }

    /// Mirrors `C4Team::RecheckPlayers`: retain configured/persisted order,
    /// remove a live player-info ID that changed teams, then append newly
    /// observed IDs in PlayerInfo order. IDs without a current runtime
    /// player remain because `GetFirstActivePlayerID` skips them at lookup.
    fn recheck_runtime_team_memberships(&mut self) {
        let mut live = self
            .players
            .values()
            .map(|player| (Self::runtime_team_order_id(player), player.team()))
            .collect::<Vec<_>>();
        live.sort_unstable_by_key(|(info_id, _)| *info_id);
        let live_teams = live.iter().copied().collect::<HashMap<_, _>>();
        for team in Rc::make_mut(&mut self.teams) {
            let team_id = team.id;
            team.player_ids.retain(|info_id| {
                live_teams
                    .get(info_id)
                    .is_none_or(|runtime_team| *runtime_team == Some(team_id))
            });
            for (info_id, _) in live
                .iter()
                .copied()
                .filter(|(_, runtime_team)| *runtime_team == Some(team_id))
            {
                if !team.player_ids.contains(&info_id) {
                    team.player_ids.push(info_id);
                }
            }
        }
    }

    /// Resolves the ordered player-info membership to current runtime player
    /// numbers. These number spaces diverge after savegame recreation.
    fn runtime_team_members_in_order(&self, team_id: i32) -> Vec<i32> {
        let mut live = self
            .players
            .values()
            .filter(|player| player.team() == Some(team_id))
            .map(|player| (Self::runtime_team_order_id(player), player.id()))
            .collect::<Vec<_>>();
        live.sort_unstable();

        let mut ordered = Vec::with_capacity(live.len());
        if let Some(team) = self.teams.iter().find(|team| team.id == team_id) {
            for info_id in &team.player_ids {
                if let Some(index) = live.iter().position(|(id, _)| id == info_id) {
                    ordered.push(live.remove(index).1);
                }
            }
        }
        ordered.extend(live.into_iter().map(|(_, number)| number));
        ordered
    }

    fn sync_team_home_base_group(&mut self, team: i32) {
        if !self.team_home_base_rule {
            return;
        }
        let members = self.runtime_team_members_in_order(team);
        if members.len() <= 1 {
            return;
        }
        let leader_id = members[0];
        let material = match self.players.get(&leader_id) {
            Some(leader) => leader.home_base_material_entries().to_vec(),
            None => return,
        };
        for member_id in members.into_iter().skip(1) {
            if let Some(member) = self.players.get_mut(&member_id) {
                member.set_home_base_material_entries(material.clone());
            }
        }
    }

    fn prune_selection(&mut self) {
        self.prune_roles();
        let listed: HashSet<ObjectId> = self
            .players
            .values()
            .flat_map(|player| player.crew().iter().copied())
            .collect();
        for object in &mut self.objects {
            let member = if self.players.is_empty() {
                object.state.crew_member
            } else {
                listed.contains(&object.id)
                    || (!self.players.contains_key(&object.state.owner)
                        && object.state.crew_member)
            };
            if !member || object.destroyed || object.state.status == ObjectStatus::Deleted {
                object.state.selected = false;
            }
        }

        // C4Player::Cursor is an enumerated object pointer, not restricted
        // to the Crew list: SetCursor deliberately installs helper objects
        // such as AIMR/SELR/CBMU while their owning clonk is deselected
        // (C4Script.cpp:2943-2963; C4Player.cpp:1745,1784-1792). Object
        // selection flags remain crew-only above, but prune Cursor only when
        // its object pointer is gone. Inactive objects remain valid pointers.
        let active: HashSet<ObjectId> = self
            .objects
            .iter()
            .filter(|object| !object.destroyed && object.state.status != ObjectStatus::Deleted)
            .map(|object| object.id)
            .collect();
        self.crew_selection.retain(|_, selection| {
            selection.prune(&active);
            !selection.is_empty()
        });
        self.sync_all_player_cursors();
    }

    fn prune_roles(&mut self) {
        if self.crew_roles.is_empty() {
            return;
        }

        let existing: HashSet<ObjectId> = self
            .objects
            .iter()
            .filter(|object| !object.destroyed && object.state.status != ObjectStatus::Deleted)
            .map(|object| object.id)
            .collect();
        let mut valid: HashMap<i32, HashSet<ObjectId>> = self
            .players
            .iter()
            .map(|(&player_id, player)| {
                (
                    player_id,
                    player
                        .crew()
                        .iter()
                        .copied()
                        .filter(|object| existing.contains(object))
                        .collect(),
                )
            })
            .collect();
        for object in &self.objects {
            if !self.players.contains_key(&object.state.owner)
                && object.state.crew_member
                && object.state.status.is_active()
                && !object.destroyed
            {
                valid
                    .entry(object.state.owner)
                    .or_default()
                    .insert(object.id);
            }
        }

        self.crew_roles.retain(|owner, assignments| {
            let roster = valid.get(owner);
            assignments
                .retain(|object_id, _| roster.is_some_and(|roster| roster.contains(object_id)));
            !assignments.is_empty()
        });
    }

    fn resolve_command_targets(&self, owner: i32, target: &CrewCommandTarget) -> Vec<ObjectId> {
        match target {
            CrewCommandTarget::Cursor => self.crew_cursor(owner).into_iter().collect(),
            CrewCommandTarget::Selection => self.selected_crew(owner),
            CrewCommandTarget::Role(role) => self
                .crew_roles
                .get(&owner)
                .map(|assignments| {
                    assignments
                        .iter()
                        .filter_map(|(&object_id, assigned)| {
                            if assigned == role {
                                Some(object_id)
                            } else {
                                None
                            }
                        })
                        .collect()
                })
                .unwrap_or_default(),
        }
    }

    /// One-time compatibility import for fixtures/old saves that carry only
    /// the Rust union membership bit. Once a Player exists its ordered Crew
    /// list is authoritative, so steady-state refresh never repeats this.
    fn bootstrap_player_crew_from_union(&mut self, player_id: i32) {
        let already_has_roster = self
            .players
            .get(&player_id)
            .is_some_and(|player| !player.crew().is_empty());
        if already_has_roster {
            return;
        }
        let crew = self
            .exec_list
            .iter()
            .rev()
            .copied()
            .filter(|object_id| {
                self.find_object_index(*object_id).is_some_and(|index| {
                    let object = &self.objects[index];
                    object.state.owner == player_id
                        && object.state.crew_member
                        && !object.destroyed
                        && object.state.status != ObjectStatus::Deleted
                })
            })
            .collect();
        if let Some(player) = self.players.get_mut(&player_id) {
            player.set_crew(crew);
        }
    }

    fn crew_insert_position(&self, roster: &[ObjectId], target: ObjectId) -> usize {
        let Some(target_index) = self.find_object_index(target) else {
            return roster.len();
        };
        let object = &self.objects[target_index];
        if self
            .definitions
            .get(&object.definition_id)
            .is_some_and(|definition| definition.line() != 0)
        {
            return roster.len();
        }
        let category = object.state.category;
        let sort_category = category & CATEGORY_SORT_LIMIT;
        if category & CATEGORY_STATIC_BACK == 0 {
            if let Some(position) = roster.iter().position(|other| {
                self.find_object_index(*other).is_some_and(|other_index| {
                    let other = &self.objects[other_index];
                    other.state.category & CATEGORY_SORT_LIMIT == sort_category
                        && other.definition_id == object.definition_id
                })
            }) {
                return position;
            }
        }
        roster
            .iter()
            .position(|other| {
                self.find_object_index(*other).is_some_and(|other_index| {
                    self.objects[other_index].state.category & CATEGORY_SORT_LIMIT
                        <= sort_category
                })
            })
            .unwrap_or(roster.len())
    }

    /// Preserve the ordered C4Player::Crew lists as authoritative pointers.
    /// Inactive and dead objects remain linked exactly like C++; only a gone
    /// object pointer is pruned. The return value is raw CrewCnt>0 by player.
    fn refresh_elimination_state(&mut self) -> HashSet<i32> {
        let mut nonempty = HashSet::new();
        if self.objects.is_empty() && self.known_crew_owners.is_empty() && self.players.is_empty() {
            return nonempty;
        }

        if self.players.is_empty() {
            for object in &self.objects {
                if object.state.crew_member
                    && object.state.owner != OWNER_NONE
                    && !object.destroyed
                    && object.state.status != ObjectStatus::Deleted
                {
                    self.known_crew_owners.insert(object.state.owner);
                    if object.state.status.is_active() && object.state.alive {
                        nonempty.insert(object.state.owner);
                    }
                }
            }
            return nonempty;
        }

        let player_ids: Vec<i32> = self.players.keys().copied().collect();
        let mut listed = HashSet::new();
        for player_id in &player_ids {
            let existing = self
                .players
                .get(player_id)
                .map(|player| player.crew().to_vec())
                .unwrap_or_default();
            let mut seen = HashSet::new();
            let retained = existing
                .into_iter()
                .filter(|id| {
                    seen.insert(*id)
                        && self.find_object_index(*id).is_some_and(|index| {
                            let object = &self.objects[index];
                            !object.destroyed && object.state.status != ObjectStatus::Deleted
                        })
                })
                .collect::<Vec<_>>();
            listed.extend(retained.iter().copied());
            if !retained.is_empty() {
                self.known_crew_owners.insert(*player_id);
                nonempty.insert(*player_id);
            }
            if let Some(player) = self.players.get_mut(player_id) {
                player.set_crew(retained);
            }
        }

        // Rust retains a compatibility union bit for older snapshots and
        // host fixtures. Keep it derived from the live per-player links;
        // never use it to reconstruct a removed link during steady state.
        for object in &mut self.objects {
            if object.state.status != ObjectStatus::Deleted {
                if listed.contains(&object.id) {
                    object.state.crew_member = true;
                } else if self.players.contains_key(&object.state.owner) {
                    object.state.crew_member = false;
                }
            }
        }
        nonempty
    }

    /// C4Object::Stabilize (C4Movement.cpp:488-516): a tilt within
    /// ±StableRange (±10, C4Physics.h:23, normalized to ±180) snaps
    /// upright when the rotation-0 shape stands contact-free at the
    /// current position; any contact keeps the tilt. NoStabilize defs opt
    /// out (:491). The upright probe is the ordinary ContactCheck, including
    /// Contact* callback dispatch for ContactCalls definitions (:503).
    fn stabilize_object(
        &mut self,
        idx: usize,
        solid_mask_indices: &[usize],
    ) -> Result<(), EngineError> {
        let rotation = self.objects[idx].state.rotation;
        // C++ repeatedly folds arbitrary saved/scripted angles into
        // [-180, 180] (C4Movement.cpp:493-494). `% 360` plus one boundary
        // adjustment is equivalent without a potentially huge loop.
        let mut signed = rotation % 360;
        if signed < -180 {
            signed += 360;
        } else if signed > 180 {
            signed -= 360;
        }
        if signed == 0 || !(-math::STABLE_RANGE..=math::STABLE_RANGE).contains(&signed) {
            return Ok(());
        }
        let no_stabilize = self
            .definitions
            .get(&self.objects[idx].definition_id)
            .is_some_and(Definition::no_stabilize);
        // C4Shape::ContactDensity is live object state. C4Object::Stabilize
        // probes Shape.CheckContact after SetContactDensity mutations
        // (C4Movement.cpp:488-516; C4Shape.cpp:495-510).
        let contact_density = self.objects[idx].state.contact_density;
        if no_stabilize {
            return Ok(());
        }
        let upright_vertices = self.objects[idx].unrotated_shape_vertices();
        let original_vertices = self.objects[idx].state.vertices.clone();
        let original_shape_vertices = self.objects[idx].state.shape_vertices.clone();
        let original_shape_rect = self.objects[idx].shape_rect;
        let original_fire_top = self.objects[idx].shape_fire_top;
        let original_shape_override = self.objects[idx].state.shape_override;
        let original_vertex_contacts = self.objects[idx].frame_vertex_contacts.clone();
        let original_shape_contact_cnat = self.objects[idx].frame_shape_contact_cnat;
        let original_shape_contact_count = self.objects[idx].frame_shape_contact_count;
        let object_id = self.objects[idx].id;
        let position = self.objects[idx].state.position;
        // C++ temporarily writes r=0 and UpdateShape() before ContactCheck,
        // so the callback observes the upright rotation and vertices. fix_r
        // is left untouched unless stabilization succeeds (:498-514).
        self.objects[idx].state.rotation = 0;
        self.objects[idx].refresh_shape_geometry();
        debug_assert_eq!(self.objects[idx].state.vertices, upright_vertices);
        let contact = self
            .landscape
            .as_ref()
            .map(|landscape| {
                let solid_masks = self.solid_masks_for_movement(solid_mask_indices);
                shape_contact_check(
                    &self.objects[idx].state.vertices,
                    position,
                    landscape,
                    &self.materials,
                    &solid_masks,
                    None,
                    contact_density,
                )
            })
            .unwrap_or_default();
        // ContactCheck always overwrites t_contact, including with zero,
        // before it dispatches Contact* callbacks (C4Movement.cpp:166-182).
        self.objects[idx].latch_shape_contact(&contact);
        if contact.is_contact() {
            self.dispatch_contact_callbacks(idx, MovementContactDispatch::ShapeProbe)?;
        }
        if let Some(index) = self.find_object_index(object_id) {
            if self.objects[index].frame_shape_contact_count != 0 {
                // ContactCheck rejected the trial: restore exactly Shape and
                // integer r. Callback changes to other fields (including
                // fix_r) remain live, matching C++'s two assignments (:505-508).
                self.objects[index].state.vertices = original_vertices;
                self.objects[index].state.shape_vertices = original_shape_vertices;
                self.objects[index].shape_rect = original_shape_rect;
                self.objects[index].shape_fire_top = original_fire_top;
                self.objects[index].state.shape_override = original_shape_override;
                self.objects[index].frame_vertex_contacts = original_vertex_contacts;
                self.objects[index].frame_shape_contact_cnat = original_shape_contact_cnat;
                self.objects[index].frame_shape_contact_count = original_shape_contact_count;
                self.objects[index].state.rotation = rotation;
            } else {
                self.objects[index].fixed_rotation = C4Fixed::ZERO;
            }
        }
        Ok(())
    }

    /// C4Object::CopyMotion (C4Movement.cpp:518-529), run for contained
    /// objects by ExecMovement (:556-561): copy the container's integer
    /// position (resorting sectors on change), snap fix_x/fix_y to
    /// itofix(x/y) and copy the container's dirs.
    fn copy_motion_from_container(&mut self, idx: usize) {
        let Some(container_idx) = self.objects[idx]
            .state
            .container
            .and_then(|container_id| self.find_object_index(container_id))
        else {
            return;
        };
        let (position, fixed_velocity) = {
            let container = &self.objects[container_idx];
            (container.state.position, container.fixed_velocity)
        };
        let moved = {
            let object = &mut self.objects[idx];
            let moved = object.state.position != position;
            object.state.position = position;
            object.fixed_position = FixedVec2::new(itofix(position.x), itofix(position.y));
            object.fixed_velocity = fixed_velocity;
            object.state.velocity = object.velocity_pixels();
            moved
        };
        if moved {
            self.update_sector_for_index(idx);
        }
    }

    /// The Mobile leg of C4Object::ExecMovement - DoMovement plus the
    /// tail C++ runs inside it: the InLiquid update
    /// (C4Movement.cpp:443-460), ContactAction/NoAttachAction dispatch
    /// (:463-470) and the Hit* calls (:472-478). Reports both whether the
    /// object survived and whether positional integration reached DoMotion;
    /// only the latter restores a moving mask's attachment backup
    /// (C4Movement.cpp:121-126,443-445).
    #[doc(hidden)]
    pub fn exec_object_movement(
        &mut self,
        idx: usize,
        _action_library: &ActionLibrary,
        definition_id: &DefinitionId,
        solid_mask_indices: &[usize],
    ) -> Result<ExecMovementOutcome, EngineError> {
        // C4Object::DoMovement resets the displacement cache before any
        // restriction, collision probe, or DoMotion call.
        self.objects[idx].motion_x = 0;
        self.objects[idx].motion_y = 0;
        // C4Object::DoMovement applies Def->NoHorizontalMove before DigFree
        // predicts its target and before the old dirs for Hit* are captured
        // (C4Movement.cpp:224-251).
        let no_horizontal_move = self
            .definitions
            .get(&self.objects[idx].definition_id)
            .map(Definition::no_horizontal_move)
            .unwrap_or(0);
        if no_horizontal_move != 0 {
            let object = &mut self.objects[idx];
            object.fixed_velocity.x = C4Fixed::ZERO;
            object.refresh_velocity_from_fixed();
        }
        self.apply_dig_procedure(idx, definition_id);
        // DoMovement snapshots post-action dirs for Hit* arguments but gates
        // the callbacks with the already-cached OCF field; command/action
        // mutations may have refreshed that cache without making its clock
        // identical to the dirs (C4Movement.cpp:250-252,477-483).
        let old_movement_velocity = self.objects[idx].fixed_velocity;
        let old_movement_hit_flags = self.objects[idx].state.ocf;
        let layer_bounds = self.layer_movement_bounds_for(idx);
        let movement_live = Cell::new(movement_live_config_for(
            &self.objects[idx],
            &self.definitions,
            layer_bounds,
        ));
        let solid_masks = self.solid_masks_for_movement(solid_mask_indices);
        let object_id = self.objects[idx].id;
        let movement = MovementContactConfig {
            live: &movement_live,
            solid_masks: &solid_masks,
            object_id,
        };
        // The contact-callback closure below early-outs unless the def sets
        // ContactCalls=1 (rare). Keep the immutable definition borrowed from
        // the definitions field: cloning it also cloned its pristine script
        // AST and action tables for every moving ContactCalls object, even on
        // frames with no contact.
        let mut contact_rng = self.rng.clone();
        let mut contact_audio = self.audio_registry.clone();
        let mut contact_next_object_id = self.next_object_id;
        let contact_global_effects = self.global_effects.clone();
        // C++ calls Contact* directly against the live game. Build our
        // snapshot adapter only if movement discovers a real contact and a
        // matching callback. In object-heavy scenarios, eagerly cloning the
        // whole world for every freely swimming ContactCalls object is an
        // accidental O(movers * objects) cost.
        let initial_contact_function_calls = self
            .definitions
            .get(&self.objects[idx].definition_id)
            .is_some_and(Definition::contact_function_calls);
        let contact_world_base = initial_contact_function_calls
            .then(|| self.host_world_context_base());
        let contact_physics = self.physics;
        let contact_environment = self.environment;
        let contact_frame = self.frame;
        let contact_game_over_triggered = self.game_over_triggered;
        let mut contact_outcomes = Vec::new();
        let mut contact_container_changes = Vec::new();
        let mut contact_change_def_reinserts = HashMap::new();
        let mut contact_change_def_solid_mask = false;
        let mut contact_selection_changes = Vec::new();
        let contact_definitions = &self.definitions;
        let contact_material_capacity = self.materials.len();
        let mut mask_attachments = None;
        let mut movement_outcome = {
            let mut landscape = self.landscape.as_mut();
            let materials = &self.materials;
            let mass_movers = &mut self.mass_movers;
            let sectors = self.sectors.as_ref();
            let (objects_before, objects_tail) = self.objects.split_at_mut(idx);
            let (object, objects_after) = objects_tail.split_first_mut().expect("index checked");
            let movement_world_source = MovementLazyHostWorldSource {
                before: Cell::new(objects_before.as_ptr()),
                before_len: objects_before.len(),
                after: Cell::new(objects_after.as_ptr()),
                after_len: objects_after.len(),
                mover_index: idx,
                definitions: std::ptr::from_ref(contact_definitions),
                landscape: Cell::new(std::ptr::null()),
            };
            // SAFETY: this provider is installed only on `contact_world`.
            // Its declaration order below makes it drop before the
            // stack-scoped source and split slices on every exit path; the
            // successful path also empties it explicitly.
            let movement_world_provider = unsafe {
                LazyHostWorldProvider::new(
                    std::ptr::from_ref(&movement_world_source).cast(),
                    Self::lazy_movement_host_world_object,
                    Self::lazy_movement_host_world_objects,
                    Self::lazy_movement_host_world_landscape,
                )
            };
            let movement_others = RefCell::new((objects_before, objects_after));
            // Declared after both the raw provider source and the split-slice
            // owner so reverse drop order destroys every provider-carrying
            // context first, including on `?` returns and panic unwinding.
            let contact_world = RefCell::new(None::<HostWorldContext>);
            let mut run_contact_callback = |object: &mut Object,
                                            landscape: &Landscape,
                                            dispatch: MovementContactDispatch|
             -> Result<(), EngineError> {
                let (directions, shape_probe) = match dispatch {
                    MovementContactDispatch::ShapeProbe => {
                        ([CNAT_LEFT, CNAT_RIGHT, CNAT_TOP, CNAT_BOTTOM], true)
                    }
                    MovementContactDispatch::Direct(cnat) => ([cnat, 0, 0, 0], false),
                };
                for cnat in directions {
                    if cnat == CNAT_NONE {
                        continue;
                    }
                    // ContactCheck's loop condition reads the live Shape;
                    // TargetBounds instead dispatches its single direct CNAT.
                    if shape_probe && object.frame_shape_contact_cnat & cnat == 0 {
                        continue;
                    }
                    let Some(function_name) = contact_callback_name(cnat) else {
                        continue;
                    };
                    let Some(definition) = contact_definitions.get(&object.definition_id) else {
                        continue;
                    };
                    if !definition.contact_function_calls() {
                        continue;
                    }
                    // C4Object::Call with no matching Contact* function is
                    // a no-op. In particular it must not run the outcome
                    // fold and its SetOCF emulation: C++ keeps Execute's
                    // pre-movement OCF cached for the later Splash gate.
                    if !definition.has_function(function_name) {
                        continue;
                    }
                    if coach_debug_id() == Some(object.id.as_u64()) {
                        crate::rng::rng_trace_line(&format!(
                            "CONTACTCB {function_name} at ({},{})",
                            object.state.position.x, object.state.position.y
                        ));
                    }
                    movement_world_source
                        .landscape
                        .set(std::ptr::from_ref(landscape));
                    if contact_world.borrow().is_none() {
                        let Some(base) = contact_world_base.as_ref() else {
                            return Ok(());
                        };
                        *contact_world.borrow_mut() = Some(
                            base.clone()
                                .with_lazy_world_provider(movement_world_provider),
                        );
                    }
                    contact_world
                        .borrow_mut()
                        .as_mut()
                        .expect("contact world initialized for matching callback")
                        .seed_object(
                            idx,
                            Self::host_world_object(contact_definitions, object),
                        );
                    let state_snapshot = object.script_state_snapshot();
                    let world = contact_world
                        .borrow()
                        .as_ref()
                        .expect("contact world initialized for matching callback")
                        .clone()
                        .with_next_object_id(contact_next_object_id);
                    let (value, mut outcome, audio_state, new_rng) = definition
                        .call_object_function(
                            &state_snapshot,
                            object.id,
                            function_name,
                            &[],
                            contact_rng.clone(),
                            &contact_global_effects,
                            contact_physics,
                            contact_environment,
                            contact_frame,
                            world,
                            contact_game_over_triggered,
                            contact_audio.clone(),
                        )?;
                    contact_rng = new_rng;
                    contact_audio = audio_state;
                    contact_next_object_id = outcome.next_object_id;

                    if let Some(preview) = outcome.host_raster_preview.clone() {
                        contact_world
                            .borrow_mut()
                            .as_mut()
                            .expect("contact world remains initialized")
                            .apply_host_raster_preview(preview);
                    } else {
                        contact_world
                            .borrow_mut()
                            .as_mut()
                            .expect("contact world remains initialized")
                            .preview_solid_mask_operations(&outcome.solid_mask_operations);
                    }

                    if let Some(update) = outcome.object_update.take() {
                        let previous_owner = object.state.owner;
                        let previous_crew_member = object.state.crew_member;
                        let previous_position = object.state.position;
                        let preserves_position = update.position.is_none();
                        let callbacks_dispatched = update
                            .action
                            .as_ref()
                            .map(|action| action.callbacks_dispatched)
                            .unwrap_or(false);
                        let delta: ObjectDelta = update.into();
                        let definition_changed = delta.change_def.is_some();
                        let callback_action_library = if let Some(new_def) =
                            delta.change_def.as_deref()
                        {
                            let definition = contact_definitions.get(new_def).ok_or_else(|| {
                                EngineError::UnknownDefinition(new_def.to_string())
                            })?;
                            Self::apply_change_object_def_to_object(
                                object,
                                new_def,
                                definition,
                                contact_material_capacity,
                                None,
                            );
                            contact_change_def_solid_mask = true;
                            definition.action_library()
                        } else {
                            contact_definitions
                                .get(&object.definition_id)
                                .ok_or_else(|| {
                                    EngineError::UnknownDefinition(object.definition_id.clone())
                                })?
                                .action_library()
                        };
                        if definition_changed {
                            contact_change_def_reinserts
                                .insert(object.id, delta.change_def_reinsert);
                        }
                        let apply_outcome = object.apply_delta(&delta, callback_action_library);
                        if definition_changed {
                            if let Some(current_definition) =
                                contact_definitions.get(&object.definition_id)
                            {
                                let contents_count = {
                                    let world = contact_world.borrow();
                                    Self::host_retained_contents_count(
                                        world
                                            .as_ref()
                                            .expect("contact world remains initialized"),
                                        &object.state.contents,
                                    )
                                };
                                object.state.ocf = current_definition
                                    .compute_ocf_with_contents_count(&object.state, contents_count);
                            }
                        }
                        if preserves_position {
                            object.state.position = previous_position;
                        }
                        if let Some(change) = apply_outcome.action_change {
                            if !callbacks_dispatched {
                                object.record_action_event(
                                    change.previous,
                                    ActionTransitionKind::Forced,
                                );
                            }
                        }
                        if let Some((previous, new)) = apply_outcome.container_change {
                            contact_container_changes.push((object.id, previous, new));
                        }
                        let new_owner = object.state.owner;
                        let new_crew_member = object.state.crew_member;
                        if previous_owner != new_owner || previous_crew_member != new_crew_member {
                            contact_selection_changes.push((
                                object.id,
                                previous_owner,
                                previous_crew_member,
                                new_owner,
                                new_crew_member,
                            ));
                        }
                    }

                    let layer_bounds = {
                        let others = movement_others.borrow();
                        let (objects_before, objects_after) = &*others;
                        layer_movement_bounds_from_split(
                            object,
                            objects_before,
                            objects_after,
                            contact_definitions,
                        )
                    };
                    movement.live.set(movement_live_config_for(
                        object,
                        contact_definitions,
                        layer_bounds,
                    ));

                    contact_outcomes.push(outcome);
                    if value.as_bool() {
                        break;
                    }
                }
                Ok(())
            };
            let mut on_do_motion = |object: &mut Object,
                                    landscape: &mut Landscape|
             -> Result<(), EngineError> {
                let mut others = movement_others.borrow_mut();
                let (objects_before, objects_after) = &mut *others;
                mask_attachments = Self::remove_solid_mask_from_fields(
                    object,
                    objects_before,
                    objects_after,
                    contact_definitions,
                    materials,
                    mass_movers,
                    landscape,
                    sectors,
                    true,
                    true,
                );
                if let Some(world) = contact_world.borrow_mut().as_mut() {
                    let bakes = objects_before
                        .iter()
                        .chain(std::iter::once(&*object))
                        .chain(objects_after.iter())
                        .filter_map(|object| {
                            object
                                .solid_mask_bake
                                .clone()
                                .map(|bake| (object.id, bake))
                        })
                        .collect();
                    world.refresh_after_do_motion(object.id, landscape, bakes);
                }
                // The mutable slice reborrow above invalidates raw pointers
                // derived before DoMotion. Re-derive them after the last
                // slice access so a later Contact* callback has current
                // provenance as well as the same stable addresses.
                movement_world_source
                    .before
                    .set(objects_before.as_ptr());
                movement_world_source.after.set(objects_after.as_ptr());
                Ok(())
            };
            let mut outcome = object.advance_fixed_position_per_pixel(
                landscape.as_deref_mut(),
                materials,
                movement,
                &mut run_contact_callback,
                &mut on_do_motion,
            )?;
            let (rotation_contact, rotation_cnat) = object.advance_fixed_rotation(
                landscape.as_deref(),
                materials,
                movement,
                outcome.no_attach,
                outcome.redirect_yr,
                outcome.solid_mask_removed,
                &mut run_contact_callback,
            )?;
            drop(on_do_motion);
            drop(run_contact_callback);
            // Drop every clone carrying the stack-scoped movement provider
            // before its raw source and split slices leave this block.
            let _ = contact_world.borrow_mut().take();
            outcome.any_contact |= rotation_contact;
            outcome.contact_cnat |= rotation_cnat;
            // DoMovement restores the accumulated iContacts after all
            // translation/rotation probes so a later free ContactCheck in
            // the same movement cannot hide an earlier rejected step.
            if outcome.any_contact {
                object.frame_t_contact = outcome.contact_cnat;
            }
            outcome
        };
        let did_motion = movement_outcome.solid_mask_removed;
        self.rng = contact_rng;
        self.audio_registry = contact_audio;
        self.sync_next_object_id(contact_next_object_id);
        for (changed_object_id, previous_owner, previous_crew_member, new_owner, new_crew_member) in
            contact_selection_changes
        {
            self.update_selection_for_state_change(
                changed_object_id,
                previous_owner,
                previous_crew_member,
                new_owner,
                new_crew_member,
            );
        }
        for (changed_object_id, previous, new) in contact_container_changes {
            self.apply_container_change(changed_object_id, previous, new, false)?;
        }
        for (changed_object_id, reinsert) in contact_change_def_reinserts {
            if reinsert {
                self.reinsert_change_def_contents_link(changed_object_id)?;
            }
        }
        if contact_change_def_solid_mask {
            self.update_solid_mask(idx);
        }
        for outcome in contact_outcomes {
            let Some(current_index) = self.find_object_index(object_id) else {
                break;
            };
            let current_definition_id = self.objects[current_index].definition_id.clone();
            let current_action_library = self
                .definitions
                .get(&current_definition_id)
                .ok_or_else(|| EngineError::UnknownDefinition(current_definition_id.clone()))?
                .action_library()
                .clone();
            self.apply_callback_outcome(
                current_index,
                outcome,
                &current_action_library,
                object_id,
                &current_definition_id,
                false,
            )?;
        }
        // DoMovement's unconditional UpdateSolidMask(true) tail precedes
        // InLiquid, ContactAction, NoAttachAction, and Hit callbacks
        // (C4Movement.cpp:443-478). With no DoMotion this performs the real
        // remove(no backup)+put cycle; after motion it re-puts at the final
        // position and translates the riders captured by the first removal.
        self.update_solid_mask(idx);
        self.restore_solid_mask_attachments(
            idx,
            did_motion.then_some(mask_attachments).flatten(),
        );
        if self.objects[idx].destroyed
            || matches!(self.objects[idx].state.status, ObjectStatus::Deleted)
        {
            return Ok(ExecMovementOutcome {
                alive: false,
                did_motion,
            });
        }
        self.update_sector_for_index(idx);
        // C4Object::InLiquid update, inline in DoMovement after
        // integration and BEFORE ContactAction/NoAttachAction
        // (C4Movement.cpp:443-460): IsInLiquidCheck probes
        // GBackLiquid(x, y + Float*Con/FullCon - 1)
        // (C4Object.cpp:5609-5612); entering liquid clears fNoAttach
        // (:452). DoMovement never runs contained or C4D_StaticBack
        // (C4Movement.cpp:553-575; the C++ Mobile gate is unmodeled).
        // The entry Splash (:450-451, OCF_HitSpeed2 && Mass>3) draws
        // synced RNG and is a documented PORT_STATUS gap.
        if self.objects[idx].state.container.is_none()
            && self.objects[idx].state.category & CATEGORY_STATIC_BACK == 0
        {
            let probe = {
                let state = &self.objects[idx].state;
                let float_line = self
                    .definitions
                    .get(&self.objects[idx].definition_id)
                    .map(|definition| definition.float_line)
                    .unwrap_or(0);
                let offset = float_line
                    .saturating_mul(state.construction)
                    .checked_div(FULL_CON)
                    .unwrap_or(0);
                Vector2::new(state.position.x, state.position.y + offset - 1)
            };
            let wet = self
                .landscape
                .as_ref()
                .map(|landscape| landscape.is_liquid_at(probe.x, probe.y))
                .unwrap_or(false);
            let state = &self.objects[idx].state;
            if wet && !state.in_liquid {
                // Entry splash (C4Movement.cpp:450-453): fast + heavy
                // objects splash — synced RNG draws + FXU1 bubbles.
                let object_mass = self.effective_object_mass(idx);
                let state = &self.objects[idx].state;
                let should_splash =
                    state.ocf & crate::ocf::HIT_SPEED2 != 0 && object_mass > 3;
                let (splash_x, splash_y, splash_amt) = {
                    let shape = self.objects[idx].current_shape_rect();
                    let area = shape
                        .map(|rect| rect.width * rect.height / 10)
                        .unwrap_or(0)
                        .min(20);
                    (state.position.x, state.position.y + 1, area)
                };
                if should_splash {
                    self.splash(splash_x, splash_y, splash_amt)?;
                }
                let state = &mut self.objects[idx].state;
                state.in_liquid = true;
                movement_outcome.no_attach = false;
            } else if !wet && self.objects[idx].state.in_liquid {
                self.objects[idx].state.in_liquid = false;
            }
        }
        // Contact Action, then Attachment Loss Action, then the Hit
        // script calls (C4Movement.cpp:463-478).
        if movement_outcome.any_contact {
            let Some(idx) = self.find_object_index(object_id) else {
                return Ok(ExecMovementOutcome {
                    alive: false,
                    did_motion,
                });
            };
            let definition_id = self.objects[idx].definition_id.clone();
            self.exec_contact_action(
                idx,
                movement_outcome.contact_cnat,
                &definition_id,
                solid_mask_indices,
            )?;
            if self.find_object_index(object_id).is_none_or(|idx| {
                self.objects[idx].destroyed
                    || matches!(self.objects[idx].state.status, ObjectStatus::Deleted)
            }) {
                return Ok(ExecMovementOutcome {
                    alive: false,
                    did_motion,
                });
            }
        }
        if movement_outcome.no_attach {
            let Some(idx) = self.find_object_index(object_id) else {
                return Ok(ExecMovementOutcome {
                    alive: false,
                    did_motion,
                });
            };
            let definition_id = self.objects[idx].definition_id.clone();
            let Some(action_library) = self
                .definitions
                .get(&definition_id)
                .map(|definition| definition.action_library().clone())
            else {
                return Ok(ExecMovementOutcome {
                    alive: false,
                    did_motion,
                });
            };
            self.apply_no_attach_action(
                idx,
                &definition_id,
                &action_library,
                solid_mask_indices,
            )?;
        }
        if movement_outcome.any_contact {
            self.invoke_movement_hit_callbacks(
                old_movement_velocity,
                old_movement_hit_flags,
                object_id,
            )?;
        }
        if self.find_object_index(object_id).is_none_or(|idx| {
            self.objects[idx].destroyed
                || matches!(self.objects[idx].state.status, ObjectStatus::Deleted)
        }) {
            return Ok(ExecMovementOutcome {
                alive: false,
                did_motion,
            });
        }

        Ok(ExecMovementOutcome {
            alive: true,
            did_motion,
        })
    }

    /// `DoGravity(this)` as used by the ExecAction idle and insufficient
    /// action-energy returns (C4Object.cpp:4644-4664, 4708-4712, 4747-4752).
    /// This is the raw native operation: no procedure gravity mask, terminal
    /// clamp, steering, phase work, or generic DoEnergy side effects.
    fn apply_do_gravity_at_index(&mut self, idx: usize) {
        if idx >= self.objects.len() {
            return;
        }
        let float_line = self
            .definitions
            .get(&self.objects[idx].definition_id)
            .map(|definition| definition.float_line)
            .unwrap_or(0);
        let floats = self.objects[idx].state.in_liquid && float_line != 0;
        let surfaced = if floats {
            let state = &self.objects[idx].state;
            let probe_y = state.position.y - 1
                + float_line
                    .saturating_mul(state.construction)
                    .checked_div(FULL_CON)
                    .unwrap_or(0)
                - 1;
            self.landscape
                .as_ref()
                .map(|landscape| !landscape.is_liquid_at(state.position.x, probe_y))
                .unwrap_or(true)
        } else {
            false
        };
        let gravity = self.physics.gravity_as_c4fixed();
        let object = &mut self.objects[idx];
        if floats {
            object.fixed_velocity.y -= math::FLOAT_ACCEL;
            let min_rise = C4Fixed::from_raw(-10 * math::FLOAT_ACCEL.val());
            if object.fixed_velocity.y < min_rise {
                object.fixed_velocity.y = min_rise;
            }
            let friction = math::FLOAT_FRICTION;
            if object.fixed_velocity.x < -friction {
                object.fixed_velocity.x += friction;
            } else if object.fixed_velocity.x > friction {
                object.fixed_velocity.x -= friction;
            }
            if object.rotation_velocity < -friction {
                object.rotation_velocity += friction;
            } else if object.rotation_velocity > friction {
                object.rotation_velocity -= friction;
            }
            if surfaced && object.fixed_velocity.y < C4Fixed::ZERO {
                object.fixed_velocity.y = C4Fixed::ZERO;
            }
        } else if object.state.category & CATEGORY_STATIC_BACK == 0 {
            object.fixed_velocity.y += gravity;
        }
        object.refresh_velocity_from_fixed();
    }

    #[doc(hidden)]
    pub fn apply_physics_at_index(&mut self, idx: usize) -> Result<bool, EngineError> {
        self.apply_physics_at_index_inner(idx, None)
    }

    fn apply_physics_at_index_inner(
        &mut self,
        mut idx: usize,
        captured_physical: Option<&mut Option<PhysicalInfo>>,
    ) -> Result<bool, EngineError> {
        if idx >= self.objects.len() {
            return Ok(false);
        }
        // Action.t_attach resets each ExecAction (C4Object.cpp:4692);
        // early returns below leave it CNAT_None for this frame's
        // movement.
        self.objects[idx].frame_t_attach = CNAT_NONE;
        // Upright attachment check precedes the idle, incomplete, and
        // action-energy gates.
        // (C4Object.cpp:4698-4705). Preserve its Action.t_attach bit even
        // when either later gate returns before procedure attachment latches.
        {
            let upright_attach = self
                .definitions
                .get(&self.objects[idx].definition_id)
                .map(|definition| definition.upright_attach())
                .unwrap_or(0);
            let object = &mut self.objects[idx];
            object.upright_t_attach = 0;
            object.swim_exit_this_frame = false;
            if !object.state.mobile && upright_attach != 0 {
                let rotation = object.state.rotation;
                let signed = if rotation > 180 {
                    rotation - 360
                } else {
                    rotation
                };
                if (-math::STABLE_RANGE..=math::STABLE_RANGE).contains(&signed) {
                    object.upright_t_attach = upright_attach as u32;
                    object.state.mobile = true;
                }
            }
            object.frame_t_attach = object.upright_t_attach;
            object.state.t_attach = object.frame_t_attach;
        }

        let (is_idle_action, incomplete_activity, energy_usage) = self
            .definitions
            .get(&self.objects[idx].definition_id)
            .map(|definition| {
                let action = &self.objects[idx].state.action;
                let library = definition.action_library();
                (
                    library.is_idle_state(action),
                    definition.incomplete_activity(),
                    library.energy_usage_for_entry(&action.name, action.act_map_index),
                )
            })
            .unwrap_or((true, false, 0));

        // Native idle actions return before C4Object::GetPhysical
        // (C4Object.cpp:4718-4723). Besides preserving hook/RNG laziness,
        // this keeps their gravity-only path out of the phase tail.
        if is_idle_action {
            if self.objects[idx].state.mobile {
                self.apply_do_gravity_at_index(idx);
            }
            return Ok(true);
        }

        // A real action on an object without OCF_FullCon is reset through
        // ordinary SetAction(ActIdle) unless its definition opts into
        // IncompleteActivity (C4Object.cpp:4725-4729). SetAction supplies the
        // synchronous Abort callback, OCF refresh and fixed-position resync;
        // ExecAction returns even when NoOtherAction rejects the transition.
        if self.objects[idx].state.ocf & crate::ocf::FULL_CON == 0 && !incomplete_activity {
            let definition_id = self.objects[idx].definition_id.clone();
            let _ = tolerate_script_error(self.action_with_calls(idx, &definition_id, "Idle"))?;
            return Ok(true);
        }

        // C++ retains pAction first, then resolves pPhysical exactly once
        // before the action-energy gate and every script-capable procedure
        // (C4Object.cpp:4731-4733). Keep the pAction-derived metadata and
        // copied physical together across callbacks below.
        let action_definition_id = self.objects[idx].definition_id.clone();
        let (
            procedure,
            movement_profile,
            mut gravity_component,
            is_idle,
            action_attach,
            action_disabled,
            in_liquid_action,
        ) = {
            let gravity = self.physics.gravity_as_c4fixed();
            if let Some(definition) = self.definitions.get(&action_definition_id) {
                let object = &self.objects[idx];
                let library = definition.action_library();
                let procedure = library.procedure_for_entry(
                    &object.state.action.name,
                    object.state.action.act_map_index,
                );
                (
                    procedure,
                    definition.movement_profile(),
                    procedure.gravity_component_fixed(gravity),
                    library.is_idle_state(&object.state.action),
                    library.attach_for_entry(
                        &object.state.action.name,
                        object.state.action.act_map_index,
                    ),
                    library.disables_object_for_entry(
                        &object.state.action.name,
                        object.state.action.act_map_index,
                    ),
                    library
                        .in_liquid_action_for_entry(
                            &object.state.action.name,
                            object.state.action.act_map_index,
                        )
                        .map(str::to_string),
                )
            } else {
                let procedure = ActionProcedure::default();
                (
                    procedure,
                    MovementProfile::default(),
                    procedure.gravity_component_fixed(gravity),
                    true,
                    0,
                    false,
                    None,
                )
            }
        };
        let physical = self.object_physical(idx);
        if let Some(slot) = captured_physical {
            *slot = Some(physical);
        }

        // C4ActionDef::EnergyUsage is a signed, nonzero gate on every real
        // ActMap action while C4RULE_StructuresNeedEnergy is active
        // (C4Object.cpp:4738-4753). It runs before Action.Time++,
        // InLiquidAction, steering and phase advance. Insufficient power is
        // the native idle return: mark NeedEnergy, apply raw gravity only to
        // Mobile objects, and skip all remaining action work.
        if self.structures_need_energy && energy_usage != 0 {
            if energy_usage <= self.objects[idx].state.energy {
                let object = &mut self.objects[idx];
                object.state.energy = object.state.energy.wrapping_sub(energy_usage);
                object.state.need_energy = false;
            } else {
                let mobile = {
                    let object = &mut self.objects[idx];
                    object.state.need_energy = true;
                    object.state.mobile
                };
                if mobile {
                    self.apply_do_gravity_at_index(idx);
                }
                return Ok(true);
            }
        }
        // Native increments the LIVE Action.Time exactly once after the
        // energy gate and before InLiquidAction/procedure dispatch
        // (C4Object.cpp:4755-4756). GetPhysical may have replaced the action,
        // so this deliberately does not write through the retained pAction.
        self.objects[idx].state.action.time = self.objects[idx].state.action.time.wrapping_add(1);
        // InLiquidAction check (C4Object.cpp:4749-4753): an InLiquid
        // object whose action declares one switches THROUGH
        // SetActionByName (Abort+Start calls, fix resync) and returns
        // early — steering and the phase advance skip; movement runs.
        if self.objects[idx].state.in_liquid {
            if let Some(target) = in_liquid_action {
                let definition_id = self.objects[idx].definition_id.clone();
                self.action_with_calls(idx, &definition_id, &target)?;
                return Ok(true);
            }
        }
        if idx >= self.objects.len() {
            return Ok(false);
        }
        let mut swim_walk_transition = false;

        let mut definition_id = self.objects[idx].definition_id.clone();
        let command_direction = self.objects[idx].state.command_direction;
        let action_target = self.objects[idx].state.action.target;

        // Latch this frame's Action.t_attach from the PRE-wrap action
        // (C4Object.cpp:4692 + per-procedure assignments): the phase-wrap
        // SetAction at ExecAction's end must not retroactively attach
        // this frame's movement.
        self.objects[idx].frame_t_attach = procedure_t_attach(
            procedure,
            is_idle,
            self.objects[idx].state.direction,
            action_attach,
            self.objects[idx].upright_t_attach,
        );
        // Mirror into the script-visible state: FnAdjustWalkRotation
        // reads Action.t_attach (C4Script.cpp:5444).
        self.objects[idx].state.t_attach = self.objects[idx].frame_t_attach;

        // Once an object is controllable again, an older attack no longer
        // owns a later environmental death (C4Object.cpp:4771-4776). Flight,
        // swimming, disabled actions, and burning deliberately retain the
        // trace so throws, drowning, and fire deaths keep their attacker.
        if !is_idle
            && !action_disabled
            && !matches!(procedure, ActionProcedure::Flight | ActionProcedure::Swim)
            && !self.objects[idx].state.on_fire
        {
            self.objects[idx].last_energy_loss_cause = OWNER_NONE;
        }

        // DFA_CONNECT is procedure work, so it follows the action-energy,
        // Action.Time, InLiquidAction, attachment, and attribution steps
        // (C4Object.cpp:4738-4776, 5341-5420). Broken targets fire LineBreak
        // and remove the line, skipping the rest of this object's exec.
        if matches!(procedure, ActionProcedure::Connect) && !self.exec_connect_line(idx)? {
            return Ok(true);
        }

        // DFA_DIG must stay attached to solid ground. C++ performs this
        // independent CNAT_Bottom probe before assigning dig velocity and
        // stops digging immediately when it fails (C4Object.cpp:4906-4911).
        // Synthetic fixture worlds without a landscape keep their historical
        // movement path; a real game always has GBack available here.
        if matches!(procedure, ActionProcedure::Dig) && self.landscape.is_some() {
            let solid_mask_indices = (0..self.objects.len()).collect::<Vec<_>>();
            let solid_masks = self.solid_masks_for_movement(&solid_mask_indices);
            let attachment = self.landscape.as_ref().map(|landscape| {
                let object = &self.objects[idx];
                let mut sample_position = object.state.position;
                let mut record = object.state.shape_attach;
                let contact_density = object.state.contact_density;
                let attached = shape_attach(
                    &object.state.vertices,
                    &mut sample_position,
                    CNAT_BOTTOM,
                    landscape,
                    &self.materials,
                    &solid_masks,
                    Some(object.id),
                    contact_density,
                    &mut record,
                );
                (attached, record)
            });
            if let Some((attached, record)) = attachment {
                self.objects[idx].state.shape_attach = record;
                if !attached {
                    self.object_com_stop_dig(idx, &definition_id)?;
                    return Ok(true);
                }
            }
        }

        if matches!(procedure, ActionProcedure::Bridge) {
            if !self.apply_bridge_procedure(idx, command_direction, &definition_id)? {
                // `if (!DoBridge(this)) return;` skips the phase tail
                // (C4Object.cpp:4998-4999).
                return Ok(true);
            }
        }

        if matches!(procedure, ActionProcedure::Build) {
            if !self.apply_build_procedure(idx)? {
                return Ok(true);
            }
        }

        if matches!(procedure, ActionProcedure::Chop)
            && !self.apply_chop_procedure(idx, &definition_id)?
        {
            return Ok(true);
        }

        // A false helper result is a native `return` from ExecAction. Signal
        // the outer object loop to skip the captured action's phase tail.
        if matches!(procedure, ActionProcedure::Fight)
            && !self.apply_fight_procedure(idx, physical)?
        {
            return Ok(true);
        }

        if matches!(procedure, ActionProcedure::Attach)
            && !self.apply_attach_procedure(idx, &definition_id)?
        {
            return Ok(true);
        }

        let mut push_handled = false;
        if matches!(procedure, ActionProcedure::Push) {
            if !self.apply_push_procedure(
                idx,
                command_direction,
                movement_profile,
                &definition_id,
                physical,
            )?
            {
                return Ok(true);
            }
            push_handled = true;
        }

        let mut pull_handled = false;
        if matches!(procedure, ActionProcedure::Pull) {
            if !self.apply_pull_procedure(
                idx,
                command_direction,
                movement_profile,
                &definition_id,
                physical,
            )?
            {
                return Ok(true);
            }
            pull_handled = true;
        }

        // DFA_LIFT applies the target force and all target callbacks before
        // the lifter's trailing DoGravity (C4Object.cpp:5266-5289). Keep this
        // ahead of the generic gravity block below so LiftTop observes the
        // pre-gravity lifter state.
        if matches!(procedure, ActionProcedure::Lift) {
            let lifter_id = self.objects[idx].id;
            if !self.apply_lift_to_target(idx, command_direction, action_target)? {
                // C++ uses ordinary SetAction(ActIdle), including its
                // Start/Abort calls and NoOtherAction gate, then returns.
                let _ = self.action_with_calls(idx, &definition_id, "Idle")?;
                return Ok(true);
            }
            let Some(live_idx) = self.find_object_index(lifter_id) else {
                return Ok(true);
            };
            idx = live_idx;
            if self.objects[idx].destroyed
                || self.objects[idx].state.status == ObjectStatus::Deleted
            {
                return Ok(true);
            }
            // LiftTop may ChangeDef the lifter. DoGravity reads the live Def
            // (notably its Float line) and live GravAccel after that callback.
            definition_id = self.objects[idx].definition_id.clone();
            gravity_component = self.physics.gravity_as_c4fixed();
        }

        // DFA_FLIGHT contained fall-out (C4Object.cpp:4893-4900): on
        // Tick10, stop into Walk and add the delayed Wait, then immediately
        // replace that stack through plain SetCommand(Exit). Keep executing
        // this frame under the captured FLIGHT procedure so gravity/mobile
        // still run after the callbacks, just as the stale pAction does.
        if matches!(procedure, ActionProcedure::Flight)
            && self.frame % 10 == 0
            && self.objects[idx].state.container.is_some()
        {
            let object_id = self.objects[idx].id;
            self.stop_action_delay_command(idx, &definition_id)?;
            let Some(live_idx) = self.find_object_index(object_id) else {
                return Ok(true);
            };
            idx = live_idx;
            self.set_plain_exit_command(idx)?;
            let Some(live_idx) = self.find_object_index(object_id) else {
                return Ok(true);
            };
            idx = live_idx;
        }

        let mut exec_set_direction = None;
        {
            // At-limit physical training before the ComDir movement: Scale
            // Tick5 (C4Object.cpp:4810-4812), Hangle Tick5 (:4844-4846),
            // Swim Tick10 (:4924-4926).
            match procedure {
                ActionProcedure::Scale if physical.scale != 0 && self.frame % 5 == 0 => {
                    let ydir = self.objects[idx].fixed_velocity.y;
                    if ydir.abs() == math::val_by_physical(200, physical.scale) {
                        self.train_physical(idx, "Scale", 1, C4_MAX_PHYSICAL);
                    }
                }
                ActionProcedure::Hang if physical.hangle != 0 && self.frame % 5 == 0 => {
                    let xdir = self.objects[idx].fixed_velocity.x;
                    if xdir.abs() == math::val_by_physical(160, physical.hangle) {
                        self.train_physical(idx, "Hangle", 1, C4_MAX_PHYSICAL);
                    }
                }
                ActionProcedure::Swim if physical.swim != 0 && self.frame % 10 == 0 => {
                    let xdir = self.objects[idx].fixed_velocity.x;
                    if xdir.abs() == math::val_by_physical(160, physical.swim) {
                        self.train_physical(idx, "Swim", 1, C4_MAX_PHYSICAL);
                    }
                }
                _ => {}
            }
            // DFA_SWIM liquid probes (C4Object.cpp:4946-4960): below =
            // GBackLiquid(x, y + 1 + Float*Con/FullCon - 1), surface =
            // GBackLiquid(x, y - 1 + Float*Con/FullCon - 1); position is
            // stable through the steering, so probe before the borrow.
            // Fixture worlds have no landscape at all — skip the liquid
            // checks entirely there (a real game always has one).
            let swim_probes_available = self.landscape.is_some();
            let (swim_below_wet, swim_surface_wet) = {
                let state = &self.objects[idx].state;
                let float_line = self
                    .definitions
                    .get(&self.objects[idx].definition_id)
                    .map(|definition| definition.float_line)
                    .unwrap_or(0);
                let offset = float_line
                    .saturating_mul(state.construction)
                    .checked_div(FULL_CON)
                    .unwrap_or(0);
                let probe = |y: i32| {
                    self.landscape
                        .as_ref()
                        .map(|landscape| landscape.is_liquid_at(state.position.x, y))
                        .unwrap_or(false)
                };
                (
                    probe(state.position.y + offset),
                    probe(state.position.y + offset - 2),
                )
            };
            let walk_rotation = if matches!(procedure, ActionProcedure::Walk) {
                self.definitions
                    .get(&definition_id)
                    .map(|definition| definition.walk_rotation_seed(&self.objects[idx].state))
            } else {
                None
            };
            let walk_landscape = self.landscape.as_ref();
            let object = &mut self.objects[idx];
            // DFA_SWIM and DFA_FLOAT never apply gravity (no DoGravity call,
            // C4Object.cpp:4920-4970/:5268-5287); the legacy halved-gravity
            // paths keep it for physical-less fixtures.
            let physical_skips_gravity = match procedure {
                ActionProcedure::Swim => physical.swim != 0,
                ActionProcedure::Float => physical.float != 0,
                _ => false,
            };
            // The C++ ExecAction default case (custom/DFA_NONE procedures,
            // C4Object.cpp:5426-5437): with an ActMap Attach the dirs are
            // zeroed and the object mobilized INSTEAD of gravity; without
            // one it just falls.
            let default_case_attach = !is_idle
                && action_attach != 0
                && matches!(
                    procedure,
                    ActionProcedure::Undefined | ActionProcedure::Other
                );
            // DoGravity (C4Object.cpp:4644-4664): the free-fall branch
            // skips C4D_StaticBack categories (:4662), and idle objects
            // only probe gravity while Mobile (C4Object.cpp:4708-4712) —
            // the Tick10 pulse in ExecMovement is what re-arms them.
            let gravity_gated_off = object.state.category & CATEGORY_STATIC_BACK != 0
                || (is_idle && !object.state.mobile)
                || default_case_attach;
            // DoGravity's float branch (C4Object.cpp:4644-4661): InLiquid
            // objects with a Def->Float line RISE instead of falling —
            // ydir -= FloatAccel clamped to FloatAccel*-10, xdir/rdir decay
            // by FloatFriction, and a float-line probe out of liquid zeroes
            // negative ydir (surface equilibrium). Free-fall is the ELSE.
            let float_line = self
                .definitions
                .get(&definition_id)
                .map(|definition| definition.float_line)
                .unwrap_or(0);
            let floats = object.state.in_liquid && float_line != 0;
            if floats && !physical_skips_gravity && !gravity_gated_off {
                object.fixed_velocity.y -= math::FLOAT_ACCEL;
                let min_rise = C4Fixed::from_raw(-10 * math::FLOAT_ACCEL.val());
                if object.fixed_velocity.y < min_rise {
                    object.fixed_velocity.y = min_rise;
                }
                let friction = math::FLOAT_FRICTION;
                if object.fixed_velocity.x < -friction {
                    object.fixed_velocity.x += friction;
                } else if object.fixed_velocity.x > friction {
                    object.fixed_velocity.x -= friction;
                }
                if object.rotation_velocity < -friction {
                    object.rotation_velocity += friction;
                } else if object.rotation_velocity > friction {
                    object.rotation_velocity -= friction;
                }
                let probe_y = object.state.position.y - 1
                    + float_line
                        .saturating_mul(object.state.construction)
                        .checked_div(FULL_CON)
                        .unwrap_or(0)
                    - 1;
                let surfaced = self
                    .landscape
                    .as_ref()
                    .map(|landscape| !landscape.is_liquid_at(object.state.position.x, probe_y))
                    .unwrap_or(true);
                if surfaced && object.fixed_velocity.y < C4Fixed::ZERO {
                    object.fixed_velocity.y = C4Fixed::ZERO;
                }
            } else if !physical_skips_gravity && !gravity_gated_off {
                object.fixed_velocity.y += gravity_component;
            }
            if default_case_attach {
                object.fixed_velocity = FixedVec2::ZERO;
            }
            // Every C++ ExecAction procedure case ends in `Mobile = 1`
            // except DFA_LIFT (the TARGET mobilizes via Lift),
            // DFA_ATTACH, DFA_CONNECT and the no-Attach default case
            // (C4Object.cpp:4791-5437).
            let procedure_mobilizes = default_case_attach
                || matches!(
                    procedure,
                    ActionProcedure::Walk
                        | ActionProcedure::Kneel
                        | ActionProcedure::Scale
                        | ActionProcedure::Hang
                        | ActionProcedure::Flight
                        | ActionProcedure::Dig
                        | ActionProcedure::Swim
                        | ActionProcedure::Throw
                        | ActionProcedure::Bridge
                        | ActionProcedure::Build
                        | ActionProcedure::Push
                        | ActionProcedure::Pull
                        | ActionProcedure::Chop
                        | ActionProcedure::Fight
                        | ActionProcedure::Float
                );
            if procedure_mobilizes {
                object.state.mobile = true;
            }
            // C++ wind reaches only PXS and particles via GBackWind
            // (C4Wrappers.h:189-192) — object motion never reads it.
            if procedure.locks_vertical_velocity() {
                object.fixed_velocity.y = C4Fixed::ZERO;
            }
            let mut pending_direction = None;
            match procedure {
                ActionProcedure::Float if physical.float != 0 => {
                    apply_float_physical_movement(
                        &mut object.fixed_velocity,
                        command_direction,
                        math::fixed100(physical.float),
                    );
                }
                ActionProcedure::Float => {
                    apply_float_command_movement(
                        &mut object.fixed_velocity,
                        command_direction,
                        movement_profile,
                    );
                }
                // After the contained Tick10 arm above, DFA_FLIGHT's
                // remaining steering is gravity + Mobile only
                // (C4Object.cpp:4893-4904): ComDir never steers a flier.
                ActionProcedure::Flight => {}
                ActionProcedure::Swim => {
                    if physical.swim != 0 {
                        pending_direction = apply_swim_physical_movement(
                            &mut object.fixed_velocity,
                            command_direction,
                            math::val_by_physical(160, physical.swim),
                        );
                    } else {
                        apply_swim_command_movement(
                            &mut object.fixed_velocity,
                            command_direction,
                            movement_profile,
                            gravity_component,
                        );
                    }
                    // Out-of-liquid checks (C4Object.cpp:4946-4960): a
                    // swimmer whose InLiquid dropped either paddles back
                    // down (liquid just below the float line) or free-falls
                    // into Walk (ObjectActionWalk, C4ObjectCom.cpp:34-39 —
                    // the early `return` skips the rest of ExecAction).
                    // The surface bound zeroes upward ydir once the float
                    // line clears the liquid.
                    if swim_probes_available {
                        if !object.state.in_liquid {
                            if swim_below_wet {
                                object.fixed_velocity.y = math::SWIM_ACCEL;
                            } else {
                                swim_walk_transition = true;
                            }
                        }
                        if !swim_walk_transition
                            && !swim_surface_wet
                            && object.fixed_velocity.y < C4Fixed::ZERO
                        {
                            object.fixed_velocity.y = C4Fixed::ZERO;
                        }
                    }
                }
                ActionProcedure::Walk => {
                    if physical.walk != 0 {
                        apply_walk_physical_movement(
                            &mut object.fixed_velocity,
                            command_direction,
                            math::val_by_physical(280, physical.walk),
                        );
                    } else {
                        apply_walk_command_movement(
                            &mut object.fixed_velocity,
                            command_direction,
                            movement_profile,
                        );
                    }
                    if let Some(seed) = walk_rotation {
                        let live_attach_vtx_x = usize::try_from(seed.attach.vtx)
                            .ok()
                            .and_then(|vtx| object.state.vertices.get(vtx))
                            .map(|vertex| vertex.x)
                            .unwrap_or(0);
                        // Internal DFA_WALK gate (C4Object.cpp:4817-4821):
                        // unlike FnAdjustWalkRotation, this does not inspect
                        // t_attach. Its false branch always stops rotation.
                        object.rotation_velocity = if seed.rotateable != 0
                            && seed.attach.mat_valid
                            && (object.fixed_velocity.x != C4Fixed::ZERO
                                || seed.def_attach_vtx_x != 0)
                        {
                            calculate_walk_rotation_velocity(
                                object.state.rotation,
                                seed.attach,
                                seed.def_attach_vtx_x,
                                live_attach_vtx_x,
                                20,
                                20,
                                100,
                                |x, y| {
                                    walk_landscape
                                        .map(|landscape| landscape.is_solid_at(x, y))
                                        .unwrap_or(false)
                                },
                            )
                        } else {
                            C4Fixed::ZERO
                        };
                    }
                }
                ActionProcedure::Scale => {
                    if physical.scale != 0 {
                        apply_scale_physical_movement(
                            &mut object.fixed_velocity,
                            command_direction,
                            math::val_by_physical(200, physical.scale),
                            object.state.direction,
                        );
                    } else {
                        apply_scale_command_movement(
                            &mut object.fixed_velocity,
                            command_direction,
                            movement_profile,
                            object.state.direction,
                        );
                    }
                }
                ActionProcedure::Hang => {
                    pending_direction = if physical.hangle != 0 {
                        apply_hangle_physical_movement(
                            &mut object.fixed_velocity,
                            command_direction,
                            math::val_by_physical(160, physical.hangle),
                            object.state.direction,
                        )
                    } else {
                        apply_hangle_command_movement(
                            &mut object.fixed_velocity,
                            command_direction,
                            movement_profile,
                            object.state.direction,
                        )
                    };
                }
                ActionProcedure::Dig => {
                    pending_direction = if physical.dig != 0 {
                        apply_dig_physical_movement(
                            &mut object.fixed_velocity,
                            command_direction,
                            math::val_by_physical(125, physical.dig),
                            object.state.direction,
                        )
                    } else {
                        apply_dig_command_movement(
                            &mut object.fixed_velocity,
                            command_direction,
                            movement_profile,
                            object.state.direction,
                        )
                    };
                }
                ActionProcedure::Push => {
                    if !push_handled {
                        // If push was not handled earlier (shouldn't happen), ensure velocities stay zeroed.
                        object.fixed_velocity = FixedVec2::ZERO;
                    }
                }
                ActionProcedure::Pull => {
                    if !pull_handled {
                        object.fixed_velocity = FixedVec2::ZERO;
                    }
                }
                _ => {}
            }
            match procedure {
                ActionProcedure::Bridge
                | ActionProcedure::Build
                | ActionProcedure::Attach
                | ActionProcedure::Throw
                | ActionProcedure::Connect
                | ActionProcedure::Chop => {
                    object.fixed_velocity = FixedVec2::ZERO;
                }
                _ => {}
            }
            // DFA_FLIGHT is only DoGravity + Mobile in C++
            // (C4Object.cpp:4893-4904). In particular, its free-fall
            // velocity is not subject to the synthetic PhysicsSettings
            // terminal-speed bounds; DoGravity keeps adding GravAccel.
            if !matches!(procedure, ActionProcedure::Flight | ActionProcedure::Lift) {
                self.physics
                    .clamp_fixed_velocity(&mut object.fixed_velocity);
            }
            object.refresh_velocity_from_fixed();
            match procedure {
                // WALK/HANGLE/DIG/SWIM all call C4Object::SetDir from the
                // raw C4Fixed xdir sign (C4Object.cpp:4802-4805,
                // 4886-4887, 4933, 4980-4981). Defer until after this borrow
                // so TurnAction runs through the full SetAction path.
                ActionProcedure::Walk
                | ActionProcedure::Hang
                | ActionProcedure::Dig
                | ActionProcedure::Swim => {
                    exec_set_direction = pending_direction.or_else(|| {
                        if object.fixed_velocity.x < C4Fixed::ZERO {
                            Some(Direction::Left)
                        } else if object.fixed_velocity.x > C4Fixed::ZERO {
                            Some(Direction::Right)
                        } else {
                            None
                        }
                    });
                }
                ActionProcedure::Bridge => {
                    // DFA_BRIDGE faces along its horizontal ComDir after
                    // DoBridge succeeds (C4Object.cpp:5000-5004).
                    exec_set_direction = match command_direction {
                        CommandDirection::Left | CommandDirection::UpLeft => Some(Direction::Left),
                        CommandDirection::Right | CommandDirection::UpRight => {
                            Some(Direction::Right)
                        }
                        _ => None,
                    };
                    object.state.mobile = true;
                }
                ActionProcedure::Push => {
                    if object.state.velocity.x < 0 {
                        object.state.direction = Direction::Left;
                    } else if object.state.velocity.x > 0 {
                        object.state.direction = Direction::Right;
                    }
                }
                ActionProcedure::Pull => {
                    if object.state.velocity.x < 0 {
                        object.state.direction = Direction::Left;
                    } else if object.state.velocity.x > 0 {
                        object.state.direction = Direction::Right;
                    }
                }
                ActionProcedure::Fight => {
                    if object.state.velocity.x < 0 {
                        object.state.direction = Direction::Left;
                    } else if object.state.velocity.x > 0 {
                        object.state.direction = Direction::Right;
                    }
                }
                _ => {}
            }
        }

        if let Some(direction) = exec_set_direction {
            self.set_exec_action_direction(idx, &definition_id, direction)?;
        }

        // Free-fall swim exit: ObjectActionWalk (SetActionByName("Walk"),
        // xdir = ydir = 0, C4ObjectCom.cpp:34-39); the DFA_SWIM case
        // `return`s so the phase advance is skipped this frame
        // (C4Object.cpp:4956).
        if swim_walk_transition {
            if self.action_with_calls(idx, &definition_id, "Walk")? {
                let object = &mut self.objects[idx];
                object.fixed_velocity = FixedVec2::ZERO;
                object.state.velocity = Vector2::ZERO;
            }
            self.objects[idx].swim_exit_this_frame = true;
            return Ok(true);
        }
        Ok(false)
    }

    fn apply_lift_to_target(
        &mut self,
        lifter_idx: usize,
        command_direction: CommandDirection,
        action_target: Option<ObjectId>,
    ) -> Result<bool, EngineError> {
        let lifter_id = self.objects[lifter_idx].id;
        let target_id = match action_target {
            Some(id) => id,
            None => return Ok(false),
        };
        let target_idx = match self.find_object_index(target_id) {
            Some(idx) => idx,
            None => return Ok(false),
        };
        if self.objects[target_idx].destroyed
            || self.objects[target_idx].state.status == ObjectStatus::Deleted
            || self.objects[target_idx].state.container.is_some()
            || !self
                .definitions
                .contains_key(&self.objects[target_idx].definition_id)
        {
            return Ok(false);
        }

        let gravity = self.physics.gravity_as_c4fixed();
        let desired_velocity = match command_direction {
            CommandDirection::Up => -itofix(2),
            CommandDirection::Stop => -gravity,
            CommandDirection::Down => itofix(2),
            _ => C4Fixed::ZERO,
        };
        // C4Object::Lift divides the constant 0.5 force by the LIVE object
        // mass, including construction, OwnMass and (normally) contents.
        let lift_force = math::fixed100(50) * 100 / self.effective_object_mass(target_idx).max(1);

        {
            let object = &mut self.objects[target_idx];
            // C4Object::Lift pre-mobilization (C4Object.cpp:1841-1845):
            // zero dirs, snap fix to the pixel position, mobilize.
            if !object.state.mobile {
                object.fixed_velocity = FixedVec2::ZERO;
                object.fixed_position = FixedVec2::new(
                    itofix(object.state.position.x),
                    itofix(object.state.position.y),
                );
                object.state.mobile = true;
            }
            math::towards(&mut object.fixed_velocity.y, desired_velocity, lift_force);
            object.refresh_velocity_from_fixed();
        }

        // Lift's stuck probe is unthrottled. The exact -GravAccel hold is
        // the sole bypass, even for noncanonical ComDir values that happen
        // to request the same raw fixed velocity.
        if desired_velocity != -gravity {
            let position = self.objects[target_idx].state.position;
            let solid_mask_indices = self.active_solid_mask_indices();
            let contacted = self
                .object_contact_check_at(target_idx, position, &solid_mask_indices)?
                .is_some_and(|contact| contact.is_contact());
            if contacted {
                // Contact callbacks above may have changed or removed the
                // target. C++ queues the object message before ~Stuck.
                if let Some(target_idx) = self.find_object_index(target_id).filter(|&index| {
                    !self.objects[index].destroyed
                        && self.objects[index].state.status != ObjectStatus::Deleted
                }) {
                    let object = &self.objects[target_idx];
                    let name = object
                        .state
                        .custom_name
                        .clone()
                        .or_else(|| {
                            self.crew_object_infos
                                .get(&target_id)
                                .map(|info| info.name.clone())
                        })
                        .or_else(|| {
                            self.definitions
                                .get(&object.definition_id)
                                .map(|definition| definition.name().to_string())
                        })
                        .unwrap_or_else(|| object.definition_id.clone());
                    self.messages.add_message(MessageSpec {
                        kind: message::MessageKind::Target,
                        text: format!("{name} is stuck!"),
                        target: Some(target_id),
                        player: None,
                        offset: Vector2::ZERO,
                        color: 0xffff_ffff,
                        flags: 0,
                        width: None,
                        decoration: None,
                        frame_decoration: None,
                        portrait: None,
                    });
                    let callback_definition_id = self.objects[target_idx].definition_id.clone();
                    if let Some(action_library) = self
                        .definitions
                        .get(&callback_definition_id)
                        .map(|definition| definition.action_library().clone())
                    {
                        let _ = tolerate_script_error(self.call_movement_object_function(
                            target_idx,
                            "Stuck",
                            &[],
                            &action_library,
                            target_id,
                            &callback_definition_id,
                        ))?;
                    }
                }
            }
        }

        // Re-read the lifter's live action/definition after target Contact
        // and Stuck callbacks. LiftTop is level-triggered on the lifter and
        // runs before the caller's trailing DoGravity.
        if let Some(lifter_idx) = self.find_object_index(lifter_id).filter(|&index| {
            !self.objects[index].destroyed
                && self.objects[index].state.status != ObjectStatus::Deleted
        }) {
            let object = &self.objects[lifter_idx];
            let live_target = object.state.action.target;
            let definition_id = object.definition_id.clone();
            let lift_top = self
                .definitions
                .get(&definition_id)
                .map(Definition::lift_top)
                .unwrap_or(0);
            let should_call = lift_top != 0
                && object.state.command_direction == CommandDirection::Up
                && live_target
                    .and_then(|id| self.find_object_index(id))
                    .is_some_and(|index| {
                        self.objects[index].state.position.y
                            <= object.state.position.y.wrapping_add(lift_top)
                    });
            if should_call {
                if let Some(action_library) = self
                    .definitions
                    .get(&definition_id)
                    .map(|definition| definition.action_library().clone())
                {
                    let _ = tolerate_script_error(self.call_movement_object_function(
                        lifter_idx,
                        "LiftTop",
                        &[],
                        &action_library,
                        lifter_id,
                        &definition_id,
                    ))?;
                }
            }
        }

        Ok(true)
    }

    fn apply_dig_procedure(&mut self, idx: usize, definition_id: &DefinitionId) {
        let (action_name, action_index, predicted, requested, object_id, construction, shape_rect) = {
            let object = &self.objects[idx];
            (
                object.state.action.name.clone(),
                object.state.action.act_map_index,
                Vector2::new(
                    math::fixtoi(object.fixed_position.x + object.fixed_velocity.x),
                    math::fixtoi(object.fixed_position.y + object.fixed_velocity.y),
                ),
                object.state.action.data != 0,
                object.id,
                object.state.construction,
                object.current_shape_rect(),
            )
        };

        let Some(action_library) = self
            .definitions
            .get(definition_id)
            .map(Definition::action_library)
        else {
            return;
        };
        if action_library.is_idle_entry(&action_name, action_index) {
            return;
        }
        let Some(dig_free_value) = action_library.dig_free_for_entry(&action_name, action_index) else {
            return;
        };

        if dig_free_value <= 0 {
            return;
        }

        if dig_free_value == 1 {
            let Some(shape_rect) = shape_rect else {
                return;
            };
            self.execute_dig_rect_operation(
                Vector2::new(
                    predicted.x.saturating_add(shape_rect.x),
                    predicted.y.saturating_add(shape_rect.y),
                ),
                shape_rect.width,
                shape_rect.height,
                requested,
                Some(object_id),
            );
        } else {
            let mut radius = dig_free_value;
            if construction < FULL_CON {
                radius = radius * 6 * construction / 5 / FULL_CON;
            }
            self.execute_dig_circle_operation(
                Vector2::new(predicted.x, predicted.y.saturating_sub(1)),
                radius,
                requested,
                Some(object_id),
            );
        }
    }

    fn dig_column(
        materials: &MaterialSet,
        landscape: &mut Landscape,
        column: i32,
        target_height: i32,
    ) -> Option<(MaterialId, i32)> {
        let width = landscape.width() as i32;
        if column < 0 || width == 0 || column >= width {
            return None;
        }

        if materials.is_empty() {
            landscape.ensure_surface_at_least(column, target_height);
            return None;
        }

        let previous_height = landscape.surface_height(column).unwrap_or(0);
        let Some(material_id) = landscape.solid_material_at(column) else {
            return None;
        };
        let Some(material) = materials.get_by_id(material_id) else {
            return None;
        };
        if !material.dig_free() {
            return None;
        }
        let clamped_target = target_height.max(0);
        let desired_target = if clamped_target <= previous_height {
            let one_beyond = clamped_target.saturating_add(1);
            if one_beyond <= previous_height {
                return None;
            }
            previous_height.saturating_add(1)
        } else {
            clamped_target
        };

        landscape.ensure_surface_at_least(column, desired_target);
        let new_height = landscape.surface_height(column).unwrap_or(previous_height);
        let removed = new_height.saturating_sub(previous_height);
        if removed <= 0 {
            return None;
        }

        Some((material_id, removed))
    }

    fn apply_bridge_procedure(
        &mut self,
        idx: usize,
        command_direction: CommandDirection,
        definition_id: &DefinitionId,
    ) -> Result<bool, EngineError> {
        let parameters = BridgeParameters::from_action_data(self.objects[idx].state.action.data);
        let action_time = self.objects[idx].state.action.time;

        if action_time >= parameters.duration {
            // ObjectActionStand runs inside DoBridge, before DFA_BRIDGE can
            // OR in CNAT_Bottom for this frame (C4Object.cpp:4584,
            // 4996-5006). Preserve only the earlier UprightAttach arm.
            let upright_attach = self.objects[idx].upright_t_attach;
            self.objects[idx].frame_t_attach = upright_attach;
            self.objects[idx].state.t_attach = upright_attach;
            let _ = self.object_action_stand(idx, definition_id)?;
            return Ok(false);
        }

        let Some(step_interval) = parameters.step_interval(command_direction) else {
            return Ok(true);
        };
        // DoBridge overrides the action-data flag for vertical walls and
        // diagonal roofs; only the wall-Up arm may move the Clonk
        // (C4Object.cpp:4587-4592).
        let move_clonk = parameters.move_clonk
            && !(parameters.wall
                && matches!(
                    command_direction,
                    CommandDirection::Left
                        | CommandDirection::Right
                        | CommandDirection::UpLeft
                        | CommandDirection::UpRight
                ));

        if step_interval == 0 || action_time % step_interval != 0 {
            return Ok(true);
        }

        let (base_position, shape_width, shape_height, facing) = {
            let object = &self.objects[idx];
            let shape = object.current_shape_rect();
            (
                object.state.position,
                shape.map(|rect| rect.width).unwrap_or(0),
                shape.map(|rect| rect.height).unwrap_or(0),
                object.state.direction,
            )
        };
        let mut clonk_x = base_position.x;
        let mut clonk_y = base_position.y;
        let mut target_x = base_position.x;
        let mut target_y = base_position.y + shape_height / 2;
        let delta_time = if move_clonk {
            0
        } else {
            (action_time / step_interval) as i32
        };

        // The target formulas are the DoBridge switch verbatim
        // (C4Object.cpp:4605-4630). Keeping all arms here prevents the
        // Tutorial-2 UpLeft path from inheriting the old x-only shortcut.
        if parameters.wall {
            match command_direction {
                CommandDirection::Left => {
                    target_x -= shape_width / 2;
                    target_y -= delta_time;
                }
                CommandDirection::Right => {
                    target_x += shape_width / 2;
                    target_y -= delta_time;
                }
                CommandDirection::Up => {
                    let x0 = if move_clonk {
                        -3
                    } else {
                        (parameters.duration / step_interval) as i32 / -2
                    };
                    let direction = if facing == Direction::Right { 1 } else { -1 };
                    target_x += (x0 + delta_time) * direction;
                    clonk_x += direction;
                    target_y -= shape_height + 3;
                }
                CommandDirection::UpLeft => {
                    target_x -= -4 + delta_time;
                    target_y += -shape_height - 7 + delta_time;
                }
                CommandDirection::UpRight => {
                    target_x += -4 + delta_time;
                    target_y += -shape_height - 7 + delta_time;
                }
                _ => return Ok(true),
            }
        } else {
            match command_direction {
                CommandDirection::Left => {
                    target_x += -2 - delta_time;
                    clonk_x -= 1;
                }
                CommandDirection::Right => {
                    target_x += 2 + delta_time;
                    clonk_x += 1;
                }
                CommandDirection::Up => {
                    let stationary = i32::from(!move_clonk);
                    target_x += (-shape_width / 2
                        + (shape_width - 1) * i32::from(facing == Direction::Right))
                        * stationary;
                    target_y += -delta_time - i32::from(move_clonk);
                    clonk_y -= 1;
                }
                CommandDirection::UpLeft => {
                    target_x += -5 - delta_time + i32::from(move_clonk) * 3;
                    target_y += 2 - delta_time - i32::from(move_clonk) * 3;
                    clonk_x -= 1;
                    clonk_y -= 1;
                }
                CommandDirection::UpRight => {
                    target_x += 5 + delta_time - i32::from(move_clonk) * 2;
                    target_y += 2 - delta_time - i32::from(move_clonk) * 3;
                    clonk_x += 1;
                    clonk_y -= 1;
                }
                _ => return Ok(true),
            }
        }

        // Shape.CheckContact(cx, cy-1) runs before drawing. A blocked moving
        // bridge rewrites the remaining bridge as stationary and immediately
        // retries at Action.Time 0 (C4Object.cpp:4631-4646).
        if move_clonk
            && self.object_shape_contacts_at(idx, Vector2::new(clonk_x, clonk_y - 1))
        {
            let mut remaining = parameters.duration.saturating_sub(action_time);
            let mut retry_time = 0;
            if parameters.wall && command_direction == CommandDirection::Up {
                retry_time = remaining;
                remaining = remaining.saturating_mul(2).min(0xffff);
            }
            let material = parameters
                .material
                .map(|material| material.index() as i32)
                .unwrap_or(-1);
            let object = &mut self.objects[idx];
            object.state.action.time = retry_time;
            object.state.action.data =
                encode_bridge_action_data(remaining, false, parameters.wall, material);
            return self.apply_bridge_procedure(idx, command_direction, definition_id);
        }

        if let Some(material) = parameters.material {
            self.draw_material_rect(material, target_x - 2, target_y, 4, 3);
        }

        if move_clonk {
            // C4Object::MovePosition removes/re-puts the solid mask with rider
            // backup, adds integer deltas to the true fixed coordinates, and
            // updates sectors (C4Movement.cpp:547-556).
            let attachments = self.remove_solid_mask_for_movement(idx);
            let object = &mut self.objects[idx];
            object.state.position = Vector2::new(clonk_x, clonk_y);
            object.fixed_position.x += itofix(clonk_x - base_position.x);
            object.fixed_position.y += itofix(clonk_y - base_position.y);
            self.update_sector_for_index(idx);
            self.update_solid_mask(idx);
            self.restore_solid_mask_attachments(idx, attachments);
        }

        Ok(true)
    }

    /// C4Landscape::DrawMaterialRect (C4Landscape.cpp:1064-1072): direct
    /// Surface8 writes, with density first and DigFree as the equal-density
    /// tie-break. SetPix preserves the destination IFT bit. Unlike script
    /// DrawMaterialQuad this deliberately does not enter PrepareChange.
    fn draw_material_rect(
        &mut self,
        material: MaterialId,
        x: i32,
        y: i32,
        width: i32,
        height: i32,
    ) {
        let Some(bridge) = self.materials.get_by_id(material) else {
            return;
        };
        let bridge_density = bridge.density();
        let bridge_dig_free = i32::from(bridge.dig_free());
        let materials = &self.materials;
        let Some(landscape) = self.landscape.as_mut() else {
            return;
        };

        for target_y in y..y.saturating_add(height) {
            for target_x in x..x.saturating_add(width) {
                let current_density = landscape.density_at(target_x, target_y, materials);
                let current_dig_free = landscape
                    .border_material_at(target_x, target_y)
                    .and_then(|current| materials.get_by_id(current))
                    .map(|current| i32::from(current.dig_free()))
                    // MatDigFree(MNone) is 1 (C4Wrappers.h:153-157).
                    .unwrap_or(1);
                if bridge_density > current_density
                    || (bridge_density == current_density
                        && bridge_dig_free <= current_dig_free)
                {
                    let _ = landscape.insert_material_pix(target_x, target_y, material);
                }
            }
        }
    }

    fn apply_build_procedure(&mut self, idx: usize) -> Result<bool, EngineError> {
        let builder_id = self.objects[idx].id;
        let category = self.objects[idx].state.category;
        let is_structure = (category & (CATEGORY_STRUCTURE | CATEGORY_STATIC_BACK)) != 0;

        let target_id = match self.objects[idx].state.action.target {
            Some(id) => id,
            None => {
                if is_structure {
                    return Ok(true);
                }
                let _ = self.object_com_stop_build(builder_id)?;
                return Ok(false);
            }
        };

        let target_idx = match self.find_object_index(target_id) {
            Some(index) if index != idx => index,
            _ => {
                let _ = self.object_com_stop_build(builder_id)?;
                return Ok(false);
            }
        };

        // An internal construction is supported only while its live
        // container is itself building and has power (C4Object.cpp:
        // 5016-5020). This bare return deliberately precedes both the area
        // and completed-target checks and does not stop the builder.
        if let Some(container_id) = self.objects[target_idx].state.container {
            let supported = self
                .find_object_index(container_id)
                .is_some_and(|container_idx| {
                    let container = &self.objects[container_idx];
                    !container.state.need_energy
                        && self.definitions.get(&container.definition_id).is_some_and(
                            |definition| {
                                definition
                                    .action_library()
                                    .procedure_for_entry(
                                        &container.state.action.name,
                                        container.state.action.act_map_index,
                                    )
                                    == ActionProcedure::Build
                            },
                        )
                });
            if !supported {
                return Ok(false);
            }
        }

        // C++ tests the builder's integer position against the target's
        // current C4Shape, with inclusive Inside bounds. A definition-less
        // shape is the native zero rectangle, not the expanded sector area.
        let builder_position = self.objects[idx].state.position;
        let target_position = self.objects[target_idx].state.position;
        let shape = self.objects[target_idx]
            .current_shape_rect()
            .unwrap_or_default();
        let dx = i64::from(builder_position.x)
            - (i64::from(target_position.x) + i64::from(shape.x));
        let dy = i64::from(builder_position.y)
            - (i64::from(target_position.y) + i64::from(shape.y));
        let in_target_area = dx >= 0
            && dx <= i64::from(shape.width)
            && dy >= -16
            && dy <= i64::from(shape.height) + 16;
        if !in_target_area {
            let _ = self.object_com_stop_build(builder_id)?;
            return Ok(false);
        }

        if !self.objects[target_idx].has_nonzero_status()
            || self.objects[target_idx].state.construction >= FULL_CON
        {
            // Target::Build returns false once full. The common failure tail
            // stops first and then may SetCommand(Exit) on an internal target.
            self.finish_failed_build(builder_id)?;
            return Ok(false);
        }

        // DFA_BUILD chooses the external/internal level before entering
        // Target::Build. GetCustomComponents may recontain the target, but
        // that side effect only changes the next tick's level.
        let level = if self.objects[target_idx].state.container.is_some() {
            1
        } else {
            10
        };
        let target_definition_id = self.objects[target_idx].definition_id.clone();
        let need_material = self.construction_needs_material
            || (self.objects[target_idx].state.category
                & (CATEGORY_STRUCTURE | CATEGORY_STATIC_BACK))
                == 0;
        let required_components = if need_material {
            self.build_required_components(&target_definition_id, builder_id)?
        } else {
            Vec::new()
        };

        let missing_component = if need_material {
            self.ensure_build_components(idx, target_idx, &required_components)?
        } else {
            None
        };
        if let Some((missing_component, missing_count)) = missing_component {
            // C4Object::Build lets the builder override missing-material
            // handling after the component-grab pass. Script errors are
            // fail-safe/falsy like C4Object::Call (C4Object.cpp:1734-1748).
            let handled = tolerate_script_error(self.call_object_function(
                idx,
                "BuildNeedsMaterial",
                vec![
                    Value::C4Id(missing_component.clone()),
                    Value::Int(missing_count),
                ],
            ))?
            .is_some_and(|value| compat::value_raw_truthy(&value));

            if !handled {
                // The callback may have changed the builder's controller,
                // OCF, commands, or definition, so re-resolve its live state.
                if let Some(builder_idx) = self.find_object_index(builder_id).filter(|&index| {
                    !self.objects[index].destroyed
                        && !matches!(self.objects[index].state.status, ObjectStatus::Deleted)
                }) {
                    if self.objects[builder_idx].state.ocf & ocf::CREW_MEMBER != 0 {
                        // AddCommand(Acquire) is a retrying SilentSub in front
                        // of the retained Build order.
                        let acquire = CommandRequest::new(CommandId::Acquire)
                            .with_data(CommandData::Text(missing_component))
                            .with_update_interval(50)
                            .with_retries(1)
                            .with_mode(CommandMode::SilentSub);
                        self.objects[builder_idx]
                            .apply_command_operations([CommandOperation::PushFront(acquire)]);
                    }

                    // C4Object::GetNeededMatStr runs after the callback and
                    // may itself call GetCustomComponents with the builder.
                    // Evaluate the existing compatibility host in the
                    // builder's context so it sees the same live state.
                    let expression = format!("GetNeededMatStr(Object({target_id}))");
                    let text = tolerate_script_error(self.direct_exec_on_object(
                        builder_idx,
                        &expression,
                        "Build:GetNeededMatStr",
                    ))?
                    .and_then(|value| match value {
                        Value::String(text) => Some(text.into_string()),
                        _ => None,
                    });
                    if let Some(text) = text {
                        if let Some(builder_idx) =
                            self.find_object_index(builder_id).filter(|&index| {
                                !self.objects[index].destroyed
                                    && !matches!(
                                        self.objects[index].state.status,
                                        ObjectStatus::Deleted
                                    )
                            })
                        {
                            let controller = self.objects[builder_idx].state.controller;
                            self.messages.add_message(MessageSpec {
                                kind: message::MessageKind::Target,
                                text,
                                target: Some(builder_id),
                                player: (controller != OWNER_NONE).then_some(controller),
                                offset: Vector2::new(-1, -1),
                                color: 0xffff_ffff,
                                flags: 0,
                                width: None,
                                decoration: None,
                                frame_decoration: None,
                                portrait: None,
                            });
                        }
                    }
                }
            }

            // BuildNeedsMaterial may itself complete, remove, or retarget the
            // construction. Re-read the native failure split before stopping.
            self.finish_failed_build(builder_id)?;
            return Ok(false);
        }

        // Component-removal callbacks may have changed either object's live
        // definition or physicals. C++ reads GetPhysical and Def->Mass only
        // after both material passes (C4Object.cpp:1751-1763).
        let Some(builder_idx) = self.find_object_index(builder_id) else {
            return Ok(false);
        };
        let mut build_speed = self.object_physical(builder_idx).can_construct;
        if build_speed == 0 {
            self.finish_failed_build(builder_id)?;
            return Ok(false);
        }
        if build_speed <= 1 {
            build_speed = 100;
        }

        let Some(target_idx) = self.find_object_index(target_id) else {
            self.finish_failed_build(builder_id)?;
            return Ok(false);
        };
        let target_mass = self
            .definitions
            .get(&self.objects[target_idx].definition_id)
            .map(Definition::mass)
            .unwrap_or(100);
        let target_mass = if target_mass == 0 { 1 } else { target_mass };
        let delta = (i64::from(level) * i64::from(build_speed) * 150)
            / i64::from(target_mass);
        let delta = delta.clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32;
        let current_construction = self.objects[target_idx].state.construction;
        let desired_construction = current_construction
            .saturating_add(delta)
            .clamp(0, FULL_CON);
        let crossed_full_con = current_construction < FULL_CON
            && desired_construction >= FULL_CON;
        let refresh_components = !need_material
            && docon_refreshes_construction(current_construction, desired_construction);
        let gained_components = refresh_components.then(|| {
            let definition_components = self
                .definitions
                .get(&self.objects[target_idx].definition_id)
                .map(|definition| {
                    definition
                        .components()
                        .iter()
                        .map(|component| (component.id.clone(), component.count))
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            docon_component_counts(
                &self.objects[target_idx].state.components,
                &self.objects[target_idx].state.component_order,
                &definition_components,
                desired_construction,
                delta,
            )
        });
        self.objects[target_idx].set_construction(desired_construction);
        if let Some(components) = gained_components {
            self.objects[target_idx].state.components = components;
        }
        self.refresh_object_ocf(target_idx);
        self.update_sector_for_index(target_idx);
        self.update_solid_mask(target_idx);

        // C4Object::DoCon dispatches Completion and then Initialize after
        // the bottom-preserving shape adjustment on the first FullCon
        // crossing (C4Object.cpp:1498-1503). Completion may delete the
        // target, in which case C++ suppresses Initialize.
        if crossed_full_con {
            if let Some(completion_idx) = self
                .find_object_index(target_id)
                .filter(|&index| self.object_survives_creation(index))
            {
                let _ = tolerate_script_error(self.call_object_function(
                    completion_idx,
                    "Completion",
                    Vec::new(),
                ))?;
            }
            if let Some(initialize_idx) = self
                .find_object_index(target_id)
                .filter(|&index| self.object_survives_creation(index))
            {
                let _ = tolerate_script_error(self.call_object_function(
                    initialize_idx,
                    "Initialize",
                    Vec::new(),
                ))?;
            }
        }

        // BuildTurnTo is read from the live definition only after DoCon's
        // Completion/Initialize callbacks, and runs on every successful
        // Build tick (C4Object.cpp:1765-1769).
        let build_turn_to = self
            .find_object_index(target_id)
            .and_then(|index| self.definitions.get(&self.objects[index].definition_id))
            .and_then(|definition| definition.build_turn_to().map(str::to_owned));
        if let (Some(target_idx), Some(build_turn_to)) =
            (self.find_object_index(target_id), build_turn_to)
        {
            let _ = self.change_object_def_live(target_idx, &build_turn_to)?;
        }
        if let Some(target_idx) = self.find_object_index(target_id) {
            self.objects[target_idx].state.damage = 0;
        }

        // Unlike most procedure attachment bits, DFA_BUILD adds Bottom only
        // after Target::Build succeeds (C4Object.cpp:5052-5055). All guard
        // and Build-failure returns retain only the pre-switch base bits.
        if let Some(builder_idx) = self.find_object_index(builder_id) {
            let builder = &mut self.objects[builder_idx];
            builder.frame_t_attach |= CNAT_BOTTOM;
            builder.state.t_attach = builder.frame_t_attach;
        }

        Ok(true)
    }

    /// `C4Def::GetComponents(..., pObjInstance=nullptr, pBuilder)` for
    /// `C4Object::Build`. The definition callback has no object `this`, but
    /// receives the builder and commits synchronous host side effects before
    /// the material scan. Only an array overrides the DefCore component list.
    fn build_required_components(
        &mut self,
        definition_id: &DefinitionId,
        builder_id: ObjectId,
    ) -> Result<Vec<DefinitionComponent>, EngineError> {
        let Some((script, static_components, has_custom_components)) = self
            .definitions
            .get(definition_id)
            .map(|definition| {
                (
                    definition.script_arc(),
                    definition.components().to_vec(),
                    definition.has_function("GetCustomComponents"),
                )
            })
        else {
            return Ok(Vec::new());
        };
        if !has_custom_components {
            return Ok(static_components);
        }

        let world = self.host_world_context();
        let (value, _args, batch, audio_state, rng, script_error) =
            ScenarioScript::call_value_for_script(
                definition_id,
                &script,
                Some(definition_id.clone()),
                "GetCustomComponents",
                &[object_reference_value(builder_id)],
                world,
                self.rng.clone(),
                self.frame,
                &self.global_effects.clone(),
                self.physics,
                self.environment,
                self.audio_registry.clone(),
                self.game_over_triggered,
            );
        self.rng = rng;
        self.audio_registry = audio_state;
        self.apply_scenario_batch(batch)?;
        if let Some(error) = script_error {
            tolerate_script_error::<()>(Err(error))?;
            return Ok(static_components);
        }

        let Some(Value::Array(values)) = value else {
            return Ok(static_components);
        };
        Ok(compat::component_list_from_custom_array(&values)
            .into_iter()
            .map(|(id, count)| DefinitionComponent { id, count })
            .collect())
    }

    /// The ordinary (non-forced) ObjectComStop used by DFA_BUILD
    /// (C4ObjectCom.cpp:239-245). Re-resolve after Idle because its callbacks
    /// may remove the builder or change the definition used by Walk.
    fn object_com_stop_build(&mut self, builder_id: ObjectId) -> Result<bool, EngineError> {
        let Some(_) = self.find_object_index(builder_id).filter(|&index| {
            !self.objects[index].destroyed
                && !matches!(self.objects[index].state.status, ObjectStatus::Deleted)
        }) else {
            return Ok(false);
        };
        self.object_com_stop_live(builder_id)
    }

    /// Shared false return from `C4Object::Build` (C4Object.cpp:5033-5051).
    /// The complete/missing decision uses the live pre-stop Action.Target;
    /// internal Exit uses the post-stop target because action callbacks may
    /// clear, replace, remove, or recontain it.
    fn finish_failed_build(&mut self, builder_id: ObjectId) -> Result<(), EngineError> {
        let complete_or_missing = self
            .find_object_index(builder_id)
            .and_then(|builder_idx| self.objects[builder_idx].state.action.target)
            .is_none_or(|target_id| {
                self.find_object_index(target_id).is_none_or(|target_idx| {
                    self.objects[target_idx].state.construction >= FULL_CON
                })
            });

        let _ = self.object_com_stop_build(builder_id)?;

        if !complete_or_missing {
            return Ok(());
        }
        let Some(target_idx) = self
            .find_object_index(builder_id)
            .and_then(|builder_idx| self.objects[builder_idx].state.action.target)
            .and_then(|target_id| self.find_object_index(target_id))
            .filter(|&target_idx| self.objects[target_idx].state.container == Some(builder_id))
        else {
            return Ok(());
        };
        self.set_plain_exit_command(target_idx)
    }

    /// DFA_CHOP (C4Object.cpp:5202-5221): every Tick3 asks the current
    /// target to Chop; C4Object::Chop applies +10 damage only on Tick10
    /// (C4Object.cpp:1775-1782). The target must remain chop-capable and
    /// cover the chopper's current position, then the chopper faces it.
    fn apply_chop_procedure(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
    ) -> Result<bool, EngineError> {
        let Some(target_id) = self.objects[idx].state.action.target else {
            let _ = self.object_action_stand(idx, definition_id)?;
            return Ok(false);
        };
        let Some(target_idx) = self.find_object_index(target_id) else {
            let _ = self.object_action_stand(idx, definition_id)?;
            return Ok(false);
        };
        let target_can_be_chopped = {
            let target = &self.objects[target_idx];
            target.has_nonzero_status()
                && target.state.container.is_none()
                && self.definitions.contains_key(&target.definition_id)
                && target.state.ocf & crate::ocf::CHOP != 0
        };
        if !target_can_be_chopped {
            let _ = self.object_action_stand(idx, definition_id)?;
            return Ok(false);
        }

        if self.frame % 3 == 0 && self.frame % 10 == 0 {
            let caused_by = self.objects[idx].state.owner;
            self.change_object_damage(target_idx, 10, C4FX_CALL_DMG_CHOP, caused_by)?;
        }

        // Damage callbacks may remove or otherwise invalidate the target;
        // C++ rechecks Action.Target immediately after Chop returns.
        let Some(target_id) = self.objects[idx].state.action.target else {
            let _ = self.object_action_stand(idx, definition_id)?;
            return Ok(false);
        };
        let Some(target_idx) = self.find_object_index(target_id) else {
            let _ = self.object_action_stand(idx, definition_id)?;
            return Ok(false);
        };
        let chopper_position = self.objects[idx].state.position;
        let target = &self.objects[target_idx];
        let target_is_at_chopper = target.has_nonzero_status()
            && target.state.container.is_none()
            && target.state.ocf & crate::ocf::CHOP != 0
            && self
                .object_shape_rect(target)
                .contains_point(chopper_position.x, chopper_position.y);
        if !target_is_at_chopper {
            let _ = self.object_action_stand(idx, definition_id)?;
            return Ok(false);
        }

        let direction = if chopper_position.x > target.state.position.x {
            Direction::Left
        } else {
            Direction::Right
        };
        self.set_exec_action_direction(idx, definition_id, direction)?;
        Ok(true)
    }

    fn ensure_build_components(
        &mut self,
        builder_idx: usize,
        target_idx: usize,
        required: &[DefinitionComponent],
    ) -> Result<Option<(DefinitionId, i32)>, EngineError> {
        if required.is_empty() {
            return Ok(None);
        }

        // Target::Build makes two independent passes: at most one full-con
        // object of every missing component from the builder, then at most
        // one more from the construction's container (C4Object.cpp:1694-1723).
        for component in required {
            let inserted = self.objects[target_idx]
                .state
                .components
                .get(&component.id)
                .copied()
                .unwrap_or(0);

            if inserted < component.count {
                if let Some(material_id) =
                    self.first_eligible_build_component(builder_idx, &component.id)
                {
                    self.credit_build_component(target_idx, &component.id, inserted);
                    self.consume_build_component(builder_idx, material_id)?;
                }
            }
        }

        for component in required {
            let inserted = self.objects[target_idx]
                .state
                .components
                .get(&component.id)
                .copied()
                .unwrap_or(0);

            if inserted < component.count {
                if let Some((container_idx, material_id)) =
                    self.first_build_component_from_container_of(target_idx, &component.id)
                {
                    self.credit_build_component(target_idx, &component.id, inserted);
                    self.consume_build_component(container_idx, material_id)?;
                }
            }
        }

        Ok(required.iter().find_map(|component| {
            (component.count != 0)
                .then(|| {
                    let inserted = self.objects[target_idx]
                        .state
                        .components
                        .get(&component.id)
                        .copied()
                        .unwrap_or(0);
                    let inserted_percent =
                        i64::from(inserted).saturating_mul(100) / i64::from(component.count);
                    let construction_percent =
                        i64::from(self.objects[target_idx].state.construction).saturating_mul(100)
                            / i64::from(FULL_CON);
                    (inserted_percent < construction_percent)
                        .then(|| (component.id.clone(), component.count.wrapping_sub(inserted)))
                })
                .flatten()
        }))
    }

    /// C4ObjectList::Find(id) returns the first matching live content. Build
    /// tests only that one for OnFire/OCF_FullCon; an ineligible head blocks
    /// later same-ID entries for this pass (C4Object.cpp:1697-1709).
    fn first_eligible_build_component(
        &self,
        container_index: usize,
        component_id: &DefinitionId,
    ) -> Option<ObjectId> {
        if container_index >= self.objects.len() {
            return None;
        }
        for &object_id in &self.objects[container_index].state.contents {
            let Some(child_index) = self.find_object_index(object_id) else {
                continue;
            };
            let child = &self.objects[child_index];
            if child.definition_id != *component_id
                || child.destroyed
                || matches!(child.state.status, ObjectStatus::Deleted)
            {
                continue;
            }
            return (!child.state.on_fire && child.state.ocf & ocf::FULL_CON != 0)
                .then_some(object_id);
        }
        None
    }

    fn first_build_component_from_container_of(
        &self,
        object_index: usize,
        component_id: &DefinitionId,
    ) -> Option<(usize, ObjectId)> {
        if object_index >= self.objects.len() {
            return None;
        }
        let container_id = match self.objects[object_index].state.container {
            Some(id) => id,
            None => return None,
        };
        let container_index = self.find_object_index(container_id)?;
        self.first_eligible_build_component(container_index, component_id)
            .map(|material_id| (container_index, material_id))
    }

    fn credit_build_component(
        &mut self,
        target_idx: usize,
        component_id: &DefinitionId,
        previous_count: i32,
    ) {
        let target_state = &mut self.objects[target_idx].state;
        if !target_state.components.contains_key(component_id) {
            target_state.component_order.push(component_id.clone());
        }
        target_state
            .components
            .insert(component_id.clone(), previous_count.wrapping_add(1));
    }

    /// Build credits the component, unlinks it from the parent list, then
    /// calls native AssignRemoval while the child's Contained pointer still
    /// names that parent (C4Object.cpp:1705-1709,1717-1721).
    fn consume_build_component(
        &mut self,
        container_index: usize,
        material_id: ObjectId,
    ) -> Result<(), EngineError> {
        if self.objects.get(container_index).is_none() {
            return Ok(());
        }
        if self.find_object_index(material_id).is_none() {
            return Ok(());
        }
        self.objects[container_index]
            .state
            .contents
            .retain(|&id| id != material_id);
        let _ = self.assign_object_removal(material_id)?;
        Ok(())
    }

    fn reset_action_to_default(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        clear_targets: bool,
    ) {
        let library = self
            .definitions
            .get(definition_id)
            .map(|definition| definition.action_library().clone())
            .unwrap_or_default();
        let default_action = library.default_action().to_string();
        let previous = self.objects[idx].state.action.clone();

        let update = ActionUpdate {
            name: Some(default_action),
            phase: Some(0),
            ticks: Some(0),
            force: true,
            data: None,
            target: if clear_targets { Some(None) } else { None },
            target2: if clear_targets { Some(None) } else { None },
            callbacks_dispatched: false,
        };

        let object = &mut self.objects[idx];
        let result = object
            .state
            .action
            .apply_update_with_library(&update, &library);
        // SetAction fix resync (C4Object.cpp:4144) — only past the
        // NoOtherAction early returns.
        if update.name.is_some() && matches!(result, ActionUpdateResult::Applied) {
            object.fixed_position =
                FixedVec2::from_ints(object.state.position.x, object.state.position.y);
        }
        if clear_targets {
            object.state.action.target = None;
            object.state.action.target2 = None;
            object.compiler_cache.action_target1 = 0;
            object.compiler_cache.action_target2 = 0;
        }
        object.state.command_direction = CommandDirection::Stop;
        object.set_velocity(Vector2::ZERO);
        if matches!(result, ActionUpdateResult::Applied)
            && (previous.name != object.state.action.name
                || previous.act_map_index != object.state.action.act_map_index)
        {
            object.record_action_event(previous, ActionTransitionKind::Forced);
        }
    }

    /// `ReduceLineSegments` (C4Object.cpp:4683-4694): remove the first
    /// redundant bend whose surrounding vertices have a clear direct path.
    /// The alternate pass skips two vertices and removes both of them.
    fn reduce_line_segments(
        landscape: Option<&Landscape>,
        vertices: &mut Vec<ObjectVertex>,
        alternate: bool,
    ) -> bool {
        let skip = 2 + usize::from(alternate);
        let redundant = (0..vertices.len().saturating_sub(skip)).find(|&index| {
            let from = Vector2::new(vertices[index].x, vertices[index].y);
            let to = Vector2::new(vertices[index + skip].x, vertices[index + skip].y);
            landscape
                .map(|landscape| landscape.path_is_clear(from, to))
                .unwrap_or(true)
        });
        let Some(index) = redundant else {
            return false;
        };
        if alternate {
            vertices.remove(index + 2);
        }
        vertices.remove(index + 1);
        true
    }

    /// The per-pixel `ForLine` walk behind C++ `PathFree`, including its
    /// canonical low-to-high major-axis traversal (C4Landscape.cpp:1670-1722).
    fn line_first_collision(
        landscape: Option<&Landscape>,
        start: Vector2,
        end: Vector2,
        ignore_vehicle: bool,
    ) -> Option<Vector2> {
        let landscape = landscape?;
        let (mut x1, mut y1) = (i64::from(start.x), i64::from(start.y));
        let (mut x2, mut y2) = (i64::from(end.x), i64::from(end.y));
        let blocked = |x: i64, y: i64| {
            let (x, y) = (x as i32, y as i32);
            let solid = if ignore_vehicle {
                landscape.is_solid_ignoring_vehicle_at(x, y)
            } else {
                landscape.is_solid_at(x, y)
            };
            solid.then_some(Vector2::new(x, y))
        };

        if (x2 - x1).abs() < (y2 - y1).abs() {
            if y1 > y2 {
                std::mem::swap(&mut x1, &mut x2);
                std::mem::swap(&mut y1, &mut y2);
            }
            let x_increment = if x2 > x1 { 1 } else { -1 };
            let dy = y2 - y1;
            let dx = (x2 - x1).abs();
            let mut decision = 2 * dx - dy;
            let advance_both = 2 * (dx - dy);
            let advance_y = 2 * dx;
            let mut x = x1;
            if let Some(hit) = blocked(x, y1) {
                return Some(hit);
            }
            for y in (y1 + 1)..=y2 {
                if decision >= 0 {
                    x += x_increment;
                    decision += advance_both;
                } else {
                    decision += advance_y;
                }
                if let Some(hit) = blocked(x, y) {
                    return Some(hit);
                }
            }
        } else {
            if x1 > x2 {
                std::mem::swap(&mut x1, &mut x2);
                std::mem::swap(&mut y1, &mut y2);
            }
            let y_increment = if y2 > y1 { 1 } else { -1 };
            let dx = x2 - x1;
            let dy = (y2 - y1).abs();
            let mut decision = 2 * dy - dx;
            let advance_both = 2 * (dy - dx);
            let advance_x = 2 * dy;
            let mut y = y1;
            if let Some(hit) = blocked(x1, y) {
                return Some(hit);
            }
            for x in (x1 + 1)..=x2 {
                if decision >= 0 {
                    y += y_increment;
                    decision += advance_both;
                } else {
                    decision += advance_x;
                }
                if let Some(hit) = blocked(x, y) {
                    return Some(hit);
                }
            }
        }
        None
    }

    /// `C4Shape::LineConnect` (C4Shape.cpp:273-326): move one endpoint of
    /// a wrapping line, inserting the first viable bend around the first
    /// solid pixel when the direct path to its neighbour is blocked.
    fn line_connect_endpoint(
        landscape: Option<&Landscape>,
        vertices: &mut Vec<ObjectVertex>,
        target: Vector2,
        endpoint: usize,
        direction: isize,
    ) -> bool {
        const MAX_VERTEX_COUNT: usize = 30; // C4D_MaxVertex

        if vertices.len() < 2 {
            return false;
        }
        let Some(neighbour) = endpoint.checked_add_signed(direction) else {
            return false;
        };
        if neighbour >= vertices.len() {
            return false;
        }
        if (vertices[endpoint].x, vertices[endpoint].y) == (target.x, target.y) {
            return true;
        }

        let neighbour_point = Vector2::new(vertices[neighbour].x, vertices[neighbour].y);
        let collision = Self::line_first_collision(landscape, target, neighbour_point, false);
        let Some(collision) = collision else {
            vertices[endpoint].x = target.x;
            vertices[endpoint].y = target.y;
            return true;
        };

        let path_is_clear =
            |from, to| Self::line_first_collision(landscape, from, to, false).is_none();
        let bend = [4, 8, 12].into_iter().find_map(|range| {
            let half = range / 2;
            [collision.x - half, collision.x + half]
                .into_iter()
                .find_map(|x| {
                    [collision.y - half, collision.y + half]
                        .into_iter()
                        .map(|y| Vector2::new(x, y))
                        .find(|&candidate| {
                            path_is_clear(candidate, target)
                                && path_is_clear(candidate, neighbour_point)
                        })
                })
        });

        let old_endpoint = Vector2::new(vertices[endpoint].x, vertices[endpoint].y);
        let path_is_clear_ignoring_vehicle =
            |from, to| Self::line_first_collision(landscape, from, to, true).is_none();
        let Some(bend) = bend.or_else(|| {
            (path_is_clear_ignoring_vehicle(old_endpoint, target)
                && path_is_clear_ignoring_vehicle(old_endpoint, neighbour_point))
            .then_some(old_endpoint)
        }) else {
            return false;
        };
        if vertices.len() >= MAX_VERTEX_COUNT {
            return false;
        }

        if direction > 0 {
            vertices.insert(endpoint + 1, ObjectVertex::new(bend.x, bend.y));
            vertices[endpoint].x = target.x;
            vertices[endpoint].y = target.y;
        } else {
            vertices.insert(endpoint, ObjectVertex::new(bend.x, bend.y));
            vertices[endpoint + 1].x = target.x;
            vertices[endpoint + 1].y = target.y;
        }
        true
    }

    /// DFA_CONNECT (C4Object.cpp:5341-5420): a Line object's first
    /// vertex tracks Action.Target and its last vertex Action.Target2 —
    /// C4D_Line_Vertex (8) connects to the target's own vertex (index
    /// from the numbered Local[2]/Local[3], both 0 for CHBM), any other
    /// line type to the target's bottom center (x, y + Shape.Hgt/4).
    /// LineIntersect=1 assigns the ABSOLUTE point directly; a missing or
    /// incomplete target fires LineBreak(true) and removes the line.
    /// Returns false when the object removed itself.
    fn exec_connect_line(&mut self, idx: usize) -> Result<bool, EngineError> {
        let definition_id = self.objects[idx].definition_id.clone();
        let Some(definition) = self.definitions.get(&definition_id) else {
            return Ok(true);
        };
        if definition.line() == 0 {
            return Ok(true);
        }
        let action_name = self.objects[idx].state.action.name.clone();
        let action_index = self.objects[idx].state.action.act_map_index;
        if definition
            .action_library()
            .procedure_for_entry(&action_name, action_index)
            != ActionProcedure::Connect
        {
            return Ok(true);
        }
        let line_vertex = definition.line() == 8; // C4D_Line_Vertex
        let line_intersect = definition.line_intersect();
        let vertex_indices = ["__local_2", "__local_3"].map(|name| {
            self.objects[idx]
                .state
                .local_vars
                .get(name)
                .and_then(Value::as_c4_int)
                .unwrap_or(0)
        });

        let mut broke = false;
        let mut points = [None, None];
        for (slot, target_id) in [
            (0usize, self.objects[idx].state.action.target),
            (1usize, self.objects[idx].state.action.target2),
        ] {
            let resolved =
                target_id
                    .and_then(|id| self.find_object_index(id))
                    .filter(|&target_idx| {
                        self.objects[target_idx].state.construction >= FULL_CON
                    });
            match resolved {
                None => broke = true,
                Some(target_idx) => {
                    let target = &self.objects[target_idx];
                    let point = if line_vertex {
                        // C4Shape::GetVertexX/Y return zero for every index
                        // outside the active vertex range.
                        let (vertex_x, vertex_y) = usize::try_from(vertex_indices[slot])
                            .ok()
                            .and_then(|index| target.state.vertices.get(index))
                            .map(|vertex| (vertex.x, vertex.y))
                            .unwrap_or((0, 0));
                        Vector2::new(
                            target.state.position.x + vertex_x,
                            target.state.position.y + vertex_y,
                        )
                    } else {
                        let height = target
                            .current_shape_rect()
                            .map(|rect| rect.height)
                            .unwrap_or(0);
                        Vector2::new(
                            target.state.position.x,
                            target.state.position.y + height / 4,
                        )
                    };
                    points[slot] = Some(point);
                }
            }
        }

        if broke {
            // Call(PSF_LineBreak, {true}) then AssignRemoval
            // (C4Object.cpp:5349-5353); the call is fail-safe like every
            // engine callback.
            if self
                .definitions
                .get(&definition_id)
                .map(|definition| definition.has_function("LineBreak"))
                .unwrap_or(false)
            {
                tolerate_script_error(self.call_object_function(
                    idx,
                    "LineBreak",
                    vec![Value::Bool(true)],
                ))?;
            }
            if idx < self.objects.len() && !self.objects[idx].destroyed {
                tracing::warn!(
                    object = self.objects[idx].id.as_u64(),
                    "CONNECTBREAK exec_connect_line removes the line"
                );
                // Connect beams carry no effects in content; drop the
                // stop events like the simple destroy paths.
                let _ = self.objects[idx].mark_destroyed();
            }
            return Ok(false);
        }

        let reduce_segments = self.frame % 35 == 0;
        let alternate_reduction = self.frame % 2 == 0;
        let movement_broke = {
            let landscape = self.landscape.as_ref();
            let object = &mut self.objects[idx];
            if object.state.vertices.is_empty() {
                return Ok(true);
            }
            let mut movement_broke = false;
            if line_intersect == 1 {
                if let Some(point) = points[0] {
                    object.state.vertices[0].x = point.x;
                    object.state.vertices[0].y = point.y;
                }
                if let Some(point) = points[1] {
                    let last = object.state.vertices.len() - 1;
                    object.state.vertices[last].x = point.x;
                    object.state.vertices[last].y = point.y;
                }
            } else {
                if let Some(point) = points[0] {
                    movement_broke |= !Self::line_connect_endpoint(
                        landscape,
                        &mut object.state.vertices,
                        point,
                        0,
                        1,
                    );
                }
                if let Some(point) = points[1] {
                    let last = object.state.vertices.len() - 1;
                    movement_broke |= !Self::line_connect_endpoint(
                        landscape,
                        &mut object.state.vertices,
                        point,
                        last,
                        -1,
                    );
                }
            }
            // ExecAction's CONNECT branch prunes at most one redundant run on
            // !Tick35, alternating one- and two-bend skips with !Tick2
            // (C4Object.cpp:5443-5445).
            if !movement_broke && reduce_segments {
                Self::reduce_line_segments(
                    landscape,
                    &mut object.state.vertices,
                    alternate_reduction,
                );
            }
            movement_broke
        };
        if movement_broke {
            if self
                .definitions
                .get(&definition_id)
                .map(|definition| definition.has_function("LineBreak"))
                .unwrap_or(false)
            {
                tolerate_script_error(self.call_object_function(idx, "LineBreak", Vec::new()))?;
            }
            if idx < self.objects.len() && !self.objects[idx].destroyed {
                let _ = self.objects[idx].mark_destroyed();
            }
            return Ok(false);
        }
        Ok(true)
    }

    /// C4Object::SetDir as reached from an internal ExecAction procedure
    /// (C4Object.cpp:4248-4265): run the current action's TurnAction through
    /// SetActionByName on a facing change, then assign the requested direction
    /// even if that transition failed or changed actions. The shared SetDir
    /// entry rejects idle and out-of-range directions first, including signed
    /// zero/negative Directions values (C4Object.cpp:4237-4240).
    fn set_exec_action_direction(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        direction: Direction,
    ) -> Result<(), EngineError> {
        let Some((current_direction, turn_action)) = self
            .definitions
            .get(definition_id)
            .and_then(|definition| {
                let library = definition.action_library();
                let action = &self.objects[idx].state.action;
                let raw_direction = direction.to_script_value();
                (!library.is_idle_state(action)
                    && raw_direction >= 0
                    && raw_direction
                        < library.directions_for_entry(&action.name, action.act_map_index))
                    .then(|| {
                        (
                            self.objects[idx].state.direction,
                            library
                                .turn_action_for_entry(&action.name, action.act_map_index)
                                .map(str::to_string),
                        )
                    })
            })
        else {
            return Ok(());
        };
        if direction != current_direction {
            if let Some(turn_action) = turn_action {
                self.action_with_calls(idx, definition_id, &turn_action)?;
            }
        }
        self.objects[idx].state.direction = direction;
        Ok(())
    }

    /// Exact `C4Object::SetDir` gate for direct command/native paths
    /// (C4Object.cpp:4235-4253). Unlike the legacy ExecAction helper above,
    /// this rejects idle/out-of-range directions and uses non-forced
    /// SetActionByName for TurnAction.
    pub(crate) fn set_command_action_direction(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        direction: Direction,
    ) -> Result<(), EngineError> {
        let object_id = self.objects[idx].id;
        let Some((current_direction, turn_action)) = self
            .definitions
            .get(definition_id)
            .and_then(|definition| {
                let library = definition.action_library();
                let action = &self.objects[idx].state.action;
                let raw_direction = direction.to_script_value();
                (!library.is_idle_state(action)
                    && raw_direction >= 0
                    && raw_direction
                        < library.directions_for_entry(&action.name, action.act_map_index) as i32)
                    .then(|| {
                        (
                            self.objects[idx].state.direction,
                            library
                                .turn_action_for_entry(&action.name, action.act_map_index)
                                .map(str::to_string),
                        )
                    })
            })
        else {
            return Ok(());
        };
        if direction != current_direction {
            if let Some(turn_action) = turn_action {
                self.action_with_calls(idx, definition_id, &turn_action)?;
            }
        }
        if let Some(idx) = self.find_object_index(object_id) {
            self.objects[idx].state.direction = direction;
        }
        Ok(())
    }

    /// Explicit `SetActionByName(..., fForce=true)` transition: applies the
    /// named action even through NoOtherAction, refreshes OCF, resyncs the
    /// fixed coords, then synchronously runs StartCall while force suppresses
    /// EndCall/AbortCall (C4ActionCallbacks.h:24-34). C++ ObjectAction helpers
    /// use the ordinary non-forced twin below.
    #[doc(hidden)]
    pub fn force_action_with_calls(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        name: &str,
    ) -> Result<bool, EngineError> {
        self.action_with_optional_target_and_calls(idx, definition_id, name, None, true)
    }

    /// Ordinary non-forced SetActionByName transition, including its
    /// synchronous StartCall/AbortCall sequence.
    pub(crate) fn action_with_calls(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        name: &str,
    ) -> Result<bool, EngineError> {
        self.action_with_optional_target_and_calls(idx, definition_id, name, None, false)
    }

    /// Ordinary target-bearing `SetActionByName`, used by ObjectActionPush
    /// and the other C++ ObjectAction helpers that do not pass `fForce`.
    pub(crate) fn action_with_target_and_calls(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        name: &str,
        target: ObjectId,
    ) -> Result<bool, EngineError> {
        self.action_with_optional_target_and_calls(idx, definition_id, name, Some(target), false)
    }

    fn action_with_optional_target_and_calls(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        name: &str,
        target: Option<ObjectId>,
        force: bool,
    ) -> Result<bool, EngineError> {
        let builtin_idle = action::is_builtin_idle_name(name);
        let name = if builtin_idle { "Idle" } else { name };
        let Some(library) = self
            .definitions
            .get(definition_id)
            .map(|definition| definition.action_library().clone())
        else {
            return Ok(false);
        };
        // SetActionByName("Idle"/"ActIdle") selects the built-in slot before scanning
        // ActMap (C4Object.cpp:4214-4215). ActionState's
        // library-aware update already models that slot; do not reject it
        // merely because a definition's map starts at Walk.
        if !action::is_builtin_idle_name(name) && !library.contains(name) {
            return Ok(false);
        }
        let previous = self.objects[idx].state.action.clone();
        let object_id = self.objects[idx].id;
        let original_definition_id = self.objects[idx].definition_id.clone();
        let update = ActionUpdate {
            name: Some(name.to_string()),
            phase: Some(0),
            ticks: Some(0),
            force,
            data: None,
            // SetAction assigns a target before SetOCF and callbacks when one
            // is supplied (C4Object.cpp:4148-4178). None preserves the old
            // target; the Idle/ActIdle name sentinel discards supplied
            // targets before SetAction (C4Object.cpp:4225-4227).
            target: (!builtin_idle).then_some(target).flatten().map(Some),
            target2: None,
            callbacks_dispatched: false,
        };
        let result = {
            let object = &mut self.objects[idx];
            object
                .state
                .action
                .apply_update_with_library(&update, &library)
        };
        if !matches!(result, ActionUpdateResult::Applied) {
            return Ok(false);
        }

        // SetOCF and fixed-position resync both precede StartCall in C++
        // (C4Object.cpp:4165-4178).
        self.refresh_object_ocf(idx);
        {
            let object = &mut self.objects[idx];
            object.fixed_position =
                FixedVec2::from_ints(object.state.position.x, object.state.position.y);
        }

        let current_action = self.objects[idx].state.action.clone();
        if !library.is_idle_state(&current_action) {
            self.invoke_action_callback(
                idx,
                ActionCallbackKind::Start,
                &current_action.name,
                current_action.act_map_index,
                None,
                None,
                None,
                None,
            )?;
        }

        // A StartCall that removes the object or changes its definition stops
        // the remaining callback sequence (C4Object.cpp:4178-4198).
        let callback_target_survived = self.objects.get(idx).is_some_and(|object| {
            object.id == object_id
                && object.definition_id == original_definition_id
                && !object.destroyed
                && !matches!(object.state.status, ObjectStatus::Deleted)
        });
        if callback_target_survived && !force && !library.is_idle_state(&previous) {
            self.invoke_action_callback(
                idx,
                ActionCallbackKind::Abort,
                &previous.name,
                previous.act_map_index,
                None,
                None,
                Some(previous.phase),
                None,
            )?;
        }

        Ok(true)
    }

    /// C4Object::ContactAction (C4Object.cpp:4307-4520): the hardcoded
    /// per-procedure contact transitions, dispatched on the frame's
    /// accumulated t_contact bits right after DoMovement
    /// (C4Movement.cpp:463-467). ObjectAction* helpers per
    /// C4ObjectCom.cpp:34-232.
    #[doc(hidden)]
    pub fn exec_contact_action(
        &mut self,
        idx: usize,
        t_contact: u32,
        _definition_id: &DefinitionId,
        solid_mask_indices: &[usize],
    ) -> Result<(), EngineError> {
        let Some(object_id) = self.objects.get(idx).map(|object| object.id) else {
            return Ok(());
        };
        // ContactAction resolves physicals before even its idle-action gate;
        // Def, Action and OCF are read only after that callback returns
        // (C4Object.cpp:4324-4330).
        let physical = self.object_physical(idx);
        let Some(idx) = self.find_object_index(object_id) else {
            return Ok(());
        };
        let live_definition_id = self.objects[idx].definition_id.clone();
        let definition_id = &live_definition_id;
        let Some(definition) = self.definitions.get(definition_id) else {
            return Ok(());
        };
        let library = definition.action_library().clone();
        let action = self.objects[idx].state.action.clone();
        let action_name = action.name.clone();
        if library.is_idle_state(&action) {
            return Ok(());
        }
        let procedure = library.procedure_for_entry(&action_name, action.act_map_index);
        let action_disabled =
            library.disables_object_for_entry(&action_name, action.act_map_index);
        let ocf = self.objects[idx].state.ocf;
        let com_dir = self.objects[idx].state.command_direction;
        let direction = self.objects[idx].state.direction;
        let can_scale = physical.can_scale != 0;
        let can_hangle = physical.can_hangle != 0;

        let com_dir_like = |com: CommandDirection, sample: CommandDirection| -> bool {
            // ComDirLike (C4ObjectCom.cpp:922-928): the two COMD ring
            // neighbours count as "like".
            let com = com.to_script_value();
            let sample = sample.to_script_value();
            com == sample || com % 8 + 1 == sample || com == sample % 8 + 1
        };

        // Hit Bottom (C4Object.cpp:4321-4367)
        if t_contact & CNAT_BOTTOM != 0 {
            match procedure {
                ActionProcedure::Flight => {
                    if self.objects[idx].fixed_velocity.y >= C4Fixed::ZERO {
                        // FlatHit / HardHit / Walk
                        if (ocf & crate::ocf::HIT_SPEED4 != 0 || action_disabled)
                            && self.object_action_flat(idx, definition_id, direction)?
                        {
                            return Ok(());
                        }
                        if ocf & crate::ocf::HIT_SPEED3 != 0
                            && self.action_with_calls(idx, definition_id, "KneelDown")?
                        {
                            let object = &mut self.objects[idx];
                            object.fixed_velocity = FixedVec2::ZERO;
                            object.state.velocity = Vector2::ZERO;
                            return Ok(());
                        }
                        // Walk keeping horizontal momentum
                        // (C4Object.cpp:4330-4338).
                        let last_xdir = self.objects[idx].fixed_velocity.x;
                        if self.action_with_calls(idx, definition_id, "Walk")? {
                            let object = &mut self.objects[idx];
                            object.fixed_velocity = FixedVec2::new(last_xdir, C4Fixed::ZERO);
                            object.state.velocity = object.velocity_pixels();
                        }
                        return Ok(());
                    }
                }
                ActionProcedure::Scale => {
                    if !com_dir_like(com_dir, CommandDirection::Down) {
                        let _ = self.object_action_corner_scale(
                            idx,
                            definition_id,
                            procedure,
                            solid_mask_indices,
                        )?;
                        return Ok(());
                    }
                    self.object_action_stand(idx, definition_id)?;
                    return Ok(());
                }
                ActionProcedure::Dig => match com_dir {
                    CommandDirection::DownLeft => {
                        self.objects[idx].state.command_direction = CommandDirection::Left;
                    }
                    CommandDirection::DownRight => {
                        self.objects[idx].state.command_direction = CommandDirection::Right;
                    }
                    _ => {
                        self.object_com_stop_dig(idx, definition_id)?;
                        return Ok(());
                    }
                },
                ActionProcedure::Swim => {
                    let above_liquid = {
                        let position = self.objects[idx].state.position;
                        self.landscape
                            .as_ref()
                            .map(|landscape| landscape.is_liquid_at(position.x, position.y - 1))
                            .unwrap_or(false)
                    };
                    if !above_liquid {
                        let _ = self.object_action_corner_scale(
                            idx,
                            definition_id,
                            procedure,
                            solid_mask_indices,
                        )?;
                    }
                    return Ok(());
                }
                _ => {}
            }
        }

        // Hit Ceiling (C4Object.cpp:4369-4404)
        if t_contact & CNAT_TOP != 0 {
            match procedure {
                ActionProcedure::Walk => {
                    self.object_action_stand(idx, definition_id)?;
                    return Ok(());
                }
                ActionProcedure::Scale => {
                    if com_dir_like(com_dir, CommandDirection::Up) {
                        if can_hangle {
                            let new_dir = if direction == Direction::Left {
                                Direction::Right
                            } else {
                                Direction::Left
                            };
                            self.object_action_hangle(idx, definition_id, new_dir)?;
                            return Ok(());
                        }
                        self.objects[idx].state.command_direction = CommandDirection::Stop;
                    }
                }
                ActionProcedure::Flight => {
                    if ocf & crate::ocf::HIT_SPEED3 != 0 || action_disabled {
                        self.object_action_tumble(
                            idx,
                            definition_id,
                            direction,
                            C4Fixed::ZERO,
                            C4Fixed::ZERO,
                        )?;
                    } else if can_hangle {
                        self.object_action_hangle(idx, definition_id, direction)?;
                        return Ok(());
                    }
                }
                ActionProcedure::Dig => {
                    self.object_com_stop_dig(idx, definition_id)?;
                    return Ok(());
                }
                ActionProcedure::Hang => {
                    self.objects[idx].state.command_direction = CommandDirection::Stop;
                }
                _ => {}
            }
        }

        // Hit Left / Right Walls (C4Object.cpp:4406-4520)
        for (cnat, wall_direction) in [(CNAT_LEFT, Direction::Left), (CNAT_RIGHT, Direction::Right)]
        {
            if t_contact & cnat == 0 {
                continue;
            }
            let tumble_x = contact_action_wall_tumble_x(cnat);
            let toward = if wall_direction == Direction::Left {
                CommandDirection::Left
            } else {
                CommandDirection::Right
            };
            let away = if wall_direction == Direction::Left {
                CommandDirection::Right
            } else {
                CommandDirection::Left
            };
            match procedure {
                ActionProcedure::Flight => {
                    if ocf & crate::ocf::HIT_SPEED3 != 0 || action_disabled {
                        self.object_action_tumble(
                            idx,
                            definition_id,
                            wall_direction,
                            tumble_x,
                            C4Fixed::ZERO,
                        )?;
                    } else if can_scale {
                        self.object_action_scale(idx, definition_id, wall_direction)?;
                        return Ok(());
                    }
                }
                ActionProcedure::Walk => {
                    if com_dir_like(com_dir, toward) {
                        if can_scale {
                            self.object_action_scale(idx, definition_id, wall_direction)?;
                            return Ok(());
                        }
                        self.objects[idx].state.command_direction = CommandDirection::Stop;
                    }
                    if com_dir_like(self.objects[idx].state.command_direction, away) {
                        // Slide off (C4Object.cpp:4437/4491).
                        let xdir = self.objects[idx].fixed_velocity.x / 2;
                        let ydir = self.objects[idx].fixed_velocity.y;
                        let _ = self.object_action_jump(idx, xdir, ydir, false)?;
                    }
                    return Ok(());
                }
                ActionProcedure::Swim => {
                    if com_dir_like(com_dir, toward) && can_scale {
                        self.object_action_scale(idx, definition_id, wall_direction)?;
                        return Ok(());
                    }
                    let _ = self.object_action_corner_scale(
                        idx,
                        definition_id,
                        procedure,
                        solid_mask_indices,
                    )?;
                    return Ok(());
                }
                ActionProcedure::Hang => {
                    if can_scale
                        && self.object_action_scale(idx, definition_id, wall_direction)?
                    {
                        return Ok(());
                    }
                    self.objects[idx].state.command_direction = CommandDirection::Stop;
                    return Ok(());
                }
                ActionProcedure::Dig => {
                    self.object_com_stop_dig(idx, definition_id)?;
                    return Ok(());
                }
                _ => {}
            }
        }

        // Flight stuck: enforce slide free (C4Object.cpp:4524-4546).
        if matches!(procedure, ActionProcedure::Flight) {
            let velocity = self.objects[idx].fixed_velocity;
            if !velocity.y.is_nonzero() {
                let allow_down = i32::from(t_contact & CNAT_BOTTOM == 0);
                if t_contact & CNAT_RIGHT != 0 {
                    let position = self.objects[idx].state.position;
                    self.force_object_position(
                        idx,
                        Vector2::new(position.x - 1, position.y + allow_down),
                    );
                    let object = &mut self.objects[idx];
                    object.fixed_velocity = FixedVec2::ZERO;
                    object.state.velocity = Vector2::ZERO;
                }
                if t_contact & CNAT_LEFT != 0 {
                    let position = self.objects[idx].state.position;
                    self.force_object_position(
                        idx,
                        Vector2::new(position.x + 1, position.y + allow_down),
                    );
                    let object = &mut self.objects[idx];
                    object.fixed_velocity = FixedVec2::ZERO;
                    object.state.velocity = Vector2::ZERO;
                }
            }
            let velocity = self.objects[idx].fixed_velocity;
            if !velocity.x.is_nonzero() && t_contact & CNAT_TOP != 0 {
                let position = self.objects[idx].state.position;
                self.force_object_position(idx, Vector2::new(position.x, position.y + 1));
                let object = &mut self.objects[idx];
                object.fixed_velocity = FixedVec2::ZERO;
                object.state.velocity = Vector2::ZERO;
            }
        }
        Ok(())
    }

    /// C4Object::ForcePosition (C4Movement.cpp:531-539): fix always
    /// resyncs; movement zeroed by the callers that need it.
    #[doc(hidden)]
    pub fn force_object_position(&mut self, idx: usize, target: Vector2) {
        let position_changed = self.objects[idx].state.position != target;
        let object = &mut self.objects[idx];
        object.fixed_position = FixedVec2::from_ints(target.x, target.y);
        object.state.position = target;
        self.update_sector_for_index(idx);
        if position_changed {
            self.update_solid_mask(idx);
        }
    }

    /// ObjectActionStand (C4ObjectCom.cpp:41-46): set ComDir Stop, then use
    /// ordinary SetActionByName("Walk") and zero both dirs only when that
    /// transition succeeds. Action callbacks may remove or redefine the
    /// object, so every post-callback write resolves its stable id again.
    fn object_action_stand_live(&mut self, object_id: ObjectId) -> Result<bool, EngineError> {
        let Some(idx) = self.find_object_index(object_id) else {
            return Ok(false);
        };
        self.objects[idx].state.command_direction = CommandDirection::Stop;
        let definition_id = self.objects[idx].definition_id.clone();
        if !self.action_with_calls(idx, &definition_id, "Walk")? {
            return Ok(false);
        }
        if let Some(idx) = self.find_object_index(object_id) {
            let object = &mut self.objects[idx];
            object.fixed_velocity = FixedVec2::ZERO;
            object.state.velocity = Vector2::ZERO;
        }
        Ok(true)
    }

    fn object_action_stand(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
    ) -> Result<bool, EngineError> {
        self.objects[idx].state.command_direction = CommandDirection::Stop;
        if self.action_with_calls(idx, definition_id, "Walk")? {
            let object = &mut self.objects[idx];
            object.fixed_velocity = FixedVec2::ZERO;
            object.state.velocity = Vector2::ZERO;
            return Ok(true);
        }
        Ok(false)
    }

    /// `ObjectComStop` (C4ObjectCom.cpp:239-245): enter ActIdle first,
    /// then stand in Walk when that action exists. Both transitions are
    /// ordinary and the Walk lookup uses the live post-Idle definition.
    fn object_com_stop_live(&mut self, object_id: ObjectId) -> Result<bool, EngineError> {
        let Some(idx) = self.find_object_index(object_id) else {
            return Ok(false);
        };
        let definition_id = self.objects[idx].definition_id.clone();
        let _ = self.action_with_calls(idx, &definition_id, "Idle")?;
        self.object_action_stand_live(object_id)
    }

    /// `ObjectComBuild` (C4ObjectCom.cpp:690-697): the target must remain
    /// valid and the builder must be in ActIdle or DFA_WALK; the ordinary,
    /// non-forced Build transition runs all action callbacks synchronously.
    fn object_com_build_live(
        &mut self,
        object_id: ObjectId,
        target_id: ObjectId,
    ) -> Result<bool, EngineError> {
        if self.find_object_index(target_id).is_none() {
            return Ok(false);
        }
        let Some(idx) = self.find_object_index(object_id) else {
            return Ok(false);
        };
        let definition_id = self.objects[idx].definition_id.clone();
        let can_build = self
            .definitions
            .get(&definition_id)
            .is_some_and(|definition| {
                let actions = definition.action_library();
                let action = &self.objects[idx].state.action;
                actions.is_idle_state(action)
                    || actions.procedure_for_entry(&action.name, action.act_map_index)
                        == ActionProcedure::Walk
            });
        if !can_build {
            return Ok(false);
        }
        self.action_with_target_and_calls(idx, &definition_id, "Build", target_id)
    }

    fn object_com_stop_action(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
    ) -> Result<bool, EngineError> {
        self.action_with_calls(idx, definition_id, "Idle")?;
        self.object_action_stand(idx, definition_id)
    }

    /// ObjectActionFlat (C4ObjectCom.cpp:96-102): "FlatUp", dirs zeroed.
    fn object_action_flat(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        direction: Direction,
    ) -> Result<bool, EngineError> {
        if self.action_with_calls(idx, definition_id, "FlatUp")? {
            let object = &mut self.objects[idx];
            object.fixed_velocity = FixedVec2::ZERO;
            object.state.velocity = Vector2::ZERO;
            object.state.direction = direction;
            return Ok(true);
        }
        Ok(false)
    }

    /// ObjectActionScale (C4ObjectCom.cpp:104-110).
    fn object_action_scale(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        direction: Direction,
    ) -> Result<bool, EngineError> {
        if self.action_with_calls(idx, definition_id, "Scale")? {
            let object = &mut self.objects[idx];
            object.fixed_velocity = FixedVec2::ZERO;
            object.state.velocity = Vector2::ZERO;
            object.state.direction = direction;
            return Ok(true);
        }
        Ok(false)
    }

    /// ObjectActionHangle (C4ObjectCom.cpp:112-118).
    fn object_action_hangle(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        direction: Direction,
    ) -> Result<bool, EngineError> {
        if self.action_with_calls(idx, definition_id, "Hangle")? {
            let object = &mut self.objects[idx];
            object.fixed_velocity = FixedVec2::ZERO;
            object.state.velocity = Vector2::ZERO;
            object.state.direction = direction;
            return Ok(true);
        }
        Ok(false)
    }

    /// ObjectActionTumble (C4ObjectCom.cpp:74-80).
    fn object_action_tumble(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        direction: Direction,
        xdir: C4Fixed,
        ydir: C4Fixed,
    ) -> Result<bool, EngineError> {
        if self.action_with_calls(idx, definition_id, "Tumble")? {
            let object = &mut self.objects[idx];
            object.state.direction = direction;
            object.fixed_velocity = FixedVec2::new(xdir, ydir);
            object.state.velocity = object.velocity_pixels();
            return Ok(true);
        }
        Ok(false)
    }

    /// ObjectComStopDig (C4ObjectCom.cpp:776-784): Stand + clear a Dig
    /// command at the stack top.
    fn object_com_stop_dig(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
    ) -> Result<(), EngineError> {
        self.object_action_stand(idx, definition_id)?;
        let object = &mut self.objects[idx];
        if object.commands.front_command_name() == Some("Dig") {
            object.commands.clear_front();
        }
        Ok(())
    }

    /// C4Object::ContactCheck (C4Movement.cpp:166-182): perform the shape
    /// probe first, then synchronously dispatch the contacted directions in
    /// Left/Right/Top/Bottom order. A truthy callback stops dispatch for this
    /// probe; engine callback errors are fail-safe.
    fn object_contact_check_at(
        &mut self,
        idx: usize,
        position: Vector2,
        solid_mask_indices: &[usize],
    ) -> Result<Option<ShapeContact>, EngineError> {
        let mut contact = {
            let Some(object) = self.objects.get(idx) else {
                return Ok(None);
            };
            let Some(landscape) = self.landscape.as_ref() else {
                return Ok(None);
            };
            let masks = self.solid_masks_for_movement(solid_mask_indices);
            let contact_density = object.state.contact_density;
            shape_contact_check(
                &object.state.vertices,
                position,
                landscape,
                &self.materials,
                &masks,
                Some(object.id),
                contact_density,
            )
        };
        if let Some(object) = self.objects.get_mut(idx) {
            object.latch_shape_contact(&contact);
        }

        self.dispatch_contact_callbacks(idx, MovementContactDispatch::ShapeProbe)?;
        if let Some(object) = self.objects.get(idx) {
            contact.contact_cnat = object.frame_shape_contact_cnat;
            if object.frame_shape_contact_count == 0 {
                contact.vertices.clear();
            }
        }
        Ok(Some(contact))
    }

    /// The callback half of `C4Object::ContactCheck` (C4Movement.cpp:
    /// 166-182): contacted directions run left/right/top/bottom and a truthy
    /// result stops the remaining calls. Both movement probes and Stabilize's
    /// temporary upright probe use this same path.
    fn dispatch_contact_callbacks(
        &mut self,
        idx: usize,
        dispatch: MovementContactDispatch,
    ) -> Result<(), EngineError> {
        let (directions, shape_probe) = match dispatch {
            MovementContactDispatch::ShapeProbe => {
                ([CNAT_LEFT, CNAT_RIGHT, CNAT_TOP, CNAT_BOTTOM], true)
            }
            MovementContactDispatch::Direct(cnat) => ([cnat, 0, 0, 0], false),
        };
        for cnat in directions {
            if cnat == CNAT_NONE {
                continue;
            }
            if self
                .objects
                .get(idx)
                .is_none_or(|object| object.state.status == ObjectStatus::Deleted)
            {
                break;
            }
            if shape_probe && self.objects[idx].frame_shape_contact_cnat & cnat == 0 {
                continue;
            }
            let Some(function_name) = contact_callback_name(cnat) else {
                continue;
            };
            let Some((object_id, callback_definition_id, action_library)) = self
                .objects
                .get(idx)
                .and_then(|object| {
                    self.definitions
                        .get(&object.definition_id)
                        .map(|definition| {
                            (
                                object.id,
                                object.definition_id.clone(),
                                definition.action_library().clone(),
                            )
                        })
                })
            else {
                break;
            };
            let contact_calls = self
                .definitions
                .get(&callback_definition_id)
                .map(|definition| definition.contact_function_calls())
                .unwrap_or(false);
            if !contact_calls {
                continue;
            }
            match tolerate_script_error(self.call_movement_object_function(
                idx,
                function_name,
                &[],
                &action_library,
                object_id,
                &callback_definition_id,
            ))? {
                Some(value) if value.as_bool() => break,
                Some(_) | None => {}
            }
        }
        Ok(())
    }

    /// ObjectActionCornerScale (C4ObjectCom.cpp:167-217): probe a free
    /// spot up-and-sideways, then KneelUp (Walk fallback) with the fixed
    /// coords shifted.
    #[doc(hidden)]
    pub fn object_action_corner_scale(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        procedure: ActionProcedure,
        solid_mask_indices: &[usize],
    ) -> Result<bool, EngineError> {
        const CORNER_RANGE: i32 = ATTACH_RANGE + 2;
        let corner_okay =
            |engine: &mut Engine, range_x: i32, range_y: i32| -> Result<bool, EngineError> {
            let (position, direction) = {
                let object = &engine.objects[idx];
                (object.state.position, object.state.direction)
            };
            let cty = position.y - range_y;
            let ctx = if direction == Direction::Left {
                position.x - range_x
            } else {
                position.x + range_x
            };
            Ok(engine
                .object_contact_check_at(
                    idx,
                    Vector2::new(ctx, cty),
                    solid_mask_indices,
                )
                ?
                .is_some_and(|contact| contact.contact_cnat == 0))
            };
        let (range_x, range_y) = if matches!(procedure, ActionProcedure::Scale) {
            // Scaling: range max to min (CheckCornerScale).
            let mut found = None;
            'outer: for range_x in (1..=CORNER_RANGE).rev() {
                for range_y in (1..=CORNER_RANGE).rev() {
                    if corner_okay(self, range_x, range_y)? {
                        found = Some((range_x, range_y));
                        break 'outer;
                    }
                }
            }
            match found {
                Some(ranges) => ranges,
                None => return Ok(false),
            }
        } else {
            // Swimming: range min to max.
            let mut range = 2;
            while !corner_okay(self, range, range)? {
                range += 1;
                if range > CORNER_RANGE {
                    return Ok(false);
                }
            }
            (range, range)
        };
        if !self.action_with_calls(idx, definition_id, "KneelUp")? {
            self.action_with_calls(idx, definition_id, "Walk")?;
        }
        let object = &mut self.objects[idx];
        object.fixed_velocity = FixedVec2::ZERO;
        object.state.velocity = Vector2::ZERO;
        if object.state.direction == Direction::Left {
            object.fixed_position.x -= itofix(range_x);
        } else {
            object.fixed_position.x += itofix(range_x);
        }
        object.fixed_position.y -= itofix(range_y);
        object.state.position = Vector2::new(
            fixtoi(object.fixed_position.x),
            fixtoi(object.fixed_position.y),
        );
        self.update_sector_for_index(idx);
        Ok(true)
    }

    /// C++'s shared `GrabLost` helper: notify the current action target,
    /// then clear commands above the first PushTo in the pusher's live stack.
    /// The callback may replace that stack, so the clear must follow it.
    fn grab_lost(&mut self, pusher_id: ObjectId) -> Result<(), EngineError> {
        let Some(target_id) = self
            .find_object_index(pusher_id)
            .and_then(|index| self.objects[index].state.action.target)
        else {
            return Ok(());
        };
        let Some(target_idx) = self.find_object_index(target_id) else {
            return Ok(());
        };

        let _ =
            tolerate_script_error(self.call_object_function(target_idx, "GrabLost", Vec::new()))?;
        if let Some(pusher_idx) = self.find_object_index(pusher_id) {
            self.objects[pusher_idx].commands.clear_to_first_push_to();
        }
        Ok(())
    }

    #[doc(hidden)]
    pub fn apply_no_attach_action(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
        library: &ActionLibrary,
        solid_mask_indices: &[usize],
    ) -> Result<(), EngineError> {
        if idx >= self.objects.len() {
            return Ok(());
        }

        let object_id = self.objects[idx].id;
        let initial_action = self.objects[idx].state.action.clone();
        if library.is_idle_state(&initial_action) {
            // Inactive objects: simple mobile natural gravity
            // (C4Object.cpp:4299-4303) — DoGravity's free-fall branch
            // still skips StaticBack (:4662).
            let gravity = self.physics.gravity_as_c4fixed();
            let object = &mut self.objects[idx];
            if object.state.category & CATEGORY_STATIC_BACK == 0 {
                object.fixed_velocity.y += gravity;
                object.refresh_velocity_from_fixed();
            }
            object.state.mobile = true;
            return Ok(());
        }

        let procedure =
            library.procedure_for_entry(&initial_action.name, initial_action.act_map_index);
        let command_direction = self.objects[idx].state.command_direction;
        let direction = self.objects[idx].state.direction;
        let scaling_upward = matches!(
            command_direction,
            CommandDirection::Up | CommandDirection::UpLeft | CommandDirection::UpRight
        ) || (command_direction == CommandDirection::Left && direction == Direction::Left)
            || (command_direction == CommandDirection::Right && direction == Direction::Right);
        if matches!(procedure, ActionProcedure::Scale) && scaling_upward {
            let corner_scaled = self.object_action_corner_scale(
                idx,
                definition_id,
                ActionProcedure::Scale,
                solid_mask_indices,
            )?;
            if corner_scaled {
                // Scaling upward tries the corner transition before the generic
                // Jump fallback (C4Object.cpp:4282-4289).
                return Ok(());
            }
        }

        // A stopped scaler that loses its wall first tries to jump away from
        // it. A failed SetAction falls through to the generic jump below, so
        // OnActionJump can run twice in that narrow case (C4Object.cpp:
        // 4290-4299).
        if matches!(procedure, ActionProcedure::Scale) {
            let stopped_scale = self.find_object_index(object_id).and_then(|live_idx| {
                let state = &self.objects[live_idx].state;
                (state.command_direction == CommandDirection::Stop).then_some((
                    live_idx,
                    if state.direction == Direction::Left {
                        itofix(1)
                    } else {
                        itofix(-1)
                    },
                ))
            });
            if let Some((live_idx, xdir)) = stopped_scale {
                if self.object_action_jump(live_idx, xdir, C4Fixed::ZERO, false)? {
                    return Ok(());
                }
            }
        }

        // Pushing off an attachment first notifies the vehicle and restores
        // the PushTo command before falling through to ObjectActionJump
        // (C4Object.cpp:4302-4306).
        if matches!(procedure, ActionProcedure::Push) {
            self.grab_lost(object_id)?;
        } else if matches!(procedure, ActionProcedure::Fight) {
            // Losing the ground during a fight records the opponent's live
            // Controller for a later fall death. This is an unconditional
            // direct assignment in C++ (including NO_OWNER), not the guarded
            // DoEnergy kill-trace update (C4Object.cpp:4304-4305).
            let opponent_controller = initial_action
                .target
                .and_then(|target_id| self.find_object_index(target_id))
                .map(|target_idx| self.objects[target_idx].state.controller);
            if let Some(controller) = opponent_controller {
                self.objects[idx].last_energy_loss_cause = controller;
            }
        }

        // GrabLost and corner-probe callbacks are synchronous. The ensuing
        // ObjectActionJump resolves the pusher's live definition and action.
        let Some(idx) = self.find_object_index(object_id).filter(|&index| {
            !self.objects[index].destroyed
                && !matches!(self.objects[index].state.status, ObjectStatus::Deleted)
        }) else {
            return Ok(());
        };
        let launch = self.objects[idx].fixed_velocity;
        let _ = self.object_action_jump(idx, launch.x, launch.y, false)?;
        Ok(())
    }

    /// The status-gated tail shared by DFA_ATTACH's two lost-target arms:
    /// ordinary SetAction(ActIdle), then AttachTargetLost on the same live
    /// object. The action transition may be denied or remove the object; its
    /// result is deliberately ignored (C4Object.cpp:5317-5325, 5341-5349).
    fn notify_attach_target_lost(&mut self, object_id: ObjectId) -> Result<(), EngineError> {
        let Some(idx) = self.find_object_index(object_id) else {
            return Ok(());
        };
        if self.objects[idx].state.status == ObjectStatus::Deleted {
            return Ok(());
        }
        let definition_id = self.objects[idx].definition_id.clone();
        let _ = tolerate_script_error(self.action_with_calls(idx, &definition_id, "Idle"))?;
        if let Some(idx) = self.find_object_index(object_id) {
            let _ = tolerate_script_error(self.call_object_function(
                idx,
                "AttachTargetLost",
                Vec::new(),
            ))?;
        }
        Ok(())
    }

    fn apply_attach_procedure(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
    ) -> Result<bool, EngineError> {
        let object_id = self.objects[idx].id;
        let Some(target_id) = self.objects[idx].state.action.target else {
            self.notify_attach_target_lost(object_id)?;
            return Ok(false);
        };

        let Some(target_idx) = self.find_object_index(target_id).filter(|&target_idx| {
            !self.objects[target_idx].destroyed
                && self.objects[target_idx].state.status != ObjectStatus::Deleted
        }) else {
            // AssignRemoval normally clears Action.Target before ExecAction.
            // Keep malformed/dangling fixture state equivalent to that null
            // pointer before dispatching the native lost-target sequence.
            if let Some(idx) = self.find_object_index(object_id) {
                if self.objects[idx].state.action.target == Some(target_id) {
                    self.objects[idx].state.action.target = None;
                    self.objects[idx].compiler_cache.action_target1 = 0;
                }
            }
            self.notify_attach_target_lost(object_id)?;
            return Ok(false);
        };

        let target_is_incomplete = self.objects[target_idx].state.ocf & ocf::FULL_CON == 0;
        let target_allows_incomplete_activity = self
            .definitions
            .get(&self.objects[target_idx].definition_id)
            .is_some_and(Definition::incomplete_activity);
        if target_is_incomplete && !target_allows_incomplete_activity {
            let _ = tolerate_script_error(self.action_with_calls(idx, definition_id, "Idle"))?;
            return Ok(false);
        }

        let target_container = self.objects[target_idx].state.container;
        let previous_container = self.objects[idx].state.container;
        if previous_container != target_container {
            match target_container {
                Some(container_id) => {
                    // Enter's bool result is intentionally ignored. A veto or
                    // callback re-entry does not stop DFA_ATTACH from using
                    // the live Action.Target below.
                    let _ = self.try_object_enter(object_id, container_id)?;
                }
                None => {
                    // This exact arm is Exit(x, y, r): preserve the current
                    // rotation, zero all dirs, and run Ejection/Departure.
                    let _ = self.exit_object_at_current_transform(object_id)?;
                }
            }

            let Some(live_idx) = self.find_object_index(object_id) else {
                return Ok(false);
            };
            if self.objects[live_idx].state.action.target.is_none() {
                self.notify_attach_target_lost(object_id)?;
                return Ok(false);
            }
        }

        // Enter/Exit callbacks may retarget, ChangeDef, change Action.Data,
        // or replace either shape. Native DFA_ATTACH rereads all of those
        // live fields, but deliberately does not repeat its completeness or
        // containment checks (C4Object.cpp:5353-5359).
        let Some(live_idx) = self.find_object_index(object_id) else {
            return Ok(false);
        };
        let Some(live_target_id) = self.objects[live_idx].state.action.target else {
            self.notify_attach_target_lost(object_id)?;
            return Ok(false);
        };
        let Some(live_target_idx) = self.find_object_index(live_target_id).filter(|&target_idx| {
            !self.objects[target_idx].destroyed
                && self.objects[target_idx].state.status != ObjectStatus::Deleted
        }) else {
            if self.objects[live_idx].state.action.target == Some(live_target_id) {
                self.objects[live_idx].state.action.target = None;
                self.objects[live_idx].compiler_cache.action_target1 = 0;
            }
            self.notify_attach_target_lost(object_id)?;
            return Ok(false);
        };

        let target_position = self.objects[live_target_idx].state.position;
        let target_vertices = self.objects[live_target_idx].state.vertices.clone();
        let object_vertices = self.objects[live_idx].state.vertices.clone();
        let action_data = self.objects[live_idx].state.action.data as u32;
        let self_vertex_index = ((action_data >> 8) & 0xFF) as usize;
        let target_vertex_index = (action_data & 0xFF) as usize;

        let self_offset = object_vertices
            .get(self_vertex_index)
            .map(|vertex| Vector2::new(vertex.x, vertex.y))
            .unwrap_or(Vector2::ZERO);
        let target_offset = target_vertices
            .get(target_vertex_index)
            .map(|vertex| Vector2::new(vertex.x, vertex.y))
            .unwrap_or(Vector2::ZERO);
        let new_position = Vector2::new(
            target_position
                .x
                .saturating_add(target_offset.x)
                .saturating_sub(self_offset.x),
            target_position
                .y
                .saturating_add(target_offset.y)
                .saturating_sub(self_offset.y),
        );

        if std::env::var("LC_ATTDBG").is_ok() && (21..=22).contains(&self.frame) {
            eprintln!(
                "ATTDBG f{} obj={} tgt_pos={:?} tgt_off={:?} self_off={:?} data={:#x} -> {:?}",
                self.frame,
                object_id.as_u64(),
                target_position,
                target_offset,
                self_offset,
                action_data,
                new_position
            );
        }
        self.force_object_position(live_idx, new_position);
        let object = &mut self.objects[live_idx];
        object.fixed_velocity.x = C4Fixed::ZERO;
        object.fixed_velocity.y = C4Fixed::ZERO;
        object.state.velocity.x = 0;
        object.state.velocity.y = 0;

        Ok(true)
    }

    /// DFA_PULL with a nonzero Walk physical (C4Object.cpp:5099-5170):
    /// pull-position math, target force via `C4Object::Push`, ComDir
    /// transfer onto walking/pulling targets, pulling-range check with
    /// GrabLost and target loss, own move toward the pulling position. The
    /// controller transfer (C4Object.cpp:5157).
    fn apply_pull_procedure_physical(
        &mut self,
        idx: usize,
        target_idx: usize,
        command_direction: CommandDirection,
        _definition_id: &DefinitionId,
        physical: PhysicalInfo,
    ) -> Result<bool, EngineError> {
        let puller_id = self.objects[idx].id;
        let position = self.objects[idx].state.position;
        let target_position = self.objects[target_idx].state.position;
        let own_width = self.objects[idx]
            .current_shape_rect()
            .map(|rect| rect.width)
            .unwrap_or(0);
        let target_rect = self.objects[target_idx]
            .current_shape_rect()
            .unwrap_or_default();
        // Pulling positions (C4Object.cpp:5110-5118).
        let pull_distance = target_rect.width / 2 + own_width / 2;
        let mut target_x = position.x;
        let mut pull_x = target_position.x;
        match command_direction {
            CommandDirection::Right => {
                target_x = target_position.x + pull_distance;
                pull_x = position.x - pull_distance;
            }
            CommandDirection::Left => {
                target_x = target_position.x - pull_distance;
                pull_x = position.x + pull_distance;
            }
            _ => {}
        }
        // Target pulling force (C4Object.cpp:5120-5126).
        let walk = math::val_by_physical(280, physical.walk);
        let movement = match command_direction {
            CommandDirection::Right => walk,
            CommandDirection::Left => -walk,
            _ => C4Fixed::ZERO,
        };
        let txdir = movement + walk * (pull_x - target_position.x).clamp(-10, 10) / 10;
        // Push object (C4Object.cpp:5129-5132).
        if !self.push_object(
            target_idx,
            txdir,
            math::val_by_physical(250, physical.push),
            false,
        )? {
            self.stop_action_delay_command_live(puller_id)?;
            return Ok(false);
        }
        // Successful target force transfers attribution before the train
        // and range checks, even when the pull is lost below
        // (C4Object.cpp:5157).
        self.objects[target_idx].state.controller = self.objects[idx].state.controller;
        // Train pulling: ComDir transfer (C4Object.cpp:5137-5143).
        let target_procedure = self
            .definitions
            .get(&self.objects[target_idx].definition_id)
            .map(|definition| {
                definition
                    .action_library()
                    .procedure_for_entry(
                        &self.objects[target_idx].state.action.name,
                        self.objects[target_idx].state.action.act_map_index,
                    )
            })
            .unwrap_or_default();
        if matches!(
            target_procedure,
            ActionProcedure::Walk | ActionProcedure::Pull
        ) {
            let mut transfer = CommandDirection::Stop;
            if txdir < C4Fixed::ZERO {
                transfer = CommandDirection::Left;
            }
            if txdir > C4Fixed::ZERO {
                transfer = CommandDirection::Right;
            }
            self.objects[target_idx].state.command_direction = transfer;
        }
        // Pulling range (C4Object.cpp:5146-5161).
        let push_distance = (own_width / 2 - 8).max(0);
        let push_range = push_distance + 20;
        let sax = target_position.x + target_rect.x;
        let say = target_position.y + target_rect.y;
        let sawdt = target_rect.width;
        let sahgt = target_rect.height;
        if !(-push_range..=sawdt - 1 + push_range).contains(&(position.x - sax))
            || !(-push_range..=sahgt - 1 + push_range).contains(&(position.y - say))
        {
            // Stop and queue the delay before notifying the actor's live
            // target. GrabLost may trim that new Wait back to PushTo and may
            // retarget the puller; C++ clears the resulting live target last
            // (C4Object.cpp:5177-5181).
            self.stop_action_delay_command_live(puller_id)?;
            self.grab_lost(puller_id)?;
            if let Some(puller_idx) = self.find_object_index(puller_id) {
                self.objects[puller_idx].state.action.target = None;
                self.objects[puller_idx].compiler_cache.action_target1 = 0;
            }
            return Ok(false);
        }
        // Move to pulling position (C4Object.cpp:5164), facing by xdir,
        // grounded.
        let xdir = movement + walk * (target_x - position.x).clamp(-10, 10) / 10;
        let physics = self.physics;
        let object = &mut self.objects[idx];
        object.fixed_velocity.x = xdir;
        if xdir < C4Fixed::ZERO {
            object.state.direction = Direction::Left;
        }
        if xdir > C4Fixed::ZERO {
            object.state.direction = Direction::Right;
        }
        object.fixed_velocity.y = C4Fixed::ZERO;
        physics.clamp_fixed_velocity(&mut object.fixed_velocity);
        object.refresh_velocity_from_fixed();
        Ok(true)
    }

    fn apply_pull_procedure(
        &mut self,
        idx: usize,
        command_direction: CommandDirection,
        movement_profile: MovementProfile,
        definition_id: &DefinitionId,
        physical: PhysicalInfo,
    ) -> Result<bool, EngineError> {
        let puller_id = self.objects[idx].id;
        let Some(target_id) = self.objects[idx].state.action.target else {
            self.stop_action_delay_command_live(puller_id)?;
            return Ok(false);
        };

        let Some(target_idx) = self.find_object_index(target_id) else {
            self.stop_action_delay_command_live(puller_id)?;
            return Ok(false);
        };

        if target_idx == idx {
            self.stop_action_delay_command_live(puller_id)?;
            return Ok(false);
        }

        let puller_container = self.objects[idx].state.container;
        if puller_container == Some(target_id) {
            self.stop_action_delay_command_live(puller_id)?;
            return Ok(false);
        }

        let target_removed = {
            let target = &self.objects[target_idx];
            target.destroyed || matches!(target.state.status, ObjectStatus::Deleted)
        };
        if target_removed {
            self.stop_action_delay_command_live(puller_id)?;
            return Ok(false);
        }

        if self.objects[target_idx].state.container.is_some() {
            self.stop_action_delay_command_live(puller_id)?;
            return Ok(false);
        }

        if physical.walk != 0 {
            return self.apply_pull_procedure_physical(
                idx,
                target_idx,
                command_direction,
                definition_id,
                physical,
            );
        }

        let walk_speed = movement_profile.walk_speed.max(0);
        let walk_accel = movement_profile.walk_acceleration.max(0);

        let puller_position = self.objects[idx].state.position;
        let target_position = self.objects[target_idx].state.position;

        let (puller_half_width, _) = Self::object_half_extents(&self.objects[idx]);
        let (target_half_width, target_half_height) =
            Self::object_half_extents(&self.objects[target_idx]);
        let pull_distance = puller_half_width.saturating_add(target_half_width);

        let horizontal_input = Self::horizontal_input_sign(command_direction);
        let base_velocity = horizontal_input.saturating_mul(walk_speed);

        let desired_puller_x = if horizontal_input == 0 {
            puller_position.x
        } else {
            target_position
                .x
                .saturating_add(horizontal_input.saturating_mul(pull_distance))
        };
        let desired_target_x = if horizontal_input == 0 {
            target_position.x
        } else {
            puller_position
                .x
                .saturating_sub(horizontal_input.saturating_mul(pull_distance))
        };

        let desired_target_velocity = Self::desired_pull_velocity(
            target_position.x,
            desired_target_x,
            base_velocity,
            walk_speed,
        );
        let desired_puller_velocity = Self::desired_pull_velocity(
            puller_position.x,
            desired_puller_x,
            base_velocity,
            walk_speed,
        );

        // Mirror C++ pull range tolerance: stay close enough to the target to keep the rope taut.
        let range_extension = puller_half_width.saturating_sub(8).max(0) + 20;
        let horizontal_gap_limit = target_half_width.saturating_add(range_extension);
        let vertical_gap_limit = target_half_height.saturating_add(range_extension);

        let horizontal_gap = (puller_position.x as i64 - target_position.x as i64).abs() as i32;
        let vertical_gap = (puller_position.y as i64 - target_position.y as i64).abs() as i32;
        if horizontal_gap > horizontal_gap_limit || vertical_gap > vertical_gap_limit {
            self.stop_action_delay_command_live(puller_id)?;
            self.grab_lost(puller_id)?;
            if let Some(puller_idx) = self.find_object_index(puller_id) {
                self.objects[puller_idx].state.action.target = None;
                self.objects[puller_idx].compiler_cache.action_target1 = 0;
            }
            return Ok(false);
        }

        let speed_limit = walk_speed.saturating_mul(2).max(walk_speed);
        let physics = self.physics;

        match idx.cmp(&target_idx) {
            std::cmp::Ordering::Less => {
                let (first, second) = self.objects.split_at_mut(target_idx);
                let puller = &mut first[idx];
                let target = &mut second[0];
                Self::update_pull_pair(
                    puller,
                    target,
                    desired_puller_velocity,
                    desired_target_velocity,
                    speed_limit,
                    walk_accel,
                    physics,
                );
            }
            std::cmp::Ordering::Greater => {
                let (first, second) = self.objects.split_at_mut(idx);
                let target = &mut first[target_idx];
                let puller = &mut second[0];
                Self::update_pull_pair(
                    puller,
                    target,
                    desired_puller_velocity,
                    desired_target_velocity,
                    speed_limit,
                    walk_accel,
                    physics,
                );
            }
            std::cmp::Ordering::Equal => {
                // Should not happen because we guard earlier, but keep the action safe.
                self.stop_action_delay_command_live(puller_id)?;
                return Ok(false);
            }
        }

        Ok(true)
    }

    fn apply_fight_procedure(
        &mut self,
        idx: usize,
        physical: PhysicalInfo,
    ) -> Result<bool, EngineError> {
        let fighter_id = self.objects[idx].id;
        let Some(target_id) = self.objects[idx].state.action.target else {
            let _ = self.object_action_stand_live(fighter_id)?;
            return Ok(false);
        };

        let Some(target_idx) = self.find_object_index(target_id) else {
            let _ = self.object_action_stand_live(fighter_id)?;
            return Ok(false);
        };

        if target_idx == idx {
            let _ = self.object_action_stand_live(fighter_id)?;
            return Ok(false);
        }

        let target_definition_id = self.objects[target_idx].definition_id.clone();
        let target_action_name = self.objects[target_idx].state.action.name.clone();
        let target_action_index = self.objects[target_idx].state.action.act_map_index;
        let target_procedure = self
            .definitions
            .get(&target_definition_id)
            .map(|definition| {
                definition
                    .action_library()
                    .procedure_for_entry(&target_action_name, target_action_index)
            })
            .unwrap_or_default();
        if !matches!(target_procedure, ActionProcedure::Fight) {
            let _ = self.object_action_stand_live(fighter_id)?;
            return Ok(false);
        }

        let fighter_container = self.objects[idx].state.container;
        let target_container = self.objects[target_idx].state.container;
        let fighter_container_is_closed = fighter_container
            .and_then(|container_id| self.find_object_index(container_id))
            .is_some_and(|container_idx| !self.objects[container_idx].state.entrance_status);
        let target_container_is_closed = target_container
            .and_then(|container_id| self.find_object_index(container_id))
            .is_some_and(|container_idx| !self.objects[container_idx].state.entrance_status);
        if fighter_container != target_container
            && (fighter_container_is_closed || target_container_is_closed)
        {
            let _ = self.object_action_stand_live(fighter_id)?;
            return Ok(false);
        }

        let fighter_position = self.objects[idx].state.position;
        let target_position = self.objects[target_idx].state.position;
        let initial_direction = self.objects[idx].state.direction;

        // Physical training (C4Object.cpp:5214-5216): Tick5 trains Fight.
        if self.frame % 5 == 0 {
            self.train_physical(idx, "Fight", 1, C4_MAX_PHYSICAL);
        }

        // Direction (C4Object.cpp:5218-5220): face the target; equal x keeps
        // the previous facing.
        let direction = if target_position.x > fighter_position.x {
            Direction::Right
        } else if target_position.x < fighter_position.x {
            Direction::Left
        } else {
            initial_direction
        };
        self.objects[idx].state.direction = direction;

        // Position (C4Object.cpp:5221-5228): stand beside the target at half
        // its shape width + 2, approach with the Walk physical:
        // lLimit = ValByPhysical(95, Walk), Towards(xdir, ±lLimit, lLimit).
        let target_half_width = self.objects[target_idx]
            .current_shape_rect()
            .unwrap_or_default()
            .width
            / 2;
        let mut approach_x = fighter_position.x;
        if direction == Direction::Left {
            approach_x = target_position.x + target_half_width + 2;
        }
        if direction == Direction::Right {
            approach_x = target_position.x - target_half_width - 2;
        }
        let limit = math::val_by_physical(95, physical.walk);
        let physics = self.physics;
        let fighter = &mut self.objects[idx];
        let mut xdir = fighter.fixed_velocity.x;
        match fighter_position.x.cmp(&approach_x) {
            std::cmp::Ordering::Equal => math::towards(&mut xdir, C4Fixed::ZERO, limit),
            std::cmp::Ordering::Less => math::towards(&mut xdir, limit, limit),
            std::cmp::Ordering::Greater => math::towards(&mut xdir, -limit, limit),
        }
        fighter.fixed_velocity.x = xdir;

        // Distance check (C4Object.cpp:5229-5234): own shape width bounds.
        let threshold = self.objects[idx]
            .current_shape_rect()
            .unwrap_or_default()
            .width;
        if (fighter_position.x - target_position.x).abs() > threshold
            || (fighter_position.y - target_position.y).abs() > threshold
        {
            let _ = self.object_action_stand_live(fighter_id)?;
            return Ok(false);
        }

        // Other (C4Object.cpp:5235-5238): grounded fighting and Tick35
        // experience after every validity check above has succeeded.
        let fighter_id = self.objects[idx].id;
        let fighter = &mut self.objects[idx];
        fighter.fixed_velocity.y = C4Fixed::ZERO;
        physics.clamp_fixed_velocity(&mut fighter.fixed_velocity);
        fighter.refresh_velocity_from_fixed();
        if self.frame % 35 == 0 {
            self.do_object_experience(fighter_id, 2);
        }

        Ok(true)
    }

    /// `C4Object::Push` (C4Object.cpp:1758-1808): grab/containment checks,
    /// force scaled against the target mass, facing from the current motion,
    /// xdir worked toward the push speed (close-enough-set), straightening
    /// for upright pushes, and the final Tick35 stuck probe.
    /// The LIVE object mass (C4Object::UpdateMass, C4Object.cpp:497-505).
    /// Objects.txt compiles the cached Mass word verbatim; only native
    /// UpdateMass paths replace it with the derived own-plus-contents value.
    fn valid_compiled_object_mass(&self, index: usize) -> Option<i32> {
        fn valid(engine: &Engine, index: usize, visiting: &mut HashSet<ObjectId>) -> bool {
            let object = &engine.objects[index];
            let retained_contents = object
                .state
                .contents
                .iter()
                .copied()
                .filter(|content| {
                    engine
                        .find_object_index(*content)
                        .is_some_and(|index| engine.objects[index].has_nonzero_status())
                })
                .collect::<Vec<_>>();
            if object.compiled_mass.is_none()
                || object.compiled_mass_contents.len() != retained_contents.len()
                || !object
                    .compiled_mass_contents
                    .iter()
                    .all(|id| retained_contents.contains(id))
            {
                return false;
            }
            if !visiting.insert(object.id) {
                return true;
            }
            let valid = retained_contents.iter().all(|content| {
                engine
                    .find_object_index(*content)
                    .is_some_and(|index| valid(engine, index, visiting))
            });
            visiting.remove(&object.id);
            valid
        }

        valid(self, index, &mut HashSet::new()).then_some(self.objects[index].compiled_mass?)
    }

    fn effective_object_mass(&self, index: usize) -> i32 {
        fn inner(
            engine: &Engine,
            index: usize,
            is_root: bool,
            visiting: &mut HashSet<ObjectId>,
        ) -> i32 {
            let object = &engine.objects[index];
            if let Some(mass) = engine.valid_compiled_object_mass(index) {
                return mass;
            }
            if !visiting.insert(object.id) {
                return 1;
            }
            let (def_mass, no_component_mass) = engine
                .definitions
                .get(&object.definition_id)
                .map(|definition| (definition.mass(), definition.no_component_mass()))
                .unwrap_or((0, false));
            // (Def->Mass + OwnMass) * Con / FullCon (C4Object.cpp:499) —
            // OwnMass carries script SetMass overrides (the ArrowPack
            // family: SetMass(GetMass(item)*PackCount), ArrowPack.c4d).
            let mut mass = ((def_mass + object.state.own_mass)
                .saturating_mul(object.state.construction)
                / FULL_CON)
                .max(1);
            if !no_component_mass {
                for content in &object.state.contents {
                    if let Some(content_idx) = engine
                        .find_object_index(*content)
                        .filter(|&index| engine.objects[index].has_nonzero_status())
                    {
                        let m = inner(engine, content_idx, false, visiting);
                        if is_root
                            && object.state.contents.len() > 20
                            && std::env::var("LC_MASSDBG").is_ok()
                        {
                            eprintln!(
                                "MASSDBG {} {}",
                                engine.objects[content_idx].definition_id.as_str(),
                                m
                            );
                        }
                        mass += m;
                    }
                }
            }
            visiting.remove(&object.id);
            mass
        }
        inner(self, index, true, &mut HashSet::new())
    }

    fn push_object(
        &mut self,
        target_idx: usize,
        txdir: C4Fixed,
        dforce: C4Fixed,
        straighten: bool,
    ) -> Result<bool, EngineError> {
        {
            let target = &self.objects[target_idx];
            if !target.has_nonzero_status() || target.state.container.is_some() {
                return Ok(false);
            }
        }
        if self.object_ocf_at_index(target_idx) & ocf::GRAB == 0 {
            return Ok(false);
        }
        // dforce divides by the LIVE Mass incl. contents (C4Object::Push
        // C4Object.cpp:1770 uses this->Mass; UpdateMass :497-505).
        let live_mass = self.effective_object_mass(target_idx);
        let (grab, mass) = self
            .definitions
            .get(&self.objects[target_idx].definition_id)
            .map(|definition| (definition.grab(), live_mass))
            .unwrap_or((0, 0));
        // Grabbing okay, no pushing (C4Object.cpp:1763).
        if grab == 2 {
            return Ok(true);
        }
        // General pushing force vs. object mass (C4Object.cpp:1770).
        let dforce = dforce * 100 / mass.max(1);
        let target_id = self.objects[target_idx].id;
        let target_definition_id = self.objects[target_idx].definition_id.clone();
        let direction = {
            let target = &mut self.objects[target_idx];
            // Mobilization check - pre-mobilization zero
            // (C4Object.cpp:1765-1768): a resting target starts from clean
            // dirs and pixel-snapped fix.
            if !target.state.mobile {
                target.fixed_velocity = FixedVec2::ZERO;
                target.fixed_position = FixedVec2::new(
                    itofix(target.state.position.x),
                    itofix(target.state.position.y),
                );
            }
            // SetDir reads the raw pre-force xdir. End this borrow before the
            // callback-capable TurnAction transition.
            if target.fixed_velocity.x < C4Fixed::ZERO {
                Some(Direction::Left)
            } else if target.fixed_velocity.x > C4Fixed::ZERO {
                Some(Direction::Right)
            } else {
                None
            }
        };
        if let Some(direction) = direction {
            self.set_command_action_direction(target_idx, &target_definition_id, direction)?;
        }
        let Some(target_idx) = self.find_object_index(target_id) else {
            return Ok(false);
        };
        let target = &mut self.objects[target_idx];
        // Work towards txdir (C4Object.cpp:1775-1783).
        let mut xdir = target.fixed_velocity.x;
        math::towards(&mut xdir, txdir, dforce);
        if std::env::var("LC_PULLDBG").is_ok() && (19..=22).contains(&self.frame) {
            eprintln!(
                "PULLDBG f{} target={} {} -> {} (txdir {} dforce {})",
                self.frame,
                target.id.as_u64(),
                target.fixed_velocity.x.val(),
                xdir.val(),
                txdir.val(),
                dforce.val()
            );
        }
        target.fixed_velocity.x = xdir;
        // Straighten (C4Object.cpp:1785-1794); the normalized rotation maps
        // back to the C++ signed range.
        if straighten {
            let rotation = target.state.rotation;
            let signed = if rotation > 180 {
                rotation - 360
            } else {
                rotation
            };
            if (-math::STABLE_RANGE..=math::STABLE_RANGE).contains(&signed) {
                target.rotation_velocity = C4Fixed::ZERO;
            } else if signed > 0 {
                if target.rotation_velocity > -math::ROTATE_ACCEL {
                    target.rotation_velocity -= dforce;
                }
            } else if target.rotation_velocity < math::ROTATE_ACCEL {
                target.rotation_velocity += dforce;
            }
        }
        // Mobilization check (C4Object.cpp:1797): any nonzero dir after the
        // force application mobilizes the target.
        if target.fixed_velocity.x.is_nonzero()
            || target.fixed_velocity.y.is_nonzero()
            || target.rotation_velocity.is_nonzero()
        {
            target.state.mobile = true;
        }
        target.refresh_velocity_from_fixed();

        // Stuck check (C4Object.cpp:1801-1807): gate on the requested raw
        // fixed speed, not on the velocity reached above. ContactCheck
        // refreshes t_contact and runs directional Contact callbacks before
        // the target message and fail-safe Stuck callback.
        let no_horizontal_move = self
            .definitions
            .get(&self.objects[target_idx].definition_id)
            .map(Definition::no_horizontal_move)
            .unwrap_or(0);
        if self.frame % 35 == 0 && txdir.is_nonzero() && no_horizontal_move == 0 {
            let target_id = self.objects[target_idx].id;
            let position = self.objects[target_idx].state.position;
            let solid_mask_indices = self.active_solid_mask_indices();
            let contacted = self
                .object_contact_check_at(target_idx, position, &solid_mask_indices)?
                .is_some_and(|contact| contact.is_contact());
            if contacted {
                if let Some(target_idx) = self.find_object_index(target_id).filter(|&index| {
                    !self.objects[index].destroyed
                        && self.objects[index].state.status != ObjectStatus::Deleted
                }) {
                    let object = &self.objects[target_idx];
                    let name = object
                        .state
                        .custom_name
                        .clone()
                        .or_else(|| {
                            self.crew_object_infos
                                .get(&target_id)
                                .map(|info| info.name.clone())
                        })
                        .or_else(|| {
                            self.definitions
                                .get(&object.definition_id)
                                .map(|definition| definition.name().to_string())
                        })
                        .unwrap_or_else(|| object.definition_id.clone());
                    self.messages.add_message(MessageSpec {
                        kind: message::MessageKind::Target,
                        text: format!("{name} is stuck!"),
                        target: Some(target_id),
                        player: None,
                        offset: Vector2::ZERO,
                        color: 0xffff_ffff,
                        flags: 0,
                        width: None,
                        decoration: None,
                        frame_decoration: None,
                        portrait: None,
                    });
                    let _ = tolerate_script_error(self.call_object_function(
                        target_idx,
                        "Stuck",
                        Vec::new(),
                    ))?;
                }
            }
        }
        Ok(true)
    }

    /// DFA_PUSH with a nonzero Walk physical (C4Object.cpp:5040-5097):
    /// target force `ValByPhysical(250, Push)` toward `±ValByPhysical(280,
    /// Walk)` per ComDir, got-hold area check with the GrabLost callback,
    /// follow xdir at the full walk limit, and controller transfer
    /// (C4Object.cpp:5082).
    fn apply_push_procedure_physical(
        &mut self,
        idx: usize,
        target_idx: usize,
        command_direction: CommandDirection,
        definition_id: &DefinitionId,
        physical: PhysicalInfo,
    ) -> Result<bool, EngineError> {
        let limit = math::val_by_physical(280, physical.walk);
        // ComDir → target speed and straightening (C4Object.cpp:5049-5057).
        let (txdir, straighten) = match command_direction {
            CommandDirection::Left | CommandDirection::DownLeft => (-limit, false),
            CommandDirection::UpLeft => (-limit, true),
            CommandDirection::Right | CommandDirection::DownRight => (limit, false),
            CommandDirection::UpRight => (limit, true),
            CommandDirection::Up => (C4Fixed::ZERO, true),
            CommandDirection::Stop | CommandDirection::Down => (C4Fixed::ZERO, false),
            _ => (C4Fixed::ZERO, false),
        };
        // Push object (C4Object.cpp:5059-5062).
        if !self.push_object(
            target_idx,
            txdir,
            math::val_by_physical(250, physical.push),
            straighten,
        )? {
            self.stop_action_delay_command(idx, definition_id)?;
            return Ok(false);
        }
        // C++ copies attribution immediately after Push succeeds, before a
        // later got-hold failure can stop the action (C4Object.cpp:5082).
        self.objects[target_idx].state.controller = self.objects[idx].state.controller;
        // Got-hold check (C4Object.cpp:5066-5080).
        let own_width = self.objects[idx]
            .current_shape_rect()
            .map(|rect| rect.width)
            .unwrap_or(0);
        let push_distance = (own_width / 2 - 8).max(0);
        let push_range = push_distance + 10;
        let target_position = self.objects[target_idx].state.position;
        let target_rect = self.objects[target_idx]
            .current_shape_rect()
            .unwrap_or_default();
        let mut sax = target_position.x + target_rect.x;
        let say = target_position.y + target_rect.y;
        let mut sawdt = target_rect.width;
        let sahgt = target_rect.height;
        let position = self.objects[idx].state.position;
        if !(-push_range..=sawdt - 1 + push_range).contains(&(position.x - sax))
            || !(-push_range..=sahgt - 1 + push_range).contains(&(position.y - say))
        {
            let pusher_id = self.objects[idx].id;
            self.stop_action_delay_command(idx, definition_id)?;
            self.grab_lost(pusher_id)?;
            return Ok(false);
        }
        // Vertical follow (C4Object.cpp:5083).
        if position.y - push_distance > say + sahgt && txdir != C4Fixed::ZERO {
            if txdir > C4Fixed::ZERO {
                sax += sawdt / 2;
            }
            sawdt /= 2;
        }
        // Horizontal follow with the full xdir reset (C4Object.cpp:5085-5087).
        let target_x = position
            .x
            .max(sax - push_distance)
            .min(sax + sawdt - 1 + push_distance);
        let physics = self.physics;
        let object = &mut self.objects[idx];
        let mut xdir = C4Fixed::ZERO;
        if position.x < target_x {
            xdir = limit;
        }
        if position.x > target_x {
            xdir = -limit;
        }
        object.fixed_velocity.x = xdir;
        // SetDir by xdir (C4Object.cpp:5089-5090), grounded (5092).
        if xdir < C4Fixed::ZERO {
            object.state.direction = Direction::Left;
        }
        if xdir > C4Fixed::ZERO {
            object.state.direction = Direction::Right;
        }
        object.fixed_velocity.y = C4Fixed::ZERO;
        physics.clamp_fixed_velocity(&mut object.fixed_velocity);
        object.refresh_velocity_from_fixed();
        Ok(true)
    }

    /// `StopActionDelayCommand` (C4Object.cpp:4677-4681): every failed
    /// DFA_PUSH first runs ObjectComStop (Idle, then stand in Walk) and adds
    /// a silent 50-frame Wait to the top of the command stack.
    fn stop_action_delay_command(
        &mut self,
        idx: usize,
        definition_id: &DefinitionId,
    ) -> Result<(), EngineError> {
        self.object_com_stop_action(idx, definition_id)?;
        let wait = CommandRequest::new(CommandId::Wait)
            .with_update_interval(50)
            .with_mode(CommandMode::SilentSub);
        let _ = self.objects[idx].commands.push_front(wait);
        Ok(())
    }

    /// Stable-id form used when target-side callbacks may have changed the
    /// object list or the actor's definition before the stop runs.
    fn stop_action_delay_command_live(&mut self, object_id: ObjectId) -> Result<(), EngineError> {
        let _ = self.object_com_stop_live(object_id)?;
        let wait = CommandRequest::new(CommandId::Wait)
            .with_update_interval(50)
            .with_mode(CommandMode::SilentSub);
        if let Some(idx) = self.find_object_index(object_id) {
            let _ = self.objects[idx].commands.push_front(wait);
        }
        Ok(())
    }

    fn apply_push_procedure(
        &mut self,
        idx: usize,
        command_direction: CommandDirection,
        movement_profile: MovementProfile,
        definition_id: &DefinitionId,
        physical: PhysicalInfo,
    ) -> Result<bool, EngineError> {
        let Some(target_id) = self.objects[idx].state.action.target else {
            self.stop_action_delay_command(idx, definition_id)?;
            return Ok(false);
        };
        let Some(target_idx) = self.find_object_index(target_id) else {
            self.stop_action_delay_command(idx, definition_id)?;
            return Ok(false);
        };
        if target_idx == idx {
            self.stop_action_delay_command(idx, definition_id)?;
            return Ok(false);
        }
        let target_removed = {
            let target = &self.objects[target_idx];
            target.destroyed || matches!(target.state.status, ObjectStatus::Deleted)
        };
        if target_removed {
            self.stop_action_delay_command(idx, definition_id)?;
            return Ok(false);
        }
        if self.objects[idx].state.container == Some(target_id)
            || self.objects[target_idx].state.container.is_some()
        {
            self.stop_action_delay_command(idx, definition_id)?;
            return Ok(false);
        }

        if physical.walk != 0 {
            return self.apply_push_procedure_physical(
                idx,
                target_idx,
                command_direction,
                definition_id,
                physical,
            );
        }

        let push_speed = movement_profile.walk_speed.max(0);
        let push_accel = movement_profile.walk_acceleration.max(0);
        let straighten = matches!(
            command_direction,
            CommandDirection::Up | CommandDirection::UpLeft | CommandDirection::UpRight
        );
        let desired_target_velocity = match command_direction {
            CommandDirection::Left | CommandDirection::DownLeft | CommandDirection::UpLeft => {
                -push_speed
            }
            CommandDirection::Right | CommandDirection::DownRight | CommandDirection::UpRight => {
                push_speed
            }
            _ => 0,
        };

        let physics = self.physics;

        if idx < target_idx {
            let (first, rest) = self.objects.split_at_mut(target_idx);
            let pusher = &mut first[idx];
            let target = &mut rest[0];
            Self::update_push_pair(
                pusher,
                target,
                desired_target_velocity,
                push_speed,
                push_accel,
                straighten,
                physics,
            );
        } else {
            let (first, rest) = self.objects.split_at_mut(idx);
            let target = &mut first[target_idx];
            let pusher = &mut rest[0];
            Self::update_push_pair(
                pusher,
                target,
                desired_target_velocity,
                push_speed,
                push_accel,
                straighten,
                physics,
            );
        }

        Ok(true)
    }

    fn update_pull_pair(
        puller: &mut Object,
        target: &mut Object,
        desired_puller_velocity: i32,
        desired_target_velocity: i32,
        speed_limit: i32,
        acceleration: i32,
        physics: PhysicsSettings,
    ) {
        let accel = itofix(acceleration.max(0));
        // DFA_PULL moves the target through C4Object::Push, so the same
        // pre-mobilization zero + mobilization check apply
        // (C4Object.cpp:1765-1768,1797).
        if !target.state.mobile {
            target.fixed_velocity = FixedVec2::ZERO;
            target.fixed_position = FixedVec2::new(
                itofix(target.state.position.x),
                itofix(target.state.position.y),
            );
        }
        let new_target_velocity = step_fixed_toward(
            target.fixed_velocity.x,
            itofix(desired_target_velocity),
            accel,
        );
        target.fixed_velocity.x = clamp_fixed_to_limit(new_target_velocity, speed_limit);
        physics.clamp_fixed_velocity(&mut target.fixed_velocity);
        if target.fixed_velocity.x.is_nonzero()
            || target.fixed_velocity.y.is_nonzero()
            || target.rotation_velocity.is_nonzero()
        {
            target.state.mobile = true;
        }
        target.refresh_velocity_from_fixed();
        target.state.controller = puller.state.controller;

        let new_puller_velocity = step_fixed_toward(
            puller.fixed_velocity.x,
            itofix(desired_puller_velocity),
            accel,
        );
        puller.fixed_velocity.x = clamp_fixed_to_limit(new_puller_velocity, speed_limit);
        puller.fixed_velocity.y = C4Fixed::ZERO;
        physics.clamp_fixed_velocity(&mut puller.fixed_velocity);
        puller.refresh_velocity_from_fixed();
    }

    fn update_push_pair(
        pusher: &mut Object,
        target: &mut Object,
        desired_target_velocity: i32,
        push_speed: i32,
        push_accel: i32,
        straighten: bool,
        physics: PhysicsSettings,
    ) {
        let push_accel = push_accel.max(0);
        let push_accel_fixed = itofix(push_accel);
        // C4Object::Push pre-mobilization zero (C4Object.cpp:1765-1768).
        if !target.state.mobile {
            target.fixed_velocity = FixedVec2::ZERO;
            target.fixed_position = FixedVec2::new(
                itofix(target.state.position.x),
                itofix(target.state.position.y),
            );
        }
        let new_target_velocity = step_fixed_toward(
            target.fixed_velocity.x,
            itofix(desired_target_velocity),
            push_accel_fixed,
        );
        target.fixed_velocity.x = clamp_fixed_to_limit(new_target_velocity, push_speed);
        if straighten && push_accel > 0 {
            target.fixed_velocity.y =
                decelerate_fixed_toward_zero(target.fixed_velocity.y, push_accel_fixed);
        }
        physics.clamp_fixed_velocity(&mut target.fixed_velocity);
        // Mobilization check (C4Object.cpp:1797).
        if target.fixed_velocity.x.is_nonzero()
            || target.fixed_velocity.y.is_nonzero()
            || target.rotation_velocity.is_nonzero()
        {
            target.state.mobile = true;
        }
        target.refresh_velocity_from_fixed();
        target.state.controller = pusher.state.controller;

        let mut desired_pusher_velocity = desired_target_velocity;
        if desired_pusher_velocity == 0 {
            let delta = target.state.position.x - pusher.state.position.x;
            let threshold = push_speed.max(1);
            if delta > threshold {
                desired_pusher_velocity = push_speed;
            } else if delta < -threshold {
                desired_pusher_velocity = -push_speed;
            }
        }

        let new_pusher_velocity = step_fixed_toward(
            pusher.fixed_velocity.x,
            itofix(desired_pusher_velocity),
            push_accel_fixed,
        );
        pusher.fixed_velocity.x = clamp_fixed_to_limit(new_pusher_velocity, push_speed);
        pusher.fixed_velocity.y = C4Fixed::ZERO;
        physics.clamp_fixed_velocity(&mut pusher.fixed_velocity);
        pusher.refresh_velocity_from_fixed();
    }

    fn desired_pull_velocity(
        current_position: i32,
        desired_position: i32,
        base_velocity: i32,
        walk_speed: i32,
    ) -> i32 {
        let delta = desired_position.saturating_sub(current_position);
        let correction = delta.clamp(-10, 10) / 10;
        base_velocity + walk_speed.saturating_mul(correction)
    }

    fn object_half_extents(object: &Object) -> (i32, i32) {
        if object.state.vertices.is_empty() {
            // Without explicit vertex data fall back to a generous default so pull spacing stays stable.
            return (10, 10);
        }

        let mut min_x = object.state.vertices[0].x;
        let mut max_x = min_x;
        let mut min_y = object.state.vertices[0].y;
        let mut max_y = min_y;
        for vertex in &object.state.vertices {
            if vertex.x < min_x {
                min_x = vertex.x;
            }
            if vertex.x > max_x {
                max_x = vertex.x;
            }
            if vertex.y < min_y {
                min_y = vertex.y;
            }
            if vertex.y > max_y {
                max_y = vertex.y;
            }
        }

        let width = max_x.saturating_sub(min_x);
        let height = max_y.saturating_sub(min_y);
        let half_width = if width <= 0 { 10 } else { (width + 1) / 2 };
        let half_height = if height <= 0 { 10 } else { (height + 1) / 2 };
        (half_width, half_height)
    }

    fn horizontal_input_sign(command_direction: CommandDirection) -> i32 {
        match command_direction {
            CommandDirection::Left | CommandDirection::UpLeft | CommandDirection::DownLeft => -1,
            CommandDirection::Right | CommandDirection::UpRight | CommandDirection::DownRight => 1,
            _ => 0,
        }
    }

    #[doc(hidden)]
    pub fn apply_landscape_at_index(&mut self, idx: usize) {
        if idx >= self.objects.len() || self.objects[idx].state.vertices.is_empty() {
            return;
        }

        let procedure = {
            let object = &self.objects[idx];
            let definition_id = object.definition_id.clone();
            self.definitions
                .get(&definition_id)
                .map(|definition| {
                    definition
                        .action_library()
                        .procedure_for_entry(
                            &object.state.action.name,
                            object.state.action.act_map_index,
                        )
                })
                .unwrap_or_default()
        };

        if matches!(procedure, ActionProcedure::Attach) {
            return;
        }

        let resolution = match self.landscape.as_ref() {
            Some(landscape) => {
                let (position, velocity) = {
                    let object = &self.objects[idx];
                    (object.state.position, object.state.velocity)
                };
                landscape.resolve_collision(position, velocity)
            }
            None => return,
        };
        if !resolution.collided {
            return;
        }
        let object = &mut self.objects[idx];
        object.apply_collision_resolution(&resolution);
        if let Some(material_id) = resolution.material {
            if let Some(material) = self.materials.get_by_id(material_id) {
                object.apply_material_interaction(material);
            }
        }
    }

    /// `C4GameObjects::CrossCheck` reverse area check
    /// (C4GameObjects.cpp:140-197), run once per frame after object    /// execution: every frame an OCF_Alive victim takes OCF_HitSpeed2 hits
    /// from C4D_Object projectiles inside its shape; on Tick3 frames
    /// collection runs (OCF_Collection vs OCF_Carryable, Collection rect).
    /// Candidates are deduplicated per victim like the C++ Marker. Pass 1
    /// (Tick5 fight / Tick35 contact incineration) and pass 3 (contained
    /// fight) still need the hostility and fire models.
    #[doc(hidden)]
    pub fn cross_check(&mut self, frame: u64) -> Result<(), EngineError> {
        self.cross_check_at_object_pass(frame)?;
        self.cross_check_reverse_area_pass(frame)?;
        self.cross_check_contained_pass(frame)
    }

    /// CrossCheck pass 3: Contained check (C4GameObjects.cpp:199-230). On
    /// Tick10 frames, contained FightReady objects fight hostile FightReady
    /// company sharing their container — directly, with no RejectFight veto.
    fn cross_check_contained_pass(&mut self, frame: u64) -> Result<(), EngineError> {
        if frame % 10 != 0 {
            return Ok(());
        }
        let focf = crate::ocf::FIGHT_READY;
        let tocf = crate::ocf::FIGHT_READY;
        let object_ids = self.exec_list.iter().rev().copied().collect::<Vec<_>>();
        'outer: for obj1_id in object_ids {
            let Some(idx) = self.find_object_index(obj1_id) else {
                continue;
            };
            let container = {
                let obj1 = &self.objects[idx];
                if obj1.destroyed || !obj1.state.status.is_active() {
                    continue;
                }
                match obj1.state.container {
                    Some(container) => container,
                    None => continue,
                }
            };
            if self.object_ocf_at_index(idx) & focf == 0 {
                continue;
            }
            let obj1_layer = self.objects[idx].state.layer;
            let contents = match self
                .find_object_index(container)
                .map(|container_idx| self.objects[container_idx].state.contents.clone())
            {
                Some(contents) => contents,
                None => continue,
            };
            for obj2_id in contents {
                if obj2_id == obj1_id {
                    continue;
                }
                // Object indices are stable mid-tick (the Vec only appends
                // until the end-of-tick retain), so obj1'"'"'s index from the
                // outer loop stays valid; C++ re-checks the FLAGS after
                // callbacks, not the identity (C4GameObjects.cpp:186-192).
                let Some(obj2_idx) = self.find_object_index(obj2_id) else {
                    continue;
                };
                {
                    let obj2 = &self.objects[obj2_idx];
                    if !obj2.has_nonzero_status()
                        || obj2.state.container.is_none()
                        || obj2.state.layer != obj1_layer
                    {
                        continue;
                    }
                }
                if self.object_ocf_at_index(obj2_idx) & tocf == 0 {
                    continue;
                }
                let ocf1 = self.object_ocf_at_index(idx);
                // Fight (C4GameObjects.cpp:218-227)
                if ocf1 & crate::ocf::FIGHT_READY != 0 {
                    let owner1 = self.objects[idx].state.owner;
                    let owner2 = self.objects[obj2_idx].state.owner;
                    if self.players_hostile(owner1, owner2) {
                        self.object_action_fight(obj1_id, obj2_id);
                        self.object_action_fight(obj2_id, obj1_id);
                        // obj1 might have been tampered with
                        let Some(idx) = self.find_object_index(obj1_id) else {
                            continue 'outer;
                        };
                        let obj1 = &self.objects[idx];
                        if obj1.destroyed
                            || !obj1.state.status.is_active()
                            || obj1.state.container.is_some()
                            || self.object_ocf_at_index(idx) & focf == 0
                        {
                            continue 'outer;
                        }
                    }
                }
            }
        }
        Ok(())
    }

    /// CrossCheck pass 1: AtObject check (C4GameObjects.cpp:97-138). On Tick5
    /// frames FightReady objects standing at a hostile FightReady object    /// start fighting both ways after the RejectFight callbacks. The Tick35
    /// contact-incineration arm (OCF_OnFire vs OCF_Inflammable with the
    /// `!Random(ContactIncinerate)` draw) still needs the fire model — no
    /// Rust object ever carries OCF_OnFire yet, so the C++ stream consumes no
    /// draws for it either.
    fn cross_check_at_object_pass(&mut self, frame: u64) -> Result<(), EngineError> {
        let tick5 = frame % 5 == 0;
        let tick35 = frame % 35 == 0;
        let mut focf = crate::ocf::NONE;
        let mut tocf = crate::ocf::NONE;
        if tick5 {
            focf |= crate::ocf::FIGHT_READY;
            tocf |= crate::ocf::FIGHT_READY;
        }
        // Very low level: Incineration (C4GameObjects.cpp:106-110)
        if tick35 {
            focf |= crate::ocf::ON_FIRE;
            tocf |= crate::ocf::INFLAMMABLE;
        }
        if focf == 0 || tocf == 0 {
            return Ok(());
        }
        let object_ids = self.exec_list.iter().rev().copied().collect::<Vec<_>>();
        for obj1_id in object_ids {
            let Some(idx) = self.find_object_index(obj1_id) else {
                continue;
            };
            {
                let obj1 = &self.objects[idx];
                if obj1.destroyed
                    || !obj1.state.status.is_active()
                    || obj1.state.container.is_some()
                {
                    continue;
                }
            }
            let ocf1 = self.object_ocf_at_index(idx);
            if ocf1 & focf == 0 {
                continue;
            }
            let position = self.objects[idx].state.position;
            let Some((obj2_idx, obj2_id, ocf2)) = self.at_object(position, tocf, Some(obj1_id))
            else {
                continue;
            };
            // Incineration (C4GameObjects.cpp:120-125): the Random draw runs
            // whenever the OCF pair matches, regardless of its outcome.
            if ocf1 & crate::ocf::ON_FIRE != 0 && ocf2 & crate::ocf::INFLAMMABLE != 0 {
                let contact_incinerate = self
                    .definitions
                    .get(&self.objects[obj2_idx].definition_id)
                    .map(|definition| definition.contact_incinerate())
                    .unwrap_or(0);
                if self.rng.random(contact_incinerate) == 0 {
                    // GetFireCausePlr: the fire effect's CausedBy, NO_OWNER
                    // unless it is a valid player.
                    let cause = self.objects[idx].state.fire_caused_by;
                    let cause = if self.players.contains_key(&cause) {
                        cause
                    } else {
                        OWNER_NONE
                    };
                    let _ = self.incinerate_object(obj2_idx, cause, false, Some(obj1_id))?;
                    continue;
                }
            }
            // Fight (C4GameObjects.cpp:126-136)
            if ocf1 & crate::ocf::FIGHT_READY != 0 && ocf2 & crate::ocf::FIGHT_READY != 0 {
                let owner1 = self.objects[idx].state.owner;
                let owner2 = self.objects[obj2_idx].state.owner;
                if !self.players_hostile(owner1, owner2) {
                    continue;
                }
                // RejectFight callbacks (C4GameObjects.cpp:131-132)
                let reject1 = self.call_object_function(
                    idx,
                    "RejectFight",
                    vec![object_reference_value(obj2_id)],
                )?;
                if reject1.as_bool() {
                    continue;
                }
                let Some(obj2_idx) = self.find_object_index(obj2_id) else {
                    continue;
                };
                let reject2 = self.call_object_function(
                    obj2_idx,
                    "RejectFight",
                    vec![object_reference_value(obj1_id)],
                )?;
                if reject2.as_bool() {
                    continue;
                }
                self.object_action_fight(obj1_id, obj2_id);
                self.object_action_fight(obj2_id, obj1_id);
            }
        }
        Ok(())
    }

    /// `ObjectActionFight` (C4ObjectCom.cpp:157-160):
    /// `SetActionByName("Fight", target)`.
    fn object_action_fight(&mut self, object_id: ObjectId, target_id: ObjectId) {
        let Some(idx) = self.find_object_index(object_id) else {
            return;
        };
        let definition_id = self.objects[idx].definition_id.clone();
        let Some(library) = self
            .definitions
            .get(&definition_id)
            .map(|definition| definition.action_library().clone())
        else {
            return;
        };
        if !library.contains("Fight") {
            return;
        }
        let previous = self.objects[idx].state.action.clone();
        let update = ActionUpdate {
            name: Some("Fight".to_string()),
            phase: Some(0),
            ticks: Some(0),
            force: false,
            data: None,
            target: Some(Some(target_id)),
            target2: Some(None),
            callbacks_dispatched: false,
        };
        let object = &mut self.objects[idx];
        let result = object
            .state
            .action
            .apply_update_with_library(&update, &library);
        // SetAction fix resync (C4Object.cpp:4144) — only past the
        // NoOtherAction early returns.
        if update.name.is_some() && matches!(result, ActionUpdateResult::Applied) {
            object.fixed_position =
                FixedVec2::from_ints(object.state.position.x, object.state.position.y);
        }
        if matches!(result, ActionUpdateResult::Applied)
            && (previous.name != object.state.action.name
                || previous.act_map_index != object.state.action.act_map_index)
        {
            object.record_action_event(previous, ActionTransitionKind::Forced);
        }
    }

    /// `C4PlayerList::Hostile` (C4PlayerList.cpp:82-92): false for missing or
    /// identical players; one-way declarations count both ways.
    fn players_hostile(&self, player1: i32, player2: i32) -> bool {
        let (Some(plr1), Some(plr2)) = (self.players.get(&player1), self.players.get(&player2))
        else {
            return false;
        };
        if plr1.id() == plr2.id() {
            return false;
        }
        plr1.is_hostile_towards(plr2.id()) || plr2.is_hostile_towards(plr1.id())
    }

    /// CrossCheck pass 2: reverse area check (C4GameObjects.cpp:140-197).
    fn cross_check_reverse_area_pass(&mut self, frame: u64) -> Result<(), EngineError> {
        let tick3 = frame % 3 == 0;
        let mut focf = crate::ocf::ALIVE;
        let mut tocf = crate::ocf::HIT_SPEED2;
        if tick3 {
            focf |= crate::ocf::COLLECTION;
            tocf |= crate::ocf::CARRYABLE;
        }
        let object_ids = self.exec_list.iter().rev().copied().collect::<Vec<_>>();
        'outer: for obj1_id in object_ids {
            let Some(idx) = self.find_object_index(obj1_id) else {
                continue;
            };
            {
                let obj1 = &self.objects[idx];
                if obj1.destroyed
                    || !obj1.state.status.is_active()
                    || obj1.state.container.is_some()
                {
                    continue;
                }
            }
            if self.object_ocf_at_index(idx) & focf == 0 {
                continue;
            }
            let (definition_id, obj1_layer) = {
                let obj1 = &self.objects[idx];
                (obj1.definition_id.clone(), obj1.state.layer)
            };
            let collection_rect = self
                .definitions
                .get(&definition_id)
                .and_then(|definition| definition.collection_rect());
            // obj1->Area: candidates from the sector lists under the shape
            let collector_shape_rect = self.object_shape_rect(&self.objects[idx]);
            let candidate_ids = self
                .sectors
                .as_ref()
                .map(|sectors| {
                    let area = sectors.area(collector_shape_rect);
                    sectors.object_ids_in_area(&area)
                })
                .unwrap_or_else(|| self.objects.iter().map(|object| object.id).collect());
            // handle collision only once (Marker, C4GameObjects.cpp:163-165)
            let mut marker: HashSet<ObjectId> = HashSet::new();
            for candidate_id in candidate_ids {
                // Object indices are stable mid-tick (the Vec only appends
                // until the end-of-tick retain), so obj1'"'"'s index from the
                // outer loop stays valid; C++ re-checks the FLAGS after
                // callbacks, not the identity (C4GameObjects.cpp:186-192).
                let Some(candidate_idx) = self.find_object_index(candidate_id) else {
                    continue;
                };
                if candidate_idx == idx {
                    continue;
                }
                {
                    let candidate = &self.objects[candidate_idx];
                    if candidate.destroyed
                        || !candidate.state.status.is_active()
                        || candidate.state.container.is_some()
                        || candidate.state.layer != obj1_layer
                    {
                        continue;
                    }
                }
                let ocf2 = self.object_ocf_at_index(candidate_idx);
                if ocf2 & tocf == 0 {
                    continue;
                }
                let obj1_position = self.objects[idx].state.position;
                let candidate_position = self.objects[candidate_idx].state.position;
                let dx = candidate_position.x - obj1_position.x;
                let dy = candidate_position.y - obj1_position.y;
                // Inside(obj2->x - (obj1->x + Shape.x), 0, Shape.Wdt - 1).
                // This is the raw LIVE Shape, without Area's addtop expansion;
                // re-read it for each candidate because an earlier callback may
                // change obj1's shape (C4GameObjects.cpp:159-160).
                let shape_rect = self.objects[idx].current_shape_rect();
                if let Some(shape) = shape_rect {
                    if !shape.contains_offset(dx, dy) {
                        continue;
                    }
                } else {
                    let (half_w, half_h) = Self::object_half_extents(&self.objects[idx]);
                    if dx < -half_w || dx >= half_w || dy < -half_h || dy >= half_h {
                        continue;
                    }
                }
                if !marker.insert(candidate_id) {
                    continue;
                }
                let ocf1 = self.object_ocf_at_index(idx);
                // Hit (C4GameObjects.cpp:167-184)
                if ocf2 & crate::ocf::HIT_SPEED2 != 0
                    && ocf1 & crate::ocf::ALIVE != 0
                    && self.objects[candidate_idx].state.category & CATEGORY_OBJECT != 0
                {
                    let by_value = object_reference_value(candidate_id);
                    let query =
                        self.call_object_function(idx, "QueryCatchBlow", vec![by_value.clone()])?;
                    if !query.as_bool() {
                        // "realistic" hit energy (C4GameObjects.cpp:171-173)
                        let v1 = self.objects[idx].fixed_velocity;
                        let v2 = self.objects[candidate_idx].fixed_velocity;
                        let dx_dir = v2.x - v1.x;
                        let dy_dir = v2.y - v1.y;
                        // "realistic" hit energy uses the LIVE Mass
                        // (C4GameObjects.cpp:171; UpdateMass includes
                        // contents).
                        let candidate_mass = self.effective_object_mass(candidate_idx);
                        let hit_energy =
                            fixtoi((dx_dir * dx_dir + dy_dir * dy_dir) * candidate_mass / 5);
                        // reduced to 1/3rd, but never dropped to zero by it
                        let hit_energy = (hit_energy / 3).max(i32::from(hit_energy != 0));
                        self.change_object_energy(
                            idx,
                            -(hit_energy / 5),
                            C4FX_CALL_ENG_OBJ_HIT,
                            self.objects[candidate_idx].state.controller,
                        )?;
                        // tmass = max(obj1->Mass, 50) with the LIVE mass
                        // (C4GameObjects.cpp:174).
                        let tmass = self.effective_object_mass(idx).max(50);
                        let candidate_velocity = self.objects[candidate_idx].fixed_velocity;
                        // fling unless airborne off-Tick3 (C4GameObjects.cpp:176)
                        let procedure = self
                            .definitions
                            .get(&definition_id)
                            .map(|definition| {
                                definition
                                    .action_library()
                                    .procedure_for_entry(
                                        &self.objects[idx].state.action.name,
                                        self.objects[idx].state.action.act_map_index,
                                    )
                            })
                            .unwrap_or_default();
                        let has_action = !self.objects[idx].state.action.name.is_empty();
                        if tick3 || (has_action && procedure != ActionProcedure::Flight) {
                            let txdir = C4Fixed::from_raw(
                                candidate_velocity.x.val().wrapping_mul(50) / tmass,
                            );
                            let tydir = C4Fixed::from_raw(
                                -(candidate_velocity.y.val() / 2).abs().wrapping_mul(50) / tmass,
                            );
                            let caused_by = self.objects[candidate_idx].state.controller;
                            self.fling_object(idx, txdir, tydir, caused_by);
                        }
                        let _ = self.call_object_function(
                            idx,
                            "CatchBlow",
                            vec![Value::Int(-(hit_energy / 5)), by_value],
                        )?;
                        // obj1 might have been tampered with
                        let Some(idx) = self.find_object_index(obj1_id) else {
                            continue 'outer;
                        };
                        let obj1 = &self.objects[idx];
                        if obj1.destroyed
                            || !obj1.state.status.is_active()
                            || obj1.state.container.is_some()
                            || self.object_ocf_at_index(idx) & focf == 0
                        {
                            continue 'outer;
                        }
                        continue;
                    }
                }
                // Collection (C4GameObjects.cpp:185-194)
                if ocf1 & crate::ocf::COLLECTION != 0 && ocf2 & crate::ocf::CARRYABLE != 0 {
                    let Some(collection_rect) = collection_rect.filter(|rect| rect.is_positive())
                    else {
                        continue;
                    };
                    if !collection_rect.contains_offset(dx, dy) {
                        continue;
                    }
                    // C4Object::Collect rejects FLAG/FlyBase before Enter
                    // when cached C4RULE_FlagRemoveable is off. Keep this
                    // ahead of RejectEntrance and every mutation/callback
                    // (C4Object.cpp:5693-5700).
                    if compat::flag_collection_blocked(
                        self.objects[candidate_idx].definition_id.as_str(),
                        self.objects[candidate_idx].state.action.name.as_str(),
                        self.flag_removeable,
                    ) {
                        continue;
                    }
                    if coach_debug_id() == Some(candidate_id.as_u64())
                        || coach_debug_id() == Some(obj1_id.as_u64())
                    {
                        crate::rng::rng_trace_line(&format!(
                            "XCOLLECT collector={} ({:?}) at {:?} takes {} at {:?}",
                            obj1_id.as_u64(),
                            self.objects[idx].definition_id,
                            obj1_position,
                            candidate_id.as_u64(),
                            candidate_position
                        ));
                    }
                    // C4Object::Collect runs the full Enter-and-tail path:
                    // both vetoes, fCopyMotion=false callbacks, attach
                    // cancellation, Collection/Hit and the final conditional
                    // CopyMotion (C4Object.cpp:5693-5715).
                    let _ = self.try_object_collect(candidate_id, obj1_id)?;
                    // obj1 might have been tampered with
                    let Some(idx) = self.find_object_index(obj1_id) else {
                        continue 'outer;
                    };
                    let obj1 = &self.objects[idx];
                    if obj1.destroyed
                        || !obj1.state.status.is_active()
                        || obj1.state.container.is_some()
                        || self.object_ocf_at_index(idx) & focf == 0
                    {
                        continue 'outer;
                    }
                }
            }
        }
        Ok(())
    }

    fn call_command_buy_value(
        &mut self,
        actor_id: ObjectId,
        item_definition: &str,
        base_id: ObjectId,
        buyer: i32,
    ) -> Result<Option<i32>, EngineError> {
        let idx = self
            .find_object_index(actor_id)
            .ok_or(EngineError::UnknownObject(actor_id))?;
        let (definition_id, state_snapshot) = {
            let object = &self.objects[idx];
            (object.definition_id.clone(), object.script_state_snapshot())
        };
        let definition = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        let action_library = definition.action_library().clone();
        let call = definition.command_buy_value(
            &state_snapshot,
            actor_id,
            item_definition,
            base_id,
            buyer,
            self.rng.clone(),
            &self.global_effects.clone(),
            self.physics,
            self.environment,
            self.frame,
            self.host_world_context_for_object(idx),
            self.game_over_triggered,
            self.audio_registry.clone(),
        );
        let (price, outcome, audio_state, new_rng) = match call {
            Ok(ok) => ok,
            Err(error) => {
                return Err(self.apply_script_error_recovery(
                    error,
                    idx,
                    &action_library,
                    actor_id,
                    &definition_id,
                    false,
                ));
            }
        };
        self.rng = new_rng;
        self.audio_registry = audio_state;
        self.apply_callback_outcome(
            idx,
            outcome,
            &action_library,
            actor_id,
            &definition_id,
            false,
        )?;
        Ok(price)
    }

